/* Generated by scripts/render/styles-css.mjs — do not edit by hand. */
:root {
  /* "Ledger" — a warm trading-desk canvas: espresso ink under parchment
     type, the way a ruled ledger or an FT page reads, not the default
     cool-slate SaaS dark mode. Atmosphere is elevation + hairlines, never
     decorative gradients. The signature chromatic note is a brass/gold
     accent (ticker-tape brass, not the generic fintech green); market
     direction owns green/red on its own (--pos / --neg), so the accent is
     never confused with "up". */
  --bg:#0c0b09;
  --surface:#17150f;
  --surface-2:#201d15;
  --surface-3:#2b271d;
  --border:rgba(244,233,210,0.10);
  --border-strong:rgba(244,233,210,0.18);
  --hairline:rgba(244,233,210,0.06);
  --text:#e7e0d2;
  --text-strong:#faf5ea;
  --muted:#8d8472;
  --muted-strong:#b6ac96;
  /* Signature brass — the Ledger accent in one chip. Used sparingly for
     active states, focus rings, eyebrows, CTAs and section marks. It is
     deliberately NOT the up/positive color; green (--pos) carries that, so
     the brand color never doubles as a market signal. Never flood large
     fields with it. */
  --accent:#d9a533;
  --accent-soft:rgba(217,165,51,0.11);
  --accent-strong:#efc15c;
  --accent-glow:rgba(217,165,51,0.26);
  --accent-glow-soft:rgba(217,165,51,0.13);
  --accent-tint-1:rgba(217,165,51,0.06);
  --accent-tint-2:rgba(217,165,51,0.12);
  --pos:#3ad29a;
  --pos-soft:rgba(58,210,154,0.11);
  --pos-glow:rgba(58,210,154,0.18);
  --pos-tint:rgba(58,210,154,0.07);
  --neg:#f2645f;
  --neg-soft:rgba(242,100,95,0.11);
  --neg-glow:rgba(242,100,95,0.18);
  --neg-tint:rgba(242,100,95,0.07);
  --warn:#f08a3c;
  --warn-soft:rgba(240,138,60,0.13);
  --warn-tint:rgba(240,138,60,0.08);
  --info:#5b9bd6;
  --info-soft:rgba(91,155,214,0.11);
  --info-tint:rgba(91,155,214,0.07);
  /* Violet — the non-valenced "intensity" hue (Trending IV tiers). Chosen so
     magnitude scales (yellow → blue → violet) never borrow red/green, which
     stay reserved for actual gain/loss direction. */
  --violet:#af8df0;
  --violet-soft:rgba(175,141,240,0.13);
  /* Institutional UIs are defined by precise hairlines + subtle drop, not
     puffy shadows. Keep elevation strictly for modals + popovers. */
  --shadow-sm:0 1px 2px rgba(0,0,0,0.35);
  --shadow-md:0 4px 16px rgba(0,0,0,0.45);
  --shadow-lg:0 24px 60px rgba(0,0,0,0.60);
  --shadow-glow-accent:0 0 0 1px color-mix(in srgb, var(--accent) 25%, transparent);
  /* Refined 4-tier elevation ladder — hairline + soft drops. Tier 0 is
     flat (data rows). Tier 1 is the resting card. Tier 2 is a raised
     surface (hero readouts, pinned strip). Tier 3 is modal/popover. */
  --elev-0:0 0 0 1px var(--hairline);
  --elev-1:inset 0 1px 0 rgba(255,255,255,0.03), 0 1px 0 var(--hairline), 0 2px 6px rgba(0,0,0,0.50), 0 8px 20px -12px rgba(0,0,0,0.55);
  --elev-2:0 1px 0 var(--hairline), 0 8px 24px rgba(0,0,0,0.50), inset 0 1px 0 rgba(255,255,255,0.02);
  --elev-2-hover:0 1px 0 var(--hairline), 0 14px 34px -10px rgba(0,0,0,0.55), inset 0 1px 0 rgba(255,255,255,0.04);
  --elev-3:0 0 0 1px var(--border-strong), 0 24px 60px rgba(0,0,0,0.65), inset 0 1px 0 rgba(255,255,255,0.04);
  --elev-pop:var(--elev-3);
  --elev-focus:0 0 0 1px var(--accent), 0 0 0 4px var(--accent-glow-soft);
  --elev-glow:0 0 24px -4px var(--accent-glow);
  /* Glass surfaces — sticky header, popovers, command palette only.
     Never on data cards. */
  --glass-bg:color-mix(in srgb, var(--surface) 72%, transparent);
  --glass-border:color-mix(in srgb, var(--text-strong) 8%, var(--border));
  --glass-blur:saturate(160%) blur(16px);
  /* Accent ramp extras for tinted backgrounds and on-fill text. Brass fills
     take dark espresso ink as their foreground (not white) — the high-
     contrast, "stamped foil" reading. */
  --accent-dim:#a87a1c;
  --accent-fg:#211705;
  --accent-line:color-mix(in srgb, var(--accent) 38%, var(--border));
  /* Gradient skins — applied via background-image so borders + box-shadow
     compose cleanly on top. The "hero" gradient is reserved for the
     few flagship surfaces (score readout, AI review, sign-in card). */
  --gradient-card:var(--surface);
  --gradient-positive:linear-gradient(180deg, color-mix(in srgb, var(--pos) 10%, var(--surface)) 0%, var(--surface) 70%);
  --gradient-negative:linear-gradient(180deg, color-mix(in srgb, var(--neg) 10%, var(--surface)) 0%, var(--surface) 70%);
  --grad-surface:linear-gradient(180deg, color-mix(in srgb, #ffffff 5%, var(--surface)) 0%, var(--surface) 60%);
  --grad-surface-raised:linear-gradient(180deg, color-mix(in srgb, var(--accent) 4%, var(--surface-2)) 0%, var(--surface) 70%);
  --grad-pos:linear-gradient(180deg, var(--pos-tint) 0%, transparent 60%);
  --grad-neg:linear-gradient(180deg, var(--neg-tint) 0%, transparent 60%);
  --grad-warn:linear-gradient(180deg, var(--warn-tint) 0%, transparent 60%);
  --grad-hero:linear-gradient(135deg, color-mix(in srgb, var(--accent) 15%, var(--surface)) 0%, var(--surface) 58%, color-mix(in srgb, #c65f2e 7%, var(--surface)) 100%);
  /* Display typography — large hero numbers (equity, score) lean on
     this weight + slight negative tracking. */
  --fw-display:700;
  --ls-display:-0.03em;
  --r-1:4px; --r-2:6px; --r-3:8px; --r-4:14px; --r-5:18px; --r-pill:999px;
  --s-1:4px; --s-2:8px; --s-3:12px; --s-4:16px; --s-5:20px; --s-6:24px; --s-7:32px; --s-8:48px;
  --fs-2xs:10px; --fs-xs:11px; --fs-sm:13px; --fs-md:15px; --fs-lg:16px; --fs-xl:19px; --fs-2xl:25px; --fs-3xl:33px; --fs-hero:50px; --fs-mega:64px;
  --lh-tight:1.15; --lh-snug:1.35; --lh-normal:1.55;
  --ls-num:-0.01em; --ls-caps:0.10em;
  --font-sans:"Hanken Grotesk", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, system-ui, sans-serif;
  --font-mono:"JetBrains Mono", "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* Display serif (Fraunces) — card titles, hero headlines, section marks
     and the wordmark. A high-contrast, optically-sized "old-style" serif
     with real character: it gives the product an editorial, art-directed
     voice that a geometric sans can't, and signals a human hand over a
     template. Pairs with Hanken Grotesk (--font-sans) for dense UI and
     JetBrains Mono (--font-mono) for tabular data. The var name stays
     --font-serif for compatibility with existing uses. */
  --font-serif:"Fraunces", "Hanken Grotesk", "Iowan Old Style", Georgia, serif;
  --focus-ring:0 0 0 2px color-mix(in srgb, var(--accent) 45%, transparent);
  --ease-out:cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out:cubic-bezier(0.4, 0, 0.2, 1);
  /* One restrained-overshoot easing reserved for press/lift micro-feedback. */
  --ease-spring:cubic-bezier(0.34, 1.56, 0.64, 1);
  --dur-0:90ms; --dur-1:120ms; --dur-2:220ms; --dur-3:350ms;
  /* Offset focus ring — a --bg-colored gap separates the accent ring from
     busy/glass surfaces (header, command palette). Gap flips per theme via
     --bg, so it stays crisp on both. */
  --focus-ring-bold:0 0 0 2px var(--bg), 0 0 0 4px var(--accent), 0 0 0 8px var(--accent-glow-soft);
  /* Alias tokens — these were referenced across the vol / strategies / OI /
     heatmap tabs (100+ uses) but never declared, so they silently fell through
     (color → inherited, radius → 0, transition → none). They are var()-based,
     so this single base definition resolves correctly in BOTH themes. */
  --text-2:var(--muted-strong);
  --text-3:var(--muted);
  --text-muted:var(--muted);
  --up:var(--pos);
  --dn:var(--neg);
  --xt:.12s var(--ease-out);
  --r-md:var(--r-3);
  --r-sm:var(--r-2);
  --accent-on:var(--accent-fg);
  /* Unified content widths — wider than the legacy 760px to give the new
     dashboard layouts room to breathe without losing the focused feel. */
  --w-content:1120px;
  --w-shell:1220px;
  color-scheme:dark;
}
:root[data-theme="light"] {
  /* Light theme — a cool slate-gray trading canvas. It avoids the glare of
     white while keeping cards, controls, chart grids and dense tables clearly
     separated. Text tokens retain WCAG-friendly contrast on every surface. */
  --bg:#e9eef5;
  --surface:#f2f5f8;
  --surface-2:#e9eef4;
  --surface-3:#e1e7ef;
  --border:rgba(30,41,59,0.15);
  --border-strong:rgba(30,41,59,0.24);
  --hairline:rgba(30,41,59,0.09);
  --text:#273449;
  --text-strong:#111827;
  --muted:#64748b;
  --muted-strong:#475569;
  --accent:#9a6f12;
  --accent-soft:rgba(154,111,18,0.10);
  --accent-strong:#7d590a;
  --accent-glow:rgba(154,111,18,0.20);
  --accent-glow-soft:rgba(154,111,18,0.10);
  --accent-tint-1:rgba(154,111,18,0.05);
  --accent-tint-2:rgba(154,111,18,0.10);
  --pos:#0f9d5e;
  --pos-soft:rgba(15,157,94,0.10);
  --pos-glow:rgba(15,157,94,0.16);
  --pos-tint:rgba(15,157,94,0.06);
  --neg:#d8453f;
  --neg-soft:rgba(216,69,63,0.10);
  --neg-glow:rgba(216,69,63,0.14);
  --neg-tint:rgba(216,69,63,0.06);
  --warn:#b5700f;
  --warn-soft:rgba(181,112,15,0.10);
  --warn-tint:rgba(181,112,15,0.07);
  --info:#2f6fb5;
  --info-soft:rgba(47,111,181,0.10);
  --info-tint:rgba(47,111,181,0.06);
  --violet:#6d47bd;
  --violet-soft:rgba(109,71,189,0.10);
  --shadow-sm:0 1px 2px rgba(15,23,42,0.05);
  --shadow-md:0 4px 12px rgba(15,23,42,0.08);
  --shadow-lg:0 24px 48px rgba(15,23,42,0.12);
  --shadow-glow-accent:0 0 0 1px color-mix(in srgb, var(--accent) 25%, transparent);
  --elev-0:0 0 0 1px var(--hairline);
  --elev-1:0 1px 0 var(--hairline), 0 2px 6px rgba(15,23,42,0.06), 0 10px 22px -14px rgba(15,23,42,0.10);
  --elev-2:0 1px 0 var(--hairline), 0 10px 28px rgba(15,23,42,0.10);
  --elev-2-hover:0 1px 0 var(--hairline), 0 16px 34px -12px rgba(15,23,42,0.14);
  --elev-3:0 0 0 1px var(--border-strong), 0 28px 60px rgba(15,23,42,0.18);
  --elev-pop:var(--elev-3);
  --elev-focus:0 0 0 1px var(--accent), 0 0 0 4px var(--accent-glow-soft);
  --elev-glow:0 0 22px -4px var(--accent-glow);
  --glass-bg:color-mix(in srgb, var(--surface) 78%, transparent);
  --glass-border:color-mix(in srgb, var(--text-strong) 6%, var(--border));
  --glass-blur:saturate(150%) blur(16px);
  --accent-dim:#0b7d4d;
  --accent-fg:#ffffff;
  --accent-line:color-mix(in srgb, var(--accent) 35%, var(--border));
  --gradient-card:var(--surface);
  --gradient-positive:linear-gradient(180deg, color-mix(in srgb, var(--pos) 8%, var(--surface)) 0%, var(--surface) 70%);
  --gradient-negative:linear-gradient(180deg, color-mix(in srgb, var(--neg) 8%, var(--surface)) 0%, var(--surface) 70%);
  --grad-surface:linear-gradient(180deg, var(--surface) 0%, color-mix(in srgb, var(--surface) 96%, var(--surface-2)) 100%);
  --grad-surface-raised:linear-gradient(180deg, color-mix(in srgb, var(--accent) 3%, var(--surface)) 0%, var(--surface) 70%);
  --grad-hero:linear-gradient(135deg, color-mix(in srgb, var(--accent) 11%, var(--surface)) 0%, var(--surface) 58%, color-mix(in srgb, #c65f2e 6%, var(--surface)) 100%);
  --focus-ring:0 0 0 2px color-mix(in srgb, var(--accent) 40%, transparent);
  color-scheme:light;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font: var(--fs-md)/var(--lh-normal) var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
  font-feature-settings: "cv11", "ss01", "tnum" 1;
  /* One restrained vignette behind the masthead — replaces the multi-radial
     accent halos that read as the AI-template default. Just enough depth
     to seat the header without competing with content. */
  background-image:
    radial-gradient(ellipse 1100px 380px at 50% -120px,
      color-mix(in srgb, var(--accent) 5%, transparent) 0%,
      transparent 75%);
  background-attachment: fixed;
  background-repeat: no-repeat;
  letter-spacing: 0;
}
:root[data-theme="light"] body {
  background-image:
    radial-gradient(ellipse 1100px 380px at 50% -120px,
      color-mix(in srgb, var(--accent) 4%, transparent) 0%,
      transparent 75%);
}
/* Numeric data — always tabular and slightly tighter than prose */
.num, .mono, code, kbd, samp,
.pf-symbol, .pf-equity-now, .pf-equity-chg,
.pf-perf-pnl-value, .pf-stat-value,
.pf-mark-value, .pf-pnl-pct, .pf-pnl-total {
  font-feature-settings: "tnum" 1, "ss01" 1;
  font-variant-numeric: tabular-nums;
}
/* Standard institutional "eyebrow" label — tracked-out small caps used
   above every data section. Pairs with --muted to read as metadata. */
.eyebrow {
  font-size: var(--fs-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  color: var(--muted);
  font-feature-settings: "tnum" 1;
}
@keyframes pf-fade-in {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes pf-shimmer {
  from { background-position: -200px 0; }
  to   { background-position: calc(200px + 100%) 0; }
}

/* === Motion primitives ===================================================
   Tasteful, professional micro-animations. All gated under
   prefers-reduced-motion: no-preference so accessibility settings short-
   circuit motion entirely. Reuses --ease-out (1,0.3,1 cubic-bezier) so
   timing matches the rest of the UI's transitions.

   stonks-fade-up:   subtle 8px rise + opacity 0→1, used for card entrances
   stonks-fade-in:   pure opacity 0→1, used for page-pane swaps where a
                     translate would conflict with the underlying layout
   stonks-draw:      stroke-dashoffset 1→0, used for SVG paths drawing in
   stonks-pulse:     soft scale 1→1.04→1, used for value-change emphasis
   ----------------------------------------------------------------------*/
@keyframes stonks-fade-up {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes stonks-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes stonks-draw {
  to { stroke-dashoffset: 0; }
}
/* Hero surfaces (score readout, AI review) softly breathe an accent
   halo so the user's eye returns to them. Capped iteration so the
   motion doesn't feel relentless on long sessions. */
@keyframes stonks-glow-pulse {
  0%, 100% { box-shadow: var(--elev-2), 0 0 0 0 var(--accent-glow-soft); }
  50%      { box-shadow: var(--elev-2), 0 0 24px 2px var(--accent-glow); }
}

@media (prefers-reduced-motion: no-preference) {
  /* Page-tab swap: fade the freshly-shown pane in with a small upward
     translate. Gives the top-level nav a sense of weight without
     disrupting layout. */
  .page-pane:not([hidden]) {
    animation: stonks-fade-up var(--dur-3) var(--ease-out);
  }
  /* Calendar chips cascade in on first paint of a day group. Limit the
     cascade depth so a heavy news day doesn't ripple visibly for 2s. */
  .cal-chip {
    animation: stonks-fade-up .32s var(--ease-out) both;
  }
  .cal-day .cal-chip:nth-child(1) { animation-delay: 0ms; }
  .cal-day .cal-chip:nth-child(2) { animation-delay: 30ms; }
  .cal-day .cal-chip:nth-child(3) { animation-delay: 60ms; }
  .cal-day .cal-chip:nth-child(4) { animation-delay: 90ms; }
  .cal-day .cal-chip:nth-child(5) { animation-delay: 120ms; }
  .cal-day .cal-chip:nth-child(n+6) { animation-delay: 140ms; }
  .cal-chip {
    transition: border-color .15s var(--ease-out), transform .15s var(--ease-out), background .15s var(--ease-out);
  }
  .cal-chip:hover {
    transform: translateX(2px);
    background: color-mix(in srgb, var(--accent) 4%, var(--surface-2));
  }

  /* Portfolio risk: stagger the four sub-blocks on first render so the
     dashboard composes itself instead of slamming in. */
  .pf-risk-block {
    animation: stonks-fade-up .35s var(--ease-out) both;
    transition: transform .18s var(--ease-out), border-color .18s var(--ease-out);
  }
  .pf-risk-grid .pf-risk-block:nth-child(1) { animation-delay: 0ms; }
  .pf-risk-grid .pf-risk-block:nth-child(2) { animation-delay: 50ms; }
  .pf-risk-grid .pf-risk-block:nth-child(3) { animation-delay: 100ms; }
  .pf-risk-grid .pf-risk-block:nth-child(4) { animation-delay: 150ms; }
  .pf-risk-block:hover {
    border-color: color-mix(in srgb, var(--accent) 25%, var(--border));
  }

  /* IV card: term-structure line draws itself in. stroke-dasharray on
     the path is set inline by the renderer so the keyframe just sweeps
     the offset to zero. */
  .opt-iv-svg .opt-iv-line {
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    animation: stonks-draw .9s var(--ease-out) forwards;
  }
  .opt-iv-svg .opt-iv-dots circle {
    opacity: 0;
    animation: stonks-fade-in .25s var(--ease-out) forwards;
    animation-delay: .55s;
  }

  /* Flow chips already have a hover background; add a tiny translate so
     the interaction feels intentional rather than flat. */
  .flow-chip {
    transition: background .15s var(--ease-out), border-color .15s var(--ease-out), transform .15s var(--ease-out);
  }
  .flow-chip:hover {
    transform: translateY(-1px);
  }
  /* Narrative cards: subtle lift on hover. Many cards on screen at once,
     so keep it light to avoid making the page feel busy. */
  .narr-industry, .narr-card {
    transition: transform .18s var(--ease-out), border-color .18s var(--ease-out), box-shadow .18s var(--ease-out);
  }
  .narr-card:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px -6px rgba(0, 0, 0, .35);
  }

  /* Sidebar nav items: smoothing the color/background transition makes
     switching between sections feel less abrupt. */
  .page-tab {
    transition: color .15s var(--ease-out), background .15s var(--ease-out), box-shadow .15s var(--ease-out);
  }

  /* Primary CTAs and pill toggles get a press-down state for tactility. */
  .pf-btn, .calendar-pill, .flow-pill, .opt-tab, .acc-tab {
    transition: color .12s var(--ease-out), background .12s var(--ease-out), border-color .12s var(--ease-out), transform .08s var(--ease-out);
  }
  .pf-btn:active, .calendar-pill:active, .flow-pill:active, .opt-tab:active, .acc-tab:active {
    transform: translateY(1px);
  }

  /* Cards opted into hover lift get a subtle raise + accent-tinted
     shadow. Sentiment-keyed surfaces (sector overviews, recommendation
     cards) compose this with their existing background gradient. */
  .card.is-hoverable:hover {
    transform: translateY(-1px);
    box-shadow: var(--elev-2), var(--elev-glow);
  }

  /* Sidebar slide — open/close glides instead of snapping. */
  .side-nav {
    transition: transform .22s var(--ease-out), visibility .22s;
  }
  body { transition: padding-left .22s var(--ease-out); }
}

@media (prefers-reduced-motion: reduce) {
  .side-nav { transition: none; }
  .opt-rec-card, .pf-review-card { animation: none; }
}

.skeleton {
  display: inline-block;
  background: linear-gradient(90deg,
    var(--surface-2) 0%,
    var(--surface-3) 50%,
    var(--surface-2) 100%);
  background-size: 200px 100%;
  background-repeat: no-repeat;
  border-radius: var(--r-2);
  color: transparent;
  animation: pf-shimmer 1.4s linear infinite;
}
@media (prefers-reduced-motion: reduce) {
  .skeleton { animation: none; }
}
.mono, code, kbd, samp {
  font-family: var(--font-mono);
  font-feature-settings: "tnum" 1, "ss01" 1;
}
a { color: var(--accent); text-decoration: none; }
a:hover { color: var(--accent-strong); text-decoration: underline; }
button { font: inherit; }
/* Global focus ring — primary accent ring + soft outer halo so the focused
   element stands out without looking aggressive. Components on busy/glass
   surfaces override box-shadow with var(--focus-ring)/-bold explicitly. */
:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--accent) 45%, transparent),
    0 0 0 5px color-mix(in srgb, var(--accent) 12%, transparent);
  border-radius: var(--r-2);
}
/* Text selection carries the brass accent — a small signature detail the
   OS-default blue highlight would break on the warm canvas. */
::selection {
  background: color-mix(in srgb, var(--accent) 28%, transparent);
  color: var(--text-strong);
}
/* Themed scrollbars everywhere — the OS-default chrome-grey track is the
   one piece of UI the tokens didn't reach. Thumb only, transparent track,
   padded by a transparent border so it floats off the edge. */
html {
  scrollbar-color: color-mix(in srgb, var(--muted) 35%, transparent) transparent;
}
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--muted) 30%, transparent);
  border-radius: 999px;
  border: 3px solid transparent;
  background-clip: padding-box;
}
::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb, var(--muted) 50%, transparent);
  border: 3px solid transparent;
  background-clip: padding-box;
}
/* Ragged two-line headlines read as unfinished; balance keeps hero titles
   and card headings visually centered. No layout risk — line boxes only. */
h1, h2, .landing-hero-title, .landing-section-title { text-wrap: balance; }

/* === Layout ===
   Top utility bar — sticky glass chrome that floats over the scroll.
   Backed by a translucent surface + backdrop blur so content reads
   through without bleeding. Border-bottom carries the hairline so the
   strip below it (page-sub / freshness) doesn't double up. */
.site-header {
  position: sticky;
  top: 0;
  z-index: 60;
  display: flex; align-items: center; justify-content: space-between;
  margin: 0 auto;
  padding: var(--s-3) var(--s-6);
  /* A solid masthead band — not a translucent floating glass bar (that
     backdrop-blur chrome is the giveaway of a generated template). The
     surface band sits a step above the page ink and is underlined by a
     two-rule keyline: a brass hairline over a faint shadow, the way a
     printed masthead is ruled off from the body. */
  background: var(--surface);
  border-bottom: 1px solid color-mix(in srgb, var(--accent) 30%, var(--border));
  box-shadow: 0 1px 0 var(--accent-line), 0 6px 18px -12px rgba(0,0,0,0.7);
}
:root[data-theme="light"] .site-header {
  box-shadow: 0 1px 0 var(--accent-line), 0 6px 18px -12px rgba(15,23,42,0.10);
}
.site-header-inner {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%;
  max-width: var(--w-shell);
  margin: 0 auto;
}
/* Sidebar toggle + brand grouped on the header's left so space-between
   keeps the utility nav pinned right. */
.site-header-lead {
  display: flex; align-items: center; gap: var(--s-3);
  min-width: 0;
}
.side-nav-toggle { flex: 0 0 auto; }
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .site-header { background: var(--surface); }
}
.brand {
  display: inline-flex; align-items: center; gap: var(--s-3);
  color: var(--text-strong);
  font-family: var(--font-serif);
  font-weight: 600; font-size: 22px;
  letter-spacing: -0.01em;
  font-style: italic;
}
.brand:hover { text-decoration: none; }
.brand-word { line-height: 1; }
.brand-mark {
  color: var(--accent);
  transition: transform .35s var(--ease-out);
}
.brand:hover .brand-mark { transform: rotate(28deg); }
.brand-tag {
  font-family: var(--font-sans);
  font-style: normal;
  font-size: 11px; font-weight: 600;
  color: var(--muted); letter-spacing: 0.18em;
  text-transform: uppercase;
  padding: 0;
  border: 0;
  border-radius: 0;
  margin-left: var(--s-1);
  padding-left: var(--s-3);
  border-left: 1px solid var(--hairline);
  background: transparent;
}
.site-nav { display: inline-flex; gap: var(--s-2); align-items: center; }
.discord-btn,
.donate-btn {
  display: inline-flex; align-items: center; gap: 7px;
  height: 34px; padding: 0 13px; border-radius: 999px;
  color: #fff;
  font-size: 13px; font-weight: 700; line-height: 1; text-decoration: none;
  transition: transform .15s var(--ease-out), filter .15s var(--ease-out);
}
.discord-btn {
  background: #5865f2; border: 1px solid #7480ff;
  box-shadow: 0 5px 16px color-mix(in srgb, #5865f2 24%, transparent);
}
.donate-btn {
  background: #ff5e5b; border: 1px solid #ff7774;
  box-shadow: 0 5px 16px color-mix(in srgb, #ff5e5b 24%, transparent);
}
.discord-btn:hover,
.donate-btn:hover { color: #fff; text-decoration: none; filter: brightness(1.06); transform: translateY(-1px); }
.discord-btn:focus-visible,
.donate-btn:focus-visible { outline: none; box-shadow: var(--focus-ring-bold); }
.discord-btn svg,
.donate-btn svg { flex: none; }
@media (max-width: 760px) {
  .discord-btn span, .donate-btn span { display: none; }
  .discord-btn, .donate-btn { width: 36px; padding: 0; justify-content: center; }
}
.auth-chip {
  display: inline-flex; align-items: center; gap: 7px;
  height: 32px; padding: 0 10px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface-2, transparent);
  color: var(--muted);
  font-size: 13.5px; line-height: 1;
}
.auth-chip svg { color: var(--accent, #5865f2); flex: none; }
.auth-chip .auth-name { color: var(--text); font-weight: 600; max-width: 140px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.auth-chip .auth-logout {
  color: var(--muted); text-decoration: none; font-weight: 600;
  padding-left: 8px; margin-left: 2px; border-left: 1px solid var(--border);
}
.auth-chip .auth-logout:hover { color: var(--text); text-decoration: underline; }
@media (max-width: 560px) { .auth-chip .auth-name { display: none; } }
/* Owner destinations must not flash while /me is unresolved or for visitors. */
body:not(.is-owner) [data-go="picks"],
body:not(.is-owner) [data-go="market"],
body:not(.is-owner) [data-go="stocks"],
body:not(.is-owner) [data-go="rotation"],
body:not(.is-owner) [data-go="levetf"],
body:not(.is-owner) [data-go="track"],
body:not(.is-owner) [data-go="daytrade"],
body:not(.is-owner) [data-go="daytrack"],
body:not(.is-owner) [data-go="quant"] { display:none !important; }
.icon-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 32px; height: 32px;
  border-radius: var(--r-2);
  background: transparent;
  border: 1px solid var(--border);
  color: var(--muted);
  cursor: pointer;
  transition: color .15s var(--ease-out), border-color .15s var(--ease-out),
              background .15s var(--ease-out);
}
.icon-btn:hover {
  color: var(--text-strong);
  border-color: var(--border-strong);
  background: var(--surface-2);
  text-decoration: none;
}
:root:not([data-theme="dark"]) .icon-btn .i-moon { display: none; }
:root[data-theme="dark"] .icon-btn .i-sun { display: none; }

/* Marketing tagline under the header — kept small + muted so it reads as
   metadata, not as a hero. Institutional dashboards don't need a pitch. */
.page-sub {
  max-width: var(--w-content); margin: 0 auto;
  padding: var(--s-3) var(--s-5) 0;
  color: var(--muted);
  font-size: var(--fs-sm);
  letter-spacing: 0;
  line-height: var(--lh-snug);
}

main {
  max-width: var(--w-content); margin: 0 auto;
  padding: var(--s-3) var(--s-5) var(--s-7);
}

/* === Sidebar navigation ===
   Every destination lives in a collapsible left sidebar, grouped by trader
   task inside native disclosure sections. Desk + Ideas start open. Desktop
   (>=1024px): the sidebar pushes the page content (body padding-left) and
   defaults open; the collapsed preference persists to localStorage. Below
   that it's an overlay drawer over a dimming backdrop, closed by default
   and auto-closed on navigation. */
/* Heights of the pinned chrome stack, shared so stacked stickies (the Grade
   tab's verdict bar) can offset below them. --header-h matches the sticky
   .site-header; --sidenav-w is the sidebar's width (and the desktop content
   offset while it's open). */
:root { --header-h: 56px; --sidenav-w: 240px; }
.side-nav {
  position: fixed;
  top: var(--header-h);
  bottom: 0;
  left: 0;
  width: var(--sidenav-w);
  z-index: 55;
  /* Recessed rail — a step below the card surface so the sidebar reads as
     chrome (the binding of the ledger), not as another content panel. */
  background: color-mix(in srgb, var(--surface) 55%, var(--bg));
  border-right: 1px solid var(--border);
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--muted) 35%, transparent) transparent;
  /* Mobile default: off-canvas drawer. body.sidenav-open slides it in;
     desktop overrides below. visibility keeps the hidden drawer out of
     the tab order without display:none (which would kill the slide). */
  transform: translateX(-100%);
  visibility: hidden;
}
.side-nav::-webkit-scrollbar { width: 8px; }
.side-nav::-webkit-scrollbar-track { background: transparent; }
.side-nav::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--muted) 30%, transparent);
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
body.sidenav-open .side-nav {
  transform: translateX(0);
  visibility: visible;
  /* Drawer floats over content on mobile — give it real elevation so the
     edge is unambiguous against a busy tab. */
  box-shadow: 24px 0 60px -28px rgba(0, 0, 0, 0.65);
}
/* Dimming backdrop behind the mobile drawer — tap to close. */
.side-nav-backdrop {
  position: fixed;
  inset: var(--header-h) 0 0 0;
  z-index: 54;
  background: rgba(8, 7, 5, 0.5);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
}
.side-nav-backdrop[hidden] { display: none; }
@media (max-width: 1023px) {
  /* The mobile drawer owns the full viewport. Leaving it below --header-h
     creates an empty dark strip whenever the sticky header is outside the
     captured/visible area, which reads as a blank black box above the menu. */
  .side-nav {
    top: 0;
    z-index: 65;
    padding-top: env(safe-area-inset-top);
  }
  .side-nav-backdrop {
    inset: 0;
    z-index: 64;
  }
}
@media (min-width: 1024px) {
  /* Desktop: open by default (no body class), pushes the content over.
     body.sidenav-closed collapses it off-canvas. */
  .side-nav { transform: none; visibility: visible; }
  body.sidenav-open .side-nav { box-shadow: none; }
  body.sidenav-closed .side-nav { transform: translateX(-100%); visibility: hidden; }
  body:not(.sidenav-closed) { padding-left: var(--sidenav-w); }
  .side-nav-backdrop { display: none !important; }
}
.page-tabs {
  display: flex;
  flex-direction: column;
  padding: var(--s-4) 10px var(--s-7);
}
.side-nav-group { display: block; }
.side-nav-group[hidden] { display: none; }
.side-nav-group + .side-nav-group {
  margin-top: 6px;
}
/* Collapsible group label — the chevron makes the hierarchy explicit while
   the ledger rule preserves the printed-index character of the rail. */
.side-nav-group-label {
  display: flex;
  align-items: center;
  gap: var(--s-2);
  min-height: 28px;
  padding: 5px var(--s-2) 5px var(--s-3);
  list-style: none;
  cursor: pointer;
  font-size: var(--fs-2xs);
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--muted) 85%, transparent);
  border-radius: var(--r-2);
  transition: color var(--dur-1) var(--ease-out), background var(--dur-1) var(--ease-out);
}
.side-nav-group-label::-webkit-details-marker { display: none; }
.side-nav-group-label:hover { color: var(--text); background: color-mix(in srgb, var(--text-strong) 4%, transparent); }
.side-nav-group-label:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.side-nav-group-label::before {
  content: "›";
  flex: 0 0 auto;
  color: var(--muted);
  font-size: 14px;
  line-height: 1;
  transform-origin: center;
  transition: transform var(--dur-1) var(--ease-out), color var(--dur-1) var(--ease-out);
}
.side-nav-group[open] > .side-nav-group-label { color: var(--muted-strong); }
.side-nav-group[open] > .side-nav-group-label::before { transform: rotate(90deg); color: var(--accent); }
.side-nav-group-label::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--hairline);
}
.side-nav-group-items {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-top: 2px;
}
/* Destination-only panes (Grade a ticker): the button stays in the DOM so
   selectTab / cmd-K / "open in Grade tab" links keep working, but it never
   shows in the sidebar. */
.page-tab[data-nav-hidden] { display: none !important; }
.page-tab {
  position: relative;
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 32px;
  text-align: left;
  background: transparent;
  border: 0;
  color: var(--muted-strong);
  font: inherit;
  font-size: var(--fs-sm);
  font-weight: 500;
  letter-spacing: 0.01em;
  padding: 6px 10px 6px var(--s-3);
  border-radius: var(--r-3);
  cursor: pointer;
  transition: color var(--dur-1) var(--ease-out),
              background var(--dur-1) var(--ease-out),
              box-shadow var(--dur-1) var(--ease-out);
}
.page-tab .pt-ico {
  flex: 0 0 auto;
  color: var(--muted);
  opacity: 0.8;
  transition: color var(--dur-1) var(--ease-out), opacity var(--dur-1) var(--ease-out);
}
.page-tab .pt-label {
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.page-tab:hover {
  color: var(--text-strong);
  background: color-mix(in srgb, var(--text-strong) 5%, transparent);
}
.page-tab:hover .pt-ico { color: var(--muted-strong); opacity: 1; }
/* Active item — a softly brass-washed row, a hairline keyline, a rounded
   accent bar on the left edge and a brass glyph. The wash fades out to the
   right so the row reads lit-from-the-spine rather than flood-filled. */
.page-tab[aria-selected="true"] {
  color: var(--text-strong);
  font-weight: 600;
  background: linear-gradient(90deg, var(--accent-tint-2), var(--accent-tint-1) 78%);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 20%, transparent);
}
.page-tab[aria-selected="true"]::before {
  content: "";
  position: absolute;
  left: 0;
  top: 7px;
  bottom: 7px;
  width: 3px;
  border-radius: var(--r-pill);
  background: var(--accent);
}
.page-tab[aria-selected="true"] .pt-ico { color: var(--accent); opacity: 1; }
.page-tab:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.page-pane[hidden] { display: none; }
/* Reference / legal / info pages (Buyer's manual, Chart patterns, What's
   included, Privacy, Terms) mounted as in-app tabs. The host is a bare block —
   all visual styling lives inside its shadow root (scripts/render/docs.mjs), so
   the page keeps its own bespoke look with no collision against the app CSS. */
.doc-pane { padding: 0; }
.doc-host { display: block; }

.site-footer {
  max-width: var(--w-shell);
  margin: var(--s-7) auto 0;
  padding: var(--s-5) var(--s-5) var(--s-6);
  color: var(--muted); font-size: var(--fs-xs);
  display: flex; flex-wrap: wrap; gap: var(--s-4); justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--hairline);
  font-family: var(--font-sans);
  font-feature-settings: "tnum" 1;
  letter-spacing: 0;
  text-transform: none;
}
.site-footer > div { display: inline-flex; align-items: center; gap: var(--s-2); }
.site-footer .muted { color: var(--muted); text-transform: none; letter-spacing: 0; }
.site-footer .mono, .site-footer time { font-family: var(--font-mono); }
.site-footer a {
  color: var(--muted);
  border-bottom: 1px solid transparent;
  transition: color .12s var(--ease-out), border-color .12s var(--ease-out);
}
.site-footer a:hover {
  color: var(--text);
  border-bottom-color: var(--accent);
  text-decoration: none;
}
/* Community invite stays recognizable in Discord's brand colour without
   competing with the persistent header button. */
.site-footer a.foot-discord {
  color: #7480ff;
  font-weight: 600;
  border-bottom-color: transparent;
}
.site-footer a.foot-discord:hover { color: #8e97ff; border-bottom-color: #8e97ff; }
:root[data-theme="light"] .site-footer a.foot-discord { color: #4652c4; }
:root[data-theme="light"] .site-footer a.foot-discord:hover { color: #35409f; border-bottom-color: #35409f; }
/* Donation link is accented without competing with the header button. */
.site-footer a.foot-support {
  color: #ff6966;
  font-weight: 600;
  border-bottom-color: transparent;
}
.site-footer a.foot-support:hover { color: #ff6966; border-bottom-color: #ff6966; }

/* === Status strip ===
   Sits between the header and the page tabs. Three slots laid out like a
   trader-desk system bar: SYSTEM STATUS · DATA TIMESTAMP · MARKET STATE.
   Each is a label-over-value cell with a hairline divider between, mono
   font for the value so timestamps line up. */
.freshness {
  max-width: var(--w-content);
  margin: 0 auto var(--s-2);
  padding: var(--s-3) var(--s-5) var(--s-2);
  display: flex;
  gap: var(--s-3);
  align-items: center;
  flex-wrap: wrap;
  color: var(--muted);
  font-size: var(--fs-sm);
  font-family: var(--font-sans);
  font-feature-settings: "tnum" 1;
  letter-spacing: 0;
  text-transform: none;
}
/* Quiet, static status mark — a small filled disc, no pulsing halo. The
   color carries the signal; the heartbeat-style animation reads as
   generative-AI chrome and isn't needed. */
.freshness .freshness-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--pos); flex: 0 0 6px;
}
.freshness.warn .freshness-dot { background: var(--warn); }
.freshness.bad  .freshness-dot { background: var(--neg); }
@keyframes freshness-pulse {
  0%, 100% {
    box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 18%, transparent),
                0 0 0 0 color-mix(in srgb, currentColor 40%, transparent);
  }
  50% {
    box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 18%, transparent),
                0 0 0 6px color-mix(in srgb, currentColor 0%, transparent);
  }
}
.freshness .freshness-dot { color: var(--pos); }
.freshness.warn .freshness-dot { color: var(--warn); }
.freshness.bad .freshness-dot { color: var(--neg); }
@media (prefers-reduced-motion: reduce) {
  .freshness .freshness-dot { animation: none; }
}
.freshness-detail { color: var(--muted); text-transform: none; letter-spacing: 0; }
.freshness #freshness-text { color: var(--text); font-weight: 500; }
.freshness .mono, .freshness time { font-family: var(--font-mono); font-feature-settings: "tnum" 1; }
.freshness.warn #freshness-text { color: var(--warn); }
.freshness.bad  #freshness-text { color: var(--neg); }

/* Live market-status badge in the freshness banner. A quiet pill whose leading
   dot carries the state: open = green, pre-market / after-hours = amber,
   closed (weekend/holiday) = grey. Computed client-side from ET wall-clock. */
.market-status {
  display: inline-flex;
  align-items: center;
  gap: var(--s-2);
  padding: 2px var(--s-3);
  border-radius: 999px;
  border: 1px solid var(--border);
  color: var(--muted);
  font-size: var(--fs-sm);
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
  white-space: nowrap;
}
.market-status::before {
  content: "";
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--muted); flex: 0 0 6px;
}
.market-status-open   { color: var(--pos);  border-color: color-mix(in srgb, var(--pos) 35%, var(--border)); }
.market-status-open::before   { background: var(--pos); }
.market-status-pre,
.market-status-after  { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 35%, var(--border)); }
.market-status-pre::before,
.market-status-after::before  { background: var(--warn); }
.market-status-closed { color: var(--muted); }
.market-status-closed::before { background: var(--muted); }

/* Top-Picks "markets closed" context note — explains a short list outside the
   live session is expected (picks need live option quotes), not a failure. */
.picks-market-note {
  margin: 0 0 var(--s-4);
  padding: var(--s-3) var(--s-4);
  border-radius: var(--r-2);
  border: 1px solid color-mix(in srgb, var(--warn) 30%, var(--border));
  background: color-mix(in srgb, var(--warn) 8%, transparent);
  color: var(--text);
  font-size: var(--fs-sm);
  line-height: 1.5;
}
.picks-market-note strong { color: var(--warn); font-weight: 700; }

/* === Landing / Home tab ===
   First view a user lands on. A welcome hero + a grid of clickable
   section cards. Each card uses the new gradient skin + glow tokens
   so the entry point reads as the showcase surface. */
.landing-hero {
  position: relative;
  max-width: var(--w-content);
  margin: 0 auto var(--s-5);
  padding: var(--s-6) var(--s-4) var(--s-4);
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--hairline);
  border-radius: 0;
  box-shadow: none;
  overflow: visible;
}
.landing-hero-main {
  display: grid;
  grid-template-columns: minmax(250px, .82fr) minmax(460px, 1.18fr);
  align-items: end;
  gap: clamp(20px, 4vw, 48px);
}
.landing-hero-copy { min-width: 0; }
/* Kicker above the headline — set as small caps with a hairline rule on
   the left so it reads like a printed publication's section mark rather
   than a SaaS eyebrow chip. */
.landing-hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font: 600 var(--fs-xs)/1 var(--font-sans);
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: var(--muted-strong);
  margin-bottom: var(--s-4);
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}
.landing-hero-eyebrow::before {
  content: "";
  display: inline-block;
  width: 28px; height: 1px;
  background: var(--accent);
  opacity: 0.85;
}
.landing-hero-title {
  margin: 0 0 var(--s-3);
  font-family: var(--font-serif);
  font-size: clamp(36px, 4.4vw, 52px);
  font-weight: 500;
  letter-spacing: -0.025em;
  color: var(--text-strong);
  line-height: 1.02;
  max-width: 15ch;
}
.landing-hero-sub {
  margin: 0;
  color: var(--muted);
  font-size: var(--fs-sm);
  letter-spacing: 0.02em;
  line-height: 1.5;
  max-width: 52ch;
}
.landing-hero-sub .mono { color: var(--text); }
.landing-quick {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  min-width: 0;
}
.landing-quick-card {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 3px 8px;
  min-width: 0;
  padding: 11px 34px 11px 12px;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface);
  color: var(--text);
  text-align: left;
  font: inherit;
  cursor: pointer;
  transition: border-color .15s var(--ease-out), background .15s var(--ease-out), transform .2s var(--ease-out);
}
.landing-quick-card:hover { border-color: color-mix(in srgb, var(--accent) 45%, var(--border)); background: var(--surface-2); transform: translateY(-1px); }
.landing-quick-card:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--elev-focus); }
.landing-quick-card > span { grid-column: 1; color: var(--accent); font: 700 8.5px/1.1 var(--font-sans); letter-spacing: .08em; text-transform: uppercase; }
.landing-quick-card > b { grid-column: 1; color: var(--text-strong); font: 700 12.5px/1.2 var(--font-sans); }
.landing-quick-card > small { grid-column: 1; color: var(--muted); font: 400 9.5px/1.3 var(--font-sans); }
.landing-quick-card > em { position: absolute; top: 50%; right: 12px; color: var(--muted); font: 500 15px/1 var(--font-sans); font-style: normal; transform: translateY(-50%); transition: color .15s var(--ease-out), transform .2s var(--ease-out); }
.landing-quick-card:hover > em { color: var(--accent); transform: translate(3px, -50%); }

/* Market-pulse strip — major index ETFs with their last-close 1-day move,
   tucked under the hero sub. Each item is a hairline pill; the move number is
   tinted by tone (green up / red down, inverted for the volatility proxy). */
.landing-pulse {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-2);
  margin-top: var(--s-4);
}
.pulse-item {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  padding: 7px var(--s-3);
  background: color-mix(in srgb, var(--surface) 60%, transparent);
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  box-shadow: var(--elev-0);
  white-space: nowrap;
}
.pulse-name {
  font: 600 var(--fs-xs)/1 var(--font-sans);
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.pulse-sym {
  font: 500 var(--fs-2xs)/1 var(--font-mono);
  color: var(--muted-strong);
  letter-spacing: 0.04em;
  opacity: 0.7;
}
.pulse-move {
  font: 700 var(--fs-sm)/1 var(--font-mono);
  letter-spacing: var(--ls-num);
  color: var(--muted-strong);
  font-variant-numeric: tabular-nums;
}
.pulse-item.is-up { border-color: var(--accent-line); }
.pulse-item.is-up .pulse-move { color: var(--pos); }
.pulse-item.is-dn { border-color: color-mix(in srgb, var(--neg) 35%, var(--border)); }
.pulse-item.is-dn .pulse-move { color: var(--neg); }
.pulse-item.is-flat .pulse-move { color: var(--text); }

.landing-grid {
  max-width: var(--w-content);
  margin: 0 auto var(--s-4);
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--s-4);
}

/* Landing sections — group the cards into Find ideas / Research / Act
   so the tab strip's 13 destinations don't dump on the user as a flat
   list. Each section has a short eyebrow + sub explaining the cluster. */
.landing-section {
  max-width: var(--w-content);
  margin: 0 auto var(--s-5);
  padding: 0;
}
.landing-section-head {
  padding: 0 var(--s-1);
  margin: 0 0 var(--s-3);
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.landing-section-title {
  margin: 0;
  font: 700 var(--fs-md)/1.2 var(--font-sans);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-strong);
}
.landing-section-sub {
  margin: 0;
  font-size: var(--fs-xs);
  color: var(--muted);
  line-height: var(--lh-normal);
}
.landing-section .landing-grid { margin-bottom: 0; }

.landing-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--s-2);
  padding: var(--s-6);
  min-height: 194px;
  text-align: left;
  cursor: pointer;
  appearance: none;
  color: var(--text);
  background: var(--surface);
  background-image: var(--grad-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-4);
  box-shadow: var(--elev-1);
  font: inherit;
  transition: transform .25s var(--ease-out),
              box-shadow .25s var(--ease-out),
              border-color .15s var(--ease-out),
              background .15s var(--ease-out);
  overflow: hidden;
}
/* Hover state — a single hairline at the bottom in the accent color, like
   an underline drawn by hand. No gradient sweep, no glow. */
.landing-card::after {
  content: "";
  position: absolute;
  left: var(--s-6); right: var(--s-6); bottom: var(--s-5);
  height: 1px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .35s var(--ease-out);
  pointer-events: none;
  opacity: 0.7;
}
.landing-card:hover {
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border-strong));
  background: var(--surface);
  box-shadow: var(--elev-2);
}
.landing-card:hover::after { transform: scaleX(1); }
.landing-card:focus-visible {
  outline: none;
  box-shadow: var(--elev-focus);
  border-color: var(--accent);
}
.landing-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-2);
  margin-bottom: var(--s-1);
}
.landing-card-eyebrow {
  font: 700 var(--fs-md)/1.1 var(--font-sans);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-strong);
}
.landing-card-arrow {
  font-size: var(--fs-lg);
  color: var(--muted);
  transform: translateX(0);
  transition: transform .25s var(--ease-out), color .15s var(--ease-out);
}
.landing-card:hover .landing-card-arrow {
  color: var(--accent-strong);
  transform: translateX(4px);
}
.landing-card-stat {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(40px, 4.4vw, 56px);
  letter-spacing: -0.02em;
  line-height: 1;
  color: var(--text-strong);
  font-variant-numeric: tabular-nums;
}
.landing-card-sub {
  font-size: var(--fs-xs);
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.10em;
  font-weight: 500;
  margin-top: 2px;
}
.landing-card-desc {
  margin: auto 0 0;
  color: var(--text);
  font-size: var(--fs-sm);
  line-height: var(--lh-snug);
  padding-top: var(--s-2);
  border-top: 1px solid var(--hairline);
}

/* Hot variant — used for Unusual flow when there's active flagging. The
   accent shows up as a small pulsing dot in the corner rather than a
   permanent border tint, so the badge means "live activity" instead of
   competing with the user's other cards. */
/* "Hot" badge — a quiet static disc, no pulsing. The hover underline
   already signals activity; the dot just confirms there's something fresh
   without behaving like a status LED. */
.landing-card-hot {
  position: relative;
}
.landing-card-hot > .landing-card-head::after {
  content: "";
  display: inline-block;
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--accent);
  margin-left: 8px;
  vertical-align: 1px;
}

.landing-foot {
  max-width: var(--w-content);
  margin: 0 auto var(--s-5);
  padding: 0 var(--s-2);
  text-align: center;
  color: var(--muted);
  font-size: var(--fs-xs);
  letter-spacing: 0.02em;
}
.landing-foot kbd {
  display: inline-block;
  padding: 1px 6px;
  margin: 0 2px;
  border: 1px solid var(--border);
  border-radius: var(--r-1);
  background: var(--surface-2);
  color: var(--text);
  font: 600 11px/1 var(--font-mono);
}

@media (max-width: 640px) {
  .landing-hero-main { grid-template-columns: minmax(0, 1fr); align-items: stretch; gap: var(--s-4); }
  .landing-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--s-3); }
  .landing-hero { padding: var(--s-5) var(--s-4); }
  .landing-hero-title { font-size: var(--fs-2xl); }
  .landing-card { min-height: 0; padding: var(--s-4); }
  .landing-card-stat { font-size: var(--fs-3xl); }
}

@media (prefers-reduced-motion: no-preference) {
  /* Stagger the landing cards in on first paint of the home pane so the
     hub feels considered, not slammed in. */
  .landing-card { animation: stonks-fade-up .42s var(--ease-out) both; }
  .landing-grid .landing-card:nth-child(1) { animation-delay: 0ms; }
  .landing-grid .landing-card:nth-child(2) { animation-delay: 60ms; }
  .landing-grid .landing-card:nth-child(3) { animation-delay: 120ms; }
  .landing-grid .landing-card:nth-child(4) { animation-delay: 180ms; }
  .landing-grid .landing-card:nth-child(5) { animation-delay: 240ms; }
  .landing-grid .landing-card:nth-child(6) { animation-delay: 300ms; }
}

/* === Cards ===
   Flat surface with a precise 1px hairline. Elevation by border, not shadow
   — institutional UIs read cleaner this way. */
.card {
  position: relative;
  background: var(--surface);
  background-image: var(--grad-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-4);
  padding: var(--s-5) var(--s-6);
  margin-bottom: var(--s-4);
  box-shadow: var(--elev-1);
  transition: box-shadow .25s var(--ease-out),
              transform .25s var(--ease-out),
              border-color .15s var(--ease-out);
}
.card.is-hoverable { cursor: default; }
.card-header {
  display: flex; align-items: center; gap: var(--s-3);
  padding-bottom: var(--s-3);
  margin-bottom: var(--s-4);
  border-bottom: 1px solid var(--hairline);
}
.card-title {
  margin: 0;
  font-family: var(--font-serif);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-transform: none;
  color: var(--text-strong);
  display: inline-flex; align-items: baseline; gap: 12px;
  line-height: 1.15;
}
/* A typographic mark before the title — replaces the glowing accent pill.
   Reads as a printed publication's section dingbat instead of a status LED. */
.card-title::before {
  content: '§';
  font-family: var(--font-serif);
  font-style: italic;
  font-weight: 500;
  font-size: 0.85em;
  color: var(--accent);
  opacity: 0.85;
  line-height: 1;
}
.card-eyebrow {
  font-size: var(--fs-xs); color: var(--muted);
  text-transform: none; letter-spacing: 0; font-weight: 500;
  font-family: var(--font-sans);
  font-feature-settings: "tnum" 1;
  margin-left: auto;
}
.card-eyebrow .mono, .card-eyebrow time {
  font-family: var(--font-mono); font-feature-settings: "tnum" 1;
}
/* Small pill link in a card header that hops to a sibling tab (e.g.
   Calendar → Index calendar). Sits between the title and the eyebrow. */
.card-jump {
  appearance: none; border: 1px solid var(--border); background: var(--surface-2);
  color: var(--muted-strong); font: 600 11px/1 var(--font-sans);
  padding: 5px 10px; border-radius: var(--r-pill); cursor: pointer;
  white-space: nowrap; transition: color .12s, border-color .12s;
}
.card-jump:hover, .card-jump:focus-visible { color: var(--accent-strong); border-color: var(--accent); }
.hint {
  margin: 0 0 var(--s-3);
  color: var(--muted);
  font-size: var(--fs-sm);
  line-height: 1.55;
  /* Hairline left accent — gives the descriptive intro paragraph
     visual weight without competing with the card title above. */
  border-left: 2px solid color-mix(in srgb, var(--accent) 35%, var(--hairline));
  padding-left: var(--s-2);
}
.hint em {
  color: var(--text);
  font-style: normal;
  font-weight: 600;
}
.hint code {
  font-family: var(--font-mono);
  font-size: 13px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-1);
  padding: 1px 6px;
}

/* Collapsible explainer (infoNote() in html.mjs) — the long per-tab "how this
   works" intros are folded behind this disclosure, defaulted CLOSED so each tab
   is quick to scan (mobile especially). No information is removed — clicking the
   summary reveals the full methodology. Mirrors the .picks-howto / .bonds-primer
   disclosure look so the whole site reads consistently. */
.info-note {
  margin: 0 0 var(--s-3);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface);
  font-size: var(--fs-sm);
  color: var(--text);
}
.info-note > summary {
  cursor: pointer;
  padding: 9px 12px;
  font: 600 13px/1.35 var(--font-sans);
  color: var(--muted-strong);
  list-style: none;
  user-select: none;
  border-radius: var(--r-2);
  display: flex;
  align-items: center;
  gap: var(--s-2);
  transition: color .12s var(--ease-out), background .12s var(--ease-out);
}
.info-note > summary::-webkit-details-marker { display: none; }
.info-note > summary::before {
  content: "ⓘ";
  flex: none;
  color: var(--accent);
  font-size: 14px;
}
.info-note > summary::after {
  content: "▸";
  margin-left: auto;
  flex: none;
  color: var(--muted);
  font-size: 11px;
  transition: transform .15s var(--ease-out);
}
.info-note[open] > summary::after { transform: rotate(90deg); }
.info-note > summary:hover {
  color: var(--text-strong);
  background: color-mix(in srgb, var(--accent) 5%, var(--surface));
}
.info-note[open] > summary {
  color: var(--text-strong);
  border-bottom: 1px solid var(--border);
  border-radius: var(--r-2) var(--r-2) 0 0;
}
.info-note-body {
  padding: 10px 14px 12px;
  line-height: 1.55;
  color: var(--text);
}
.info-note-body p { margin: 0 0 var(--s-2); }
.info-note-body p:last-child { margin-bottom: 0; }
.info-note-body em { color: var(--text); font-style: normal; font-weight: 600; }
.info-note-body b, .info-note-body strong { color: var(--text-strong); font-weight: 600; }
.info-note-body a { color: var(--accent); }
.info-note-body code {
  font-family: var(--font-mono);
  font-size: 13px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-1);
  padding: 1px 6px;
}

/* === Narratives === */
/* Market pulse — cross-sector summary above the sector tabs. Aggregates every
   real (non-watchlist) narrative into one at-a-glance read: strength-weighted
   bull/bear tilt, headline counts, and the strongest stories market-wide as
   click-to-jump chips. The "front page" of the narratives section. */
.narr-pulse {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
  gap: var(--s-3) var(--s-4);
  margin: var(--s-3) 0 var(--s-2);
  padding: var(--s-4);
  background: linear-gradient(180deg, color-mix(in srgb, var(--surface-2) 80%, transparent), var(--surface));
  border: 1px solid var(--border);
  border-radius: var(--r-4);
}
.narr-pulse[hidden] { display: none; }
.narr-decision {
  --flow-decision-tone: var(--text-strong);
  grid-column: 1 / -1;
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--border));
  border-radius: var(--r-3);
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 7%, var(--surface-2)), var(--surface));
}
.narr-decision.is-reference {
  border-color: color-mix(in srgb, var(--warn) 38%, var(--border));
  background: linear-gradient(135deg, color-mix(in srgb, var(--warn) 7%, var(--surface-2)), var(--surface));
}
.narr-decision-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--s-4);
}
.narr-decision-kicker {
  display: block;
  margin-bottom: 5px;
  color: var(--accent-strong);
  font: 800 9px/1 var(--font-mono);
  letter-spacing: .09em;
  text-transform: uppercase;
}
.narr-decision h3,
.narr-empty-decision h3 {
  margin: 0;
  color: var(--text-strong);
  font-size: var(--fs-lg);
  line-height: var(--lh-tight);
}
.narr-decision-status {
  flex: none;
  padding: 5px 8px;
  border: 1px solid color-mix(in srgb, var(--pos) 34%, var(--border));
  border-radius: 999px;
  background: var(--surface);
  color: var(--pos);
  font: 700 9px/1 var(--font-mono);
  letter-spacing: .035em;
  white-space: nowrap;
}
.narr-decision.is-reference .narr-decision-status {
  border-color: color-mix(in srgb, var(--warn) 42%, var(--border));
  color: var(--warn);
}
.narr-decision-read {
  margin: 8px 0 0;
  max-width: 84ch;
  color: var(--muted-strong);
  font-size: var(--fs-sm);
  line-height: var(--lh-relaxed);
}
.narr-decision-rules {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 11px;
}
.narr-decision-rules > div {
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-2);
  background: color-mix(in srgb, var(--surface) 80%, transparent);
}
.narr-decision-rules span {
  display: block;
  margin-bottom: 4px;
  color: var(--muted);
  font: 800 8.5px/1 var(--font-mono);
  letter-spacing: .07em;
  text-transform: uppercase;
}
.narr-decision-rules b {
  display: block;
  color: var(--text);
  font-size: var(--fs-xs);
  line-height: var(--lh-snug);
}
.narr-decision-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 11px;
}
@media (max-width: 720px) {
  .narr-pulse { grid-template-columns: 1fr; }
  .narr-decision-head { display: block; }
  .narr-decision-status { display: inline-flex; margin-top: 9px; white-space: normal; }
  .narr-decision-rules { grid-template-columns: 1fr; }
  .narr-decision-actions .flow-decision-action { flex: 1 1 145px; justify-content: center; }
}
@media (max-width: 440px) {
  .narr-decision { padding: 12px; }
  .narr-decision-actions .flow-decision-action { flex-basis: 100%; }
}
.narr-pulse-tilt { display: flex; flex-direction: column; gap: 6px; justify-content: center; }
.narr-pulse-head { display: flex; align-items: baseline; justify-content: space-between; gap: var(--s-2); }
.narr-pulse-eyebrow {
  font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.09em;
  color: var(--muted);
}
.narr-pulse-verdict {
  font-family: var(--font-serif);
  font-size: var(--fs-md); font-weight: 700; letter-spacing: -0.01em;
}
.narr-pulse-verdict.is-bull { color: var(--pos); }
.narr-pulse-verdict.is-bear { color: var(--neg); }
.narr-pulse-verdict.is-mixed { color: var(--warn); }
.narr-pulse-bar {
  position: relative; display: flex; height: 9px;
  border-radius: var(--r-pill); overflow: hidden; background: var(--surface-3);
}
.narr-pulse-bar-bull { background: linear-gradient(90deg, color-mix(in srgb, var(--pos) 60%, transparent), var(--pos)); }
.narr-pulse-bar-bear { background: linear-gradient(90deg, var(--neg), color-mix(in srgb, var(--neg) 60%, transparent)); }
.narr-pulse-bar-mid {
  position: absolute; left: 50%; top: -1px; bottom: -1px; width: 2px;
  transform: translateX(-50%); background: var(--surface); opacity: 0.7;
}
.narr-pulse-legend {
  display: flex; justify-content: space-between; gap: var(--s-2);
  font-family: var(--font-mono); font-size: 11.5px; font-variant-numeric: tabular-nums;
}
.narr-pulse-legend .is-bull { color: var(--pos); }
.narr-pulse-legend .is-bear { color: var(--neg); }
.narr-pulse-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--s-2); align-content: center; }
.narr-pulse-stat {
  appearance: none;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
  padding: 8px 4px;
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--r-2);
  color: inherit; font: inherit; text-align: center;
}
.narr-pulse-stat:disabled { opacity: .58; }
.narr-pulse-stat.is-actionable { cursor: pointer; transition: transform .12s var(--ease-out), border-color .12s var(--ease-out), background .12s var(--ease-out); }
.narr-pulse-stat.is-actionable:hover { transform: translateY(-1px); border-color: var(--border-strong); background: var(--surface-2); }
.narr-pulse-stat.is-actionable:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.narr-pulse-stat-num {
  font-family: var(--font-mono); font-size: var(--fs-lg); font-weight: 700;
  font-variant-numeric: tabular-nums; color: var(--text-strong); line-height: 1;
}
.narr-pulse-stat-num.is-warn { color: var(--warn); }
.narr-pulse-stat-num.is-accent { color: var(--accent-strong); }
.narr-pulse-stat-num.is-pos { color: var(--pos); }
.narr-pulse-stat-num.is-neg { color: var(--neg); }
.narr-pulse-stat-label {
  font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em;
  color: var(--muted);
}
.narr-pulse-leaders {
  grid-column: 1 / -1;
  display: flex; flex-direction: column; gap: 6px;
  padding-top: var(--s-3); margin-top: 2px;
  border-top: 1px dashed var(--hairline);
}
.narr-pulse-leaders-label {
  font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.07em;
  color: var(--muted);
}
.narr-pulse-leader-list { display: flex; flex-wrap: wrap; gap: var(--s-2); }
.narr-pulse-leader {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 7px 11px 7px 9px;
  background: var(--surface); border: 1px solid var(--border);
  border-left-width: 3px; border-radius: var(--r-2);
  cursor: pointer; font: inherit; text-align: left;
  transition: border-color .12s var(--ease-out), background .12s var(--ease-out), transform .12s var(--ease-out);
}
.narr-pulse-leader.bullish { border-left-color: var(--pos); }
.narr-pulse-leader.bearish { border-left-color: var(--neg); }
.narr-pulse-leader:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border-strong));
  border-left-color: color-mix(in srgb, var(--accent) 35%, var(--border-strong));
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
}
.narr-pulse-leader.bullish:hover { border-left-color: var(--pos); }
.narr-pulse-leader.bearish:hover { border-left-color: var(--neg); }
.narr-pulse-leader:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.narr-pulse-leader-rank { font-family: var(--font-mono); font-size: 11px; font-weight: 700; color: var(--muted); }
.narr-pulse-leader-name {
  font-family: var(--font-serif);
  font-size: 13px; font-weight: 600; letter-spacing: -0.01em; color: var(--text-strong);
  white-space: nowrap; max-width: 240px; overflow: hidden; text-overflow: ellipsis;
}
.narr-pulse-leader-meta { display: inline-flex; align-items: center; gap: 6px; }
.narr-pulse-leader-sector { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.04em; }
.narr-pulse-leader-str { font-family: var(--font-mono); font-size: 12px; font-weight: 700; font-variant-numeric: tabular-nums; }
.narr-pulse-leader-str.bullish { color: var(--pos); }
.narr-pulse-leader-str.bearish { color: var(--neg); }

/* Sector tab strip across the top of the narratives card. Wraps onto a
   second row on desktop (no scrollbar); the phone media query switches it
   back to a one-row flick strip with the scrollbar hidden. */
.narr-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin: var(--s-2) 0 var(--s-3);
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border);
}
.narr-tab {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  font-size: var(--fs-sm);
  font-weight: 600;
  color: var(--muted);
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--r-pill);
  cursor: pointer;
  transition: color .12s ease, background .12s ease, border-color .12s ease;
  white-space: nowrap;
}
.narr-tab:hover { color: var(--text); background: var(--surface-2); }
.narr-tab.is-active {
  color: var(--accent-strong);
  background: var(--accent-soft);
  border-color: color-mix(in srgb, var(--accent) 30%, transparent);
}
.narr-tab-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--muted);
  background: var(--surface-3);
  border-radius: var(--r-pill);
}
.narr-tab.is-active .narr-tab-count {
  color: var(--accent-strong);
  background: color-mix(in srgb, var(--accent) 20%, transparent);
}
.narr-panel { display: flex; flex-direction: column; gap: var(--s-3); }
/* Sector-overview banner — the top-down story for the active sector. Sits
   above the sub-industry blocks. Colour-keyed by stance so the user reads
   "bullish / bearish / mixed" at a glance, with the watch-for panel nested
   below the thesis. */
.narr-sector-overview {
  position: relative;
  padding: var(--s-3) var(--s-3) var(--s-3);
  border: 1px solid var(--border);
  border-left: 4px solid var(--border-strong);
  border-radius: var(--r-3);
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--surface-2) 92%, transparent) 0%,
    var(--surface) 100%);
  display: flex;
  flex-direction: column;
  gap: var(--s-2);
}
.narr-sector-overview[data-stance="bullish"] {
  border-left-color: var(--pos);
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--pos-soft) 55%, var(--surface-2)) 0%,
    var(--surface) 100%);
}
.narr-sector-overview[data-stance="bearish"] {
  border-left-color: var(--neg);
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--neg-soft) 55%, var(--surface-2)) 0%,
    var(--surface) 100%);
}
.narr-sector-overview[data-stance="mixed"] {
  border-left-color: var(--warn);
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--warn-soft) 45%, var(--surface-2)) 0%,
    var(--surface) 100%);
}
.narr-sector-overview.is-empty { border-left-color: var(--border-strong); }
.narr-sector-overview-head {
  display: flex; align-items: center; flex-wrap: wrap;
  gap: var(--s-2);
}
.narr-sector-overview-eyebrow {
  font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--muted);
}
.narr-sector-overview-title {
  margin: 0;
  font-family: var(--font-serif);
  font-size: var(--fs-xl);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-strong);
}
.narr-sector-overview-stance {
  display: inline-flex; align-items: center;
  height: 22px; padding: 0 10px;
  font-size: 12px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.06em;
  border-radius: var(--r-pill);
}
.narr-sector-overview-stance.bullish {
  color: var(--pos);
  background: var(--pos-soft);
  border: 1px solid color-mix(in srgb, var(--pos) 40%, transparent);
}
.narr-sector-overview-stance.bearish {
  color: var(--neg);
  background: var(--neg-soft);
  border: 1px solid color-mix(in srgb, var(--neg) 40%, transparent);
}
.narr-sector-overview-stance.mixed {
  color: var(--warn);
  background: var(--warn-soft);
  border: 1px solid color-mix(in srgb, var(--warn) 40%, transparent);
}
.narr-sector-overview-thesis {
  margin: 0;
  font-size: var(--fs-md);
  line-height: 1.65;
  color: var(--text);
  max-width: 78ch;
}
.narr-sector-overview-thesis.muted { color: var(--muted); font-style: italic; }
.narr-posture {
  display: grid;
  grid-template-columns: 104px minmax(0, 1fr);
  gap: var(--s-3);
  align-items: start;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: var(--r-2);
  background: color-mix(in srgb, var(--surface-2) 88%, transparent);
}
.narr-posture-label {
  padding-top: 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .07em;
  line-height: 1.35;
  text-transform: uppercase;
}
.narr-posture b { display: block; color: var(--text-strong); font-size: 13px; line-height: 1.35; }
.narr-posture p { margin: 3px 0 0; color: var(--text); font-size: 12.5px; line-height: 1.45; }
.narr-posture small { display: block; margin-top: 5px; color: var(--muted); font-size: 11.5px; line-height: 1.4; }
.narr-posture small strong { color: var(--text); }
.narr-posture-ready { border-left-color: var(--pos); background: color-mix(in srgb, var(--pos-soft) 52%, var(--surface-2)); }
.narr-posture-watch { border-left-color: var(--accent); }
.narr-posture-caution,
.narr-posture-late { border-left-color: var(--warn); background: color-mix(in srgb, var(--warn-soft) 42%, var(--surface-2)); }
.narr-posture-pass { border-left-color: var(--neg); background: color-mix(in srgb, var(--neg-soft) 48%, var(--surface-2)); }
.narr-research,
.narr-sector-detail {
  margin-top: var(--s-2);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: color-mix(in srgb, var(--surface-2) 72%, transparent);
  overflow: clip;
}
.narr-research > summary,
.narr-sector-detail > summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  min-height: 42px;
  padding: 8px 10px;
  cursor: pointer;
  list-style: none;
}
.narr-research > summary::-webkit-details-marker,
.narr-sector-detail > summary::-webkit-details-marker { display: none; }
.narr-research > summary > span,
.narr-sector-detail > summary > span { display: flex; min-width: 0; flex-direction: column; gap: 2px; }
.narr-research > summary b,
.narr-sector-detail > summary b { color: var(--text-strong); font-size: 12px; line-height: 1.3; }
.narr-research > summary small,
.narr-sector-detail > summary small { color: var(--muted); font-size: 10.5px; line-height: 1.35; }
.narr-research > summary em,
.narr-sector-detail > summary em {
  flex: 0 0 auto;
  color: var(--accent-strong);
  font-size: 0;
  font-style: normal;
  font-weight: 700;
}
.narr-research > summary em::after,
.narr-sector-detail > summary em::after { content: 'Open'; font-size: 11px; }
.narr-research[open] > summary em::after,
.narr-sector-detail[open] > summary em::after { content: 'Close'; }
.narr-research[open] > summary,
.narr-sector-detail[open] > summary { background: var(--surface-2); }
.narr-research-body,
.narr-sector-detail-body { padding: 10px; border-top: 1px solid var(--border); }
.narr-industries { display: flex; flex-direction: column; gap: var(--s-6); }
.narr-industry {
  display: flex;
  flex-direction: column;
  gap: var(--s-3);
}
.narr-industry-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--s-2);
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border);
}
.narr-industry-name {
  margin: 0;
  font-family: var(--font-serif);
  font-size: var(--fs-lg);
  font-weight: 700;
  letter-spacing: -0.015em;
  color: var(--text-strong);
}
.narr-industry-count {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
  color: var(--muted);
}
.narr-industry-list {
  display: flex;
  flex-direction: column;
  gap: var(--s-4);
}
.narr-empties {
  margin-top: var(--s-2);
  padding: var(--s-2) var(--s-3);
  background: var(--surface-2);
  border: 1px dashed var(--border);
  border-radius: var(--r-2);
  color: var(--muted);
  font-size: var(--fs-sm);
}
.narr-empties > summary {
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: center;
  gap: var(--s-2);
}
.narr-empties > summary::-webkit-details-marker { display: none; }
.narr-empties-label {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 700;
  color: var(--muted);
}
.narr-empties-count {
  margin-left: auto;
  font-variant-numeric: tabular-nums;
  font-size: 12px;
}
.narr-empties-list {
  margin: var(--s-2) 0 0;
  padding: 0;
  list-style: none;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 4px 12px;
  color: var(--text);
  font-size: 13px;
}
.narr-empties-list li::before {
  content: "·";
  margin-right: 6px;
  color: var(--muted);
}
/* Collapsible watchlist strip — one row per industry, with the tickers
   as compact chips. Replaces a stack of identical "no single narrative
   driving X — these names are in scope" cards. */
.narr-watchlists {
  margin-top: var(--s-2);
  padding: var(--s-2) var(--s-3);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  color: var(--text);
  font-size: var(--fs-sm);
}
.narr-watchlists > summary {
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: center;
  gap: var(--s-2);
}
.narr-watchlists > summary::-webkit-details-marker { display: none; }
.narr-watchlists-label {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 700;
  color: var(--muted);
}
.narr-watchlists-count {
  margin-left: auto;
  font-variant-numeric: tabular-nums;
  font-size: 12px;
  color: var(--muted);
}
.narr-watchlists-body {
  margin-top: var(--s-3);
  display: flex;
  flex-direction: column;
  gap: var(--s-3);
}
.narr-watchlist-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--s-2);
  padding-bottom: var(--s-2);
  border-bottom: 1px dashed var(--hairline);
}
.narr-watchlist-row:last-child { border-bottom: 0; padding-bottom: 0; }
.narr-watchlist-ind {
  font-weight: 600;
  font-size: 13px;
  color: var(--text);
  min-width: 160px;
}
.narr-watchlist-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.narr-list { display: flex; flex-direction: column; gap: var(--s-3); }
.narr-list:empty { display: none; }
.narr {
  position: relative;
  padding: var(--s-4) var(--s-5);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-3);
  transition: border-color .15s var(--ease-out), background .15s var(--ease-out), transform .15s var(--ease-out);
}
.narr:hover {
  border-color: color-mix(in srgb, var(--accent) 22%, var(--border-strong));
  background: color-mix(in srgb, var(--accent) 2%, var(--surface));
  transform: translateY(-1px);
}
.narr:focus-visible,
.narr.is-review-target {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 20%, transparent), var(--elev-2);
}
.narr-accent {
  position: absolute; left: 12px; top: 14px; bottom: 14px;
  width: 2px; border-radius: 1px;
  background: var(--pos);
  transition: box-shadow .15s var(--ease-out);
}
.narr:hover .narr-accent {
  box-shadow: 0 0 8px color-mix(in srgb, var(--pos) 50%, transparent);
}
.narr[data-sent="bearish"]:hover .narr-accent {
  box-shadow: 0 0 8px color-mix(in srgb, var(--neg) 50%, transparent);
}
.narr[data-sent="bearish"] .narr-accent { background: var(--neg); }
.narr-head {
  display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-2);
  margin-bottom: 0;
}
.narr-name {
  margin: 0;
  font-family: var(--font-serif);
  font-size: var(--fs-xl);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.02em;
  color: var(--text-strong);
}
/* Metadata strip under the headline — status / timeframe / confidence / tenure.
   Muted + secondary so the headline and thesis carry the read (editorial feel). */
.narr-meta {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px;
  margin: var(--s-2) 0 var(--s-1);
}
.narr-tag {
  font-size: 12px; font-weight: 600;
  letter-spacing: 0.01em;
  padding: 2px 8px;
  border-radius: var(--r-pill);
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--muted);
}
.narr-tag.sent.bullish { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 35%, transparent); background: var(--pos-soft); }
.narr-tag.sent.bearish { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 35%, transparent); background: var(--neg-soft); }
.narr-life {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 12px; font-weight: 500;
  padding: 2px 8px 2px 6px;
  border-radius: var(--r-pill);
  background: var(--surface-2);
  border: 1px solid var(--border);
  color: var(--muted);
}
.narr-life-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--accent);
}
.narr-thesis {
  margin: var(--s-2) 0;
  color: var(--text);
  font-size: var(--fs-md);
  line-height: 1.7;
  max-width: 72ch;
}
/* Supporting analytics — strength / lifecycle / hype — grouped below the prose
   behind a hairline so the story reads first and the gauges read as "the data
   behind it" rather than competing with the headline. */
.narr-analytics {
  display: grid;
  grid-template-columns: minmax(170px, 1fr) auto auto;
  align-items: center;
  gap: 8px 12px;
  margin-top: var(--s-3);
  padding-top: var(--s-2);
  border-top: 1px solid var(--hairline);
}
.narr-analytics .narr-strength { margin-top: 0; }
.narr-analytics .narr-lifecycle { margin-top: 0; }
.narr-hype-badge {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 3px 8px;
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  color: var(--text);
  background: var(--surface-2);
  font-size: 10.5px;
  font-weight: 700;
  white-space: nowrap;
}
.narr-hype-badge.is-fundamentals { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 35%, transparent); background: var(--pos-soft); }
.narr-hype-badge.is-balanced { color: var(--accent-strong); border-color: color-mix(in srgb, var(--accent) 35%, transparent); background: var(--accent-soft); }
.narr-hype-badge.is-hype { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 35%, transparent); background: var(--neg-soft); }
.narr-side-row {
  display: flex; flex-wrap: wrap; align-items: center;
  gap: 6px;
  margin: 4px 0;
}
.narr-side-label {
  font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.06em;
  margin-right: 4px;
}
.narr-side-row.long  .narr-side-label { color: var(--pos); }
.narr-side-row.short .narr-side-label { color: var(--neg); }
.narr-chip {
  display: inline-flex; align-items: center;
  height: 22px;
  padding: 0 8px;
  font-size: 12px; font-weight: 600;
  font-variant-numeric: tabular-nums;
  border-radius: var(--r-1);
  background: var(--surface-2);
  border: 1px solid var(--border);
  color: var(--text);
}
.narr-chip.long  { border-color: color-mix(in srgb, var(--pos) 35%, transparent); }
.narr-chip.short { border-color: color-mix(in srgb, var(--neg) 35%, transparent); }
/* Clickable ticker chips inside narrative cards — they're rendered as
   buttons whenever the symbol is in our curated list so users can jump
   straight to the Grade tab from the thesis. */
button.narr-chip {
  font: inherit;
  cursor: pointer;
  letter-spacing: inherit;
  transition: background .12s var(--ease-out), border-color .12s var(--ease-out), transform .12s var(--ease-out);
}
button.narr-chip:hover {
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-2));
  border-color: color-mix(in srgb, var(--accent) 50%, transparent);
  transform: translateY(-1px);
}
button.narr-chip.long:hover  { border-color: color-mix(in srgb, var(--pos) 60%, transparent); }
button.narr-chip.short:hover { border-color: color-mix(in srgb, var(--neg) 60%, transparent); }
button.narr-chip:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.narr-ended { margin-top: var(--s-4); }
.narr-ended:empty { display: none; }
.narr-ended-head {
  font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--muted); font-weight: 700;
  margin-bottom: var(--s-2);
}
.narr-ended-strip {
  display: flex; gap: var(--s-2);
  overflow-x: auto;
  padding-bottom: var(--s-1);
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
}
.narr-ended-card {
  flex: 0 0 220px;
  scroll-snap-align: start;
  padding: var(--s-3);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  transition: border-color .15s var(--ease-out), background .15s var(--ease-out);
}
.narr-ended-card:hover {
  border-color: var(--border-strong);
  background: var(--surface-3);
}
.narr-ended-name { font-size: var(--fs-sm); font-weight: 600; color: var(--text); margin-bottom: 2px; }
.narr-ended-meta { font-size: 12px; color: var(--muted); }
.narr-empty { color: var(--muted); font-size: var(--fs-sm); padding: var(--s-1) 0; }
.narr-empty[hidden] { display: none; }
.narr-empty-decision {
  --flow-decision-tone: var(--text-strong);
  padding: var(--s-5);
  border: 1px dashed color-mix(in srgb, var(--warn) 42%, var(--border));
  border-radius: var(--r-3);
  background: color-mix(in srgb, var(--warn-soft) 28%, var(--surface));
}
.narr-empty-decision p {
  max-width: 72ch;
  margin: 7px 0 0;
  color: var(--muted-strong);
  line-height: var(--lh-relaxed);
}

/* Narrative rank, strength meter, status / timeframe tags, triggers, conflicts, macro digest */
.narr-rank {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 22px; height: 22px;
  padding: 0 6px;
  font-family: var(--font-mono);
  font-size: 12px; font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--muted);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  letter-spacing: -0.02em;
  margin-right: 2px;
}
.narr:first-child .narr-rank {
  color: var(--accent-strong);
  border-color: color-mix(in srgb, var(--accent) 45%, transparent);
  background: var(--accent-soft);
}
.narr-tag.status {
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.narr-tag.status.active   { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 35%, transparent); background: var(--pos-soft); }
.narr-tag.status.building { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 40%, transparent); background: var(--warn-soft); }
.narr-tag.status.fading   { color: var(--muted); border-color: var(--border); background: var(--surface-2); }
.narr-tag.stale {
  color: var(--warn);
  border-color: color-mix(in srgb, var(--warn) 40%, transparent);
  background: var(--warn-soft);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.narr[data-status="fading"]   { opacity: 0.78; }
.narr[data-status="fading"]:hover { opacity: 1; }
.narr.is-stale .narr-thesis { color: var(--muted); }
.narr-tag.tf {
  color: var(--text);
  background: var(--surface-3);
  font-variant-numeric: tabular-nums;
}
.narr-strength {
  display: flex; align-items: center; gap: var(--s-2);
  margin: 2px 0 var(--s-2);
}
.narr-strength-track {
  position: relative;
  flex: 1 1 auto;
  height: 6px;
  background: var(--surface-3);
  border-radius: var(--r-pill);
  overflow: hidden;
}
.narr-strength-fill {
  position: absolute; left: 0; top: 0; bottom: 0;
  border-radius: var(--r-pill);
  background: var(--accent);
  transition: width .2s ease;
}
.narr-strength-fill.hi  {
  background: linear-gradient(90deg, var(--accent), var(--accent-strong));
  box-shadow: 0 0 6px color-mix(in srgb, var(--accent) 45%, transparent);
}
.narr-strength-fill.mid { background: var(--accent); opacity: 0.85; }
.narr-strength-fill.lo  {
  background: color-mix(in srgb, var(--muted) 65%, var(--border-strong));
  opacity: 0.9;
}
.narr-strength-num {
  font-family: var(--font-mono);
  font-size: 12px; font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--muted);
  min-width: 28px; text-align: right;
}
/* Strength momentum — change vs the most recent prior narrative snapshot.
   Lazy-fetched from data/trends-history.json once the Narratives tab is
   open; shows ▲+5 / ▼-3 next to the strength number. Color-coded by sign. */
.narr-delta {
  font-family: var(--font-mono);
  font-size: 11px; font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
  padding: 1px 5px;
  border-radius: var(--r-pill);
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--muted);
  line-height: 1.4;
  min-width: 36px; text-align: center;
}
.narr-delta.up {
  color: var(--pos);
  border-color: color-mix(in srgb, var(--pos) 35%, transparent);
  background: var(--pos-soft);
}
.narr-delta.down {
  color: var(--neg);
  border-color: color-mix(in srgb, var(--neg) 35%, transparent);
  background: var(--neg-soft);
}
.narr-delta.flat { opacity: 0.6; }
/* Red-flag / watch-for panel — the catalysts that would FLIP this narrative.
   Used by both the per-narrative card and the sector overview banner. Styled
   as a "danger watchlist" with a warm accent border so it visually pops vs.
   the thesis paragraph above it. */
.narr-watchfor {
  margin-top: var(--s-2);
  padding: var(--s-2) var(--s-2) calc(var(--s-2) - 2px);
  border: 1px solid color-mix(in srgb, var(--warn) 40%, var(--border));
  border-left-width: 3px;
  border-radius: var(--r-2);
  background: color-mix(in srgb, var(--warn-soft) 55%, transparent);
}
.narr[data-status="building"] .narr-watchfor {
  border-color: color-mix(in srgb, var(--warn) 55%, var(--border));
  background: color-mix(in srgb, var(--warn-soft) 70%, transparent);
}
.narr-watchfor-head {
  display: inline-flex; align-items: center; gap: 6px;
  margin-bottom: 4px;
}
.narr-watchfor-icon {
  font-size: 13px;
  color: var(--warn);
  line-height: 1;
}
.narr-watchfor-label {
  font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--warn);
}
.narr-watchfor-list {
  margin: 0; padding: 0 0 0 16px;
  font-size: var(--fs-sm); color: var(--text);
  line-height: 1.5;
}
.narr-watchfor-list li + li { margin-top: 3px; }
.narr-watchfor-list li::marker { color: var(--warn); }
.narr-conflicts {
  display: flex; flex-wrap: wrap; align-items: center;
  gap: 6px;
  margin-top: var(--s-2);
}
.narr-conflicts-label {
  font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--neg);
  margin-right: 2px;
}
.narr-conflict-chip {
  display: inline-flex; align-items: center;
  height: 20px;
  padding: 0 8px;
  font-size: 12px; font-weight: 600;
  color: var(--neg);
  background: var(--neg-soft);
  border: 1px solid color-mix(in srgb, var(--neg) 35%, transparent);
  border-radius: var(--r-pill);
}

/* Narrative lifecycle stepper — the 6-stage boom→bust arc (catalysts →
   amplification → validation → peak → challenges → collapse). Past stages read
   muted; the current stage is highlighted accent while rising (≤ peak) and
   negative once falling (challenges/collapse) as an exhaustion cue. */
.narr-lifecycle { display: flex; align-items: center; gap: 8px; margin-top: 8px; }
.narr-lifecycle-label,
.narr-hype-label {
  font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  color: var(--muted); flex: 0 0 auto;
}
.narr-lifecycle-steps { display: inline-flex; gap: 3px; flex: 0 0 auto; }
.narr-life-step { width: 16px; height: 5px; border-radius: var(--r-pill); background: var(--surface-3); }
.narr-life-step.is-past { background: color-mix(in srgb, var(--muted) 55%, transparent); }
.narr-lifecycle.is-rising .narr-life-step.is-on {
  background: linear-gradient(90deg, var(--accent), var(--accent-strong));
  box-shadow: 0 0 6px color-mix(in srgb, var(--accent) 45%, transparent);
}
.narr-lifecycle.is-falling .narr-life-step.is-on {
  background: var(--neg);
  box-shadow: 0 0 6px color-mix(in srgb, var(--neg) 45%, transparent);
}
.narr-lifecycle-stage { font-size: 12px; font-weight: 700; color: var(--text); }
.narr-lifecycle.is-falling .narr-lifecycle-stage { color: var(--neg); }

/* Lifecycle outlook — the why-here / what's-next / watch-for read under the
   stepper. Compact key/value rows on a left-railed card; the "Next" stage chip
   is accent-coloured, tinted red when the story is advancing toward collapse
   and green when it is recovering back up the arc. */
.narr-life-outlook {
  margin-top: 6px; display: flex; flex-direction: column; gap: 3px;
  padding: 6px 8px; border-radius: var(--r-1);
  background: var(--surface-2); border-left: 2px solid var(--border-strong);
}
.narr-life-outlook-row { display: grid; grid-template-columns: 62px 1fr; gap: 8px; align-items: baseline; }
.narr-life-outlook-k {
  font-size: 10px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase;
  color: var(--muted);
}
.narr-life-outlook-v { font-size: 12.5px; color: var(--text); line-height: 1.35; }
.narr-life-outlook-next { font-weight: 700; color: var(--accent-strong); }
.narr-life-outlook-next.is-advancing { color: var(--neg); }
.narr-life-outlook-next.is-recovering { color: var(--pos); }

/* Fundamentals → hype gauge. The track is a fixed fundamentals(green) →
   hype(red) gradient; the marker shows where this story sits on it. */
.narr-hype { margin-top: 8px; }
.narr-hype-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 4px; }
.narr-hype-verdict { font-size: 12px; font-weight: 700; color: var(--text); }
.narr-hype.is-fundamentals .narr-hype-verdict { color: var(--pos); }
.narr-hype.is-hype .narr-hype-verdict { color: var(--neg); }
.narr-hype.is-balanced .narr-hype-verdict { color: var(--accent-strong); }
.narr-hype-track {
  position: relative; height: 6px; border-radius: var(--r-pill);
  background: linear-gradient(90deg, var(--pos), var(--accent) 50%, var(--neg));
  opacity: .85;
}
.narr-hype-fill {
  position: absolute; top: -2px; bottom: -2px; width: 3px; transform: translateX(-50%);
  background: var(--text); border-radius: var(--r-pill);
  box-shadow: 0 0 0 2px var(--surface);
}
.narr-hype-why { display: block; margin-top: 4px; font-size: 12px; color: var(--muted); line-height: 1.35; }

/* Bull / Base / Bear scenario block — the optimistic / most-likely / pessimistic
   paths, colour-keyed on the left rail. */
.narr-scenarios { display: flex; flex-direction: column; gap: 4px; margin-top: 8px; }
.narr-scenario {
  display: grid; grid-template-columns: 40px 1fr; gap: 8px; align-items: baseline;
  padding: 4px 8px; border-radius: var(--r-1);
  background: var(--surface-2); border-left: 2px solid var(--border-strong);
}
.narr-scenario-tag { font-size: 10px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }
.narr-scenario-text { font-size: 12.5px; color: var(--text); line-height: 1.35; }
.narr-scenario.bull { border-left-color: var(--pos); }
.narr-scenario.bull .narr-scenario-tag { color: var(--pos); }
.narr-scenario.base { border-left-color: var(--accent); }
.narr-scenario.base .narr-scenario-tag { color: var(--accent-strong); }
.narr-scenario.bear { border-left-color: var(--neg); }
.narr-scenario.bear .narr-scenario-tag { color: var(--neg); }

/* Sector industry-group grade breakdown — makes the two-level rollup visible
   (sector grade = the average of these). Magnitude bar coloured by stance. */
.narr-iggrades { margin-top: var(--s-2); }
.narr-iggrades-summary {
  font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  color: var(--muted); cursor: pointer; list-style: none;
}
.narr-iggrades-summary::-webkit-details-marker { display: none; }
.narr-iggrades-summary::before { content: '▸ '; }
.narr-iggrades[open] .narr-iggrades-summary::before { content: '▾ '; }
.narr-iggrades-hint { font-weight: 500; text-transform: none; letter-spacing: 0; opacity: .8; }
.narr-iggrades-list { list-style: none; margin: 6px 0 0; padding: 0; }
.narr-iggrade { display: grid; grid-template-columns: minmax(0,1fr) 80px 34px; gap: 8px; align-items: center; padding: 2px 0; }
.narr-iggrade-name { font-size: 12px; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.narr-iggrade-count {
  font-size: 10px; font-weight: 700; color: var(--muted);
  background: var(--surface-3); border-radius: var(--r-pill); padding: 0 5px; margin-left: 4px;
}
.narr-iggrade-bar { position: relative; height: 5px; border-radius: var(--r-pill); background: var(--surface-3); overflow: hidden; }
.narr-iggrade-fill { position: absolute; left: 0; top: 0; bottom: 0; border-radius: var(--r-pill); }
.narr-iggrade[data-stance="bullish"] .narr-iggrade-fill { background: var(--pos); }
.narr-iggrade[data-stance="bearish"] .narr-iggrade-fill { background: var(--neg); }
.narr-iggrade[data-stance="mixed"]   .narr-iggrade-fill { background: var(--muted); }
.narr-iggrade-score {
  font-family: var(--font-mono); font-size: 12px; font-weight: 700;
  font-variant-numeric: tabular-nums; text-align: right; color: var(--muted);
}
.narr-iggrade[data-stance="bullish"] .narr-iggrade-score { color: var(--pos); }
.narr-iggrade[data-stance="bearish"] .narr-iggrade-score { color: var(--neg); }

/* Per-narrative source citations — appears under watchFor/conflicts. Each
   entry is a verified headline that informed the thesis. Hairline divider
   above to separate from the thesis body; tracked-uppercase eyebrow label;
   mono publisher tag + regular-weight title + UTC date so traders can
   recognize the wire at a glance. */
.narr-sources {
  margin-top: var(--s-3);
  padding-top: var(--s-2);
  border-top: 1px dashed var(--hairline);
}
.narr-sources-label {
  display: inline-block;
  margin-bottom: 6px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  color: var(--muted);
  font-family: var(--font-mono);
}
.narr-sources-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.narr-source {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-size: 12px;
  line-height: 1.4;
}
.narr-source-pub {
  flex: 0 0 auto;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-strong);
  padding: 2px 6px;
  border: 1px solid var(--border);
  border-radius: var(--r-1);
  background: var(--surface-2);
  white-space: nowrap;
}
.narr-source-title {
  flex: 1 1 auto;
  color: var(--text);
  min-width: 0;
}
.narr-source-date {
  flex: 0 0 auto;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--muted);
  font-feature-settings: "tnum" 1;
}

.narr-macro { margin-top: var(--s-4); }
.narr-macro:empty { display: none; }
.narr-macro-details {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-3);
  padding: var(--s-2) var(--s-3);
}
.narr-macro-details > summary {
  cursor: pointer;
  display: flex; align-items: center; gap: var(--s-2);
  list-style: none;
}
.narr-macro-details > summary::-webkit-details-marker { display: none; }
.narr-macro-details > summary::after {
  content: '+';
  margin-left: auto;
  color: var(--muted);
  font-family: var(--font-mono);
  font-weight: 700;
}
.narr-macro-details[open] > summary::after { content: '−'; }
.narr-macro-head {
  font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--text); font-weight: 700;
}
.narr-macro-meta { font-size: 12px; color: var(--muted); }
.narr-macro-list {
  margin: var(--s-2) 0 0; padding: 0;
  list-style: none;
  display: flex; flex-direction: column; gap: 4px;
  font-size: var(--fs-sm);
}
.narr-macro-list li {
  display: grid;
  grid-template-columns: auto auto 1fr;
  gap: var(--s-2);
  align-items: baseline;
  padding: 4px 0;
  border-top: 1px solid var(--border);
}
.narr-macro-list li:first-child { border-top: none; }
.narr-macro-date {
  font-family: var(--font-mono);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  color: var(--muted);
}
.narr-macro-pub {
  font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.04em;
  color: var(--accent-strong);
  white-space: nowrap;
}
.narr-macro-title { color: var(--text); }
/* Macro headlines link to their source article when the feed gave us a
   permalink. Title links read as body text until hover; a small ↗ marks them. */
a.narr-macro-title {
  text-decoration: none;
  transition: color .12s var(--ease-out);
}
a.narr-macro-title:hover { color: var(--accent-strong); text-decoration: underline; text-underline-offset: 2px; }
a.narr-macro-title:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 2px; }
.narr-macro-ext { margin-left: 4px; font-size: 10px; color: var(--muted); }
a.narr-macro-title:hover .narr-macro-ext { color: var(--accent-strong); }

/* Macro shell — top-3 pill strip + collapsed full list. Replaces the
   purely-collapsed details so the user can see the freshest macro hits
   without clicking. */
.narr-macro-shell {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-3);
  padding: var(--s-2) var(--s-3) var(--s-3);
  display: flex; flex-direction: column; gap: var(--s-2);
}
.narr-macro-bar {
  display: flex; align-items: baseline; gap: var(--s-2);
  flex-wrap: wrap;
}
.narr-macro-pills {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--s-2);
}
@media (max-width: 720px) { .narr-macro-pills { grid-template-columns: 1fr; } }
.narr-macro-pill {
  display: flex; flex-direction: column; gap: 4px;
  padding: 8px 10px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  cursor: default;
  text-decoration: none;
  min-width: 0;
}
.narr-macro-pill-date {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.narr-macro-pill-pub {
  font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.05em;
  color: var(--accent-strong);
}
.narr-macro-pill-title {
  font-size: 13px;
  line-height: 1.35;
  color: var(--text);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  word-break: break-word;
}
/* When the feed gave us a permalink the pill is a real <a> — make it feel
   clickable (lift + accent border on hover) and badge the publisher with ↗. */
.narr-macro-pill.is-link {
  cursor: pointer;
  transition: border-color .12s var(--ease-out), background .12s var(--ease-out), transform .12s var(--ease-out), box-shadow .12s var(--ease-out);
}
.narr-macro-pill.is-link:hover {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border-strong));
  background: color-mix(in srgb, var(--accent) 5%, var(--surface));
  transform: translateY(-1px);
}
.narr-macro-pill.is-link:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.narr-macro-pill-ext { margin-left: 5px; font-size: 10px; color: var(--muted); vertical-align: 1px; }
.narr-macro-pill.is-link:hover .narr-macro-pill-ext { color: var(--accent-strong); }
.narr-macro-shell .narr-macro-details {
  border: 0;
  padding: 0;
  background: transparent;
  border-top: 1px dashed var(--hairline);
  border-radius: 0;
  padding-top: var(--s-2);
}
.narr-macro-shell .narr-macro-details > summary {
  font-size: 12px;
  color: var(--muted);
  font-weight: 600;
  letter-spacing: 0.03em;
}
.narr-macro-shell .narr-macro-details > summary::after {
  content: '+';
}
.narr-macro-shell .narr-macro-details[open] > summary::after { content: '−'; }

/* Confidence — replaces the "Conf · High" text tag with a 3-dot indicator
   that visually mirrors signal-strength rows used elsewhere in the app. */
.narr-conf {
  display: inline-flex; align-items: center; gap: 5px;
  height: 22px;
  padding: 0 8px;
  border-radius: var(--r-pill);
  border: 1px solid var(--border);
  background: var(--surface-2);
}
.narr-conf-label {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--muted);
}
.narr-conf-dots {
  display: inline-flex; align-items: center; gap: 3px;
}
.narr-conf-dot {
  width: 5px; height: 5px;
  border-radius: 50%;
  background: var(--border-strong);
  display: inline-block;
}
.narr-conf-dot.is-on { background: var(--accent-strong); }

/* Fresh badge — narratives whose first detection is today's build. */
.narr-tag.fresh {
  color: var(--accent-strong);
  background: var(--accent-soft);
  border-color: color-mix(in srgb, var(--accent) 40%, transparent);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 700;
}
.narr.is-fresh .narr-accent {
  background: var(--accent);
  box-shadow: 0 0 6px color-mix(in srgb, var(--accent) 35%, transparent);
}

/* Sector tab stance dot — color-keyed to sectorOverviews[sec].stance so
   users read the top-down view (bullish / bearish / mixed) per sector at
   a glance, without clicking each tab. */
.narr-tab-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  background: var(--border-strong);
  flex: 0 0 auto;
}
.narr-tab-dot.is-bullish { background: var(--pos); box-shadow: 0 0 4px color-mix(in srgb, var(--pos) 40%, transparent); }
.narr-tab-dot.is-bearish { background: var(--neg); box-shadow: 0 0 4px color-mix(in srgb, var(--neg) 40%, transparent); }
.narr-tab-dot.is-mixed   { background: var(--warn); box-shadow: 0 0 4px color-mix(in srgb, var(--warn) 40%, transparent); }

/* Sector rollup strip — bullish/bearish split, building count, fresh count,
   plus the tickers driving the sector (most-frequently-cited across narratives).
   Sits between the stance pill and the strength bar in the overview banner. */
.narr-sec-stats {
  display: flex; align-items: center; flex-wrap: wrap;
  gap: 4px 6px;
  font-size: 12px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.narr-sec-stat strong {
  color: var(--text);
  font-weight: 700;
  font-family: var(--font-mono);
  margin-right: 3px;
}
.narr-sec-stat.is-pos strong   { color: var(--pos); }
.narr-sec-stat.is-neg strong   { color: var(--neg); }
.narr-sec-stat.is-warn strong  { color: var(--warn); }
.narr-sec-stat.is-accent strong{ color: var(--accent-strong); }
.narr-sec-stat-sep {
  color: var(--border-strong);
  margin: 0 1px;
}
.narr-sec-drivers {
  display: flex; align-items: center; flex-wrap: wrap;
  gap: 6px;
  margin-top: var(--s-1);
}
.narr-sec-drivers-label {
  font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--muted);
}
.narr-sec-driver-list {
  display: flex; flex-wrap: wrap; gap: 4px;
  align-items: center;
}
.narr-sec-driver-count {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--muted);
  margin-right: 4px;
  margin-left: -2px;
  font-variant-numeric: tabular-nums;
}

/* Source compactness — wrap overflow titles and tuck overflow entries
   behind a "+N more" toggle so the source list doesn't dominate the card
   when a narrative has 5+ citations. */
.narr-sources-more {
  margin-top: 4px;
}
.narr-sources-more > summary {
  list-style: none;
  cursor: pointer;
  font-size: 11px;
  color: var(--muted);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 2px 0;
}
.narr-sources-more > summary::-webkit-details-marker { display: none; }
.narr-sources-more > summary:hover { color: var(--text); }
.narr-sources-more[open] > summary::before { content: '− '; }
.narr-sources-more:not([open]) > summary::before { content: '+ '; }
.narr-sources-more > .narr-sources-list { margin-top: 4px; }
.narr-source-title { word-break: break-word; }

/* === Option eval card === */
.opt-controls {
  display: flex; flex-wrap: wrap; gap: var(--s-2);
  align-items: stretch;
  margin-bottom: var(--s-3);
}
.opt-workflow {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: var(--s-3) 0;
}
.opt-workflow-step {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  grid-template-rows: auto auto;
  gap: 2px 8px;
  align-items: center;
  min-width: 0;
  padding: 9px 10px;
  background: color-mix(in srgb, var(--surface-2) 75%, transparent);
  border: 1px solid var(--hairline);
  border-radius: var(--r-2);
}
.opt-workflow-step > span {
  grid-row: 1 / span 2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent-soft);
  color: var(--accent);
  font: 700 11px/1 var(--font-mono);
}
.opt-workflow-step > b {
  min-width: 0;
  color: var(--text-strong);
  font: 700 12px/1.2 var(--font-sans);
}
.opt-workflow-step > small {
  min-width: 0;
  color: var(--muted);
  font: 400 10.5px/1.25 var(--font-sans);
}
.opt-direction {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  margin: var(--s-3) 0 0;
  padding: 9px 10px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-2);
  background: color-mix(in srgb, var(--surface-2) 78%, transparent);
}
.opt-direction-copy { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.opt-direction-copy > span { color: var(--text-strong); font: 700 11px/1.2 var(--font-sans); text-transform: uppercase; letter-spacing: .06em; }
.opt-direction-copy > small { color: var(--muted); font: 400 10.5px/1.3 var(--font-sans); }
.opt-direction .segmented { flex: 0 0 auto; }
@media (max-width: 560px) {
  .opt-workflow { gap: 6px; }
  .opt-workflow-step {
    grid-template-columns: 20px minmax(0, 1fr);
    padding: 8px 6px;
    gap: 4px;
  }
  .opt-workflow-step > span { width: 20px; height: 20px; font-size: 10px; }
  .opt-workflow-step > b { font-size: 10.5px; }
  .opt-workflow-step > small { display: none; }
  .opt-direction { align-items: stretch; }
  .opt-direction-copy > small { max-width: 23ch; }
}
/* The contract-grade controls live inside the Contract grade tab now; the call/put
   segmented sits alone there (the ticker combo stays at the top of the card). */
.opt-controls-contract { margin-bottom: var(--s-2); }
/* Contract-grade section wrapper inside its tab pane. */
.opt-contract-grade { margin: 0; }
.opt-chain-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--s-2) var(--s-3);
  margin-bottom: var(--s-2);
  padding: 4px 8px;
  margin-inline: -8px;
  border-radius: var(--r-2);
  transition: background .15s var(--ease-out), box-shadow .15s var(--ease-out);
}
.opt-chain-row:hover { background: var(--accent-tint-1); }
.opt-chain-row:focus-within { box-shadow: var(--elev-focus); }
@media (max-width: 480px){ .opt-chain-row { grid-template-columns: 1fr; } }
.field {
  display: flex; flex-direction: column; gap: 4px;
}
.field-label {
  font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--muted);
}
.field select, .opt-manual-field input, .opt-manual-field select {
  height: 42px; padding: 0 var(--s-3);
  border-radius: var(--r-3);
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  font: inherit; font-size: var(--fs-md);
  font-variant-numeric: tabular-nums;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.field select:focus-visible, .opt-manual-field input:focus-visible, .opt-manual-field select:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: var(--focus-ring);
}

/* === Combobox === */
.combo {
  position: relative;
  flex: 1 1 260px; min-width: 200px;
}
.combo input {
  width: 100%; height: 42px;
  padding: 0 36px 0 var(--s-3);
  border-radius: var(--r-3);
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  font: inherit; font-size: var(--fs-md);
  transition: border-color .15s, box-shadow .15s;
}
.combo input::placeholder { color: var(--muted); opacity: 0.8; }
.combo input:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--focus-ring); }
.combo-clear {
  position: absolute; right: 6px; top: 50%; transform: translateY(-50%);
  width: 28px; height: 28px;
  border: none; background: transparent;
  color: var(--muted);
  font-size: 18px; line-height: 1;
  border-radius: var(--r-1);
  cursor: pointer;
}
.combo-clear:hover { color: var(--text); background: var(--surface-2); }
.combo ul {
  position: absolute; left: 0; right: 0; top: calc(100% + 4px);
  z-index: 20;
  list-style: none; margin: 0; padding: 4px;
  max-height: min(50vh, 320px); overflow: auto;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-3);
  box-shadow: var(--elev-3);
}
.combo ul li {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: var(--s-2);
  align-items: center;
  padding: 8px var(--s-3);
  border-radius: var(--r-1);
  cursor: pointer;
  font-size: var(--fs-sm);
  transition: background .1s var(--ease-out);
}
.combo ul li.is-active, .combo ul li:hover {
  background: var(--accent-soft);
}
.combo ul li.is-active::before {
  content: "";
  position: absolute;
  left: 2px; top: 6px; bottom: 6px;
  width: 2px;
  background: var(--accent);
  border-radius: 1px;
}
.combo-sym { font-weight: 700; color: var(--text-strong); font-variant-numeric: tabular-nums; }
.combo-spot { color: var(--muted); font-size: 13px; font-variant-numeric: tabular-nums; }
.combo-sector {
  font-size: 12px; color: var(--muted);
  padding: 2px 6px; border-radius: var(--r-1);
  background: var(--surface-2);
  border: 1px solid var(--border);
}
.combo-empty { padding: 10px var(--s-3); color: var(--muted); font-size: var(--fs-sm); }

/* === Top Picks "grade any ticker" search === */
.picks-search { margin: 0 0 var(--s-4); }
.picks-search-label {
  display: block;
  font: 600 var(--fs-sm)/1.2 inherit;
  color: var(--text);
  margin: 0 0 6px;
}
/* The .combo defaults to flex:1 for the header layout; here it's a standalone
   field, so cap its width and let it size itself. */
.picks-search .combo { flex: none; max-width: 460px; min-width: 0; }
.picks-search-hint { margin: 6px 0 0; font-size: 13px; color: var(--muted); }
/* Grade chip shown in each search row once grades.json loads — color by sign
   via the shared .sig-pos / .sig-neg / .sig-zero tokens. */
.picks-search-grade {
  font: 700 13px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.picks-search-miss { padding: var(--s-3); color: var(--muted); font-size: var(--fs-sm); }
.picks-search-miss .pick-symbol { margin-left: 4px; }

/* === Segmented control === */
.segmented {
  display: inline-flex;
  padding: 3px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  position: relative;
}
.segmented input {
  position: absolute; opacity: 0; pointer-events: none;
}
.segmented label {
  cursor: pointer;
  padding: 6px 16px;
  font-size: var(--fs-sm); font-weight: 600;
  color: var(--muted);
  border-radius: var(--r-pill);
  transition: color .15s ease, background .15s ease, box-shadow .15s ease;
}
.segmented input:checked + label {
  color: var(--text-strong);
  background: var(--surface);
  box-shadow: var(--shadow-sm);
}
.segmented input:focus-visible + label { box-shadow: var(--focus-ring); }

/* === Status === */
.opt-status {
  font-size: var(--fs-sm);
  min-height: 18px; margin: var(--s-1) 0;
  color: var(--muted);
  display: flex; align-items: center; gap: var(--s-2);
}

/* --- Compare companies (Tools) ---------------------------------------- */
.cmp-controls { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-bottom: 8px; }
.cmp-controls .combo { flex: 1 1 180px; min-width: 160px; }
.cmp-btn {
  appearance: none; border: 1px solid var(--border); background: var(--surface);
  color: var(--text-strong); border-radius: var(--r-1); padding: 7px 12px;
  font: 600 13px/1 var(--font-sans); cursor: pointer;
}
.cmp-btn:hover { border-color: var(--accent); }
.cmp-btn-quick { color: var(--accent); }
.cmp-btn-ghost { color: var(--muted); }
.cmp-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 6px; }
.cmp-chips:empty { display: none; }
.cmp-chip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 4px 6px 4px 10px; border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
  border: 1px solid var(--border); font: 600 12px/1 var(--font-sans);
}
.cmp-chip-base { border-color: color-mix(in srgb, var(--accent) 45%, var(--border)); }
.cmp-chip-base-tag { font: 700 9px/1 var(--font-sans); text-transform: uppercase; color: var(--accent); letter-spacing: 0.04em; }
.cmp-chip-name { font-weight: 400; color: var(--muted); max-width: 140px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cmp-chip-x { appearance: none; border: 0; background: transparent; color: var(--muted); font-size: 16px; line-height: 1; cursor: pointer; padding: 0 2px; }
.cmp-chip-x:hover { color: var(--neg); }
.cmp-series-0 { --cmp-series: #e3ad36; }
.cmp-series-1 { --cmp-series: #57b9d9; }
.cmp-series-2 { --cmp-series: #a78bfa; }
.cmp-series-3 { --cmp-series: #f07f67; }
.cmp-chip-swatch {
  flex: 0 0 auto; width: 8px; height: 8px; border-radius: 999px;
  background: var(--cmp-series);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--cmp-series) 16%, transparent);
}
.cmp-legend-swatch {
  flex: 0 0 auto; width: 22px; height: 3px; border-radius: 999px;
  background: var(--cmp-series);
}
.cmp-legend-item.cmp-series-1 .cmp-legend-swatch { background: repeating-linear-gradient(90deg, var(--cmp-series) 0 8px, transparent 8px 11px); }
.cmp-legend-item.cmp-series-2 .cmp-legend-swatch { background: repeating-linear-gradient(90deg, var(--cmp-series) 0 2px, transparent 2px 5px); }
.cmp-legend-item.cmp-series-3 .cmp-legend-swatch { background: repeating-linear-gradient(90deg, var(--cmp-series) 0 9px, transparent 9px 12px, var(--cmp-series) 12px 14px, transparent 14px 17px); }
.cmp-chart-card {
  margin: 8px 0 12px; padding: 14px;
  border: 1px solid var(--border); border-radius: var(--r-2);
  background: color-mix(in srgb, var(--surface-2) 60%, var(--surface));
  overflow: hidden;
}
.cmp-chart-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; margin-bottom: 10px; }
.cmp-chart-eyebrow { font: 700 9.5px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .08em; color: var(--accent); margin-bottom: 4px; }
.cmp-chart-title { margin: 0; font: 700 16px/1.2 var(--font-sans); color: var(--text-strong); }
.cmp-chart-sub { margin: 4px 0 0; font: 400 11.5px/1.4 var(--font-sans); color: var(--muted); }
.cmp-range {
  display: inline-flex; flex: 0 0 auto; padding: 3px; gap: 2px;
  border: 1px solid var(--border); border-radius: var(--r-pill); background: var(--surface);
}
.cmp-range-btn {
  appearance: none; border: 0; border-radius: var(--r-pill); background: transparent;
  color: var(--muted); min-width: 42px; padding: 6px 9px;
  font: 700 11px/1 var(--font-mono); cursor: pointer;
}
.cmp-range-btn:hover { color: var(--text-strong); }
.cmp-range-btn.is-active { color: var(--text-strong); background: var(--surface-3); box-shadow: var(--shadow-sm); }
.cmp-range-btn:focus-visible { box-shadow: var(--focus-ring); }
.cmp-chart-legend {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px; margin-bottom: 8px;
}
.cmp-legend-item {
  display: grid; grid-template-columns: auto auto 1fr; align-items: center; gap: 6px;
  min-width: 0; padding: 7px 8px; border: 1px solid var(--border);
  border-radius: var(--r-1); background: var(--surface);
}
.cmp-legend-sym { font: 750 12px/1 var(--font-sans); color: var(--text-strong); }
.cmp-legend-last { min-width: 0; text-align: right; }
.cmp-legend-return { display: block; font: 750 12px/1.1 var(--font-mono); font-variant-numeric: tabular-nums; }
.cmp-legend-price { display: block; margin-top: 2px; font: 500 9.5px/1 var(--font-mono); color: var(--muted); font-variant-numeric: tabular-nums; }
.cmp-ret-pos { color: var(--pos); }
.cmp-ret-neg { color: var(--neg); }
.cmp-ret-flat { color: var(--muted); }
.cmp-chart-stage {
  display: grid; grid-template-columns: 48px minmax(0, 1fr);
  grid-template-rows: clamp(250px, 34vw, 340px) 22px;
  column-gap: 7px; row-gap: 2px;
}
.cmp-y-axis { position: relative; grid-column: 1; grid-row: 1; }
.cmp-y-label {
  position: absolute; right: 0; transform: translateY(-50%);
  font: 600 9.5px/1 var(--font-mono); color: var(--muted);
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
.cmp-y-label.is-zero { color: var(--text-strong); }
.cmp-y-label:first-child { transform: none; }
.cmp-y-label:last-child { transform: translateY(-100%); }
.cmp-plot {
  position: relative; grid-column: 2; grid-row: 1; min-width: 0;
  border-left: 1px solid var(--border); border-bottom: 1px solid var(--border);
  outline: none; touch-action: pan-y;
}
.cmp-plot:focus-visible { box-shadow: var(--focus-ring); }
.cmp-chart-svg { display: block; width: 100%; height: 100%; overflow: visible; }
.cmp-chart-grid { stroke: var(--hairline); stroke-width: 1; vector-effect: non-scaling-stroke; }
.cmp-chart-zero { stroke: color-mix(in srgb, var(--text-strong) 36%, transparent); stroke-width: 1.2; vector-effect: non-scaling-stroke; }
.cmp-chart-line {
  fill: none; stroke: var(--cmp-series); stroke-width: 2.25;
  vector-effect: non-scaling-stroke; stroke-linejoin: round; stroke-linecap: round;
}
.cmp-chart-line.cmp-series-1 { stroke-dasharray: 9 3; }
.cmp-chart-line.cmp-series-2 { stroke-dasharray: 2 3; }
.cmp-chart-line.cmp-series-3 { stroke-dasharray: 11 3 2 3; }
.cmp-x-axis {
  grid-column: 2; grid-row: 2; display: flex; align-items: flex-end;
  justify-content: space-between; min-width: 0;
  font: 600 9.5px/1 var(--font-mono); color: var(--muted);
}
.cmp-chart-cross {
  position: absolute; inset-block: 0; width: 1px; display: none;
  background: color-mix(in srgb, var(--text-strong) 48%, transparent);
  pointer-events: none; transform: translateX(-.5px);
}
.cmp-chart-dot {
  position: absolute; width: 9px; height: 9px; display: none;
  border: 2px solid var(--surface); border-radius: 999px;
  background: var(--cmp-series); pointer-events: none;
  transform: translate(-50%, -50%); box-shadow: 0 0 0 1px var(--cmp-series);
}
.cmp-chart-tip {
  position: absolute; z-index: 3; display: none; min-width: 150px;
  padding: 8px 9px; border: 1px solid var(--border-strong); border-radius: var(--r-1);
  background: color-mix(in srgb, var(--surface) 94%, transparent);
  box-shadow: var(--shadow-md); pointer-events: none;
}
.cmp-chart-tip-floating { z-index: 970; }
.cmp-tip-date { margin-bottom: 6px; font: 700 10px/1 var(--font-mono); color: var(--muted); }
.cmp-tip-row { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 6px; margin-top: 4px; }
.cmp-tip-sym { font: 700 11px/1 var(--font-sans); color: var(--text-strong); }
.cmp-tip-val { text-align: right; font: 700 11px/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.cmp-tip-price { color: var(--muted); font: 500 9.5px/1 var(--font-mono); }
.cmp-chart-read {
  margin-top: 8px; min-height: 18px; padding-top: 8px; border-top: 1px solid var(--border);
  font: 500 11.5px/1.45 var(--font-sans); color: var(--muted);
}
.cmp-chart-read b { color: var(--text-strong); }
.cmp-chart-empty { display: grid; place-items: center; min-height: 190px; text-align: center; color: var(--muted); font: 500 12px/1.5 var(--font-sans); }
@media (max-width: 640px) {
  .cmp-controls .combo { flex-basis: 100%; min-width: 0; }
  .cmp-btn { min-height: 40px; }
  .cmp-chip-name { max-width: 105px; }
  .cmp-chart-card { padding: 11px; }
  .cmp-chart-head { flex-direction: column; align-items: stretch; gap: 9px; }
  .cmp-range { width: 100%; }
  .cmp-range-btn { flex: 1 1 0; min-height: 38px; }
  .cmp-chart-legend { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .cmp-chart-stage { grid-template-columns: 40px minmax(0, 1fr); grid-template-rows: 235px 20px; column-gap: 5px; }
  .cmp-y-label, .cmp-x-axis { font-size: 9px; }
  .cmp-chart-line { stroke-width: 2.4; }
  .cmp-chart-tip { position: fixed; left: 8px !important; right: 8px; top: auto !important; bottom: 64px; width: auto; }
}
.cmp-summary {
  margin: 8px 0; padding: 10px 12px;
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
  border: 1px solid var(--border); border-left: 3px solid var(--accent);
  border-radius: var(--r-1);
}
.cmp-summary-head { font: 700 11px/1 var(--font-sans); text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-strong); margin-bottom: 6px; }
.cmp-summary-list { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 4px; }
.cmp-summary-list li { font: 400 13px/1.5 var(--font-sans); color: var(--text); }
.cmp-table-wrap { overflow-x: auto; -webkit-overflow-scrolling: touch; }
.cmp-table { width: 100%; border-collapse: collapse; font: 400 13px/1.3 var(--font-sans); }
.cmp-table th, .cmp-table td { padding: 7px 10px; text-align: right; border-bottom: 1px solid var(--border); white-space: nowrap; }
.cmp-table thead th { position: sticky; top: 0; background: var(--surface); z-index: 1; vertical-align: bottom; }
.cmp-th-metric, .cmp-td-metric { text-align: left; font-weight: 600; color: var(--text-strong); position: sticky; left: 0; background: var(--surface); }
.cmp-td-metric { color: var(--muted); font-weight: 500; }
.cmp-th-co { min-width: 96px; }
.cmp-th-base { box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--accent) 50%, transparent); }
.cmp-th-sym { font: 700 14px/1 var(--font-sans); color: var(--text-strong); }
.cmp-th-sector { display: block; font: 400 10px/1.2 var(--font-sans); color: var(--muted); margin-top: 2px; white-space: normal; }
.cmp-side { font: 700 9px/1 var(--font-sans); padding: 2px 4px; border-radius: 4px; vertical-align: middle; }
.cmp-side-call { color: var(--pos); background: color-mix(in srgb, var(--pos) 14%, transparent); }
.cmp-side-put { color: var(--neg); background: color-mix(in srgb, var(--neg) 14%, transparent); }
.cmp-td .cmp-val { font-variant-numeric: tabular-nums; font-weight: 600; }
.cmp-leader { background: color-mix(in srgb, var(--pos) 9%, transparent); }
.cmp-leader .cmp-val { color: var(--pos); }
.cmp-delta { display: block; font: 600 10.5px/1.2 var(--font-mono); margin-top: 1px; }
.cmp-d-good { color: var(--pos); }
.cmp-d-bad { color: var(--neg); }
.cmp-d-flat { color: var(--muted); }

/* --- Earnings tracker (season scoreboard) ------------------------------ */
.ers-pills {
  display: flex; flex-wrap: nowrap; gap: 6px; margin-bottom: 14px;
  overflow-x: auto; overscroll-behavior-inline: contain; scrollbar-width: thin;
  padding-bottom: 3px;
}
.ers-pill {
  display: inline-flex; align-items: center; gap: 6px;
  font: 600 12px/1 var(--font-sans); color: var(--muted);
  padding: 6px 10px; border: 1px solid var(--border); border-radius: 999px;
  background: var(--surface); cursor: pointer;
}
.ers-pill:hover { color: var(--text-strong); border-color: color-mix(in srgb, var(--accent) 45%, var(--border)); }
.ers-pill.is-active { color: var(--text-strong); border-color: var(--accent); background: color-mix(in srgb, var(--accent) 10%, var(--surface)); }
.ers-pill-n { font: 700 10px/1 var(--font-mono); color: var(--muted); background: color-mix(in srgb, var(--muted) 12%, transparent); padding: 2px 5px; border-radius: 999px; }
.ers-season-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px; margin-bottom: 10px; }
.ers-season-title { font: 700 16px/1.2 var(--font-sans); color: var(--text-strong); }
.ers-season-sub { font: 400 12px/1.3 var(--font-sans); color: var(--muted); }
.ers-searchbar {
  display: flex; align-items: center; gap: 12px; margin-bottom: 12px;
  padding: 10px 12px; border: 1px solid var(--border); border-radius: var(--r-2);
  background: var(--surface-2);
}
.ers-searchbar > label { flex: 0 0 auto; }
.ers-searchbar > label span,
.ers-searchbar > label small { display: block; }
.ers-searchbar > label span { color: var(--text-strong); font: 700 11px/1.2 var(--font-sans); }
.ers-searchbar > label small { margin-top: 3px; color: var(--muted); font: 600 8.5px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .05em; }
.ers-search-actions { display: flex; align-items: stretch; gap: 7px; flex: 1 1 auto; min-width: 0; }
.ers-search-input-wrap { position: relative; flex: 1 1 auto; min-width: 0; }
.ers-search-input {
  width: 100%; min-height: 38px; padding: 8px 58px 8px 11px;
  border: 1px solid var(--border); border-radius: var(--r-2);
  background: var(--surface); color: var(--text-strong);
  font: 600 13px/1.2 var(--font-sans); text-transform: uppercase;
}
.ers-search-input::placeholder { color: var(--muted); font-weight: 400; text-transform: none; }
.ers-search-input:focus { outline: none; border-color: var(--accent); box-shadow: var(--focus-ring); }
.ers-search-clear {
  position: absolute; right: 5px; top: 50%; transform: translateY(-50%);
  min-height: 28px; padding: 4px 7px; border: 0; border-radius: var(--r-1);
  background: transparent; color: var(--muted); cursor: pointer; font: 700 9px/1 var(--font-sans);
}
.ers-search-clear:hover, .ers-search-clear:focus-visible { background: var(--surface-3); color: var(--text-strong); outline: none; }
.ers-search-clear[hidden] { display: none; }
.ers-search-submit {
  flex: 0 0 auto; min-width: 76px; min-height: 38px; padding: 8px 12px;
  border: 1px solid var(--accent); border-radius: var(--r-2);
  background: var(--accent); color: var(--accent-fg); cursor: pointer;
  font: 700 11px/1 var(--font-sans);
}
.ers-search-submit:hover { filter: brightness(1.08); }
.ers-search-submit:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.ers-search-output:not(:empty) { margin-bottom: 14px; }
.ers-search-results { overflow: hidden; border: 1px solid color-mix(in srgb, var(--accent) 42%, var(--border)); border-radius: var(--r-2); background: var(--surface); }
.ers-search-results-head {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 9px 11px; border-bottom: 1px solid var(--border); background: color-mix(in srgb, var(--accent) 7%, var(--surface));
}
.ers-search-results-head span { color: var(--text-strong); font: 700 10.5px/1.2 var(--font-sans); }
.ers-search-results-head b { color: var(--muted); font: 600 9px/1.2 var(--font-mono); white-space: nowrap; }
.ers-search-list { padding: 3px 11px; }
.ers-search-result {
  display: grid; grid-template-columns: minmax(150px, 1fr) minmax(230px, 1.4fr) 100px;
  align-items: center; gap: 10px; padding: 8px 0;
  border-bottom: 1px dashed color-mix(in srgb, var(--border) 65%, transparent);
}
.ers-search-result:last-child { border-bottom: 0; }
.ers-search-company { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.ers-search-company > span { overflow: hidden; color: var(--muted); font: 400 11.5px/1.2 var(--font-sans); text-overflow: ellipsis; white-space: nowrap; }
.ers-search-context { display: flex; align-items: center; gap: 7px; min-width: 0; color: var(--muted); font: 400 11px/1.25 var(--font-sans); }
.ers-search-signal { display: inline-flex; gap: 4px; flex: 0 0 auto; }
.ers-search-context > span:last-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ers-search-value { text-align: right; white-space: nowrap; }
.ers-search-value b { display: block; color: var(--text-strong); font: 700 13px/1 var(--font-mono); }
.ers-search-value b.ers-pos { color: var(--pos); }
.ers-search-value b.ers-neg { color: var(--neg); }
.ers-search-value small { display: block; margin-top: 3px; color: var(--muted); font: 500 8.5px/1 var(--font-mono); text-transform: uppercase; }
.ers-search-empty { padding: 12px; border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface-2); color: var(--muted); font: 400 12px/1.4 var(--font-sans); }
.ers-search-empty b { color: var(--text-strong); }
.ers-posture {
  margin-bottom: 14px;
  padding: 15px 16px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--muted);
  border-radius: var(--r-2);
  background: linear-gradient(135deg, color-mix(in srgb, var(--surface-2) 92%, transparent), var(--surface));
}
.ers-posture-watch { border-left-color: var(--warn); }
.ers-posture-risk { border-left-color: var(--neg); }
.ers-posture-constructive { border-left-color: var(--pos); }
.ers-posture-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.ers-posture-kicker,
.ers-posture-state {
  color: var(--muted); font: 700 9px/1 var(--font-mono);
  text-transform: uppercase; letter-spacing: .08em;
}
.ers-posture-state { padding: 4px 7px; border-radius: var(--r-pill); background: var(--surface-3); }
.ers-posture-watch .ers-posture-state { color: var(--warn); background: color-mix(in srgb, var(--warn) 12%, transparent); }
.ers-posture-risk .ers-posture-state { color: var(--neg); background: color-mix(in srgb, var(--neg) 12%, transparent); }
.ers-posture-constructive .ers-posture-state { color: var(--pos); background: color-mix(in srgb, var(--pos) 12%, transparent); }
.ers-posture h3 { margin: 8px 0 5px; color: var(--text-strong); font: 750 1.08rem/1.25 var(--font-sans); }
.ers-posture > p { max-width: 900px; margin: 0; color: var(--text); font: 400 12.5px/1.5 var(--font-sans); }
.ers-posture-metrics {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px; margin-top: 13px; overflow: hidden;
  border: 1px solid var(--border); border-radius: var(--r-2); background: var(--border);
}
.ers-posture-metrics > div { min-width: 0; padding: 10px 11px; background: var(--surface); }
.ers-posture-metrics b { display: block; color: var(--text-strong); font: 700 1rem/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.ers-posture-metrics span,
.ers-posture-metrics small { display: block; margin-top: 5px; color: var(--muted); font: 700 8.5px/1.2 var(--font-mono); text-transform: uppercase; letter-spacing: .055em; }
.ers-posture-metrics small { margin-top: 3px; font-weight: 500; text-transform: none; letter-spacing: 0; }
.ers-posture-triggers { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 9px; }
.ers-posture-triggers > div { padding: 9px 10px; border: 1px solid var(--border); border-radius: var(--r-1); background: color-mix(in srgb, var(--surface-2) 78%, transparent); }
.ers-posture-triggers span { display: block; margin-bottom: 4px; color: var(--muted); font: 700 8.5px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .07em; }
.ers-posture-triggers b { color: var(--text); font: 600 11px/1.4 var(--font-sans); }
.ers-posture-action {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 12px;
  margin-top: 10px; padding-top: 11px; border-top: 1px solid var(--border);
}
.ers-posture-action > div:first-child { max-width: 650px; }
.ers-posture-action span { display: block; margin-bottom: 4px; color: var(--accent); font: 700 8.5px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .07em; }
.ers-posture-action b { color: var(--text-strong); font: 600 11.5px/1.45 var(--font-sans); }
.ers-posture-buttons { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 6px; flex: 0 0 auto; }
.ers-action-primary, .ers-action-secondary {
  min-height: 34px; padding: 7px 10px; border-radius: var(--r-2);
  cursor: pointer; font: 650 10.5px/1 var(--font-sans);
}
.ers-action-primary { border: 1px solid var(--accent); background: var(--accent); color: var(--accent-fg); }
.ers-action-secondary { border: 1px solid var(--border); background: var(--surface); color: var(--text); }
.ers-action-primary:hover { filter: brightness(1.08); }
.ers-action-secondary:hover { border-color: color-mix(in srgb, var(--accent) 40%, var(--border)); background: var(--surface-2); }
.ers-action-primary:focus-visible, .ers-action-secondary:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.ers-pos { color: var(--pos); }
.ers-neg { color: var(--neg); }
.ers-dim { color: var(--muted); }
.ers-chip { display: inline-block; font: 700 10.5px/1 var(--font-sans); padding: 2px 6px; border-radius: 4px; white-space: nowrap; }
.ers-chip-pos { color: var(--pos); background: color-mix(in srgb, var(--pos) 14%, transparent); }
.ers-chip-neg { color: var(--neg); background: color-mix(in srgb, var(--neg) 14%, transparent); }
.ers-chip-flat { color: var(--muted); background: color-mix(in srgb, var(--muted) 14%, transparent); }
.ers-chip-warn { color: var(--warn); background: color-mix(in srgb, var(--warn) 14%, transparent); }
.ers-ai {
  padding: 0; margin-bottom: 14px;
  background: color-mix(in srgb, var(--accent) 5%, var(--surface));
  border: 1px solid var(--border); border-radius: var(--r-2);
}
.ers-ai-toggle {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px 9px;
  min-height: 48px;
  padding: 10px 14px;
  cursor: pointer;
  list-style: none;
}
.ers-ai-toggle::-webkit-details-marker { display: none; }
.ers-ai-toggle::after {
  content: '›';
  color: var(--accent);
  font: 700 1rem/1 var(--font-mono);
  transition: transform .15s ease;
}
.ers-ai[open] > .ers-ai-toggle::after { transform: rotate(90deg); }
.ers-ai-toggle .ers-ai-headline { flex: 1 1 300px; margin: 0; }
.ers-ai-toggle .ers-ai-date { margin-left: 0; }
.ers-ai-body { padding: 12px 16px 14px; border-top: 1px solid var(--border); }
.ers-ai-fallback { padding: 14px 16px; }
.ers-ai-head { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-bottom: 6px; }
.ers-ai-label { font: 600 11px/1 var(--font-sans); text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); }
.ers-ai-date { font: 400 11px/1 var(--font-sans); color: var(--muted); margin-left: auto; }
.ers-ai-headline { font: 700 15px/1.35 var(--font-sans); color: var(--text-strong); margin-bottom: 4px; }
.ers-ai-summary { font: 400 13px/1.55 var(--font-sans); color: var(--text); margin: 0; }
.ers-standouts { display: flex; flex-direction: column; gap: 5px; margin-top: 10px; }
.ers-standout { display: flex; align-items: baseline; gap: 8px; font: 400 12.5px/1.4 var(--font-sans); }
.ers-standout-note { color: var(--text); }
.ers-tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); gap: 12px; margin-bottom: 16px; }
.ers-tile { padding: 12px 14px; border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface); }
.ers-tile-label { font: 600 11px/1 var(--font-sans); text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); margin-bottom: 8px; }
.ers-tile-sub { font: 400 12.5px/1.45 var(--font-sans); color: var(--text); margin-top: 7px; }
.ers-tile-sub b { font-weight: 700; }
.ers-tile-note { font: 400 11.5px/1.45 var(--font-sans); color: var(--muted); margin-top: 4px; }
.ers-bar { display: flex; gap: 2px; height: 18px; border-radius: 4px; overflow: hidden; }
.ers-seg { display: flex; align-items: center; justify-content: center; font: 700 10px/1 var(--font-mono); color: #fff; min-width: 3px; flex-basis: 0; }
.ers-seg-pos { background: color-mix(in srgb, var(--pos) 78%, transparent); }
.ers-seg-neg { background: color-mix(in srgb, var(--neg) 78%, transparent); }
.ers-seg-flat { background: color-mix(in srgb, var(--muted) 45%, transparent); }
.ers-seg-warn { background: color-mix(in srgb, var(--warn) 78%, transparent); }
.ers-ldrs { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 12px 20px; margin-bottom: 16px; }
.ers-ldr-head { font: 700 12px/1 var(--font-sans); text-transform: uppercase; letter-spacing: 0.04em; padding-bottom: 6px; margin-bottom: 4px; border-bottom: 1px solid var(--border); }
.ers-upcoming {
  margin-bottom: 14px;
  padding: 14px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: var(--r-2);
  background: var(--surface-2);
}
.ers-upcoming-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 11px;
}
.ers-upcoming-kicker {
  display: block;
  margin-bottom: 4px;
  color: var(--accent);
  font: 700 9px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
}
.ers-upcoming-head h3 { margin: 0; color: var(--text-strong); font: 700 1rem/1.15 var(--font-sans); }
.ers-up-showing { color: var(--muted); font: 600 10px/1.2 var(--font-mono); white-space: nowrap; }
.ers-up-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 12px;
  margin-bottom: 10px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border);
}
.ers-up-window-group { display: inline-flex; gap: 4px; }
.ers-up-window,
.ers-up-sort-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  padding: 5px 9px;
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  background: var(--surface);
  color: var(--muted);
  cursor: pointer;
  font: 600 10.5px/1 var(--font-sans);
  white-space: nowrap;
}
.ers-up-window span { color: var(--muted); font: 700 9px/1 var(--font-mono); }
.ers-up-window:hover,
.ers-up-window:focus-visible,
.ers-up-sort-chip:hover,
.ers-up-sort-chip:focus-visible { border-color: var(--muted); color: var(--text-strong); }
.ers-up-window[aria-pressed="true"],
.ers-up-sort-chip[aria-pressed="true"] {
  border-color: var(--accent); color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}
/* Upcoming-strip head row: title left, sort chips right (wraps on phones). */
.ers-ldr-head-row { display: flex; align-items: center; justify-content: space-between; gap: 6px 10px; flex-wrap: wrap; }
.ers-up-sort { display: inline-flex; gap: 6px; flex-wrap: wrap; }
.ers-up-sort-chip {
  letter-spacing: normal;
  text-transform: none;
}
.ers-ldr-row { display: flex; align-items: baseline; gap: 8px; padding: 5px 0; border-bottom: 1px dashed color-mix(in srgb, var(--border) 60%, transparent); }
.ers-ldr-row:last-child { border-bottom: 0; }
.ers-ldr-name { font: 400 11.5px/1.2 var(--font-sans); color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1 1 auto; min-width: 0; }
.ers-ldr-meta { display: inline-flex; align-items: baseline; gap: 5px; font: 400 11px/1 var(--font-sans); flex: 0 0 auto; }
.ers-ldr-val { font: 700 13.5px/1 var(--font-mono); font-variant-numeric: tabular-nums; white-space: nowrap; flex: 0 0 auto; text-align: right; }
.ers-ldr-day { display: block; font: 400 10.5px/1.3 var(--font-mono); color: var(--muted); }
/* Upcoming-reporters strip: the full-span header stops auto-fit from collapsing
   its empty tracks, so pin the wrapper to exactly one or two equal columns. Rows
   are a fixed-column grid so the drift chip / date / value align across rows.
   The value track is fixed too: each row is its own grid, so max-content would
   resize per row and shift the chip / plan anchors when percentages differ. */
.ers-up-ldrs { grid-template-columns: 1fr; margin-bottom: 0; }
.ers-up-ldrs.ers-up-two { grid-template-columns: 1fr 1fr; }
.ers-up-row {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) 94px 76px;
  grid-template-areas:
    "sym name chip value"
    "date date plan plan";
  align-items: center; gap: 5px 8px; padding: 7px 0;
}
.ers-up-row > .ers-sym { grid-area: sym; }
.ers-up-row > .ers-ldr-name { grid-area: name; }
.ers-up-row > :nth-child(3) { grid-area: chip; justify-self: start; }
.ers-up-date { font: 400 11px/1 var(--font-sans); white-space: nowrap; }
.ers-up-row > .ers-up-date { grid-area: date; }
.ers-up-row > .ers-ldr-val { grid-area: value; width: 100%; justify-self: stretch; }
.ers-up-plan {
  grid-area: plan; display: inline-flex; align-items: baseline; justify-content: flex-end;
  gap: 6px; min-width: 0; padding: 4px 7px; border-radius: var(--r-1);
  background: color-mix(in srgb, var(--muted) 7%, transparent);
}
.ers-up-plan b { color: var(--text); font: 700 9.5px/1.2 var(--font-sans); white-space: nowrap; }
.ers-up-plan small { color: var(--muted); font: 600 9px/1.2 var(--font-mono); white-space: nowrap; }
.ers-up-plan-risk { background: color-mix(in srgb, var(--neg) 9%, transparent); }
.ers-up-plan-risk b { color: var(--neg); }
.ers-up-plan-warn { background: color-mix(in srgb, var(--warn) 9%, transparent); }
.ers-up-plan-warn b { color: var(--warn); }
.ers-up-more {
  width: 100%; min-height: 38px; margin-top: 10px;
  border: 1px solid var(--border); border-radius: var(--r-2);
  background: var(--surface); color: var(--text);
  cursor: pointer; font: 700 10.5px/1 var(--font-mono);
}
.ers-up-more:hover, .ers-up-more:focus-visible { border-color: var(--accent); outline: none; }
.ers-recent { border-left-color: color-mix(in srgb, var(--accent) 65%, var(--pos)); }
.ers-recent-order {
  color: var(--muted); font: 600 9px/1 var(--font-mono);
  text-transform: uppercase; letter-spacing: .06em;
}
.ers-recent-ldrs { grid-template-columns: 1fr; margin-bottom: 0; }
.ers-recent-ldrs.ers-recent-two { grid-template-columns: 1fr 1fr; }
.ers-recent-row {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) 120px 82px;
  grid-template-areas:
    "sym name result move"
    "date date eps eps";
  align-items: center; gap: 5px 8px; padding: 7px 0;
}
.ers-recent-row > .ers-sym { grid-area: sym; }
.ers-recent-row > .ers-ldr-name { grid-area: name; }
.ers-recent-result { grid-area: result; display: inline-flex; align-items: center; justify-content: flex-start; gap: 4px; }
.ers-recent-date { grid-area: date; font: 400 11px/1.2 var(--font-sans); white-space: nowrap; }
.ers-recent-eps {
  grid-area: eps; display: flex; align-items: baseline; justify-content: flex-end; gap: 6px;
  min-width: 0; color: var(--text); font: 600 10px/1.2 var(--font-mono); white-space: nowrap;
}
.ers-recent-eps small { color: var(--muted); font: 500 9px/1.2 var(--font-mono); }
.ers-recent-row > .ers-ldr-val { grid-area: move; width: 100%; justify-self: stretch; }
@media (max-width: 700px) {
  .ers-searchbar { align-items: stretch; flex-direction: column; gap: 8px; }
  .ers-searchbar > label { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
  .ers-searchbar > label small { margin-top: 0; }
  .ers-search-actions { width: 100%; }
  .ers-search-result { grid-template-columns: minmax(0, 1fr) auto; gap: 5px 8px; }
  .ers-search-company { grid-column: 1; grid-row: 1; }
  .ers-search-context { grid-column: 1 / -1; grid-row: 2; }
  .ers-search-value { grid-column: 2; grid-row: 1; }
  .ers-search-results-head { align-items: flex-start; flex-direction: column; gap: 4px; }
  .ers-up-ldrs.ers-up-two { grid-template-columns: 1fr; }
  .ers-recent-ldrs.ers-recent-two { grid-template-columns: 1fr; }
  .ers-posture { padding: 13px 12px; }
  .ers-posture-metrics { grid-template-columns: 1fr 1fr; }
  .ers-posture-triggers { grid-template-columns: 1fr; }
  .ers-posture-action { align-items: stretch; flex-direction: column; }
  .ers-posture-buttons { display: grid; grid-template-columns: minmax(0, 1fr); width: 100%; }
  .ers-action-primary, .ers-action-secondary { width: 100%; min-height: 40px; }
  .ers-ai-toggle .ers-ai-headline { order: 3; flex-basis: calc(100% - 28px); }
  .ers-ai-toggle .ers-ai-date { margin-left: auto; }
  .ers-upcoming { padding: 12px; }
  .ers-upcoming-head { align-items: flex-start; }
  .ers-up-controls { align-items: stretch; }
  .ers-up-window-group { width: 100%; }
  .ers-up-window { flex: 1 1 0; justify-content: center; }
  .ers-up-sort { width: 100%; flex-wrap: nowrap; overflow-x: auto; padding-bottom: 2px; }
  .ers-up-row {
    grid-template-columns: 52px minmax(0, 1fr) auto;
    grid-template-areas:
      "sym name value"
      "date date chip"
      "plan plan plan";
    align-items: center;
    row-gap: 5px;
    padding: 8px 0;
  }
  .ers-up-row > .ers-sym { grid-area: sym; }
  .ers-up-row > .ers-ldr-name { grid-area: name; }
  .ers-up-row > :nth-child(3) { grid-area: chip; justify-self: end; }
  .ers-up-row > .ers-up-date { grid-area: date; white-space: normal; }
  .ers-up-row > .ers-ldr-val { grid-area: value; }
  .ers-up-plan { justify-content: space-between; width: 100%; margin-top: 2px; }
  .ers-recent-order { align-self: center; }
  .ers-recent-row {
    grid-template-columns: 52px minmax(0, 1fr) auto;
    grid-template-areas:
      "sym name move"
      "date date result"
      "eps eps eps";
    row-gap: 5px; padding: 8px 0;
  }
  .ers-recent-result { justify-self: end; }
  .ers-recent-date { white-space: normal; }
  .ers-recent-eps { justify-content: space-between; width: 100%; padding-top: 2px; }
  .ers-table-details > summary small { font-size: 8px; }
}
.ers-sym {
  font: 700 12.5px/1 var(--font-sans); color: var(--text-strong);
  background: none; border: 0; padding: 0; cursor: pointer; white-space: nowrap;
}
.ers-sym:hover { color: var(--accent); text-decoration: underline; }
.ers-table-details {
  margin-top: 4px;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface);
}
.ers-table-details > summary {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 10px 12px;
  cursor: pointer;
  list-style: none;
  color: var(--text-strong);
  font: 700 .8rem/1.2 var(--font-sans);
}
.ers-table-details > summary::-webkit-details-marker { display: none; }
.ers-table-details > summary::before {
  content: '›'; color: var(--accent); font: 700 1rem/1 var(--font-mono);
  transition: transform .15s ease;
}
.ers-table-details[open] > summary::before { transform: rotate(90deg); }
.ers-table-details > summary:hover { background: var(--surface-2); }
.ers-table-details > summary small {
  margin-left: auto; color: var(--muted);
  font: 600 9px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .06em;
}
.ers-table-searchbar {
  margin: 0; border-width: 1px 0; border-radius: 0;
  background: color-mix(in srgb, var(--surface-2) 72%, transparent);
}
.ers-table-filter-status {
  flex: 0 0 auto; color: var(--muted); font: 600 9px/1.2 var(--font-mono);
  text-transform: uppercase; letter-spacing: .045em; white-space: nowrap;
}
.ers-table-empty {
  padding: 18px 12px; border-bottom: 1px solid var(--border); text-align: center;
  color: var(--muted); font: 500 12px/1.45 var(--font-sans);
}
.ers-table-empty b { color: var(--text-strong); }
.ers-table-wrap { overflow-x: auto; }
.ers-table { width: 100%; border-collapse: collapse; font: 400 12px/1.35 var(--font-sans); }
.ers-table th {
  font: 600 10.5px/1 var(--font-sans); text-transform: uppercase; letter-spacing: 0.04em;
  color: var(--muted); text-align: left; padding: 6px 8px; border-bottom: 1px solid var(--border);
  white-space: nowrap;
}
.ers-table td { padding: 6px 8px; border-bottom: 1px solid color-mix(in srgb, var(--border) 55%, transparent); white-space: nowrap; }
.ers-table th.ers-td-num, .ers-table td.ers-td-num { text-align: right; font-variant-numeric: tabular-nums; }
.ers-td-date { color: var(--muted); }
@media (max-width: 640px) {
  .ers-table-searchbar { gap: 8px; }
  .ers-table-filter-status { white-space: normal; }
}

/* --- Earnings calls (transcript AI briefs) ------------------------------ */
.ecl-dim { color: var(--muted); }
.ecl-note { font: 400 13px/1.5 var(--font-sans); margin: 8px 0 0; }
.ecl-chip { display: inline-block; font: 700 10.5px/1 var(--font-sans); padding: 2px 6px; border-radius: 4px; white-space: nowrap; }
.ecl-chip-pos { color: var(--pos); background: color-mix(in srgb, var(--pos) 14%, transparent); }
.ecl-chip-neg { color: var(--neg); background: color-mix(in srgb, var(--neg) 14%, transparent); }
.ecl-chip-flat { color: var(--muted); background: color-mix(in srgb, var(--muted) 14%, transparent); }
.ecl-chip-warn { color: var(--warn); background: color-mix(in srgb, var(--warn) 14%, transparent); }
.ecl-sym {
  font: 700 13px/1 var(--font-sans); color: var(--text-strong);
  background: none; border: 0; padding: 0; cursor: pointer; white-space: nowrap;
}
.ecl-sym:hover { color: var(--accent); text-decoration: underline; }
/* List view */
.ecl-toolbar { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }
.ecl-search {
  flex: 0 1 320px; font: 400 13px/1.2 var(--font-sans); color: var(--text-strong);
  padding: 7px 10px; border: 1px solid var(--border); border-radius: var(--r-2);
  background: var(--surface);
}
.ecl-search:focus { outline: none; border-color: var(--accent); }
.ecl-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 12px; }
.ecl-card {
  display: flex; flex-direction: column; align-items: stretch; gap: 7px; text-align: left;
  padding: 12px 14px; border: 1px solid var(--border); border-radius: var(--r-2);
  background: var(--surface); cursor: pointer; font: inherit; color: inherit;
}
.ecl-card:hover { border-color: color-mix(in srgb, var(--accent) 55%, var(--border)); }
.ecl-card-top { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.ecl-card-sym { font: 700 14px/1 var(--font-sans); color: var(--text-strong); }
.ecl-card-co { font: 400 11.5px/1.2 var(--font-sans); color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1 1 auto; min-width: 0; }
.ecl-card-date { font: 400 11px/1.2 var(--font-sans); color: var(--muted); white-space: nowrap; }
.ecl-card-head { font: 400 12.5px/1.45 var(--font-sans); color: var(--text); }
.ecl-card-chips { display: flex; flex-wrap: wrap; gap: 5px; margin-top: auto; }
/* Detail view */
.ecl-back {
  font: 600 12px/1 var(--font-sans); color: var(--muted); background: none;
  border: 1px solid var(--border); border-radius: 999px; padding: 6px 12px;
  cursor: pointer; margin-bottom: 14px;
}
.ecl-back:hover { color: var(--text-strong); border-color: color-mix(in srgb, var(--accent) 45%, var(--border)); }
.ecl-det-head { margin-bottom: 8px; }
.ecl-det-title { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px; }
.ecl-det-title .ecl-sym { font-size: 17px; }
.ecl-det-co { font: 700 16px/1.2 var(--font-sans); color: var(--text-strong); }
.ecl-det-q { font: 400 12.5px/1.2 var(--font-sans); color: var(--muted); }
.ecl-det-sub { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-top: 6px; font: 400 12px/1.3 var(--font-sans); color: var(--muted); }
.ecl-det-headline { font: 700 15.5px/1.35 var(--font-sans); color: var(--text-strong); margin: 8px 0 4px; }
.ecl-sec { margin-top: 16px; }
.ecl-sec-title {
  font: 600 11px/1 var(--font-sans); text-transform: uppercase; letter-spacing: 0.05em;
  color: var(--muted); padding-bottom: 6px; margin-bottom: 8px; border-bottom: 1px solid var(--border);
}
.ecl-bullets { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 5px; }
.ecl-bullets li { font: 400 13px/1.5 var(--font-sans); color: var(--text); }
.ecl-rows { display: flex; flex-direction: column; }
.ecl-row {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; padding: 6px 0;
  border-bottom: 1px dashed color-mix(in srgb, var(--border) 60%, transparent);
  font: 400 12.5px/1.45 var(--font-sans);
}
.ecl-row:last-child { border-bottom: 0; }
.ecl-row-label { font-weight: 600; color: var(--text-strong); flex: 0 0 auto; }
.ecl-row-val { font: 700 12.5px/1.3 var(--font-mono); font-variant-numeric: tabular-nums; color: var(--text-strong); flex: 0 0 auto; }
.ecl-row-ctx { color: var(--muted); flex: 1 1 220px; min-width: 0; }
/* Tone cards */
.ecl-tones { display: grid; grid-template-columns: repeat(auto-fit, minmax(290px, 1fr)); gap: 12px; margin-top: 16px; }
.ecl-tone {
  padding: 12px 14px; border: 1px solid var(--border); border-radius: var(--r-2);
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
}
.ecl-tone-head { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; font: 600 12px/1 var(--font-sans); color: var(--text-strong); margin-bottom: 7px; }
.ecl-tone-sum { font: 400 12.5px/1.5 var(--font-sans); color: var(--text); margin: 0 0 8px; }
.ecl-phrase { display: flex; flex-direction: column; gap: 2px; padding: 6px 0; border-top: 1px dashed color-mix(in srgb, var(--border) 60%, transparent); }
.ecl-phrase-q { font: italic 400 12.5px/1.45 var(--font-sans); color: var(--text-strong); }
.ecl-phrase-who { font: 600 11px/1.3 var(--font-sans); color: var(--muted); }
.ecl-phrase-read { font: 400 11.5px/1.45 var(--font-sans); color: var(--muted); }
/* Q&A */
.ecl-qa { padding: 10px 0; border-bottom: 1px dashed color-mix(in srgb, var(--border) 60%, transparent); }
.ecl-qa:last-child { border-bottom: 0; }
.ecl-qa-q, .ecl-qa-a { font: 400 12.5px/1.5 var(--font-sans); color: var(--text); margin-bottom: 5px; }
.ecl-qa-who { display: block; font: 700 11.5px/1.3 var(--font-sans); color: var(--text-strong); }
.ecl-qa-firm { font-weight: 400; color: var(--muted); }
.ecl-qa-a { padding-left: 14px; border-left: 2px solid color-mix(in srgb, var(--accent) 35%, var(--border)); }
.ecl-qa-take { font: 400 11.5px/1.45 var(--font-sans); color: var(--muted); }
.ecl-foot { margin-top: 18px; padding-top: 10px; border-top: 1px solid var(--border); }
.ecl-foot-who { font: 400 11.5px/1.5 var(--font-sans); color: var(--muted); margin-bottom: 4px; }
.ecl-foot-src { font: 400 11px/1.5 var(--font-sans); color: var(--muted); }
.ecl-foot-src a { color: var(--accent); }

/* Earnings-call decision queue + progressive research detail. */
.ecl-queue {
  display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(420px, 1fr); gap: 18px;
  padding: 16px; margin: 2px 0 14px; border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--border));
  border-top: 3px solid var(--accent); border-radius: var(--r-3);
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 7%, var(--surface)), var(--surface) 62%);
}
.ecl-queue-head > span, .ecl-decision-head > span {
  display: block; margin-bottom: 5px; font: 700 10px/1 var(--font-sans); letter-spacing: .09em; text-transform: uppercase; color: var(--accent);
}
.ecl-queue-head h3, .ecl-decision-head h3 { margin: 0; font: 700 18px/1.2 var(--font-sans); color: var(--text-strong); }
.ecl-queue-head p, .ecl-decision-head p { margin: 6px 0 0; max-width: 70ch; font: 400 12.5px/1.5 var(--font-sans); color: var(--muted); }
.ecl-queue-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.ecl-queue-grid > span, .ecl-decision-grid > span {
  display: flex; flex-direction: column; justify-content: center; gap: 5px; min-width: 0; padding: 10px 11px;
  border: 1px solid color-mix(in srgb, var(--border) 78%, transparent); border-radius: var(--r-2); background: color-mix(in srgb, var(--surface-2) 76%, transparent);
}
.ecl-queue-grid small, .ecl-decision-grid small { font: 700 9px/1.2 var(--font-sans); letter-spacing: .06em; text-transform: uppercase; color: var(--muted); }
.ecl-queue-grid b, .ecl-decision-grid b { font: 700 14px/1.25 var(--font-mono); color: var(--text-strong); overflow-wrap: anywhere; }
.ecl-filters { display: flex; flex-wrap: wrap; gap: 6px; margin: -2px 0 12px; }
.ecl-filter, .ecl-more {
  border: 1px solid var(--border); border-radius: 999px; background: var(--surface); color: var(--muted);
  padding: 6px 10px; font: 650 11px/1 var(--font-sans); cursor: pointer;
}
.ecl-filter:hover, .ecl-more:hover { color: var(--text-strong); border-color: color-mix(in srgb, var(--accent) 52%, var(--border)); }
.ecl-filter.is-on { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 62%, var(--border)); background: color-mix(in srgb, var(--accent) 10%, var(--surface)); }
.ecl-card { position: relative; overflow: hidden; }
.ecl-card::before { content: ''; position: absolute; inset: 0 auto 0 0; width: 3px; background: var(--border); }
.ecl-card-positive::before { background: var(--pos); }
.ecl-card-caution::before { background: var(--neg); }
.ecl-card-watch::before { background: var(--warn); }
.ecl-card-action {
  width: fit-content; padding: 3px 7px; border-radius: 999px; font: 750 10px/1 var(--font-sans); letter-spacing: .03em; text-transform: uppercase;
}
.ecl-card-action-positive { color: var(--pos); background: color-mix(in srgb, var(--pos) 13%, transparent); }
.ecl-card-action-caution { color: var(--neg); background: color-mix(in srgb, var(--neg) 13%, transparent); }
.ecl-card-action-watch { color: var(--warn); background: color-mix(in srgb, var(--warn) 13%, transparent); }
.ecl-card-why { margin: 0; font: 400 11.5px/1.42 var(--font-sans); color: var(--muted); }
.ecl-more { display: block; margin: 14px auto 0; padding: 8px 14px; }
.ecl-decision {
  margin: 12px 0 14px; padding: 16px; border: 1px solid var(--border); border-top: 3px solid var(--warn);
  border-radius: var(--r-3); background: linear-gradient(145deg, color-mix(in srgb, var(--warn) 6%, var(--surface)), var(--surface) 58%);
}
.ecl-decision-positive { border-top-color: var(--pos); background: linear-gradient(145deg, color-mix(in srgb, var(--pos) 6%, var(--surface)), var(--surface) 58%); }
.ecl-decision-caution { border-top-color: var(--neg); background: linear-gradient(145deg, color-mix(in srgb, var(--neg) 6%, var(--surface)), var(--surface) 58%); }
.ecl-decision-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; margin-top: 12px; }
.ecl-decision-columns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 10px; }
.ecl-decision-columns > div { min-width: 0; padding: 11px 12px; border: 1px solid color-mix(in srgb, var(--border) 76%, transparent); border-radius: var(--r-2); background: color-mix(in srgb, var(--surface-2) 72%, transparent); }
.ecl-decision-columns h4 { margin: 0 0 7px; font: 700 10px/1 var(--font-sans); letter-spacing: .06em; text-transform: uppercase; color: var(--text-strong); }
.ecl-decision-columns .ecl-bullets { gap: 4px; }
.ecl-decision-columns .ecl-bullets li { font-size: 12px; line-height: 1.42; }
.ecl-decision-plan {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-top: 10px;
}
.ecl-decision-plan > div {
  min-width: 0; padding: 11px 12px; border: 1px solid color-mix(in srgb, var(--border) 76%, transparent);
  border-radius: var(--r-2); background: color-mix(in srgb, var(--surface) 76%, transparent);
}
.ecl-decision-plan .ecl-plan-posture {
  grid-column: 1 / -1; display: grid; grid-template-columns: minmax(120px, .45fr) minmax(0, 1fr); align-items: center; gap: 4px 14px;
  border-color: color-mix(in srgb, var(--accent) 34%, var(--border)); background: color-mix(in srgb, var(--accent) 7%, var(--surface));
}
.ecl-decision-plan span { display: block; margin-bottom: 6px; font: 700 9px/1.2 var(--font-sans); letter-spacing: .07em; text-transform: uppercase; color: var(--muted); }
.ecl-decision-plan b { display: block; font: 700 12.5px/1.4 var(--font-sans); color: var(--text-strong); }
.ecl-decision-plan .ecl-plan-posture span { margin: 0; color: var(--accent); }
.ecl-decision-plan .ecl-plan-posture b { font-size: 14px; }
.ecl-decision-plan .ecl-plan-posture p { grid-column: 2; margin: 1px 0 0; font: 400 11px/1.4 var(--font-sans); color: var(--muted); }
.ecl-decision-actions { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 10px; }
.ecl-decision-actions .ecl-action-primary, .ecl-decision-actions .ecl-action-secondary {
  display: inline-flex; align-items: center; justify-content: center; min-height: 36px; box-sizing: border-box; padding: 7px 11px;
  border: 1px solid var(--border); border-radius: 8px; font: 700 11px/1.15 var(--font-sans); text-decoration: none; cursor: pointer;
}
.ecl-decision-actions .ecl-action-primary { border-color: var(--accent); background: var(--accent); color: var(--surface); }
.ecl-decision-actions .ecl-action-secondary { background: var(--surface); color: var(--text); }
.ecl-decision-actions .ecl-action-primary:hover, .ecl-decision-actions .ecl-action-primary:focus-visible { filter: brightness(1.06); }
.ecl-decision-actions .ecl-action-secondary:hover, .ecl-decision-actions .ecl-action-secondary:focus-visible { border-color: var(--accent); color: var(--accent); background: var(--accent-soft); }
.ecl-decision-note { margin: 10px 0 0; padding-top: 9px; border-top: 1px solid color-mix(in srgb, var(--border) 70%, transparent); font: 400 11.5px/1.45 var(--font-sans); color: var(--muted); }
.ecl-research-stack { display: flex; flex-direction: column; gap: 8px; }
.ecl-disclosure { border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface); overflow: clip; }
.ecl-disclosure summary { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 11px 13px; cursor: pointer; list-style: none; }
.ecl-disclosure summary::-webkit-details-marker { display: none; }
.ecl-disclosure summary > span { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.ecl-disclosure summary b { font: 700 12.5px/1.2 var(--font-sans); color: var(--text-strong); }
.ecl-disclosure summary small { font: 400 11px/1.35 var(--font-sans); color: var(--muted); }
.ecl-disclosure summary em { flex: 0 0 auto; font: 650 10px/1 var(--font-sans); color: var(--muted); font-style: normal; text-transform: uppercase; letter-spacing: .05em; }
.ecl-disclosure[open] summary { border-bottom: 1px solid var(--border); background: color-mix(in srgb, var(--accent) 4%, var(--surface)); }
.ecl-disclosure[open] summary em { color: var(--accent); }
.ecl-disclosure-body { padding: 2px 14px 14px; }

@media (max-width: 720px) {
  .ecl-queue { grid-template-columns: 1fr; min-width: 0; gap: 12px; padding: 13px; }
  .ecl-queue-grid, .ecl-decision-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .ecl-toolbar { align-items: stretch; flex-direction: column; }
  .ecl-search { flex-basis: auto; width: 100%; box-sizing: border-box; }
  .ecl-filters { flex-wrap: nowrap; overflow-x: auto; padding-bottom: 4px; scrollbar-width: thin; }
  .ecl-filter { flex: 0 0 auto; }
  .ecl-cards { grid-template-columns: 1fr; }
  .ecl-card-top { flex-wrap: wrap; }
  .ecl-card-date { width: 100%; }
  .ecl-decision { padding: 13px; }
  .ecl-decision-columns { grid-template-columns: 1fr; }
  .ecl-decision-plan { grid-template-columns: 1fr; }
  .ecl-decision-plan .ecl-plan-posture { grid-column: auto; grid-template-columns: 1fr; }
  .ecl-decision-plan .ecl-plan-posture p { grid-column: auto; }
  .ecl-decision-actions { display: grid; grid-template-columns: 1fr; }
  .ecl-decision-actions .ecl-action-primary, .ecl-decision-actions .ecl-action-secondary { min-height: 42px; width: 100%; }
  .ecl-disclosure summary { align-items: flex-start; }
  .ecl-disclosure summary em { margin-top: 2px; }
  .ecl-row { align-items: flex-start; }
  .ecl-row-label, .ecl-row-val, .ecl-row-ctx { flex-basis: 100%; }
  .ecl-tones { grid-template-columns: 1fr; }
}

/* --- AI CapEx (Alt data) --------------------------------------------- */
.cx-desk {
  display: flex; flex-direction: column; gap: 11px; margin: 10px 0 12px; padding: 14px;
  border: 1px solid color-mix(in srgb, var(--accent) 30%, var(--border)); border-top: 3px solid var(--accent);
  border-radius: var(--r-3); background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 6%, var(--surface)), var(--surface) 64%);
