  color: var(--accent);
  font: 700 10px/1 var(--font-mono);
  letter-spacing: .09em;
  text-transform: uppercase;
}
.cmd-desk-head h3 { margin: 4px 0 3px; color: var(--text-strong); font: 750 17px/1.25 var(--font-sans); }
.cmd-desk-head p { margin: 0; max-width: 720px; color: var(--muted); font: 500 12px/1.45 var(--font-sans); }
