.cmd-posture {
  display: grid; grid-template-columns: 104px minmax(0, 1fr); gap: 10px; padding: 10px 11px;
  border: 1px solid var(--hairline); border-left: 3px solid var(--accent); border-radius: var(--r-2); background: var(--surface);
}
.cmd-posture-label { padding-top: 2px; color: var(--accent); font: 750 9px/1.2 var(--font-mono); letter-spacing: .08em; text-transform: uppercase; }
