.cmd-posture-positive .cmd-posture-label { color: var(--pos); }
.cmd-rules { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.cmd-rule { min-width: 0; padding: 9px 10px; border: 1px solid var(--hairline); border-radius: var(--r-2); background: var(--surface); }
.cmd-rule > span { display: block; margin-bottom: 4px; font: 750 9.5px/1 var(--font-mono); letter-spacing: .07em; text-transform: uppercase; }
.cmd-rule > p { margin: 0; color: var(--text); font: 500 11.5px/1.4 var(--font-sans); }
.cmd-rule-confirm { border-left: 3px solid var(--pos); }
.cmd-rule-confirm > span { color: var(--pos); }
.cmd-rule-invalidate { border-left: 3px solid var(--neg); }
.cmd-rule-invalidate > span { color: var(--neg); }
.cmd-driver-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 9px; }
.cmd-driver {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 11px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--border-strong);
  border-radius: var(--r-2);
  background: var(--surface-2);
}
.cmd-driver-up { border-left-color: var(--pos); }
.cmd-driver-down { border-left-color: var(--neg); }
.cmd-driver-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; color: var(--muted); font: 700 9px/1 var(--font-mono); letter-spacing: .07em; text-transform: uppercase; }
.cmd-driver-top em { color: var(--muted); font-style: normal; opacity: .78; }
.cmd-driver-main { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.cmd-driver-main > div { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.cmd-driver-main b { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-strong); font: 750 13px/1.2 var(--font-sans); }
.cmd-driver-main > div small { color: var(--muted); font: 650 11px/1 var(--font-mono); }
.cmd-driver-main strong { flex: 0 0 auto; color: var(--text-strong); font: 800 12px/1 var(--font-mono); font-variant-numeric: tabular-nums; text-align: right; }
.cmd-driver-up .cmd-driver-main strong { color: var(--pos); }
.cmd-driver-down .cmd-driver-main strong { color: var(--neg); }
.cmd-driver-main strong small { display: block; margin-top: 3px; color: var(--muted); font-size: 9px; text-transform: uppercase; }
.cmd-driver-impact { align-self: flex-start; padding: 3px 6px; border: 1px solid var(--border); border-radius: var(--r-pill); color: var(--muted-strong); font: 700 9px/1 var(--font-sans); }
.cmd-impact-up { border-color: color-mix(in srgb, var(--pos) 30%, var(--border)); }
.cmd-impact-down { border-color: color-mix(in srgb, var(--neg) 30%, var(--border)); }
.cmd-driver > p {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
  margin: 0;
  color: var(--muted-strong);
  font: 500 11px/1.42 var(--font-sans);
}
.cmd-driver-foot { display: flex; align-items: center; justify-content: space-between; gap: 7px; margin-top: auto; padding-top: 7px; border-top: 1px solid var(--hairline); }
.cmd-driver-foot > span { min-width: 0; display: flex; flex-wrap: wrap; gap: 4px; }
.cmd-driver-watch { padding: 2px 6px; border: 1px solid var(--border-strong); border-radius: var(--r-pill); color: var(--text); background: var(--surface); font: 700 9px/1 var(--font-mono); }
.cmd-driver-watch:hover, .cmd-driver-watch:focus-visible { border-color: var(--accent); color: var(--accent); }
.cmd-driver-foot button { appearance: none; flex: 0 0 auto; padding: 3px 0; border: 0; background: none; color: var(--accent); cursor: pointer; font: 700 9px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .04em; }
.cmd-actions { display: flex; flex-wrap: wrap; gap: 7px; }
.cmd-action {
  min-height: 36px; padding: 8px 12px; border: 1px solid var(--border-strong); border-radius: var(--r-pill);
  background: var(--surface); color: var(--text-strong); font: 700 11px/1 var(--font-sans); cursor: pointer;
}
.cmd-action:hover, .cmd-action:focus-visible { border-color: var(--accent); color: var(--accent); }
.cmd-action-primary { border-color: var(--accent); background: var(--accent); color: var(--surface); }
.cmd-action-primary:hover, .cmd-action-primary:focus-visible { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 86%, var(--text-strong)); color: var(--surface); }
.cmd-desk-note { margin: 0; color: var(--muted); font: 500 10.5px/1.4 var(--font-sans); }
.cmd-empty-desk {
  display: flex; flex-direction: column; align-items: flex-start; gap: 7px; margin: 10px 0 12px; padding: 16px;
  border: 1px dashed var(--border-strong); border-radius: var(--r-3); background: var(--surface-2);
}
.cmd-empty-desk h3 { margin: 0; color: var(--text-strong); font: 750 17px/1.25 var(--font-sans); }
.cmd-empty-desk p { margin: 0 0 3px; max-width: 760px; color: var(--muted); font: 500 12px/1.45 var(--font-sans); }
.cmd-group { margin-bottom: 8px; border: 1px solid var(--border); border-radius: var(--r-2); overflow: clip; background: var(--surface-2); }
.cmd-group[open] { border-color: color-mix(in srgb, var(--accent) 28%, var(--border)); }
.cmd-group-summary { display: flex; align-items: center; gap: 10px; min-height: 50px; padding: 9px 12px; list-style: none; cursor: pointer; }
.cmd-group-summary::-webkit-details-marker { display: none; }
.cmd-group-summary::before { content: "›"; flex: 0 0 auto; color: var(--accent); font: 750 18px/1 var(--font-mono); transition: transform var(--dur-1); }
.cmd-group[open] > .cmd-group-summary::before { transform: rotate(90deg); }
.cmd-group-summary > span:first-of-type { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.cmd-group-summary > span:first-of-type b { color: var(--text-strong); font: 750 12px/1.2 var(--font-sans); text-transform: uppercase; letter-spacing: .05em; }
.cmd-group-summary > span:first-of-type small { color: var(--muted); font: 500 10px/1 var(--font-mono); }
.cmd-group-lead { margin-left: auto; min-width: 0; display: flex; align-items: baseline; justify-content: flex-end; gap: 8px; }
.cmd-group-lead em { max-width: 190px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--muted-strong); font: 500 11px/1.2 var(--font-sans); font-style: normal; }
.cmd-group-lead b { flex: 0 0 auto; font: 750 11px/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.cmd-up { color: var(--pos); }
.cmd-down { color: var(--neg); }
.cmd-group-body { padding: 12px; border-top: 1px solid var(--hairline); background: var(--surface); }
.cmd-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 12px; }
.cmd-card {
  padding: 12px 14px; border: 1px solid var(--border); border-radius: var(--r-2);
  background: var(--surface); min-width: 0;
}
.cmd-card[open] { border-color: color-mix(in srgb, var(--accent) 30%, var(--border)); }
.cmd-card-missing { opacity: 0.75; }
.cmd-card-aged { opacity: 0.78; border-style: dashed; }
.cmd-card-missing .cmd-card-toggle { display: none; }
.cmd-card-summary { display: flex; flex-direction: column; gap: 7px; list-style: none; cursor: pointer; }
.cmd-card-summary::-webkit-details-marker { display: none; }
.cmd-card-body { display: flex; flex-direction: column; gap: 7px; margin-top: 9px; padding-top: 9px; border-top: 1px solid var(--hairline); }
.cmd-card-head { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.cmd-card-name { font: 700 13.5px/1.3 var(--font-sans); color: var(--text-strong); }
.cmd-card-toggle { margin-left: auto; color: var(--accent); font: 700 9px/1 var(--font-mono); letter-spacing: .05em; text-transform: uppercase; }
.cmd-card-toggle::before { content: "+ "; }
.cmd-card[open] .cmd-card-toggle::before { content: "− "; }
.cmd-badge {
  font: 700 9px/1 var(--font-sans); letter-spacing: .05em; text-transform: uppercase;
  padding: 2.5px 6px; border-radius: 999px; color: var(--muted);
  border: 1px solid var(--border); white-space: nowrap;
}
.cmd-badge-proxy { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 45%, transparent); }
.cmd-badge-stale { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 40%, transparent); }
.cmd-card-val {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 7px;
  font: 800 24px/1 var(--font-mono); color: var(--text-strong); font-variant-numeric: tabular-nums;
}
.cmd-card-unit { font: 600 10.5px/1.3 var(--font-sans); color: var(--muted); letter-spacing: 0.02em; }
.cmd-card-asof { font: 400 10.5px/1.3 var(--font-sans); color: var(--muted); margin-left: auto; }
.cmd-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.cmd-compare {
  display: flex; flex-direction: column; gap: 2px;
  padding: 7px 9px; border-radius: var(--r-1);
  background: color-mix(in srgb, var(--text-strong) 4%, transparent);
}
.cmd-cmp-row {
  display: flex; align-items: baseline; gap: 7px;
  font: 600 12px/1.5 var(--font-sans); font-variant-numeric: tabular-nums;
}
.cmd-cmp-label { color: var(--muted); font-size: 10.5px; flex: 0 0 62px; text-transform: uppercase; letter-spacing: 0.03em; }
.cmd-cmp-then { color: var(--muted); font-family: var(--font-mono); }
.cmd-cmp-arrow { color: var(--muted); font-size: 10px; }
.cmd-cmp-now { color: var(--text-strong); font-family: var(--font-mono); font-weight: 700; }
.cmd-cmp-pct { margin-left: auto; font: 800 12px/1.5 var(--font-sans); padding: 0 6px; border-radius: 4px; white-space: nowrap; }
.cmd-cmp-up .cmd-cmp-pct { color: var(--pos); background: color-mix(in srgb, var(--pos) 12%, transparent); }
.cmd-cmp-down .cmd-cmp-pct { color: var(--neg); background: color-mix(in srgb, var(--neg) 12%, transparent); }
.cmd-spark { width: 100%; height: 52px; display: block; }
.cmd-spark-line { stroke-width: 1.6; vector-effect: non-scaling-stroke; }
.cmd-spark-up .cmd-spark-line { stroke: var(--pos); }
.cmd-spark-down .cmd-spark-line { stroke: var(--neg); }
.cmd-overlay {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 5px 8px;
  padding: 7px 9px; border-radius: var(--r-1);
  border: 1px dashed color-mix(in srgb, var(--accent) 40%, transparent);
  background: color-mix(in srgb, var(--accent) 5%, transparent);
}
.cmd-overlay-label { font: 700 11px/1.3 var(--font-sans); color: var(--text-strong); flex-basis: 100%; }
.cmd-overlay-val { font: 700 15px/1 var(--font-mono); color: var(--text-strong); font-variant-numeric: tabular-nums; }
.cmd-overlay-ch { font: 700 11px/1 var(--font-sans); color: var(--muted); }
.cmd-overlay-src { font: 400 10px/1.3 var(--font-sans); color: var(--muted); flex-basis: 100%; }
.cmd-note { margin: 0; font: 400 11.5px/1.5 var(--font-sans); color: var(--muted); }
.cmd-foot { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-top: auto; }
.cmd-watch-row { display: inline-flex; flex-wrap: wrap; gap: 5px; }
.cmd-watch {
  font: 700 10.5px/1 var(--font-mono); padding: 3px 8px; border-radius: 999px;
  border: 1px solid var(--border); background: none; color: var(--text-strong); cursor: pointer;
}
@media (max-width: 900px) {
  .cmd-driver-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 640px) {
  .cmd-desk { padding: 11px; }
  .cmd-desk-head { align-items: flex-start; }
  .cmd-desk-breadth { flex-direction: column; }
  .cmd-desk-source { align-items: flex-start; flex-direction: column; gap: 4px; }
  .cmd-posture { grid-template-columns: 1fr; gap: 5px; padding: 9px 10px; }
  .cmd-posture-label { padding-top: 0; }
  .cmd-rules { grid-template-columns: minmax(0, 1fr); }
  .cmd-driver-grid { display: flex; overflow-x: auto; scroll-snap-type: x proximity; scrollbar-width: none; padding-bottom: 3px; }
  .cmd-driver-grid::-webkit-scrollbar { display: none; }
  .cmd-driver { flex: 0 0 min(260px, 79vw); scroll-snap-align: start; }
  .cmd-actions { display: grid; grid-template-columns: minmax(0, 1fr); }
  .cmd-action { min-height: 42px; width: 100%; }
  .cmd-group-summary { align-items: flex-start; gap: 7px; }
  .cmd-group-lead { max-width: 48%; flex-direction: column; align-items: flex-end; gap: 3px; }
  .cmd-group-lead em { max-width: 138px; }
  .cmd-group-body { padding: 8px; }
  .cmd-grid { grid-template-columns: minmax(0, 1fr); }
}
.cmd-watch:hover, .cmd-watch:focus-visible { border-color: var(--accent); color: var(--accent); }
.cmd-src { font: 400 10.5px/1.3 var(--font-sans); color: var(--muted); margin-left: auto; white-space: nowrap; }
.cmd-src:hover { color: var(--accent); }

/* --- Trending IV (Flow) ------------------------------------------------ */
.ivt-summary {
  margin: 0 0 14px; padding: 12px 14px;
  border: 1px solid var(--border); border-radius: var(--r-1);
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
}
.ivt-summary-text { margin: 0; font: 400 13px/1.55 var(--font-sans); color: var(--text-strong); }
.ivt-sum-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 9px; }
.ivt-sum-chip {
  display: inline-flex; align-items: baseline; gap: 5px;
  padding: 3.5px 9px; border: 1px solid var(--border); border-radius: 999px;
  font: 700 11.5px/1 var(--font-mono); color: var(--text-strong); cursor: pointer;
  font-variant-numeric: tabular-nums; background: none;
}
.ivt-sum-chip:hover, .ivt-sum-chip:focus-visible { border-color: var(--accent); color: var(--accent); }
.ivt-sum-chip em { font: 700 9px/1 var(--font-sans); letter-spacing: .05em; text-transform: uppercase; font-style: normal; color: var(--muted); }
/* Tier scale is an INTENSITY ramp, not a verdict — violet → blue → brass, so
   it can't be misread as bad/neutral/good (red/green stay reserved for
   direction/P&L site-wide). */
.ivt-sum-chip.ivt-tier-surging { border-color: color-mix(in srgb, var(--violet) 45%, transparent); }
.ivt-sum-chip.ivt-tier-surging em { color: var(--violet); }
.ivt-sum-chip.ivt-tier-trending em { color: var(--info); }
.ivt-sum-chip.ivt-tier-building em { color: var(--accent); }
.ivt-sum-chip.ivt-kind-extreme { border-color: color-mix(in srgb, var(--violet) 45%, transparent); }
.ivt-sum-chip.ivt-kind-extreme em, .ivt-sum-chip.ivt-kind-unexplained em { color: var(--violet); }
.ivt-sum-chip.ivt-kind-ramping em, .ivt-sum-chip.ivt-kind-streak em { color: var(--accent); }
.ivt-sum-chip.ivt-kind-falling em { color: var(--info); }
.ivt-sum-chip b { font: 700 11px/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.ivt-sort { display: flex; flex-wrap: wrap; gap: 6px; margin: 0 0 14px; }
.ivt-sort-chip {
  display: inline-flex; align-items: baseline; gap: 5px;
  padding: 5px 10px; border: 1px solid var(--border); border-radius: 999px;
  font: 600 11px/1 var(--font-sans); color: var(--muted); cursor: pointer;
  background: none; white-space: nowrap;
}
.ivt-sort-chip:hover, .ivt-sort-chip:focus-visible { border-color: var(--muted); color: var(--text-strong); }
.ivt-sort-chip[aria-pressed="true"] {
  border-color: var(--accent); color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}
.ivt-sort-chip b { font: 700 10px/1 var(--font-mono); font-variant-numeric: tabular-nums; opacity: .8; }
.ivt-search {
  margin-left: auto; min-width: 170px;
  padding: 5px 11px; border: 1px solid var(--border); border-radius: 999px;
  font: 600 11px/1.4 var(--font-sans); color: var(--text-strong); background: none;
}
.ivt-search::placeholder { color: var(--muted); }
.ivt-search:focus { border-color: var(--accent); outline: none; }
@media (max-width: 560px) { .ivt-search { margin-left: 0; flex: 1 1 100%; } }
.ivt-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 12px; margin-bottom: 18px; }
.ivt-card {
  display: flex; flex-direction: column; gap: 7px;
  padding: 12px 13px; border: 1px solid var(--border); border-radius: var(--r-1);
  background: var(--surface); border-left-width: 3px;
}
.ivt-card.ivt-tier-surging { border-left-color: var(--violet); }
.ivt-card.ivt-tier-trending { border-left-color: var(--info); }
.ivt-card.ivt-tier-building { border-left-color: var(--accent); }
.ivt-card-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 8px; }
.ivt-badge {
  font: 700 10px/1 var(--font-sans); letter-spacing: .06em; text-transform: uppercase;
  padding: 3px 7px; border-radius: 999px;
}
.ivt-tier-surging .ivt-badge { color: var(--violet); background: var(--violet-soft); }
.ivt-tier-trending .ivt-badge { color: var(--info); background: var(--info-soft); }
.ivt-tier-building .ivt-badge { color: var(--accent); background: color-mix(in srgb, var(--accent) 16%, transparent); }
/* The symbol is a button — click jumps to the Grade tab with the ticker loaded */
.ivt-sym { font: 700 15px/1 var(--font-mono); color: var(--text-strong); background: none; border: 0; padding: 0; cursor: pointer; display: inline-flex; align-items: baseline; gap: 3px; }
.ivt-sym:hover, .ivt-sym:focus-visible { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.ivt-sym:hover .stk-sym-go, .ivt-sym:focus-visible .stk-sym-go { color: var(--accent); }
.ivt-name { font: 400 11.5px/1.3 var(--font-sans); color: var(--muted); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 100%; flex: 1 1 auto; }
.ivt-sector { font: 600 10px/1 var(--font-sans); color: var(--muted); border: 1px solid var(--border); border-radius: 999px; padding: 2.5px 7px; white-space: nowrap; }
.ivt-stats { display: flex; flex-wrap: wrap; align-items: baseline; gap: 5px 10px; }
.ivt-stat { font: 500 12px/1.3 var(--font-sans); white-space: nowrap; }
.ivt-stat b { font: 700 14px/1 var(--font-mono); color: var(--text-strong); font-variant-numeric: tabular-nums; }
.ivt-z { font: 700 11.5px/1 var(--font-mono); padding: 2.5px 6px; border-radius: 5px; white-space: nowrap; font-variant-numeric: tabular-nums; }
.ivt-z-hot { color: var(--neg); background: color-mix(in srgb, var(--neg) 12%, transparent); }
.ivt-z-warm { color: var(--accent); background: color-mix(in srgb, var(--accent) 14%, transparent); }
.ivt-z-cool { color: var(--muted); background: color-mix(in srgb, var(--border) 40%, transparent); }
.ivt-streak { color: var(--pos); font-weight: 700; }
.ivt-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.ivt-chip { display: inline-flex; align-items: baseline; gap: 3px; white-space: nowrap; font: 600 11.5px/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.ivt-chip-label { font: 600 10px/1 var(--font-sans); color: var(--muted); }
.ivt-earn { font: 600 11.5px/1.4 var(--font-sans); color: var(--text-strong); }
.ivt-noearn { font: 500 11px/1.4 var(--font-sans); color: var(--muted); font-style: italic; }
.ivt-spark { width: 100%; height: 56px; display: block; margin-top: 2px; }
.ivt-spark-line { stroke: var(--accent); stroke-width: 1.6; vector-effect: non-scaling-stroke; }
.ivt-spark-mean { stroke: var(--muted); stroke-width: 1; stroke-dasharray: 4 3; vector-effect: non-scaling-stroke; opacity: .6; }
.ivt-none { font: 400 12.5px/1.5 var(--font-sans); color: var(--muted); margin: 0 0 14px; }
.ivt-table { border-top: 1px solid var(--border); }
.ivt-trow {
  display: grid; grid-template-columns: minmax(96px, 1.4fr) .7fr .7fr .5fr .7fr .7fr 1fr .6fr;
  gap: 4px 8px; align-items: baseline;
  padding: 6px 2px; border-bottom: 1px dashed color-mix(in srgb, var(--border) 60%, transparent);
}
.ivt-thead { font: 700 10px/1.2 var(--font-sans); letter-spacing: .05em; text-transform: uppercase; color: var(--muted); border-bottom: 1px solid var(--border); }
/* Clickable column headers on the ranked table — click sorts, click again reverses. */
.ivt-th-btn { font: inherit; letter-spacing: inherit; text-transform: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; white-space: nowrap; }
.ivt-th-btn:hover, .ivt-th-btn:focus-visible { color: var(--text-strong); text-decoration: underline; text-underline-offset: 3px; }
.ivt-th-btn.is-active { color: var(--accent); }
.ivt-th-arrow { font-style: normal; font-size: 8px; margin-left: 3px; }
.ivt-trow-sym { font: 700 12.5px/1.2 var(--font-mono); color: var(--text-strong); }
.ivt-trow-symbtn { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
.ivt-trow-symbtn:hover, .ivt-trow-symbtn:focus-visible { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.ivt-trow-tier { font: 700 9px/1 var(--font-sans); letter-spacing: .05em; text-transform: uppercase; font-style: normal; color: var(--muted); }
.ivt-trow-tier.ivt-elev { color: var(--accent); border-bottom: 1px dotted color-mix(in srgb, var(--accent) 55%, transparent); cursor: help; }
.ivt-trow.ivt-tier-surging .ivt-trow-tier { color: var(--violet); }
.ivt-trow.ivt-tier-trending .ivt-trow-tier { color: var(--info); }
.ivt-trow.ivt-tier-building .ivt-trow-tier { color: var(--accent); }
.ivt-trow-num { font: 500 12px/1.2 var(--font-mono); font-variant-numeric: tabular-nums; }
.ivt-trow-earn { font: 400 11px/1.2 var(--font-sans); color: var(--muted); white-space: nowrap; }
.ivt-show-all {
  margin-top: 10px; padding: 7px 14px; font: 600 12px/1 var(--font-sans);
  color: var(--text-strong); background: var(--surface); border: 1px solid var(--border);
  border-radius: 8px; cursor: pointer;
}
.ivt-show-all:hover { border-color: var(--muted); }
@media (max-width: 640px) {
  .ivt-trow { grid-template-columns: minmax(80px, 1.2fr) .8fr .8fr .8fr .8fr; }
  .ivt-trow > :nth-child(4), .ivt-trow > :nth-child(7), .ivt-trow > :nth-child(8) { display: none; }
}

/* --- Event Spillover Matrix (premium, docs/event-spillover.md) ---------- */
.spill-root { display: flex; flex-direction: column; gap: 14px; }
.spill-desk {
  display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(360px, .9fr); gap: 14px 18px; padding: 16px;
  border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--border)); border-top: 3px solid var(--accent);
  border-radius: var(--r-3); background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 7%, var(--surface)), var(--surface) 62%);
}
.spill-desk-head > span, .spill-validation-head > span {
  display: block; margin-bottom: 5px; font: 700 10px/1 var(--font-sans); letter-spacing: .09em; text-transform: uppercase; color: var(--accent);
}
.spill-desk-head h3, .spill-validation-head h3 { margin: 0; font: 700 18px/1.2 var(--font-sans); color: var(--text-strong); }
.spill-desk-head p, .spill-validation-head p { margin: 6px 0 0; max-width: 72ch; font: 400 12.5px/1.5 var(--font-sans); color: var(--muted); }
.spill-desk-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.spill-desk-grid > div {
  display: flex; flex-direction: column; justify-content: center; gap: 5px; min-width: 0; padding: 10px 11px;
  border: 1px solid color-mix(in srgb, var(--border) 78%, transparent); border-radius: var(--r-2); background: color-mix(in srgb, var(--surface-2) 76%, transparent);
}
.spill-desk-grid small { font: 700 9px/1.2 var(--font-sans); letter-spacing: .06em; text-transform: uppercase; color: var(--muted); }
.spill-desk-grid b { font: 700 17px/1.2 var(--font-mono); color: var(--text-strong); }
.spill-protocol { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.spill-protocol > div { display: flex; align-items: flex-start; gap: 9px; min-width: 0; padding: 10px 11px; border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface); }
.spill-protocol > div > span { display: inline-flex; align-items: center; justify-content: center; flex: 0 0 22px; width: 22px; height: 22px; border-radius: 999px; background: var(--accent-soft); color: var(--accent); font: 800 10px/1 var(--font-mono); }
.spill-protocol p { margin: 0; min-width: 0; }
.spill-protocol b { display: block; margin-bottom: 3px; font: 700 11.5px/1.25 var(--font-sans); color: var(--text-strong); }
.spill-protocol small { display: block; font: 400 11px/1.4 var(--font-sans); color: var(--muted); }
.spill-model-read { grid-column: 1 / -1; display: grid; grid-template-columns: auto minmax(160px, .65fr) minmax(0, 1fr); align-items: center; gap: 7px 12px; padding: 9px 11px; border: 1px solid var(--border); border-radius: var(--r-2); background: color-mix(in srgb, var(--surface-2) 72%, transparent); }
.spill-model-read > span, .spill-validation-verdict > span { font: 700 9px/1.2 var(--font-sans); letter-spacing: .07em; text-transform: uppercase; color: var(--muted); }
.spill-model-read > b, .spill-validation-verdict > b { font: 700 12px/1.35 var(--font-sans); color: var(--text-strong); }
.spill-model-read > p, .spill-validation-verdict > p { margin: 0; font: 400 11px/1.4 var(--font-sans); color: var(--muted); }
.spill-model-read-leader { border-color: color-mix(in srgb, var(--pos) 38%, var(--border)); background: color-mix(in srgb, var(--pos) 6%, var(--surface)); }
.spill-model-read-early, .spill-model-read-building { border-color: color-mix(in srgb, var(--warn) 38%, var(--border)); background: color-mix(in srgb, var(--warn) 6%, var(--surface)); }
.spill-tools { display: flex; align-items: center; gap: 8px; }
.spill-search { flex: 0 1 280px; min-width: 160px; background: var(--surface); border: 1px solid var(--border); border-radius: var(--r-1); padding: 8px 11px; font: 600 12.5px/1.2 var(--font-mono); letter-spacing: .03em; color: var(--text-strong); text-transform: uppercase; }
.spill-search::placeholder { font: 400 12px/1.2 var(--font-sans); letter-spacing: 0; color: var(--muted); text-transform: none; }
.spill-search:focus { outline: none; border-color: var(--accent); }
.spill-btn { cursor: pointer; border: 1px solid var(--border); background: var(--surface); color: var(--muted-strong); border-radius: var(--r-1); padding: 7px 11px; font: 600 11px/1.2 var(--font-sans); }
.spill-btn:hover { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 45%, var(--border)); }
.spill-showall { align-self: flex-start; }
.spill-sub { font: 700 11px/1.2 var(--font-sans); letter-spacing: .05em; text-transform: uppercase; color: var(--muted-strong); margin-top: 4px; }
.spill-matrix-details { overflow: hidden; border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface); }
.spill-matrix-details > summary {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  min-height: 46px; padding: 10px 12px; cursor: pointer; list-style: none;
}
.spill-matrix-details > summary::-webkit-details-marker { display: none; }
.spill-matrix-details > summary span { color: var(--text-strong); font: 700 12px/1.2 var(--font-sans); }
.spill-matrix-details > summary small { display: block; margin-top: 4px; color: var(--muted); font: 500 9.5px/1.2 var(--font-sans); }
.spill-matrix-details > summary em { margin-left: auto; color: var(--muted); font: 600 9.5px/1.2 var(--font-mono); font-style: normal; white-space: nowrap; }
.spill-matrix-details > summary::after { content: '›'; color: var(--accent); font: 800 18px/1 var(--font-mono); transition: transform .15s ease; }
.spill-matrix-details[open] > summary::after { transform: rotate(90deg); }
.spill-matrix-details > summary:hover { background: var(--surface-2); }
.spill-matrix-body { display: flex; flex-direction: column; gap: 10px; padding: 0 12px 12px; border-top: 1px solid var(--border); }
.spill-matrix-body > .spill-none:first-child { padding-top: 10px; }
.spill-none { font: 400 12.5px/1.5 var(--font-sans); color: var(--muted); margin: 0; }
.spill-events { display: flex; flex-direction: column; gap: 10px; }
.spill-ev { border: 1px solid var(--border); border-left: 3px solid var(--border); border-radius: var(--r-2); padding: 11px 12px; display: flex; flex-direction: column; gap: 9px; background: var(--surface); }
.spill-ev-clean { border-left-color: var(--pos); }
.spill-ev-flagged { border-left-color: var(--warn); }
.spill-ev-conflict { border-left-color: var(--neg); }
.spill-ev-context { border-left-color: var(--muted); }
.spill-ev-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 8px; font: 400 13px/1.4 var(--font-sans); color: var(--text-strong); }
.spill-ev-imp { font: 600 11.5px/1.2 var(--font-mono); color: var(--muted-strong); font-variant-numeric: tabular-nums; }
.spill-ev-guide { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 10px 18px; padding: 10px 11px; border: 1px solid color-mix(in srgb, var(--border) 78%, transparent); border-radius: var(--r-2); background: color-mix(in srgb, var(--surface-2) 72%, transparent); }
.spill-ev-guide > div > span { display: block; margin-bottom: 4px; font: 700 9px/1.2 var(--font-sans); letter-spacing: .07em; text-transform: uppercase; color: var(--muted); }
.spill-ev-guide > div > b { display: block; font: 700 12.5px/1.3 var(--font-sans); color: var(--text-strong); }
.spill-ev-guide > div > p { margin: 4px 0 0; font: 400 11px/1.42 var(--font-sans); color: var(--muted); }
.spill-ev-guide dl { display: grid; grid-template-columns: repeat(2, minmax(72px, 1fr)); gap: 7px; margin: 0; }
.spill-ev-guide dl > div { min-width: 0; padding: 7px 9px; border-left: 1px solid var(--border); }
.spill-ev-guide dt { font: 700 8.5px/1.2 var(--font-sans); letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
.spill-ev-guide dd { margin: 4px 0 0; font: 700 14px/1.2 var(--font-mono); color: var(--text-strong); }
.spill-chip { font: 700 9.5px/1 var(--font-sans); letter-spacing: .05em; text-transform: uppercase; padding: 3px 8px; border-radius: 999px; border: 1px solid var(--border); color: var(--muted-strong); cursor: default; }
.spill-chip[title] { cursor: help; }
.spill-iso-clean { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 45%, transparent); }
.spill-iso-flagged { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 45%, transparent); }
.spill-iso-conflict { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 45%, transparent); }
.spill-scroll { overflow-x: auto; }
.spill-tbl { width: 100%; border-collapse: collapse; font: 500 12px/1.35 var(--font-mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
.spill-tbl th { font: 700 10px/1.2 var(--font-sans); letter-spacing: .05em; text-transform: uppercase; color: var(--muted); text-align: left; padding: 5px 10px 5px 0; border-bottom: 1px solid var(--border); }
.spill-tbl td { padding: 5px 10px 5px 0; border-bottom: 1px dashed color-mix(in srgb, var(--border) 60%, transparent); }
.spill-sym { font: 700 12.5px/1.2 var(--font-mono); color: var(--text-strong); text-decoration: none; }
.spill-sym:hover, .spill-sym:focus-visible { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.spill-arrow { color: var(--muted); margin: 0 3px; }
.spill-row-dim td { color: var(--muted); }
.spill-row-dim .spill-sym { color: var(--muted-strong); }
.spill-row-q td { color: var(--text-strong); }
.spill-edge-pos { color: var(--pos); font-weight: 700; }
.spill-edge-neg { color: var(--muted-strong); }
.spill-q { color: var(--pos); font: 700 10px/1 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; }
.spill-nq { color: var(--muted); font: 600 10.5px/1 var(--font-sans); }
.spill-validation { display: grid; grid-template-columns: minmax(0, 1fr) minmax(360px, .95fr); gap: 12px 18px; padding: 15px; border: 1px solid var(--border); border-radius: var(--r-3); background: color-mix(in srgb, var(--surface-2) 52%, var(--surface)); }
.spill-engines { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.spill-engine { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px 10px; padding: 10px 11px; border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface); }
.spill-engine > span { grid-column: 1 / -1; font: 750 11px/1.2 var(--font-sans); color: var(--text-strong); }
.spill-engine > small { grid-column: 1 / -1; margin-top: -5px; font: 400 9.5px/1.3 var(--font-sans); color: var(--muted); }
.spill-engine > div { min-width: 0; }
.spill-engine > div b { display: block; font: 700 13px/1.2 var(--font-mono); color: var(--text-strong); }
.spill-engine > div em { display: block; margin-top: 3px; font: 600 8.5px/1.2 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; color: var(--muted); font-style: normal; }
.spill-engine > p { grid-column: 1 / -1; margin: 0; padding-top: 5px; border-top: 1px dashed var(--border); font: 400 9.5px/1.3 var(--font-sans); color: var(--muted); }
.spill-validation-verdict { grid-column: 1 / -1; display: grid; grid-template-columns: auto minmax(160px, .65fr) minmax(0, 1fr); align-items: center; gap: 7px 12px; padding: 9px 11px; border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface); }
.spill-note { font: 400 11.5px/1.55 var(--font-sans); color: var(--muted); margin: 0; }
.spill-ev-grp { color: var(--muted-strong); }
.spill-group { border: 1px solid var(--border); border-radius: var(--r-1); background: var(--surface); }
.spill-group summary { cursor: pointer; padding: 9px 12px; font: 600 12px/1.4 var(--font-sans); color: var(--text-strong); }
.spill-group summary:hover { color: var(--accent); }
.spill-group[open] summary { border-bottom: 1px dashed color-mix(in srgb, var(--border) 60%, transparent); }
.spill-group-etf { font: 600 10.5px/1 var(--font-mono); color: var(--muted); }
.spill-group .spill-scroll, .spill-group .spill-none { padding: 8px 12px; margin: 0; }
@media (max-width: 760px) {
  .spill-desk, .spill-validation { grid-template-columns: 1fr; padding: 13px; }
  .spill-protocol { grid-template-columns: 1fr; }
  .spill-model-read, .spill-validation-verdict { grid-template-columns: 1fr; gap: 4px; }
  .spill-ev-guide { grid-template-columns: 1fr; }
  .spill-ev-guide dl { width: 100%; }
  .spill-ev-guide dl > div:first-child { border-left: 0; }
}
@media (max-width: 460px) {
  .spill-desk-grid, .spill-engines { grid-template-columns: 1fr; }
  .spill-tools { align-items: stretch; flex-direction: column; }
  .spill-search, .spill-btn { width: 100%; box-sizing: border-box; }
}

/* --- Quant Lab (deterministic screens, premium) ------------------------ */
.dt-lab { display: flex; flex-direction: column; gap: 12px; margin-bottom: 20px; padding: 15px; border: 1px solid color-mix(in srgb, var(--accent) 42%, var(--border)); border-radius: 12px; background: linear-gradient(145deg, color-mix(in srgb, var(--accent) 5%, var(--surface)), var(--surface) 48%); }
.dt-lab-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.dt-lab-head > div > span { display: block; margin-bottom: 4px; color: var(--accent); font: 750 9px/1 var(--font-mono); letter-spacing: .09em; text-transform: uppercase; }
.dt-lab-head h2, .dt-lab-head h3 { margin: 0; color: var(--text-strong); font: 780 19px/1.2 var(--font-sans); }
.dt-stamp { padding: 5px 8px; border: 1px solid var(--border); border-radius: 999px; color: var(--muted-strong); background: var(--surface); font: 700 9px/1 var(--font-mono); text-transform: capitalize; white-space: nowrap; }
.dt-root { display: flex; flex-direction: column; gap: 12px; }
.dt-market { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); overflow: hidden; border: 1px solid var(--border); border-radius: 9px; background: var(--surface); }
.dt-market > span { display: flex; flex-direction: column; gap: 4px; min-width: 0; padding: 9px 10px; border-right: 1px solid var(--border); }
.dt-market > span:last-child { border-right: 0; }
.dt-market small, .dt-book small, .dt-analytics small { color: var(--muted); font: 700 8.5px/1.1 var(--font-mono); letter-spacing: .055em; text-transform: uppercase; }
.dt-market b { color: var(--text-strong); font: 750 12px/1.2 var(--font-sans); text-transform: capitalize; }
.dt-market em { color: var(--muted); font: 500 9px/1.35 var(--font-sans); font-style: normal; overflow-wrap: anywhere; }
.dt-books { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.dt-book { min-width: 0; padding: 11px 12px; border: 1px solid var(--border); border-radius: 9px; background: var(--surface); }
.dt-book-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; margin-bottom: 9px; }
.dt-book-head h4 { margin: 3px 0 0; color: var(--text-strong); font: 760 18px/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.dt-book-head > span { padding: 4px 7px; border-radius: 999px; border: 1px solid var(--border); color: var(--muted-strong); font: 700 8.5px/1 var(--font-sans); text-transform: uppercase; white-space: nowrap; }
.dt-book-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; }
.dt-book-grid > span { display: flex; flex-direction: column; gap: 3px; padding: 7px 8px; border-radius: 7px; background: var(--surface-2); }
.dt-book-grid b { color: var(--text-strong); font: 700 11px/1.25 var(--font-mono); font-variant-numeric: tabular-nums; }
.dt-track { margin-top: 9px; border-top: 1px dashed var(--border); }
.dt-track summary { padding-top: 8px; color: var(--accent); cursor: pointer; font: 700 10px/1.3 var(--font-sans); }
.dt-analytics { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 5px; margin-top: 8px; }
.dt-analytics > span { display: flex; flex-direction: column; gap: 2px; min-width: 0; padding: 7px; border: 1px solid var(--border); border-radius: 6px; }
.dt-analytics b { color: var(--text-strong); font: 700 10.5px/1.25 var(--font-mono); }
.dt-analytics em { color: var(--muted); font: 500 8.5px/1.3 var(--font-sans); font-style: normal; overflow-wrap: anywhere; }
.dt-table .dt-wrap { min-width: 190px; white-space: normal; color: var(--muted-strong); font-family: var(--font-sans); }
.quant-warn { color: var(--warn) !important; }
@media (max-width: 900px) { .dt-market { grid-template-columns: repeat(2, minmax(0, 1fr)); } .dt-market > span { border-bottom: 1px solid var(--border); } .dt-books { grid-template-columns: 1fr; } }
@media (max-width: 520px) { .dt-lab { padding: 11px; } .dt-lab-head { flex-direction: column; } .dt-market, .dt-book-grid, .dt-analytics { grid-template-columns: 1fr; } .dt-market > span { border-right: 0; } }

/* Tools → Refresh schedule. Static, workflow-backed publication map. */
.refresh-schedule { display: flex; flex-direction: column; gap: 14px; }
.refresh-schedule-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.refresh-schedule-card { display: flex; flex-direction: column; gap: 7px; min-width: 0; padding: 14px; border: 1px solid var(--border); border-radius: 10px; background: var(--surface-2); }
.refresh-schedule-card.is-lead { border-color: color-mix(in srgb, var(--accent) 56%, var(--border)); background: linear-gradient(145deg, color-mix(in srgb, var(--accent) 8%, var(--surface-2)), var(--surface-2) 62%); }
.refresh-schedule-card > span { color: var(--accent); font: 750 10px/1.25 var(--font-mono); letter-spacing: .045em; text-transform: uppercase; }
.refresh-schedule-card h3 { margin: 0; color: var(--text-strong); font: 760 17px/1.2 var(--font-sans); }
.refresh-schedule-card p { margin: 0; color: var(--muted-strong); font-size: 12px; line-height: 1.52; }
.refresh-schedule-card em { margin-top: auto; padding-top: 4px; color: var(--muted); font: 650 9px/1.3 var(--font-mono); font-style: normal; text-transform: uppercase; letter-spacing: .035em; }
.refresh-schedule-rule { padding: 11px 12px; border-left: 3px solid var(--accent); border-radius: 0 8px 8px 0; background: color-mix(in srgb, var(--accent) 6%, var(--surface-2)); color: var(--muted-strong); font-size: 12px; line-height: 1.5; }
.refresh-schedule-rule b { color: var(--text-strong); }
@media (max-width: 720px) { .refresh-schedule-grid { grid-template-columns: 1fr; } }
.owner-suite { display: flex; flex-direction: column; gap: 13px; margin-bottom: 20px; padding: 16px; border: 1px solid color-mix(in srgb, var(--accent) 46%, var(--border)); border-radius: 14px; background: linear-gradient(145deg, color-mix(in srgb, var(--accent) 7%, var(--surface)), var(--surface) 46%); }
.owner-suite-head { display: grid; grid-template-columns: minmax(180px, .7fr) minmax(260px, 1.3fr); gap: 18px; align-items: end; padding-bottom: 12px; border-bottom: 1px solid var(--border); }
.owner-suite-head span, .owner-risk-card > header small { display: block; margin-bottom: 4px; color: var(--accent); font: 750 9px/1 var(--font-mono); letter-spacing: .09em; text-transform: uppercase; }
.owner-suite-head h3, .owner-risk-card > header h3 { margin: 0; color: var(--text-strong); font: 780 19px/1.2 var(--font-sans); }
.owner-suite-head p, .owner-risk-card > header p { margin: 0; color: var(--muted); font: 450 11.5px/1.5 var(--font-sans); }
.owner-position { margin: 0; }
.owner-tool-root { min-width: 0; }
.owner-tool-loading { margin: 0; padding: 11px 12px; border: 1px dashed var(--border); border-radius: 8px; color: var(--muted); font: 500 11px/1.45 var(--font-sans); }
.owner-risk-card { display: flex; flex-direction: column; gap: 11px; padding: 13px; border: 1px solid var(--border); border-radius: 10px; background: color-mix(in srgb, var(--surface-2) 66%, transparent); }
.owner-risk-card > header { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; }
.owner-risk-card > header p { max-width: 620px; }
.owner-size-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.owner-size-row { min-width: 0; padding: 9px 10px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); }
.owner-size-row > header { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-bottom: 7px; }
.owner-size-row > header > span:not(.rot-live):not(.lev-dir) { color: var(--muted-strong); font: 650 10px/1.2 var(--font-sans); }
.owner-size-row .rot-live, .owner-size-row .lev-live { margin-left: auto; }
.owner-size-row .rot-size, .owner-size-row .lev-size { margin-top: 0; }
@media (max-width: 760px) { .owner-suite-head { grid-template-columns: 1fr; align-items: start; } .owner-size-list { grid-template-columns: 1fr; } .owner-risk-card > header { align-items: flex-start; flex-direction: column; } }
.quant-root { display: flex; flex-direction: column; gap: 14px; }
.quant-desk { display: flex; flex-direction: column; gap: 10px; padding: 13px 14px; border: 1px solid color-mix(in srgb, var(--accent) 34%, var(--border)); border-left: 3px solid var(--accent); border-radius: 10px; background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 5%, var(--surface)), var(--surface) 62%); }
.quant-desk.is-reference { border-color: color-mix(in srgb, var(--warn) 40%, var(--border)); border-left-color: var(--warn); background: linear-gradient(135deg, color-mix(in srgb, var(--warn) 6%, var(--surface)), var(--surface) 62%); }
.quant-desk-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.quant-desk-head > div { min-width: 0; }
.quant-desk-kicker { display: block; margin-bottom: 4px; color: var(--accent); font: 700 9px/1 var(--font-mono); letter-spacing: .08em; text-transform: uppercase; }
.quant-desk.is-reference .quant-desk-kicker { color: var(--warn); }
.quant-desk h3 { margin: 0; color: var(--text-strong); font: 760 16px/1.25 var(--font-sans); }
.quant-desk-freshness { flex: 0 0 auto; padding: 4px 7px; border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--border)); border-radius: 999px; color: var(--accent); background: var(--surface); font: 700 9px/1 var(--font-mono); white-space: nowrap; }
.quant-desk.is-reference .quant-desk-freshness { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 38%, var(--border)); }
.quant-desk-read { margin: 0; color: var(--muted-strong); font: 500 11.5px/1.5 var(--font-sans); }
.quant-focus-map { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); overflow: hidden; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); }
.quant-focus-map > span { display: flex; flex-direction: column; gap: 3px; min-width: 0; padding: 8px 9px; border-right: 1px solid var(--border); }
.quant-focus-map > span:last-child { border-right: 0; }
.quant-focus-map small, .quant-desk-metric small { color: var(--muted); font: 700 8px/1 var(--font-mono); letter-spacing: .06em; text-transform: uppercase; }
.quant-focus-map b { color: var(--text-strong); font: 700 11px/1.25 var(--font-sans); overflow-wrap: anywhere; }
.quant-focus-map em { color: var(--muted); font: 500 9px/1.3 var(--font-sans); font-style: normal; overflow-wrap: anywhere; }
.quant-focus-empty { display: flex; flex-direction: column; gap: 4px; padding: 9px 10px; border: 1px dashed var(--border-strong); border-radius: 8px; background: var(--surface); }
.quant-focus-empty b { color: var(--text-strong); font: 700 11px/1.3 var(--font-sans); }
.quant-focus-empty span { color: var(--muted); font: 500 10px/1.4 var(--font-sans); }
.quant-desk-actions { display: flex; flex-wrap: wrap; gap: 6px; }
.quant-desk-actions .flow-decision-action { text-decoration: none; }
.quant-desk-metrics { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; }
.quant-desk-metric { appearance: none; display: flex; flex-direction: column; align-items: flex-start; gap: 3px; min-width: 0; min-height: 58px; padding: 8px 9px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface-2); color: inherit; text-align: left; cursor: pointer; }
.quant-desk-metric:hover, .quant-desk-metric:focus-visible { border-color: var(--accent); background: var(--accent-soft); }
.quant-desk-metric b { color: var(--text-strong); font: 750 14px/1.1 var(--font-mono); font-variant-numeric: tabular-nums; }
.quant-desk-metric span { color: var(--muted); font: 500 9.5px/1.25 var(--font-sans); overflow-wrap: anywhere; }
.quant-desk-rule { margin: 0; color: var(--muted); font: 500 10px/1.45 var(--font-sans); }
