.quant-tbl th { font: 700 10px/1.2 var(--font-sans); letter-spacing: .05em; text-transform: uppercase; color: var(--muted); text-align: left; padding: 5px 10px 5px 0; border-bottom: 1px solid var(--border); }
.quant-tbl td { padding: 5px 10px 5px 0; border-bottom: 1px dashed color-mix(in srgb, var(--border) 60%, transparent); }
.quant-sym { font: 700 12.5px/1.2 var(--font-mono); color: var(--text-strong); text-decoration: none; }
.quant-sym:hover, .quant-sym:focus-visible { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.quant-vs { color: var(--muted); margin: 0 3px; }
.quant-dim { color: var(--muted); }
.quant-pos { color: var(--pos); }
.quant-neg { color: var(--neg); }
.quant-z { font-weight: 700; }
.quant-z-hot { color: var(--neg); }
.quant-z-cold { color: var(--pos); }
.quant-z-warm { color: var(--accent); }
.quant-sit { font: 700 10px/1 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; padding: 3px 8px; border-radius: 999px; border: 1px solid var(--border); white-space: nowrap; }
.quant-sit-pos { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 40%, transparent); }
.quant-sit-neg { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 40%, transparent); }
.quant-em, .quant-read { font: 400 11.5px/1.4 var(--font-sans); color: var(--muted-strong); white-space: normal; min-width: 180px; }
.quant-mr-ok { color: var(--pos); font: 600 11px/1.2 var(--font-sans); }
.quant-mr-no { color: var(--muted); font: 600 11px/1.2 var(--font-sans); cursor: help; }
.quant-cols { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 12px; }
.quant-mini { border: 1px solid var(--border); border-radius: var(--r-1); padding: 10px 12px; background: var(--surface); min-width: 0; }
.quant-mini-title { font: 700 11px/1.3 var(--font-sans); color: var(--text-strong); margin-bottom: 6px; }
.quant-disp { font: 400 12.5px/1.6 var(--font-sans); color: var(--muted-strong); border: 1px solid var(--border); border-radius: var(--r-1); padding: 10px 12px; background: var(--surface); }
.quant-disp b { color: var(--text-strong); font-variant-numeric: tabular-nums; }
.quant-collecting { color: var(--accent); font-weight: 600; }
.quant-playbook { display: flex; flex-direction: column; gap: 6px; }
.quant-tbl-wrap { overflow-x: auto; }
.quant-play-tbl { font: 400 12px/1.45 var(--font-sans); white-space: normal; }
.quant-play-tbl td { color: var(--muted-strong); min-width: 140px; }
.quant-play-tbl td:first-child { font-weight: 650; color: var(--text-strong); }
.quant-empty { font: 400 12.5px/1.5 var(--font-sans); color: var(--muted); }
/* Aggregate ideas (confluence screen) */
.quant-conf-note { border-style: solid; }
.quant-conf-count { font: 700 11px/1 var(--font-mono); color: var(--muted-strong); border: 1px solid var(--border); border-radius: 999px; padding: 3px 7px; white-space: nowrap; }
.quant-conf-count.is-q { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 45%, transparent); }
.quant-conf-q { font: 700 10px/1 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; color: var(--accent); border: 1px solid color-mix(in srgb, var(--accent) 45%, transparent); border-radius: 999px; padding: 3px 8px; white-space: nowrap; }
.quant-conf-qrow td { background: color-mix(in srgb, var(--accent) 5%, transparent); }
.quant-conf-lean { font: 700 10px/1 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; }
.quant-conf-src { font-size: 11.5px; }
/* Regime conditioning strip + regime-adjusted badges */
.quant-regime { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; border: 1px solid var(--border); border-radius: var(--r-1); padding: 9px 12px; background: var(--surface); }
.quant-reg-title { font: 700 10px/1.2 var(--font-sans); letter-spacing: .05em; text-transform: uppercase; color: var(--muted); cursor: help; }
.quant-reg-chip { display: inline-flex; align-items: baseline; gap: 5px; font: 700 11px/1 var(--font-sans); color: var(--text-strong); border: 1px solid var(--border); border-radius: 999px; padding: 4px 9px; white-space: nowrap; cursor: help; }
.quant-reg-chip em { font: 700 9px/1 var(--font-sans); font-style: normal; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
.quant-reg-chip.is-good { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 40%, transparent); }
.quant-reg-chip.is-warn { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 45%, transparent); }
.quant-reg-chip.is-bad { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 45%, transparent); }
.quant-reg-bars { flex-basis: 100%; font: 400 11.5px/1.5 var(--font-sans); color: var(--muted); }
.quant-pri { font: 700 9.5px/1 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; color: var(--neg); border: 1px solid color-mix(in srgb, var(--neg) 45%, transparent); border-radius: 999px; padding: 2px 7px; white-space: nowrap; cursor: help; }
.quant-pri-cold { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 45%, transparent); }
.quant-deprio td { opacity: .62; }
.quant-evt { font: 700 9.5px/1 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; color: var(--warn); border: 1px solid color-mix(in srgb, var(--warn) 45%, transparent); border-radius: 999px; padding: 2px 7px; white-space: nowrap; cursor: help; }
/* Pairs methodology cells */
.quant-eg-ok { font: 700 10px/1 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; color: var(--pos); border: 1px solid color-mix(in srgb, var(--pos) 40%, transparent); border-radius: 999px; padding: 3px 8px; white-space: nowrap; cursor: help; }
.quant-eg-no { color: var(--muted); font: 600 11px/1.2 var(--font-sans); cursor: help; }
.quant-stab-ok { font: 700 9.5px/1 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; color: var(--pos); cursor: help; }
.quant-stab-no { font: 700 9.5px/1 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; color: var(--warn); cursor: help; }
.quant-match { font: 700 10px/1 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; border: 1px solid var(--border); border-radius: 999px; padding: 3px 8px; white-space: nowrap; cursor: help; }
.quant-match-good { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 40%, transparent); }
.quant-match-fair { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 45%, transparent); }
.quant-match-poor { color: var(--muted); }
.quant-ready, .quant-watch { display: inline-flex; align-items: center; padding: 3px 7px; border: 1px solid var(--border); border-radius: 999px; font: 700 9px/1 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; white-space: nowrap; cursor: help; }
.quant-ready { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 42%, var(--border)); background: color-mix(in srgb, var(--pos) 7%, transparent); }
.quant-watch { color: var(--muted); }
.quant-ready-row td { background: color-mix(in srgb, var(--pos) 4%, transparent); }

@media (max-width: 760px) {
  .quant-desk-head { flex-direction: column; }
  .quant-desk-freshness { white-space: normal; }
  .quant-focus-map { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .quant-focus-map > span { border-bottom: 1px solid var(--border); }
  .quant-focus-map > span:nth-child(2n) { border-right: 0; }
  .quant-focus-map > span:nth-last-child(-n+2) { border-bottom: 0; }
  .quant-desk-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 480px) {
  .quant-desk { padding: 11px; }
  .quant-desk-actions { display: grid; grid-template-columns: minmax(0, 1fr); }
  .quant-desk-actions .flow-decision-action { width: 100%; min-height: 42px; justify-content: center; }
  .quant-desk-metric { min-height: 64px; }
}

/* --- Stock Picks (quality-dip screen, premium) ------------------------- */
.stk-root { display: flex; flex-direction: column; gap: 14px; }
.stk-desk { display: flex; align-items: flex-start; justify-content: space-between; gap: 18px; padding: 14px; border: 1px solid color-mix(in srgb, var(--accent) 30%, var(--border)); border-radius: 12px; background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 5%, var(--surface)), var(--surface) 58%); }
.stk-desk > div:first-child { min-width: 0; max-width: 720px; }
.stk-desk-kicker { display: block; margin-bottom: 5px; color: var(--accent); font: 700 9.5px/1 var(--font-mono); letter-spacing: .09em; text-transform: uppercase; }
.stk-desk h3 { margin: 0; color: var(--text-strong); font: 750 17px/1.3 var(--font-sans); }
.stk-desk p { margin: 6px 0 0; color: var(--muted-strong); font: 400 12px/1.5 var(--font-sans); }
.stk-desk-stats { display: grid; grid-template-columns: repeat(3, minmax(88px, 1fr)); gap: 6px; flex: 0 0 auto; }
.stk-desk-stats > span { display: flex; flex-direction: column; gap: 3px; min-width: 0; padding: 8px 9px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface-2); }
.stk-desk-stats b { color: var(--text-strong); font: 800 18px/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.stk-desk-stats small { color: var(--muted); font: 650 8px/1.2 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; }
.stk-desk-start b { color: var(--pos); }
.stk-desk-wait b { color: var(--warn); }
.stk-desk-research b { color: var(--neg); }
.stk-funnel { font: 400 12.5px/1.55 var(--font-sans); color: var(--muted-strong); margin: 0; }
.stk-funnel b { font-weight: 700; color: var(--text-strong); font-variant-numeric: tabular-nums; }
.stk-tiers { display: flex; flex-direction: column; gap: 18px; }
.stk-tier { display: flex; flex-direction: column; gap: 13px; padding: 14px; border: 1px solid var(--border); border-radius: 12px; background: color-mix(in srgb, var(--surface) 96%, transparent); }
.stk-tier-buy { border-color: color-mix(in srgb, var(--pos) 30%, var(--border)); background: linear-gradient(135deg, color-mix(in srgb, var(--pos) 4%, var(--surface)), var(--surface) 42%); }
.stk-tier-watch { border-color: color-mix(in srgb, var(--warn) 30%, var(--border)); background: linear-gradient(135deg, color-mix(in srgb, var(--warn) 4%, var(--surface)), var(--surface) 42%); }
.stk-tier-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; padding-bottom: 11px; border-bottom: 1px solid var(--border); }
.stk-tier-head > div:first-child { min-width: 0; }
.stk-tier-kicker { display: block; margin-bottom: 4px; color: var(--muted); font: 700 8.5px/1 var(--font-mono); letter-spacing: .08em; text-transform: uppercase; }
.stk-tier-head h3 { display: flex; align-items: baseline; gap: 7px; margin: 0; color: var(--text-strong); font: 750 18px/1.2 var(--font-sans); }
.stk-tier-buy .stk-tier-head h3 { color: var(--pos); }
.stk-tier-watch .stk-tier-head h3 { color: var(--warn); }
.stk-tier-head h3 b { display: inline-flex; align-items: center; justify-content: center; min-width: 23px; height: 23px; padding: 0 6px; border-radius: 999px; color: var(--text-strong); background: color-mix(in srgb, var(--border) 50%, transparent); font: 750 11px/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.stk-tier-head p { max-width: 700px; margin: 5px 0 0; color: var(--muted-strong); font: 400 11.5px/1.45 var(--font-sans); }
.stk-tier-chips { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 5px; flex: 0 0 auto; }
.stk-tier-chip { display: inline-flex; align-items: baseline; gap: 5px; padding: 5px 7px; border: 1px solid var(--border); border-radius: 999px; color: var(--muted-strong); background: var(--surface-2); font: 650 9.5px/1 var(--font-sans); white-space: nowrap; }
.stk-tier-chip b { color: var(--text-strong); font: 750 10px/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.stk-tier-chip-starter b { color: var(--pos); }
.stk-tier-chip-wait b { color: var(--warn); }
.stk-tier-chip-research b { color: var(--neg); }
.stk-action-group { display: flex; flex-direction: column; gap: 9px; }
.stk-action-group + .stk-action-group { padding-top: 12px; border-top: 1px solid var(--border); }
.stk-action-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.stk-action-head > div { display: flex; flex-direction: column; gap: 3px; }
.stk-action-head small { color: var(--muted); font: 700 8px/1 var(--font-mono); letter-spacing: .07em; text-transform: uppercase; }
.stk-action-head h4 { margin: 0; color: var(--text-strong); font: 700 12.5px/1.2 var(--font-sans); }
.stk-action-starter .stk-action-head h4 { color: var(--pos); }
.stk-action-wait .stk-action-head h4 { color: var(--warn); }
.stk-action-research .stk-action-head h4 { color: var(--neg); }
.stk-action-head span { color: var(--muted); font: 600 9.5px/1.2 var(--font-mono); white-space: nowrap; }
.stk-tier-empty { margin: 0; color: var(--muted); font: 400 12px/1.4 var(--font-sans); font-style: italic; }
.stk-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 12px; }
.stk-card {
  display: flex; flex-direction: column; gap: 8px;
  padding: 12px 14px; border: 1px solid var(--border); border-left-width: 3px;
  border-left-color: var(--warn); border-radius: var(--r-1); background: var(--surface);
}
.stk-card-clean { border-left-color: var(--pos); }
/* Two fixed rows — identity (sym + name + sector), then badges (zone + score) —
   so the Buy zone / flag badge lines up across every card no matter how long
   the company name runs. */
.stk-head { display: flex; flex-direction: column; gap: 7px; }
.stk-head-id { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.stk-head-badges { display: flex; align-items: center; gap: 8px; }
/* The symbol is a button — click jumps to the Grade tab with the ticker loaded */
.stk-sym { font: 700 15px/1 var(--font-mono); color: var(--text-strong); background: none; border: 0; padding: 0; cursor: pointer; display: inline-flex; align-items: baseline; gap: 3px; }
.stk-sym:hover, .stk-sym:focus-visible { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.stk-sym-go { font: 600 10px/1 var(--font-sans); color: var(--muted); text-decoration: none; }
.stk-sym:hover .stk-sym-go, .stk-sym:focus-visible .stk-sym-go { color: var(--accent); }
.stk-name { font: 400 11.5px/1.3 var(--font-sans); color: var(--muted-strong); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 100%; flex: 1 1 auto; }
.stk-sector { font: 600 10px/1 var(--font-sans); color: var(--muted); border: 1px solid var(--border); border-radius: 999px; padding: 2.5px 7px; white-space: nowrap; }
.stk-zone { font: 700 9.5px/1 var(--font-sans); text-transform: uppercase; letter-spacing: 0.05em; border-radius: 999px; padding: 3.5px 7px; white-space: nowrap; cursor: help; }
.stk-zone-buy, .stk-zone-starter { color: var(--pos); background: color-mix(in srgb, var(--pos) 13%, transparent); }
.stk-zone-wait, .stk-zone-flag { color: var(--warn); background: var(--warn-soft); }
.stk-zone-research { color: var(--neg); background: var(--neg-soft); }
.stk-score { margin-left: auto; font: 700 12px/1 var(--font-mono); font-variant-numeric: tabular-nums; padding: 3px 7px; border-radius: 6px; color: var(--accent); background: color-mix(in srgb, var(--accent) 14%, transparent); cursor: help; }
.stk-spot-row { display: flex; align-items: center; gap: 10px; }
.stk-spot-row > b { font: 700 15px/1 var(--font-mono); font-variant-numeric: tabular-nums; color: var(--text-strong); }
.stk-range { display: flex; align-items: center; gap: 6px; flex: 1 1 auto; min-width: 0; }
.stk-range-lo, .stk-range-hi { font: 500 10px/1 var(--font-mono); color: var(--muted); white-space: nowrap; }
.stk-range-track { position: relative; flex: 1 1 auto; height: 3px; border-radius: 2px; background: color-mix(in srgb, var(--border) 70%, transparent); min-width: 40px; }
.stk-range-dot { position: absolute; top: 50%; width: 7px; height: 7px; border-radius: 50%; background: var(--text-strong); transform: translate(-50%, -50%); }
.stk-spark { width: 100%; height: 52px; display: block; }
.stk-spark-up .stk-spark-line { stroke: var(--pos); }
.stk-spark-down .stk-spark-line { stroke: var(--neg); }
.stk-spark-line { stroke-width: 1.6; vector-effect: non-scaling-stroke; }
/* Module 1 — quality-gate pills */
.stk-quality { display: flex; flex-wrap: wrap; gap: 4px 6px; }
.stk-q { font: 600 10.5px/1.2 var(--font-sans); color: var(--pos); border: 1px solid color-mix(in srgb, var(--pos) 35%, transparent); border-radius: 999px; padding: 2.5px 7px; white-space: nowrap; cursor: help; }
.stk-q-fail { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 35%, transparent); }
/* Module 2 — the five dip reads. Fired vs unfired is a COLOR split (text vs
   muted-strong) + the ○/● bullet — not opacity, which was illegible in both
   themes. */
.stk-sigs, .stk-flags { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
.stk-sig { font: 400 12px/1.45 var(--font-sans); color: var(--muted-strong); }
.stk-sig b { font-weight: 650; }
.stk-sig::before { content: '○'; font: 700 11px/1 var(--font-mono); margin-right: 5px; }
.stk-sig-fired { color: var(--text); }
.stk-sig-fired b { color: var(--text-strong); }
.stk-sig-fired::before { content: '●'; color: var(--accent); }
/* Module 3 — trap flags (yellow warnings) / the zero-flag buy-zone line */
.stk-flag { font: 400 12px/1.45 var(--font-sans); color: var(--muted-strong); }
.stk-flag b { font-weight: 650; color: var(--warn); }
.stk-flag::before { content: '⚠'; font: 700 11px/1 var(--font-mono); color: var(--warn); margin-right: 5px; }
.stk-clean { font: 600 12px/1.45 var(--font-sans); color: var(--pos); }
.stk-plan { display: flex; flex-direction: column; gap: 7px; padding: 9px 10px; border: 1px solid var(--border); border-radius: 9px; background: var(--surface-2); }
.stk-plan-starter { border-color: color-mix(in srgb, var(--pos) 36%, var(--border)); background: color-mix(in srgb, var(--pos) 4%, var(--surface-2)); }
.stk-plan-wait { border-color: color-mix(in srgb, var(--warn) 34%, var(--border)); background: color-mix(in srgb, var(--warn) 4%, var(--surface-2)); }
.stk-plan-research { border-color: color-mix(in srgb, var(--neg) 30%, var(--border)); background: color-mix(in srgb, var(--neg) 3%, var(--surface-2)); }
.stk-plan > header { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.stk-plan > header > span { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.stk-plan > header small { color: var(--accent); font: 700 8.5px/1 var(--font-mono); letter-spacing: .07em; text-transform: uppercase; }
.stk-plan > header b { color: var(--text-strong); font: 750 12px/1.25 var(--font-sans); }
.stk-plan-starter > header b { color: var(--pos); }
.stk-plan-wait > header b { color: var(--warn); }
.stk-plan-research > header b { color: var(--neg); }
.stk-plan > header em { flex: 0 0 auto; color: var(--muted); font: 600 8.5px/1 var(--font-sans); font-style: normal; letter-spacing: .04em; text-transform: uppercase; }
.stk-plan-detail { margin: 0; color: var(--muted-strong); font: 400 10.5px/1.45 var(--font-sans); }
.stk-plan-proof { display: flex; flex-wrap: wrap; gap: 5px; }
.stk-plan-proof span { padding: 4px 6px; border-radius: 5px; background: color-mix(in srgb, var(--border) 48%, transparent); color: var(--muted); font: 650 9px/1.2 var(--font-sans); }
.stk-plan-proof span.is-on { color: var(--pos); background: var(--pos-soft); }
.stk-plan-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); border: 1px solid var(--border); border-radius: 8px; overflow: hidden; background: var(--surface); }
.stk-plan-grid > span { display: flex; flex-direction: column; gap: 3px; min-width: 0; padding: 7px 8px; border-right: 1px solid var(--border); }
.stk-plan-grid > span:first-child { grid-column: 1 / -1; border-right: 0; border-bottom: 1px solid var(--border); }
.stk-plan-grid > span:last-child { border-right: 0; }
.stk-plan-grid small { color: var(--muted); font: 700 8px/1 var(--font-mono); letter-spacing: .06em; text-transform: uppercase; }
.stk-plan-grid b { color: var(--text-strong); font: 700 10.5px/1.25 var(--font-sans); overflow-wrap: anywhere; }
.stk-plan-grid > span:nth-child(2) b { color: var(--neg); }
.stk-plan-grid > span:nth-child(3) b { color: var(--pos); }
.stk-plan-grid em { color: var(--muted); font: 500 9px/1.3 var(--font-sans); font-style: normal; overflow-wrap: anywhere; }
.stk-plan-payoff { display: flex; flex-wrap: wrap; gap: 5px 11px; margin: 0; color: var(--muted); font: 550 9.5px/1.25 var(--font-sans); }
.stk-plan-payoff b { color: var(--text-strong); font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
/* Expandable investment-thesis checklist */
.stk-thesis { border-top: 1px solid var(--border); padding-top: 8px; margin-top: 2px; }
.stk-thesis > summary { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 10px; cursor: pointer; list-style: none; }
.stk-thesis > summary::-webkit-details-marker { display: none; }
.stk-thesis > summary::before { content: '▸'; color: var(--muted); font-size: 11px; }
.stk-thesis[open] > summary::before { content: '▾'; }
.stk-thesis-title { font: 650 12px/1.3 var(--font-sans); color: var(--text-strong); }
.stk-thesis-counts { font: 500 10.5px/1.3 var(--font-mono); font-variant-numeric: tabular-nums; color: var(--muted); }
.stk-thesis-note { font: 400 11px/1.5 var(--font-sans); color: var(--muted-strong); margin: 8px 0 2px; }
.stk-cl-bar { display: inline-flex; width: 56px; height: 5px; border-radius: 999px; overflow: hidden; align-self: center; background: color-mix(in srgb, var(--border) 45%, transparent); }
.stk-cl-bar i { display: block; height: 100%; }
.stk-cl-bar-a { background: var(--pos); }
.stk-cl-bar-u { background: var(--warn); }
.stk-cl-bar-n { background: transparent; }
.stk-cl-sec { margin-top: 6px; }
.stk-cl-sec > summary { display: flex; align-items: center; gap: 7px; cursor: pointer; list-style: none; padding: 3px 0; }
.stk-cl-sec > summary::-webkit-details-marker { display: none; }
.stk-cl-sec > summary::before { content: '▸'; color: var(--muted); font-size: 10px; }
.stk-cl-sec[open] > summary::before { content: '▾'; }
.stk-cl-sec h4 { font: 700 10.5px/1.3 var(--font-sans); text-transform: uppercase; letter-spacing: 0.05em; color: var(--muted); margin: 0; }
.stk-cl-mini { margin-left: auto; display: inline-flex; gap: 4px; }
.stk-cl-mini b { font: 700 9px/1 var(--font-mono); font-variant-numeric: tabular-nums; border-radius: 999px; padding: 3px 6px; }
.stk-cl-mini-a { color: var(--pos); background: color-mix(in srgb, var(--pos) 13%, transparent); }
.stk-cl-mini-u { color: var(--warn); background: var(--warn-soft); }
.stk-cl-mini-n { color: var(--muted); background: color-mix(in srgb, var(--border) 45%, transparent); }
.stk-cl-sec ul { list-style: none; margin: 5px 0 4px; padding: 0 0 0 17px; display: flex; flex-direction: column; gap: 7px; }
.stk-cl-item { display: flex; gap: 7px; align-items: flex-start; }
.stk-cl-badge { flex: 0 0 auto; font: 700 8.5px/1 var(--font-sans); text-transform: uppercase; letter-spacing: 0.04em; border-radius: 999px; padding: 3px 6px; margin-top: 1px; }
.stk-cl-answered .stk-cl-badge { color: var(--pos); background: color-mix(in srgb, var(--pos) 13%, transparent); }
.stk-cl-unsure .stk-cl-badge { color: var(--warn); background: var(--warn-soft); }
.stk-cl-unanswered .stk-cl-badge { color: var(--muted); background: color-mix(in srgb, var(--border) 45%, transparent); }
.stk-cl-text { font: 400 11.5px/1.5 var(--font-sans); color: var(--muted-strong); display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.stk-cl-text b { font-weight: 650; color: var(--text-strong); }
.stk-cl-unanswered .stk-cl-text b { color: var(--muted); }
.stk-empty { font: 400 12.5px/1.5 var(--font-sans); color: var(--muted-strong); font-style: italic; margin: 0; }
/* Daily DCA dial (VOO/QQQ) — the sizing card block above the dip screen */
.stk-dca { display: flex; flex-direction: column; gap: 10px; padding-bottom: 14px; border-bottom: 1px solid var(--border); }
.stk-dca-top { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px 14px; }
.stk-dca-title { font: 700 13.5px/1.3 var(--font-sans); color: var(--text-strong); margin: 0; }
.stk-dca-baselab { margin-left: auto; display: inline-flex; align-items: baseline; gap: 4px; font: 600 11px/1.3 var(--font-sans); color: var(--muted-strong); white-space: nowrap; }
.stk-dca-baselab input { width: 62px; font: 700 12px/1.2 var(--font-mono); font-variant-numeric: tabular-nums; color: var(--text-strong); background: var(--surface); border: 1px solid var(--border); border-radius: 6px; padding: 4px 7px; }
.stk-dca-hint { font: 400 12px/1.55 var(--font-sans); color: var(--muted-strong); margin: 0; }
.stk-dca-hint b { font-weight: 650; color: var(--text-strong); }
.stk-dca-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(290px, 1fr)); gap: 12px; }
.stk-dca-card {
  display: flex; flex-direction: column; gap: 8px;
  padding: 12px 14px; border: 1px solid var(--border); border-left-width: 3px;
  border-left-color: var(--border); border-radius: var(--r-1); background: var(--surface);
}
.stk-dca-tier-lean { border-left-color: var(--accent); }
.stk-dca-tier-double, .stk-dca-tier-heavy, .stk-dca-tier-max { border-left-color: var(--pos); }
.stk-dca-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 10px; }
.stk-dca-id { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.stk-dca-sym { font: 700 15px/1 var(--font-mono); color: var(--text-strong); }
a.stk-dca-sym:hover, a.stk-dca-sym:focus-visible { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
/* Ticker jumps are real anchors now (?s= deep links) — keep the chip/button
   look: no default underline (each class's hover rule opts back in). */
a.ers-sym, a.ecl-sym, a.stk-sym, a.stk-dca-sym, a.ivt-sym, a.ivt-sum-chip, a.ivt-trow-symbtn,
a.cmd-watch, a.cr-tkr, a.f13-sym, a.brief-chip, a.cal-chip-sym { text-decoration: none; }
.stk-dca-name { font: 400 11.5px/1.3 var(--font-sans); color: var(--muted-strong); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.stk-dca-stale { font: 700 9px/1 var(--font-sans); text-transform: uppercase; letter-spacing: 0.05em; color: var(--warn); background: var(--warn-soft); border-radius: 999px; padding: 3px 6px; cursor: help; }
.stk-dca-px { margin-left: auto; font: 600 12.5px/1 var(--font-mono); font-variant-numeric: tabular-nums; color: var(--text-strong); }
.stk-dca-verdict { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.stk-dca-amt { font: 800 24px/1 var(--font-mono); font-variant-numeric: tabular-nums; color: var(--text-strong); }
.stk-dca-tier-double .stk-dca-amt, .stk-dca-tier-heavy .stk-dca-amt, .stk-dca-tier-max .stk-dca-amt { color: var(--pos); }
.stk-dca-tier-lean .stk-dca-amt { color: var(--accent); }
.stk-dca-verdict-sub { font: 600 12px/1.4 var(--font-sans); color: var(--muted-strong); display: inline-flex; align-items: baseline; gap: 6px; flex-wrap: wrap; }
.stk-dca-mult { font: 700 10px/1 var(--font-sans); text-transform: uppercase; letter-spacing: 0.04em; border: 1px solid var(--border); border-radius: 999px; padding: 3px 7px; color: var(--text-strong); }
.stk-dca-pts { font: 500 11px/1 var(--font-mono); font-variant-numeric: tabular-nums; color: var(--muted-strong); cursor: help; }
.stk-dca-note { font: 400 12px/1.5 var(--font-sans); color: var(--muted-strong); margin: 0; font-style: italic; }
.stk-dca-reads { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
/* Fired vs un-fired reads are distinguished by COLOR (text vs muted-strong) and
   the ○/● bullet — not opacity, which made the un-fired rows illegible in both
   themes. Keep every row at full opacity. */
.stk-dca-read { font: 400 12px/1.45 var(--font-sans); color: var(--muted-strong); display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 6px; }
.stk-dca-read b { font-weight: 650; }
.stk-dca-read::before { content: '○'; font: 700 11px/1 var(--font-mono); }
.stk-dca-read-on { color: var(--text); }
.stk-dca-read-on b { color: var(--text-strong); }
.stk-dca-read-on::before { content: '●'; color: var(--pos); }
.stk-dca-read-pts { font: 700 10px/1 var(--font-mono); font-variant-numeric: tabular-nums; color: var(--muted-strong); border: 1px solid var(--border); border-radius: 999px; padding: 2px 5px; }
.stk-dca-read-on .stk-dca-read-pts { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 35%, transparent); }
.stk-dca-read-det { flex-basis: 100%; font-size: 11px; }
.stk-dca-hist { display: flex; gap: 4px; flex-wrap: wrap; border-top: 1px solid var(--border); padding-top: 8px; }
.stk-dca-h { font: 700 9.5px/1 var(--font-mono); font-variant-numeric: tabular-nums; border-radius: 5px; padding: 4px 6px; color: var(--muted); background: color-mix(in srgb, var(--border) 45%, transparent); cursor: help; }
.stk-dca-h-lean { color: var(--accent); background: color-mix(in srgb, var(--accent) 14%, transparent); }
.stk-dca-h-hi { color: var(--pos); background: color-mix(in srgb, var(--pos) 14%, transparent); }
.stk-dca-h-max { color: var(--pos); background: color-mix(in srgb, var(--pos) 26%, transparent); }
@media (max-width: 760px) {
  .stk-desk { flex-direction: column; }
  .stk-desk-stats { width: 100%; }
  .stk-tier { padding: 11px; }
  .stk-tier-head { flex-direction: column; }
  .stk-tier-chips { justify-content: flex-start; }
  .stk-action-head { align-items: flex-start; flex-direction: column; gap: 3px; }
  .stk-grid, .stk-dca-grid { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 480px) {
  .stk-desk { padding: 11px; }
  .stk-desk-stats { grid-template-columns: minmax(0, 1fr); }
  .stk-desk-stats > span { flex-direction: row; align-items: baseline; justify-content: space-between; }
  .stk-plan-grid { grid-template-columns: minmax(0, 1fr); }
  .stk-plan-grid > span, .stk-plan-grid > span:first-child { grid-column: auto; border-right: 0; border-bottom: 1px solid var(--border); }
  .stk-plan-grid > span:last-child { border-bottom: 0; }
  .stk-plan > header { align-items: flex-start; }
}

/* --- Sector Rotation (quality dislocation + rebound confirmation) ------- */
.rot-root { display: flex; flex-direction: column; gap: 14px; min-width: 0; }
.rot-up { color: var(--pos) !important; }
.rot-down { color: var(--neg) !important; }
.rot-summary { display: flex; align-items: flex-start; justify-content: space-between; gap: 18px; padding: 14px; border: 1px solid color-mix(in srgb, var(--accent) 30%, var(--border)); border-radius: 12px; background: var(--surface); }
.rot-summary > div:first-child { min-width: 0; max-width: 720px; }
.rot-kicker { display: block; margin-bottom: 5px; color: var(--accent); font: 700 9.5px/1 var(--font-mono); letter-spacing: .09em; text-transform: uppercase; }
.rot-summary h3 { margin: 0; color: var(--text-strong); font: 750 17px/1.3 var(--font-sans); }
.rot-summary p { margin: 6px 0 0; color: var(--muted-strong); font: 400 12.5px/1.5 var(--font-sans); }
.rot-summary-stats { display: grid; grid-template-columns: repeat(2, minmax(82px, 1fr)); gap: 6px; flex: 0 0 auto; }
.rot-summary-stats > span { display: flex; flex-direction: column; gap: 2px; padding: 7px 9px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface-2); }
.rot-summary-stats b { color: var(--text-strong); font: 800 17px/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.rot-summary-stats small { color: var(--muted); font: 650 8.5px/1.15 var(--font-sans); letter-spacing: .04em; text-transform: uppercase; }
.rot-process { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; margin: -4px 0 0; padding: 0; list-style: none; counter-reset: none; }
.rot-process li { display: flex; flex-direction: column; gap: 4px; min-width: 0; padding: 9px 10px; border: 1px solid var(--border); border-radius: 9px; background: var(--surface); }
.rot-process b { display: flex; align-items: center; gap: 6px; color: var(--text-strong); font: 700 10.5px/1.2 var(--font-sans); }
.rot-process b em { display: inline-flex; width: 18px; height: 18px; flex: 0 0 auto; align-items: center; justify-content: center; border-radius: 50%; background: var(--accent-soft); color: var(--accent); font: 800 9px/1 var(--font-mono); font-style: normal; }
.rot-process span { color: var(--muted); font: 400 10px/1.35 var(--font-sans); }
.rot-scope-note { margin: -7px 0 0; color: var(--muted); font: 400 10px/1.35 var(--font-sans); }
.rot-scope-note b { color: var(--muted-strong); font-weight: 650; }
.rot-brief { display: grid; grid-template-columns: minmax(0, .85fr) minmax(0, 1.15fr); gap: 10px; padding: 13px; border: 1px solid color-mix(in srgb, var(--warn) 34%, var(--border)); border-left-width: 3px; border-radius: 12px; background: linear-gradient(135deg, color-mix(in srgb, var(--warn) 6%, var(--surface)), var(--surface) 58%); min-width: 0; }
.rot-brief-act { border-color: color-mix(in srgb, var(--pos) 42%, var(--border)); background: linear-gradient(135deg, color-mix(in srgb, var(--pos) 6%, var(--surface)), var(--surface) 58%); }
.rot-brief-pass { border-color: color-mix(in srgb, var(--neg) 34%, var(--border)); background: linear-gradient(135deg, color-mix(in srgb, var(--neg) 5%, var(--surface)), var(--surface) 58%); }
.rot-brief-no-focus { grid-template-columns: minmax(0, 1fr); }
.rot-brief-read { display: flex; flex-direction: column; gap: 6px; min-width: 0; padding: 2px 3px; }
.rot-brief-read .rot-kicker { margin: 0; }
.rot-brief-title { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; }
.rot-brief-title h3 { margin: 0; color: var(--text-strong); font: 780 18px/1.2 var(--font-sans); }
.rot-brief-title > b { padding: 4px 7px; border-radius: 6px; font: 750 9.5px/1 var(--font-sans); }
.rot-brief-read > p { margin: 0; color: var(--text); font: 650 12px/1.4 var(--font-sans); }
.rot-brief-read > span { color: var(--muted-strong); font: 400 10.5px/1.45 var(--font-sans); }
.rot-brief-counts { display: flex; flex-wrap: wrap; gap: 5px; margin-top: auto; padding-top: 5px; }
.rot-brief-counts b { padding: 4px 6px; border-radius: 5px; background: var(--surface-2); color: var(--muted-strong); font: 650 9px/1.2 var(--font-mono); font-variant-numeric: tabular-nums; }
.rot-brief-focus { display: flex; flex-direction: column; gap: 8px; min-width: 0; padding: 10px; border: 1px solid var(--border); border-radius: 9px; background: var(--surface-2); }
.rot-brief-focus-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; min-width: 0; }
.rot-brief-focus-head > span { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.rot-brief-focus-head small { color: var(--muted); font: 650 8.5px/1 var(--font-sans); letter-spacing: .045em; text-transform: uppercase; }
.rot-brief-focus-head b { color: var(--accent); font: 800 16px/1.15 var(--font-mono); }
.rot-brief-focus-head b em { margin-left: 5px; color: var(--muted-strong); font: 550 10px/1.2 var(--font-sans); font-style: normal; }
.rot-brief-focus-head > strong { flex: 0 0 auto; max-width: 48%; padding: 4px 7px; border-radius: 6px; font: 700 9.5px/1.2 var(--font-sans); text-align: right; }
.rot-brief-focus > p { margin: 0; color: var(--muted-strong); font: 500 10.5px/1.4 var(--font-sans); }
.rot-brief-levels { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 5px; }
.rot-brief-levels > span { display: flex; flex-direction: column; gap: 3px; min-width: 0; padding: 6px 7px; border: 1px solid var(--border); border-radius: 7px; background: var(--surface); }
.rot-brief-levels small { color: var(--muted); font: 650 8px/1.1 var(--font-sans); letter-spacing: .03em; text-transform: uppercase; }
.rot-brief-levels b { color: var(--text-strong); font: 730 10.5px/1.2 var(--font-mono); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.rot-brief-actions { display: flex; flex-wrap: wrap; gap: 6px; }
.rot-brief-actions button { appearance: none; min-height: 34px; flex: 1 1 135px; padding: 7px 9px; border: 1px solid var(--border-strong); border-radius: 7px; background: var(--surface); color: var(--text); font: 700 10px/1.2 var(--font-sans); cursor: pointer; }
.rot-brief-actions button:first-child { border-color: color-mix(in srgb, var(--accent) 48%, var(--border)); background: var(--accent-soft); color: var(--accent); }
.rot-brief-actions button:hover { border-color: var(--accent); color: var(--accent); }
.rot-record { display: flex; flex-direction: column; gap: 10px; padding: 13px 14px; border: 1px solid var(--border); border-radius: 12px; background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 5%, var(--surface)), var(--surface) 55%); min-width: 0; }
.rot-record-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.rot-record-head > div { min-width: 0; }
.rot-record-head .rot-kicker { margin-bottom: 4px; }
