  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-1);
  color: var(--muted);
  font: 500 var(--fs-2xs)/1.35 var(--font-sans);
}
.cr-desk-source b { color: var(--pos); }
.cr-desk-reference .cr-desk-source b { color: var(--warn); }
.cr-desk-source small { flex: 0 0 auto; color: var(--muted); font: 500 10px/1.3 var(--font-mono); }
.cr-mix {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--s-2);
}
.cr-mix > span {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2px var(--s-2);
  min-width: 0;
  padding: var(--s-2) var(--s-3);
  border: 1px solid var(--border);
  border-top: 2px solid var(--warn);
  border-radius: var(--r-3);
  background: var(--surface-1);
}
.cr-mix > .cr-mix-risk { border-top-color: var(--neg); }
.cr-mix > .cr-mix-positive { border-top-color: var(--pos); }
.cr-mix small {
  align-self: center;
  font-size: var(--fs-2xs);
  font-weight: 700;
  color: var(--muted);
  letter-spacing: var(--ls-caps);
  text-transform: uppercase;
}
.cr-mix b {
  grid-column: 2;
  grid-row: 1 / 3;
  align-self: center;
  font: 800 var(--fs-2xl)/1 var(--font-mono);
  color: var(--text);
}
.cr-mix em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font: 400 var(--fs-2xs)/1.2 var(--font-mono);
  color: var(--muted);
}
.cr-lead {
  padding: var(--s-3);
  border: 1px solid var(--border);
  border-left: 3px solid var(--warn);
  border-radius: var(--r-3);
  background: color-mix(in srgb, var(--surface-3) 72%, transparent);
}
.cr-lead.cr-tone-risk { border-left-color: var(--neg); }
.cr-lead.cr-tone-positive { border-left-color: var(--pos); }
.cr-lead.cr-tone-review { border-left-color: var(--muted); }
.cr-lead > div {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: var(--s-2);
  margin-top: 5px;
}
.cr-lead > div > b { font-size: var(--fs-sm); }
.cr-lead > div > strong {
  margin-left: auto;
  font: 700 var(--fs-md)/1 var(--font-mono);
}
.cr-lead p {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: var(--fs-xs);
  line-height: var(--lh-snug);
}
.cr-lead-check {
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
  gap: var(--s-2);
  align-items: start;
  margin-top: var(--s-2);
  padding-top: var(--s-2);
  border-top: 1px solid var(--hairline);
}
.cr-lead-check span {
  color: var(--muted);
  font: 700 var(--fs-2xs)/1.3 var(--font-sans);
  letter-spacing: var(--ls-caps);
  text-transform: uppercase;
}
.cr-lead-check b { color: var(--text); font-size: var(--fs-xs); font-weight: 600; line-height: var(--lh-snug); }
.cr-lead-meta { display: block; margin-top: 5px; color: var(--muted); font: 400 var(--fs-2xs)/1.2 var(--font-mono); }
.cr-rules {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--s-2);
}
.cr-rules > div {
  display: grid;
  gap: 5px;
  padding: 10px 11px;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-1);
}
.cr-rules span {
  color: var(--muted);
  font: 700 var(--fs-2xs)/1.2 var(--font-sans);
  letter-spacing: var(--ls-caps);
  text-transform: uppercase;
}
.cr-rules b { color: var(--text); font-size: var(--fs-xs); font-weight: 600; line-height: var(--lh-snug); }
.cr-actions { display: flex; flex-wrap: wrap; gap: 7px; }
.cr-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 36px;
  padding: 8px 12px;
  border: 1px solid var(--border-strong);
  border-radius: var(--r-pill);
  background: var(--surface);
  color: var(--text-strong);
  font: 700 11px/1 var(--font-sans);
  text-decoration: none;
  cursor: pointer;
}
.cr-action:hover,
.cr-action:focus-visible { border-color: var(--accent); color: var(--accent); }
.cr-action-primary { border-color: var(--accent); background: var(--accent); color: var(--surface); }
.cr-action-primary:hover,
.cr-action-primary:focus-visible { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 86%, var(--text-strong)); color: var(--surface); }
.cr-empty-desk {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--s-2);
  padding: var(--s-4);
  border: 1px dashed var(--border-strong);
  border-radius: var(--r-4);
  background: var(--surface-2);
}
.cr-empty-desk h3 { margin: 0; color: var(--text-strong); font-size: var(--fs-xl); line-height: var(--lh-tight); }
.cr-empty-desk p { max-width: 78ch; margin: 0; color: var(--muted); font-size: var(--fs-sm); line-height: var(--lh-snug); }
.cr-empty-desk .cr-desk-source { width: 100%; }
.cr-ledger,
.cr-kind-group {
  overflow: clip;
  border: 1px solid var(--border);
  border-radius: var(--r-3);
  background: var(--surface-2);
}
.cr-ledger > summary,
.cr-kind-group > summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto 14px;
  gap: var(--s-3);
  align-items: center;
  min-height: 48px;
  padding: var(--s-2) var(--s-3);
  list-style: none;
  cursor: pointer;
}
.cr-ledger > summary::-webkit-details-marker,
.cr-kind-group > summary::-webkit-details-marker { display: none; }
.cr-ledger > summary:hover,
.cr-kind-group > summary:hover { background: color-mix(in srgb, var(--surface-3) 64%, transparent); }
.cr-ledger > summary > span,
.cr-kind-group > summary > span { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.cr-ledger > summary b,
.cr-kind-group > summary b { font-size: var(--fs-sm); color: var(--text); }
.cr-ledger > summary small,
.cr-kind-group > summary small { font-size: var(--fs-2xs); color: var(--muted); }
.cr-ledger > summary em,
.cr-kind-group > summary em {
  font: 400 var(--fs-2xs)/1.2 var(--font-mono);
  color: var(--muted);
}
.cr-chevron {
  display: block;
  width: 7px;
  height: 7px;
  border-right: 1.5px solid var(--muted);
  border-bottom: 1.5px solid var(--muted);
  transform: rotate(45deg) translate(-1px, -1px);
  transition: transform .15s ease;
}
.cr-ledger[open] > summary .cr-chevron,
.cr-kind-group[open] > summary .cr-chevron { transform: rotate(225deg) translate(-1px, -1px); }
.cr-ledger-body {
  display: flex;
  flex-direction: column;
  gap: var(--s-2);
  padding: var(--s-3);
  border-top: 1px solid var(--border);
}
.cr-kind-group { background: var(--surface-1); }
.cr-kind-body { padding: var(--s-2); border-top: 1px solid var(--border); }
.cr-rows { display: flex; flex-direction: column; gap: var(--s-2); }
.cr-row {
  padding: var(--s-3);
  border: 1px solid var(--border);
  border-left: 3px solid var(--warn);
  border-radius: var(--r-2);
  background: var(--surface-2);
}
.cr-row.cr-tone-risk { border-left-color: var(--neg); }
.cr-row.cr-tone-positive { border-left-color: var(--pos); }
.cr-row.cr-tone-review { border-left-color: var(--muted); }
.cr-row-top { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.cr-kind { font: 700 10px/1 var(--font-sans); text-transform: uppercase; letter-spacing: 0.03em; padding: 3px 7px; border-radius: 999px; }
.cr-debt { color: var(--neg); background: color-mix(in srgb, var(--neg) 13%, transparent); }
.cr-conv { color: var(--warn); background: color-mix(in srgb, var(--warn) 16%, transparent); }
.cr-equity { color: var(--accent); background: color-mix(in srgb, var(--accent) 14%, transparent); }
.cr-buyback { color: var(--pos); background: color-mix(in srgb, var(--pos) 14%, transparent); }
.cr-tkr { font: 700 14px/1 var(--font-sans); color: var(--text-strong); }
/* As a button (tracked ticker → Grade tab): keep the plain-text look. */
a.cr-tkr { background: none; border: 0; padding: 0; cursor: pointer; display: inline-flex; align-items: baseline; gap: 3px; }
a.cr-tkr:hover, a.cr-tkr:focus-visible { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
a.cr-tkr:hover .stk-sym-go, a.cr-tkr:focus-visible .stk-sym-go { color: var(--accent); }
.cr-name { font: 400 12px/1 var(--font-sans); color: var(--muted); }
.cr-amt { margin-left: auto; font: 700 14px/1 var(--font-mono); color: var(--text-strong); }
.cr-headline { font: 500 13.5px/1.45 var(--font-sans); color: var(--text); margin: 6px 0 4px; }
.cr-headline a { color: var(--text); text-decoration: none; border-bottom: 1px solid var(--border); }
.cr-headline a:hover { color: var(--accent); border-color: var(--accent); }
.cr-meta { font: 400 11.5px/1.3 var(--font-sans); color: var(--muted); }
.cr-filed { color: var(--text-strong); }
.cr-event-read {
  display: grid;
  grid-template-columns: minmax(150px, .35fr) 1fr;
  gap: var(--s-3);
  margin: var(--s-2) 0;
  padding: var(--s-2);
  border-radius: var(--r-2);
  background: var(--surface-1);
}
.cr-event-read b { font-size: var(--fs-xs); color: var(--text); }
.cr-event-read span { font-size: var(--fs-xs); color: var(--muted); line-height: var(--lh-snug); }
.cr-scope {
  margin: var(--s-1) 0 0;
  color: var(--muted);
  font-size: var(--fs-2xs);
  line-height: var(--lh-snug);
}
@media (max-width: 720px) {
  .cr-desk { padding: var(--s-3); }
  .cr-desk-head h3 { font-size: var(--fs-lg); }
  .cr-desk-head p { font-size: var(--fs-xs); }
  .cr-desk-source { align-items: flex-start; flex-direction: column; gap: 3px; }
  .cr-desk-source small { flex: none; }
  .cr-mix { gap: 5px; }
  .cr-mix > span {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
    padding: 7px;
  }
  .cr-mix b { order: -1; font-size: var(--fs-xl); }
  .cr-mix small { font-size: 9px; }
  .cr-mix em { max-width: 100%; font-size: 9px; }
  .cr-lead > div > strong { margin-left: 0; }
  .cr-lead-check { grid-template-columns: 1fr; gap: 3px; }
  .cr-rules { grid-template-columns: minmax(0, 1fr); }
  .cr-actions { display: grid; grid-template-columns: minmax(0, 1fr); width: 100%; }
  .cr-action { width: 100%; min-height: 42px; }
  .cr-empty-desk { padding: var(--s-3); }
  .cr-empty-desk h3 { font-size: var(--fs-lg); }
  .cr-empty-desk p { font-size: var(--fs-xs); }
  .cr-ledger > summary,
  .cr-kind-group > summary {
    grid-template-columns: minmax(0, 1fr) 14px;
    gap: 3px var(--s-2);
  }
  .cr-ledger > summary > em,
  .cr-kind-group > summary > em { grid-column: 1; grid-row: 2; }
  .cr-ledger > summary .cr-chevron,
  .cr-kind-group > summary .cr-chevron { grid-column: 2; grid-row: 1 / 3; }
  .cr-event-read { grid-template-columns: 1fr; gap: 3px; }
  .cr-amt { margin-left: 0; }
}

