.fomc-vote-switches { display: flex; flex-wrap: wrap; gap: 5px; padding-top: 7px; border-top: 1px solid var(--hairline); }
.fomc-vote-switches > b { width: 100%; font: 700 10px/1 var(--font-mono); letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
.fomc-vote-switch {
  padding: 4px 7px;
