}
.fomc-vote-no-switch, .fomc-vote-pending { margin: 0; font-size: 11px; line-height: 1.4; color: var(--muted); }
.fomc-vote-source { width: max-content; max-width: 100%; color: var(--accent-strong); font: 600 11px/1.3 var(--font-sans); text-decoration: none; }
