.fomc-vote-method { margin: 9px 0 0; font-size: 11px; line-height: 1.45; color: var(--muted); }
.fomc-vote-method b { color: var(--text); }
.fomc-details {
  border-top: 1px solid var(--hairline);
  padding-top: var(--s-2);
}
.fomc-details > summary {
