  color: var(--text);
}
.fomc-details > summary::-webkit-details-marker { display: none; }
.fomc-details > summary > span:first-child { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.fomc-details > summary b { font: 700 13px/1.2 var(--font-sans); color: var(--text-strong); }
