/* Prediction-market cross-check (Kalshi + Polymarket) under the futures table. */
.fomc-pm { margin-top: var(--s-2); }
.fomc-pm-head {
  font: 600 11px/1 var(--font-mono);
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 4px;
