.f13-signal-card p { margin: 0; color: var(--muted-strong); font: 500 11.5px/1.45 var(--font-sans); }
.f13-signal-card p b { color: var(--text); }
.f13-rules { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.f13-rules > div {
  display: grid;
  gap: 5px;
  padding: 10px 11px;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-2);
}
.f13-rules span { color: var(--muted); font: 750 9px/1.2 var(--font-mono); letter-spacing: .07em; text-transform: uppercase; }
.f13-rules b { color: var(--text-strong); font: 650 11px/1.4 var(--font-sans); }
.f13-actions { display: flex; flex-wrap: wrap; gap: 7px; }
.f13-action {
  min-height: 36px;
  padding: 8px 12px;
  border: 1px solid var(--border-strong);
  border-radius: var(--r-pill);
  background: var(--surface);
  color: var(--text-strong);
  font: 700 11px/1 var(--font-sans);
  cursor: pointer;
}
.f13-action:hover, .f13-action:focus-visible { border-color: var(--accent); color: var(--accent); }
.f13-action-primary { border-color: var(--accent); background: var(--accent); color: var(--surface); }
.f13-action-primary:hover, .f13-action-primary:focus-visible { background: color-mix(in srgb, var(--accent) 86%, var(--text-strong)); color: var(--surface); }
.f13-empty-desk {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  padding: 16px;
  border: 1px dashed var(--border-strong);
  border-radius: var(--r-3);
  background: var(--surface-2);
}
.f13-empty-desk h3 { margin: 0; color: var(--text-strong); font: 750 18px/1.25 var(--font-sans); }
.f13-empty-desk p { max-width: 78ch; margin: 0; color: var(--muted); font: 500 12px/1.45 var(--font-sans); }
.f13-desk-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.f13-desk-side { overflow: hidden; border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface-2); }
.f13-desk-buy { border-left: 3px solid var(--pos); }
.f13-desk-sell { border-left: 3px solid var(--neg); }
.f13-desk-side-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 8px 10px; border-bottom: 1px solid var(--hairline); }
.f13-desk-side-head span { font: 750 10px/1 var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--text-strong); }
.f13-desk-side-head small { font: 600 9px/1 var(--font-sans); text-transform: uppercase; letter-spacing: .05em; color: var(--muted); }
.f13-desk-row {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 9px;
  min-height: 38px;
  padding: 6px 10px;
  border-bottom: 1px solid var(--hairline);
}
.f13-desk-row:last-child { border-bottom: 0; }
.f13-desk-symbol { font: 750 13px/1 var(--font-mono); color: var(--text-strong); }
.f13-desk-issuer { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 500 12px/1.2 var(--font-sans); color: var(--muted-strong); }
.f13-desk-row b { font: 700 12px/1 var(--font-mono); color: var(--text-strong); font-variant-numeric: tabular-nums; }
.f13-desk-row small { min-width: 42px; text-align: right; font: 600 10px/1 var(--font-mono); color: var(--muted); }
.f13-desk-buy .f13-desk-row b { color: var(--pos); }
.f13-desk-sell .f13-desk-row b { color: var(--neg); }
.f13-lag-note { margin: 0; font: 500 11px/1.45 var(--font-sans); color: var(--muted); }
.f13-lag-note strong { color: var(--warn); }
.f13-disclosure {
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-2);
  overflow: clip;
}
.f13-disclosure[open] { border-color: color-mix(in srgb, var(--accent) 30%, var(--border)); }
.f13-disclosure > summary {
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 8px 12px;
  list-style: none;
  cursor: pointer;
}
.f13-disclosure > summary::-webkit-details-marker { display: none; }
.f13-disclosure > summary::before { content: '›'; flex: 0 0 auto; color: var(--accent); font-size: 18px; line-height: 1; transition: transform var(--dur-1); }
.f13-disclosure[open] > summary::before { transform: rotate(90deg); }
.f13-disclosure > summary > span:first-of-type { display: flex; flex-direction: column; gap: 3px; min-width: 0; flex: 1; }
.f13-disclosure > summary b { font: 700 13px/1.2 var(--font-sans); color: var(--text-strong); }
.f13-disclosure > summary small { font: 500 11px/1.3 var(--font-sans); color: var(--muted); }
.f13-disclosure-count { flex: 0 0 auto; padding: 3px 7px; border: 1px solid var(--border); border-radius: 999px; font: 650 10px/1 var(--font-mono); color: var(--muted-strong); white-space: nowrap; }
.f13-disclosure-body { display: flex; flex-direction: column; gap: var(--s-2); padding: 10px 12px 12px; border-top: 1px solid var(--hairline); background: var(--surface); }
.f13-block {
  display: flex;
  flex-direction: column;
  gap: var(--s-2);
}
.f13-block-title {
  font: 600 13px/1.2 var(--font-mono);
  letter-spacing: .03em;
  color: var(--text);
  margin: 0;
}
.f13-note, .f13-tail {
  font-size: 12px;
  color: var(--muted);
  margin: 0;
  font-style: italic;
}
.f13-paragraph {
  font-size: 13px;
  color: var(--text);
  margin: 0;
  line-height: 1.5;
}
.f13-list {
  margin: 0;
  padding-left: 20px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 13px;
  line-height: 1.5;
}
.f13-table-scroll {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-2);
}
.f13-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  min-width: 680px;
}
.f13-table th, .f13-table td {
  padding: 7px 10px;
  text-align: left;
  border-bottom: 1px solid var(--hairline);
  white-space: nowrap;
}
.f13-table th {
  font: 600 11px/1 var(--font-mono);
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--muted);
  background: var(--surface);
}
.f13-table tbody tr:last-child td { border-bottom: none; }
.f13-table tbody tr:hover { background: color-mix(in srgb, var(--accent) 6%, transparent); }
.f13-num { text-align: right; font-variant-numeric: tabular-nums; font-family: var(--font-mono); }
.f13-tkr { font: 600 13px/1.2 var(--font-mono); color: var(--text-strong); letter-spacing: .02em; }
/* Curated tickers render as buttons → Grade tab; inherit the cell's mono look. */
.f13-sym { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
.f13-sym:hover, .f13-sym:focus-visible { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.f13-muted { color: var(--muted); }
.f13-rank-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.f13-rank-row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 13px;
  line-height: 1.5;
  padding: 4px 8px;
  border-bottom: 1px solid var(--hairline);
  flex-wrap: wrap;
}
.f13-rank-row:last-child { border-bottom: none; }
.f13-rank {
  font: 700 12px/1 var(--font-mono);
  color: var(--accent);
  min-width: 32px;
  letter-spacing: .04em;
}
.f13-rank-range {
  color: var(--muted);
  font-weight: 600;
  min-width: auto;
}
.f13-pos-name {
  color: var(--muted);
  font-size: 13px;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f13-pos-note {
  color: var(--muted);
  font-size: 12px;
  font-style: italic;
}
.f13-firm {
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-2);
  margin-top: var(--s-2);
  overflow: hidden;
}
.f13-firm[open] {
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border));
}
.f13-firm-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-2);
  padding: var(--s-2) var(--s-3);
  cursor: pointer;
  user-select: none;
  list-style: none;
  flex-wrap: wrap;
}
.f13-firm-summary::-webkit-details-marker { display: none; }
.f13-firm-summary::before {
  content: "▸";
  display: inline-block;
  color: var(--muted);
  transition: transform .12s;
  margin-right: 4px;
}
.f13-firm[open] .f13-firm-summary::before { transform: rotate(90deg); }
.f13-firm-name {
  font: 600 13px/1.2 var(--font-mono);
  color: var(--text-strong);
  letter-spacing: .03em;
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
}
.f13-firm-meta {
  font-size: 12px;
  color: var(--muted);
  font-family: var(--font-mono);
  white-space: nowrap;
}
.f13-firm .f13-table-scroll {
  border: none;
  border-top: 1px solid var(--hairline);
  border-radius: 0;
  background: var(--surface);
}
.f13-flow-pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--s-3);
}
.f13-flow-col {
  padding: var(--s-2) var(--s-3);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-2);
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.f13-flow-buy { border-left: 3px solid var(--pos); }
.f13-flow-sell { border-left: 3px solid var(--neg); }
.f13-footer {
  border-top: 1px solid var(--border);
  padding-top: var(--s-2);
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.f13-disclaimer, .f13-links {
  font-size: 12px;
  color: var(--muted);
  margin: 0;
  line-height: 1.5;
}
@media (max-width: 640px) {
  .f13-flow-pair { grid-template-columns: 1fr; }
  .f13-desk { padding: 11px; }
  .f13-desk-head { flex-direction: column; gap: 10px; }
  .f13-coverage { width: 100%; flex-direction: row; align-items: baseline; justify-content: space-between; }
  .f13-source { flex-direction: column; gap: 6px; }
  .f13-desk-source { align-items: flex-start; flex-direction: column; gap: 3px; }
  .f13-desk-source small { flex: none; }
  .f13-signal-grid { grid-template-columns: 1fr; }
  .f13-signal-card header { align-items: flex-start; }
  .f13-rules { grid-template-columns: minmax(0, 1fr); }
  .f13-actions { display: grid; grid-template-columns: minmax(0, 1fr); width: 100%; }
  .f13-action { width: 100%; min-height: 42px; }
  .f13-empty-desk { padding: 12px; }
  .f13-empty-desk h3 { font-size: 16px; }
  .f13-empty-desk p { font-size: 11px; }
  .f13-desk-grid { grid-template-columns: 1fr; }
  .f13-desk-row { grid-template-columns: 58px minmax(0, 1fr) auto; gap: 7px; }
  .f13-desk-issuer { display: none; }
  .f13-desk-row b { justify-self: end; }
  .f13-disclosure > summary { align-items: flex-start; gap: 8px; padding: 9px 10px; }
  .f13-disclosure-count { margin-top: 1px; }
  .f13-disclosure-body { padding: 9px; }
}

.f4-desk {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--violet) 32%, var(--border));
  border-radius: var(--r-3);
  background: linear-gradient(145deg, color-mix(in srgb, var(--violet) 5%, var(--surface)), var(--surface));
}
.f4-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; }
.f4-head h3 { margin: 3px 0 5px; color: var(--text-strong); font-size: 20px; }
.f4-head p { margin: 0; max-width: 780px; color: var(--text-2); font-size: 13px; line-height: 1.5; }
.f4-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.f4-side {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface);
}
.f4-side > header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--hairline);
  color: var(--text-strong);
  font-weight: 750;
}
.f4-side > header small { color: var(--muted); font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: .04em; }
.f4-side-buy > header { box-shadow: inset 3px 0 0 var(--up); }
.f4-side-sell > header { box-shadow: inset 3px 0 0 var(--dn); }
.f4-row { display: flex; flex-direction: column; gap: 5px; padding: 9px 10px; border-top: 1px solid var(--hairline); }
.f4-side > header + .f4-row { border-top: 0; }
.f4-row-top { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 8px; }
.f4-row-top b { overflow: hidden; color: var(--text-strong); text-overflow: ellipsis; white-space: nowrap; }
.f4-row-top time { color: var(--muted); font: 600 11px/1 var(--font-mono); }
.f4-row-metrics { display: flex; flex-wrap: wrap; gap: 6px 10px; color: var(--text-2); font: 600 12px/1.25 var(--font-mono); }
.f4-buy .f4-row-metrics strong { color: var(--up); }
.f4-sell .f4-row-metrics strong { color: var(--dn); }
.f4-row > small { color: var(--muted); font-size: 10px; line-height: 1.3; }
.f4-none { margin: 0; padding: 16px 10px; color: var(--muted); font-size: 12px; }
.f4-all { border-top: 1px solid var(--hairline); padding-top: 10px; }
.f4-all > summary { cursor: pointer; color: var(--text-strong); font-weight: 700; }
.f4-all > summary span { margin-left: 5px; color: var(--muted); font-family: var(--font-mono); }
.f4-table { margin-top: 10px; min-width: 760px; }
.f4-table a { color: var(--accent-strong); text-decoration: underline; text-underline-offset: 2px; }
.f4-other-row { color: var(--muted); }
@media (max-width: 760px){
  .f4-head { flex-direction: column; }
  .f4-grid { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 480px){
  .f4-desk { padding: 10px; }
  .f4-row-top { grid-template-columns: auto minmax(0, 1fr); }
  .f4-row-top time { grid-column: 2; }
}

/* === Top picks tab === */
/* Master → detail. The landing view is a grid of clickable ticker tabs;
   clicking one opens a focused page that judges just that ticker, with a back
   button to return. Keeps the long judgment cards off the landing view entirely
   — far cleaner to scan, especially on mobile. */
.picks-listview[hidden],
.picks-detail[hidden] { display: none; }
.picks-detail { margin-top: var(--s-3); }

/* Landing grid of ticker tabs. */
.picks-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(232px, 1fr));
  gap: 10px;
  margin-top: var(--s-3);
}
.pick-tab-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas:
    "rank head   score"
    "rank tier   tier"
    "rank thesis thesis"
    "rank entry  entry"
    "rank con    con"
    "rank meta   meta"
    "rank cta    cta";
  column-gap: 12px;
  row-gap: 3px;
  align-items: center;
  text-align: left;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-left-width: 4px;
  border-radius: var(--r-3);
  background: var(--surface-2);
  background-image: var(--grad-surface);
  box-shadow: var(--elev-1);
  color: var(--text);
  cursor: pointer;
  appearance: none;
  font: inherit;
  transition: border-color .15s var(--ease-out), box-shadow .15s var(--ease-out), transform .12s var(--ease-out);
}
.pick-tab-card:hover {
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border));
  box-shadow: var(--elev-2);
  transform: translateY(-1px);
}
.pick-tab-card.call { border-left-color: var(--pos); }
.pick-tab-card.put  { border-left-color: var(--neg); }
.ptc-rank {
  grid-area: rank;
  align-self: start;
  font: 700 20px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--muted);
}
.pick-tab-card.call .ptc-rank { color: color-mix(in srgb, var(--pos) 70%, var(--muted)); }
.pick-tab-card.put  .ptc-rank { color: color-mix(in srgb, var(--neg) 70%, var(--muted)); }
.ptc-head { grid-area: head; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; min-width: 0; }
/* The ticker is the card's headline — it must never truncate. Keep it from
   shrinking; the side/timing badges wrap to a second line on a narrow card
   instead of crushing the symbol to "C…". */
.ptc-sym {
  flex: 0 0 auto;
  font: 700 16px/1 var(--font-mono);
  color: var(--text-strong);
  letter-spacing: .02em;
  white-space: nowrap;
}
.ptc-side {
  flex: 0 0 auto;
  font: 700 9px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .06em;
  padding: 3px 5px;
  border-radius: 3px;
}
.ptc-side-call { color: var(--pos); background: color-mix(in srgb, var(--pos) 12%, transparent); }
.ptc-side-put  { color: var(--neg); background: color-mix(in srgb, var(--neg) 12%, transparent); }
/* Neutral muted tint over the card (the card itself is --surface-2, so a flat
   --surface-2 chip would vanish). Geometry matches the adjacent .ptc-side chip;
   only the hue is neutral instead of the call/put green/red. */
.ptc-streak {
  flex: 0 0 auto;
  font: 700 9px/1 var(--font-mono);
  letter-spacing: .06em;
  padding: 3px 5px;
  border-radius: 3px;
  color: var(--muted);
  background: color-mix(in srgb, var(--muted) 16%, transparent);
  white-space: nowrap;
}
/* Live "since it appeared" modeled-contract mark, read from the track record.
   Mono, tabular, color-coded by sign (sig-pos/sig-neg set the hue); the "new"
   variant (same-build debut) is a muted, neutral badge. */
.ptc-live {
  flex: 0 0 auto;
  font: 700 10px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  letter-spacing: .02em;
  padding: 3px 5px;
  border-radius: 3px;
  white-space: nowrap;
  background: color-mix(in srgb, currentColor 12%, transparent);
}
.ptc-live-new {
  color: var(--muted);
  background: color-mix(in srgb, var(--muted) 14%, transparent);
}
.ptc-score {
  grid-area: score;
  align-self: start;
  font: 700 20px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--text-strong);
}
/* P5.1 execution-cost debit beside the score — the round-trip spread charged
   against the grade for roster ranking. */
.ptc-cost {
  font: 600 12px/1 var(--font-mono);
  color: var(--warn);
  white-space: nowrap;
}
.pick-tab-card.call .ptc-score { color: var(--pos); }
.pick-tab-card.put  .ptc-score { color: var(--neg); }
.ptc-tier {
  grid-area: tier;
  font: 600 12px/1.3 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .03em;
  color: var(--text-strong);
}
/* Entry call — "buy now" (green) vs a specific wait-for trigger price (amber).
   Surfaced on the grid tile so the ranked list is triageable at a glance. */
.ptc-entry {
  grid-area: entry;
  justify-self: start;
  font: 700 11px/1 var(--font-mono);
  letter-spacing: .03em;
  padding: 4px 8px;
  border-radius: 4px;
  white-space: nowrap;
}
.ptc-entry-now {
  color: var(--pos);
  background: color-mix(in srgb, var(--pos) 16%, transparent);
  border: 1px solid color-mix(in srgb, var(--pos) 40%, var(--border));
}
.ptc-entry-wait {
  color: var(--warn);
  background: color-mix(in srgb, var(--warn) 14%, var(--surface));
  border: 1px solid color-mix(in srgb, var(--warn) 36%, var(--border));
}
/* Live overlay states (applyLiveEntryChips, 30s quote poll): -live = the
   pullback/dip trigger has been reached — the plan's buy zone is here now
   (green, pulsing); -arm = a 20D reclaim level crossed intraday, still
   needs a confirming close (amber, dashed). */
.ptc-entry-live {
  color: var(--pos);
  background: color-mix(in srgb, var(--pos) 22%, transparent);
  border: 1px solid color-mix(in srgb, var(--pos) 55%, var(--border));
  animation: entry-live-pulse 2.2s ease-in-out infinite;
}
.ptc-entry-arm {
  color: var(--warn);
  background: color-mix(in srgb, var(--warn) 20%, var(--surface));
  border: 1px dashed color-mix(in srgb, var(--warn) 55%, var(--border));
}
@keyframes entry-live-pulse {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--pos) 35%, transparent); }
  50% { box-shadow: 0 0 0 5px transparent; }
}
@media (prefers-reduced-motion: reduce) {
  .ptc-entry-live, .pick-rr-live { animation: none; }
}
/* Contract economics line — strike·DTE, premium, move-to-breakeven, earnings
   flag. Makes the premium / breakeven sorts legible on the grid and lets picks
   be compared without drilling into each detail page. */
.ptc-contract {
  grid-area: con;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 3px 8px;
  margin-top: 1px;
  font: 600 12px/1.2 var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.ptc-con-k { color: var(--text-strong); }
.ptc-con-prem { color: var(--text); }
.ptc-con-be { color: var(--muted); }
/* Breakeven move colored by reachability vs the chain-priced 1σ move (rrRatio). */
.ptc-con-be-good { color: var(--pos); }
.ptc-con-be-fair { color: var(--warn); }
.ptc-con-be-bad  { color: var(--neg); }
.ptc-con-er {
  color: var(--warn);
  font-weight: 700;
  letter-spacing: .03em;
}
/* Defined-risk debit-spread marker on the landing tile (PICKS_VERT_AUTO). */
.ptc-con-spread {
  color: var(--accent);
  font-weight: 700;
  letter-spacing: .02em;
}
/* Probability-of-profit chip on the landing tile (color via .ptc-con-be-*). */
.ptc-con-pop { font-weight: 700; letter-spacing: .02em; }
/* Defined-risk spread structure block on the pick detail (pickVerticalStructureHtml). */
.pick-vert {
  margin: 10px 0 4px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent) 6%, transparent);
}
.pick-vert-head {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: .02em;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.pick-vert-tag {
  font-size: 11.5px;
  font-weight: 600;
  color: var(--muted);
  letter-spacing: .03em;
}
.pick-vert-legs { margin: 8px 0; display: flex; flex-direction: column; gap: 4px; }
.pick-vert-leg {
  display: grid;
  grid-template-columns: 52px 1fr auto;
  align-items: center;
  gap: 8px;
  font-size: 13.5px;
}
.pick-vert-side { font-size: 11px; font-weight: 700; letter-spacing: .04em; }
.pick-vert-long  { color: var(--pos); }
.pick-vert-short { color: var(--neg); }
.pick-vert-k { color: var(--text); font-variant-numeric: tabular-nums; }
.pick-vert-prem { color: var(--muted); font-variant-numeric: tabular-nums; }
.pick-vert-econ { display: flex; gap: 16px; flex-wrap: wrap; padding-top: 6px; border-top: 1px dashed var(--border); }
.pick-vert-stat-label { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
.pick-vert-stat-val { font-size: 14px; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--text); }
.pick-vert-loss { color: var(--neg); }
.pick-vert-profit { color: var(--pos); }
.ptc-thesis {
  grid-area: thesis;
  font: 400 12.5px/1.45 var(--font-sans); color: var(--text);
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.ptc-meta { grid-area: meta; font-size: 12px; color: var(--muted); }
.ptc-cta {
  grid-area: cta;
  margin-top: 4px;
  font: 600 11px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--accent);
}

/* Detail page back button. */
.picks-back {
  display: inline-flex;
  align-items: center;
  padding: 7px 13px;
  margin-bottom: var(--s-3);
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  background: var(--surface-2);
  color: var(--text);
  cursor: pointer;
  appearance: none;
  font: 600 13px/1 var(--font-mono);
  transition: background .15s var(--ease-out), border-color .15s var(--ease-out);
}
.picks-back:hover {
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
  border-color: color-mix(in srgb, var(--accent) 30%, var(--border));
}
.picks-empty {
  padding: var(--s-4) var(--s-3);
  text-align: center;
  color: var(--muted);
  font-size: 13px;
}
.picks-foot {
  font-size: 11px;
  color: var(--muted);
  margin: var(--s-3) 0 0;
  line-height: 1.45;
}
.pick-card {
  display: grid;
  /* Two columns: rank gutter + main body. The score breakdown used to be a
     third always-on column; it now lives inside the body as the "Grade" tab. */
  grid-template-columns: 48px minmax(0, 1fr);
  gap: var(--s-3);
  padding: var(--s-3);
  border: 1px solid var(--border);
  border-left-width: 4px;
  border-radius: var(--r-3);
  background: var(--surface-2);
  background-image: var(--grad-surface);
  box-shadow: var(--elev-1);
  align-items: stretch;
  /* Tab switches scroll here; clear the sticky site-header + ticker tab strip. */
  scroll-margin-top: 108px;
  transition: border-color .18s var(--ease-out), box-shadow .18s var(--ease-out), transform .18s var(--ease-out);
}
/* Side color bleeds into the rank gutter only, then fades — a directional
   cue that doesn't wash the whole card. */
.pick-card.call { border-left-color: var(--pos); background-image: linear-gradient(90deg, color-mix(in srgb, var(--pos) 7%, transparent) 0, transparent 64px), var(--grad-surface); }
.pick-card.put  { border-left-color: var(--neg); background-image: linear-gradient(90deg, color-mix(in srgb, var(--neg) 7%, transparent) 0, transparent 64px), var(--grad-surface); }
.pick-card:hover {
  border-color: color-mix(in srgb, var(--accent) 30%, var(--border));
}
/* The #1 leader card sits proud — real elevation + a side-keyed top wash +
   a contained directional glow, not the old near-invisible flat tint. */
.pick-card.pick-card-leader {
  border-left-width: 5px;
  box-shadow: var(--elev-2);
}
.pick-card-leader.call {
  background-image: linear-gradient(180deg, color-mix(in srgb, var(--pos) 12%, var(--surface-2)) 0%, var(--surface-2) 42%), var(--grad-surface);
  box-shadow: var(--elev-2), 0 0 28px -10px var(--pos-glow);
}
.pick-card-leader.put {
  background-image: linear-gradient(180deg, color-mix(in srgb, var(--neg) 12%, var(--surface-2)) 0%, var(--surface-2) 42%), var(--grad-surface);
  box-shadow: var(--elev-2), 0 0 28px -10px var(--neg-glow);
}

.pick-rank {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 1px;
  /* Anchor the rank to the top of the gutter so it baseline-aligns with the
     ticker in the head row — not floating at the vertical center of a very
     tall card. */
  align-self: start;
  padding-top: 2px;
  text-align: center;
  color: var(--muted);
  letter-spacing: -.02em;
}
.pick-rank-hash {
  font: 600 13px/1 var(--font-mono);
  opacity: .55;
}
.pick-rank-num {
  font: 700 26px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.pick-card.call .pick-rank { color: color-mix(in srgb, var(--pos) 70%, var(--muted)); }
.pick-card.put  .pick-rank { color: color-mix(in srgb, var(--neg) 70%, var(--muted)); }
.pick-card.call .pick-rank-top1 { color: var(--pos); }
.pick-card.put  .pick-rank-top1 { color: var(--neg); }
/* The #1 pick gets a filled medallion instead of plain "#1" text. */
.pick-rank-top1 .pick-rank-hash { display: none; }
.pick-rank-top1 .pick-rank-num {
  color: var(--accent-fg);
  border-radius: var(--r-pill);
  padding: 4px 9px;
  font-size: 24px;
  box-shadow: var(--elev-glow);
}
.pick-card.call .pick-rank-top1 .pick-rank-num { background: var(--pos); }
.pick-card.put  .pick-rank-top1 .pick-rank-num { background: var(--neg); }
.pick-rank-top2 .pick-rank-num,
.pick-rank-top3 .pick-rank-num { font-size: 28px; }
.pick-main { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.pick-head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}
.pick-symbol {
  appearance: none;
  background: transparent;
  border: 0;
  padding: 0;
  font: 700 16px/1 var(--font-mono);
  color: var(--text-strong);
  cursor: pointer;
  letter-spacing: .02em;
  transition: color .12s var(--ease-out);
}
.pick-symbol:hover { color: var(--accent); }
.pick-spot {
  font: 500 13px/1 var(--font-mono);
  color: var(--muted);
}
.pick-sector {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--muted);
  padding: 2px 6px;
  border-radius: var(--r-1);
  border: 1px solid var(--border);
}
.pick-side {
  font: 700 11px/1 var(--font-mono);
  letter-spacing: .08em;
  padding: 3px 7px;
  border-radius: var(--r-1);
}
.pick-side-call { background: var(--pos-soft); color: var(--pos); }
.pick-side-put { background: var(--neg-soft); color: var(--neg); }
.pick-side-neutral { background: var(--surface); color: var(--muted); border: 1px solid var(--border); }

/* Grade-only card (off-list searched ticker) — no rank gutter, so collapse the
   pick-card's two-column grid to a single column. */
.pick-card.pick-grade-card { grid-template-columns: minmax(0, 1fr); }
/* No-trade names render neutral (no green/red side wash). */
.pick-card.pick-grade-neutral { border-left-color: var(--border); }
.pick-offlist-note {
  margin: 0 0 var(--s-3);
  padding: 8px 10px;
  border-radius: var(--r-2);
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--muted);
  font-size: var(--fs-sm);
  line-height: 1.45;
}
.pick-streak {
  font: 600 11px/1 var(--font-mono);
  letter-spacing: .04em;
  padding: 3px 6px;
  border-radius: var(--r-1);
}
.pick-streak-green { background: var(--pos-soft); color: var(--pos); }
.pick-streak-red { background: var(--neg-soft); color: var(--neg); }
.pick-tenure {
  font: 600 11px/1 var(--font-mono);
  letter-spacing: .04em;
  padding: 3px 6px;
  border-radius: var(--r-1);
  background: var(--surface-2);
  color: var(--muted);
  cursor: help;
}
.pick-thesis {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: var(--text);
}
.pick-drivers {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 2px;
}
.pick-driver {
  font: 500 11px/1.3 var(--font-mono);
  padding: 2px 7px;
  border-radius: var(--r-pill);
  border: 1px solid var(--border);
  color: var(--muted);
  background: var(--surface);
  transition: border-color .12s var(--ease-out), background .12s var(--ease-out), color .12s var(--ease-out);
}
.pick-driver:hover { color: var(--text); border-color: var(--border-strong); }
.pick-driver-pos {
  color: var(--pos);
  border-color: color-mix(in srgb, var(--pos) 30%, var(--border));
  background: color-mix(in srgb, var(--pos) 5%, var(--surface));
}
.pick-driver-pos:hover {
  border-color: color-mix(in srgb, var(--pos) 55%, var(--border));
  background: color-mix(in srgb, var(--pos) 8%, var(--surface));
}
.pick-driver-neg {
  color: var(--neg);
  border-color: color-mix(in srgb, var(--neg) 30%, var(--border));
  background: color-mix(in srgb, var(--neg) 5%, var(--surface));
}
.pick-driver-neg:hover {
  border-color: color-mix(in srgb, var(--neg) 55%, var(--border));
  background: color-mix(in srgb, var(--neg) 8%, var(--surface));
}
.pick-driver-narrative { font-weight: 600; }

/* Grouped driver rows — "For" (signals aligned with this pick's side) and
   "Against" (signals pulling the other way). Stacks vertically; the label
   chip sits inline at the start of each row so the eye groups chips by
   stance instead of treating a bullish chip next to a bearish chip as the
   same kind of evidence. */
.pick-drivers-grouped {
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
}
.pick-drivers-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
}
.pick-drivers-label {
  font: 700 11px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 2px 6px;
  border-radius: var(--r-pill);
  color: var(--muted);
  background: var(--surface-3);
  border: 1px solid var(--hairline);
  margin-right: 2px;
}
.pick-drivers-for .pick-drivers-label {
  color: var(--pos);
  background: color-mix(in srgb, var(--pos) 10%, transparent);
  border-color: color-mix(in srgb, var(--pos) 35%, var(--hairline));
}
.pick-drivers-against .pick-drivers-label {
  color: var(--neg);
  background: color-mix(in srgb, var(--neg) 10%, transparent);
  border-color: color-mix(in srgb, var(--neg) 35%, var(--hairline));
}

/* Suggested contract block — strike/expiry, quote, Greeks, breakeven, and
   a one-click jump into the grader pre-filled with the recommendation. */
.pick-contract {
  margin-top: 8px;
  padding: 8px 10px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.pick-card.call .pick-contract { border-left: 2px solid color-mix(in srgb, var(--pos) 45%, var(--border)); }
.pick-card.put  .pick-contract { border-left: 2px solid color-mix(in srgb, var(--neg) 45%, var(--border)); }
.pick-contract-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}
.pick-contract-label {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
}
.pick-contract-strike {
  font: 700 13px/1.2 var(--font-mono);
  color: var(--text-strong);
  font-variant-numeric: tabular-nums;
  letter-spacing: -.01em;
}
.pick-contract-meta {
  font: 500 12px/1.4 var(--font-mono);
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

/* Stat grid — replaces the dense mono lines (quote, greeks, breakeven) with
   a labeled three-cell layout so the user can find the price, the breakeven,
   and the greek summary at a glance. Each stat is a small card with a
   muted uppercase label, a tabular numeric primary value, and a muted
   sub-line of context (bid/ask, % to breakeven, etc.). */
.pick-stat-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, 1.4fr);
  gap: 6px;
  margin-top: 6px;
  /* The three readouts now read as one recessed instrument cluster rather
     than three loose boxes. */
  padding: 8px;
  background: color-mix(in srgb, var(--bg) 35%, var(--surface));
  border: 1px solid var(--hairline);
  border-radius: var(--r-2);
}
.pick-stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 2px 6px;
  border-radius: var(--r-1);
  background: transparent;
  border: 0;
  min-width: 0;
}
.pick-stat-label {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
}
/* "● live" badge next to the Greeks label — the row recomputes from the polled
   spot every 30s while the Top Picks tab is open. */
.pick-greeks-live {
  margin-left: 5px;
  color: var(--pos);
  letter-spacing: .04em;
}
.pick-stat-value {
  font: 800 16px/1.1 var(--font-mono);
  color: var(--text-strong);
  font-variant-numeric: tabular-nums;
  letter-spacing: -.01em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pick-stat-sub {
  font: 500 11px/1.2 var(--font-mono);
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pick-stat-greeks .pick-stat-greek-row {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font: 500 12px/1.2 var(--font-mono);
  color: var(--text);
  font-variant-numeric: tabular-nums;
}
.pick-stat-greeks .pick-stat-greek-row > span {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
}
.pick-stat-greeks .pick-stat-greek-row b {
  color: var(--muted);
  font-weight: 600;
  width: 1.1em;
  display: inline-block;
}
@media (max-width: 640px) {
  .pick-stat-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .pick-stat-greeks { grid-column: 1 / -1; }
  .pick-stat-greeks .pick-stat-greek-row { flex-direction: row; flex-wrap: wrap; gap: 8px; }
}
.pick-contract-grade {
  align-self: flex-start;
  margin-top: 4px;
  padding: 6px 10px;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--border));
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
  color: var(--text-strong);
  border-radius: var(--r-2);
  font: 600 13px/1 var(--font-sans);
  cursor: pointer;
  transition: background .15s var(--ease-out), border-color .15s var(--ease-out);
}
.pick-contract-grade:hover {
  background: color-mix(in srgb, var(--accent) 18%, var(--surface));
  border-color: color-mix(in srgb, var(--accent) 60%, var(--border));
}

/* Overall-quality accent: an extra glow tint when every component
   grades clean. Subtle on dark, near-invisible on light. */
.pick-contract-overall-good {
  background-image: linear-gradient(180deg,
    color-mix(in srgb, var(--accent) 6%, var(--surface)) 0%,
    var(--surface) 70%);
  box-shadow: var(--elev-1), 0 0 18px -8px var(--accent-glow);
}
.pick-contract-overall-bad {
  background-image: linear-gradient(180deg,
    color-mix(in srgb, var(--neg) 6%, var(--surface)) 0%,
    var(--surface) 70%);
}

/* Risk/reward readout — compares required breakeven move to
   IV-implied 1σ expected move. Color-coded by ratio. */
.pick-contract-rr {
  font: 600 12px/1.3 var(--font-mono);
  font-variant-numeric: tabular-nums;
  padding: 3px 8px;
  border-radius: var(--r-pill);
  display: inline-block;
  margin-top: 2px;
  /* Demoted from a heavy filled block to a hairline chip so this secondary
     risk readout stops out-shouting the tier banner above it. */
  background: transparent;
  border: 1px solid var(--border);
}
.pick-rr-good { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 30%, var(--border)); }
.pick-rr-fair { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 30%, var(--border)); }
/* Live entry overlay on the detail card (mirrors .ptc-entry-live/-arm). */
.pick-rr-live { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 55%, var(--border)); animation: entry-live-pulse 2.2s ease-in-out infinite; }
.pick-rr-arm { color: var(--warn); border-style: dashed; border-color: color-mix(in srgb, var(--warn) 55%, var(--border)); }
.pick-rr-bad  { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 30%, var(--border)); }

/* Contract-quality chip row — Spread / Liq / Δ / Θ / IV. Each chip
   shows label + grade, color-coded so the user can eyeball
   mechanical risk before pulling the trigger. */
.pick-contract-quality {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
}
.pick-qchip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: var(--r-pill);
  font: 600 11px/1 var(--font-mono);
  letter-spacing: 0.04em;
  border: 1px solid var(--hairline);
  background: transparent;
}
.pick-qchip-label { color: var(--muted); text-transform: uppercase; }
.pick-qchip-val { color: var(--text); }
.pick-qchip-good {
  background: transparent;
  border-color: color-mix(in srgb, var(--pos) 40%, var(--hairline));
}
.pick-qchip-good .pick-qchip-val { color: var(--pos); }
/* "fair" is the resting/neutral state — hairline only, so it recedes and the
   problem ("bad") chip is the one that pops. */
.pick-qchip-fair {
  background: transparent;
  border-color: var(--hairline);
}
.pick-qchip-fair .pick-qchip-val { color: var(--warn); }
.pick-qchip-bad {
  background: var(--neg-soft);
  border-color: color-mix(in srgb, var(--neg) 45%, transparent);
}
.pick-qchip-bad .pick-qchip-val { color: var(--neg); }

/* Earnings-in-window badge — small warning chip in the header. */
.pick-badge {
  display: inline-block;
  padding: 2px 6px;
  border-radius: var(--r-pill);
  font: 700 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border: 1px solid transparent;
}
.pick-badge-warn {
  color: var(--warn);
  background: var(--warn-soft);
  border-color: color-mix(in srgb, var(--warn) 40%, transparent);
}

.pick-conviction {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 6px 4px;
  border-left: 1px solid var(--border);
  min-width: 60px;
}
.pick-conv-label {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
}
.pick-conv-value {
  font: 700 24px/1 var(--font-mono);
  color: var(--text-strong);
  font-variant-numeric: tabular-nums;
  display: inline-flex;
  align-items: baseline;
}
.pick-conv-max {
  font: 500 12px/1 var(--font-mono);
  color: var(--muted);
  margin-left: 1px;
}
.pick-conv-bar {
  width: 36px;
  height: 6px;
  background: color-mix(in srgb, var(--text) 8%, var(--surface));
  border-radius: var(--r-pill);
  overflow: hidden;
  position: relative;
}
.pick-conv-fill {
  display: block;
  width: var(--pick-conv-pct, 50%);
  height: 100%;
  background: color-mix(in srgb, var(--accent) 70%, transparent);
  border-radius: var(--r-pill);
  transition: height .3s var(--ease-out), width .3s var(--ease-out);
}
.pick-card.call .pick-conv-fill { background: color-mix(in srgb, var(--pos) 75%, transparent); }
.pick-card.put .pick-conv-fill { background: color-mix(in srgb, var(--neg) 75%, transparent); }
.pick-card.call .pick-conv-value { color: color-mix(in srgb, var(--pos) 65%, var(--text-strong)); }
.pick-card.put  .pick-conv-value { color: color-mix(in srgb, var(--neg) 65%, var(--text-strong)); }

/* Controls bar above the picks list — currently just a sort dropdown. */
.picks-controls {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-3);
  align-items: center;
  margin: 0 0 12px;
}
.picks-sort,
.streaks-sort,
.vol-sort,
.acc-sort {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--fs-sm);
  color: var(--muted);
}
.picks-sort-label,
.streaks-sort-label,
.vol-sort-label,
.acc-sort-label {
  font-size: var(--fs-xs);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 700;
}
.picks-sort select,
.streaks-sort select,
.vol-sort select,
.acc-sort select {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  color: var(--text);
  font: inherit;
  font-size: var(--fs-sm);
  padding: 4px 8px;
  cursor: pointer;
}
.picks-sort select:focus-visible,
.streaks-sort select:focus-visible,
.vol-sort select:focus-visible,
.acc-sort select:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border));
}
.vol-sort { margin-left: auto; }
/* Track-record resolved-list sort rides inside the mono-uppercase group head —
   undo the inherited casing/spacing so the control reads as UI, not a heading. */
.acc-sort {
  margin-left: auto;
  font: 400 var(--fs-sm)/1.2 var(--font-sans);
  text-transform: none;
  letter-spacing: normal;
}
.acc-sort select { text-transform: none; letter-spacing: normal; }
@media (max-width: 640px){
  .vol-sort { margin-left: 0; }
  .picks-sort-label,
  .streaks-sort-label,
  .vol-sort-label,
  .acc-sort-label { display: none; }
}

/* Streaks controls row — filter fields + sort selector sit just above the
   two-column bullish/bearish grid. */
.streaks-controls {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-3);
  align-items: center;
  margin: 0 0 12px;
}
.streaks-field {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--fs-sm);
  color: var(--muted);
}
.streaks-field-label {
  font-size: var(--fs-xs);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 700;
}
.streaks-field select,
.streaks-field input {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  color: var(--text);
  font: inherit;
  font-size: var(--fs-sm);
  padding: 4px 8px;
}
.streaks-field select { cursor: pointer; }
.streaks-field-search input { width: 9ch; transition: width .15s var(--ease-out); }
.streaks-field-search input:focus { width: 12ch; }
.streaks-field select:focus-visible,
.streaks-field input:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border));
}
.streaks-sort { margin-left: auto; }
@media (max-width: 640px) {
  .streaks-sort { margin-left: 0; }
  .streaks-field-label { display: none; }
}

/* Summary strip — small chip row above the cards that shows the shape of
   today's picks (counts of call/put, average conviction, any earnings-window
   contracts) so the user can read the list's character before scrolling. */
.picks-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}
.picks-summary:empty { display: none; }
.picks-summary-chip {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  padding: 6px 10px;
  border-radius: var(--r-2);
  border: 1px solid var(--border);
  background: var(--surface);
  box-shadow: var(--elev-1);
}
.picks-summary-num {
  font: 800 18px/1 var(--font-mono);
  color: var(--text-strong);
  font-variant-numeric: tabular-nums;
  letter-spacing: var(--ls-display);
}
.picks-summary-lbl {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
}
.picks-summary-call {
  border-color: color-mix(in srgb, var(--pos) 30%, var(--border));
  background: color-mix(in srgb, var(--pos) 5%, var(--surface));
}
.picks-summary-call .picks-summary-num { color: var(--pos); }
.picks-summary-call .picks-summary-lbl { color: var(--pos); opacity: .8; }
.picks-summary-put {
  border-color: color-mix(in srgb, var(--neg) 30%, var(--border));
  background: color-mix(in srgb, var(--neg) 5%, var(--surface));
}
.picks-summary-put .picks-summary-num { color: var(--neg); }
.picks-summary-put .picks-summary-lbl { color: var(--neg); opacity: .8; }
.picks-summary-warn {
  border-color: color-mix(in srgb, var(--warn) 35%, var(--border));
  background: color-mix(in srgb, var(--warn) 6%, var(--surface));
}
.picks-summary-warn .picks-summary-num { color: var(--warn); }
.picks-summary-warn .picks-summary-lbl { color: var(--warn); opacity: .85; }
/* "Strong" tier count — the most important number in the strip. The markup
   has always emitted .picks-summary-strong but no rule existed, so it looked
   the least special. Give it the accent treatment. */
.picks-summary-strong {
  border-color: color-mix(in srgb, var(--accent) 40%, var(--border));
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
  box-shadow: var(--elev-1), 0 0 16px -8px var(--accent-glow);
}
.picks-summary-strong .picks-summary-num { color: var(--accent); }
.picks-summary-strong .picks-summary-lbl { color: var(--accent); opacity: .85; }

/* --- Live "market tape" — cross-asset macro regime ----------------------- */
/* display:contents keeps the live-replaced regime chip inline with the other
   summary chips while its wrapper carries the stable #picks-regime-chip id. */
.picks-regime-slot { display: contents; }
.picks-tape-dot { color: var(--pos); font-size: .8em; animation: tape-pulse 2.2s ease-in-out infinite; }
@keyframes tape-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }

.market-action { margin: 0 0 var(--s-4); }
.market-action[hidden] { display: none; }
.market-action-card {
  overflow: hidden;
  border: 1px solid var(--border);
  border-left: 3px solid var(--border-strong);
  border-radius: var(--r-4);
  background: linear-gradient(145deg, color-mix(in srgb, var(--text) 3%, var(--surface)), var(--surface-2));
  box-shadow: var(--elev-1);
}
.market-action-on { border-left-color: var(--pos); }
.market-action-off { border-left-color: var(--neg); }
.market-action-warn { border-left-color: var(--warn); }
.market-action-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--s-4);
  padding: var(--s-4);
  border-bottom: 1px solid var(--border);
}
.market-action-kicker,
.market-action-grid small,
.market-action-why small {
  display: block;
  color: var(--muted);
  font: 700 var(--fs-2xs)/1 var(--font-mono);
  letter-spacing: var(--ls-caps);
  text-transform: uppercase;
}
.market-action-head h3 {
  margin: 5px 0 6px;
  color: var(--text-strong);
  font-size: var(--fs-xl);
  line-height: var(--lh-tight);
}
.market-action-on .market-action-head h3 { color: var(--pos); }
.market-action-off .market-action-head h3 { color: var(--neg); }
.market-action-warn .market-action-head h3 { color: var(--warn); }
.market-action-head p {
  max-width: 88ch;
  margin: 0;
  color: var(--text);
  font-size: var(--fs-sm);
  line-height: var(--lh-snug);
}
.market-action-head p b { color: var(--text-strong); }
.market-action-source {
  flex: none;
  padding: 5px 8px;
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  color: var(--muted);
  font: 700 var(--fs-2xs)/1 var(--font-mono);
  letter-spacing: .05em;
  text-transform: uppercase;
  white-space: nowrap;
}
.market-action-source.is-live { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 40%, var(--border)); }
.market-action-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-bottom: 1px solid var(--border);
}
.market-action-grid > span {
  min-width: 0;
  padding: var(--s-3) var(--s-4);
  border-right: 1px solid var(--border);
}
.market-action-grid > span:last-child { border-right: 0; }
.market-action-grid b {
  display: block;
  margin-top: 5px;
  color: var(--text-strong);
  font-size: var(--fs-sm);
  line-height: var(--lh-tight);
}
.market-action-grid b.picks-summary-call { color: var(--pos); }
.market-action-grid b.picks-summary-put { color: var(--neg); }
.market-action-grid b.picks-summary-warn { color: var(--warn); }
.market-action-why {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--s-3);
  padding: var(--s-3) var(--s-4);
  border-bottom: 1px solid var(--border);
}
.market-action-why p {
  min-width: 0;
  margin: 0;
  padding: var(--s-3);
  border: 1px solid var(--border);
  border-radius: var(--r-3);
  background: var(--surface);
}
.market-action-why span {
  display: block;
  margin-top: 6px;
  color: var(--muted);
  font-size: var(--fs-xs);
  line-height: var(--lh-snug);
}
.market-action-why span b,
.market-action-why span i { color: var(--text); }
.market-action-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-4);
  padding: var(--s-3) var(--s-4);
}
.market-action-foot > span { color: var(--muted); font-size: var(--fs-xs); line-height: var(--lh-snug); }
.market-action-foot > span b { color: var(--text-strong); }
.market-action-foot > div { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: var(--s-2); }
.market-action-foot button {
  padding: 8px 11px;
  border: 1px solid var(--border-strong);
  border-radius: var(--r-2);
  background: var(--surface);
  color: var(--text);
  font: 700 var(--fs-2xs)/1 var(--font-sans);
  cursor: pointer;
  white-space: nowrap;
}
.market-action-foot button:first-child { border-color: var(--accent); background: var(--accent-tint-1); }
.market-action-foot button:hover,
.market-action-foot button:focus-visible { border-color: var(--accent); background: var(--accent-tint-2); outline: none; }
@media (max-width: 760px) {
  .market-action-head { padding: var(--s-3); flex-direction: column; gap: var(--s-2); }
  .market-action-source { align-self: flex-start; }
  .market-action-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .market-action-grid > span:nth-child(2) { border-right: 0; }
  .market-action-grid > span:nth-child(-n+2) { border-bottom: 1px solid var(--border); }
  .market-action-why { grid-template-columns: 1fr; padding: var(--s-3); }
  .market-action-foot { align-items: stretch; flex-direction: column; padding: var(--s-3); }
  .market-action-foot > div { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); justify-content: stretch; }
  .market-action-foot button { min-width: 0; white-space: normal; }
}
@media (max-width: 430px) {
  .market-action-head h3 { font-size: var(--fs-lg); }
  .market-action-head p { font-size: var(--fs-xs); }
  .market-action-grid > span { padding: 9px; }
  .market-action-grid b { font-size: var(--fs-xs); }
  .market-action-foot > div { grid-template-columns: 1fr; }
}

/* --- Forward scenario + sensitivity engine ----------------------------- */
.market-scenario-engine { margin: 0 0 var(--s-4); min-width: 0; }
.market-scenario-engine[hidden] { display: none; }
.scenario-shell {
  min-width: 0; overflow: hidden;
  border: 1px solid var(--border); border-left: 3px solid var(--accent);
  border-radius: var(--r-3);
  background: linear-gradient(150deg, color-mix(in srgb, var(--accent) 4%, var(--surface)), var(--surface-2));
  box-shadow: var(--elev-1);
}
.market-scenario-engine.is-fragile .scenario-shell { border-left-color: var(--neg); }
.market-scenario-engine.is-watch .scenario-shell { border-left-color: var(--warn); }
.scenario-head {
  display: flex; align-items: flex-start; justify-content: space-between; gap: var(--s-4);
  padding: var(--s-4); border-bottom: 1px solid var(--border);
}
.scenario-kicker,
.scenario-section > header small,
.scenario-driver > header small,
.scenario-path summary small,
.scenario-transition small,
.scenario-shocks small,
.scenario-controls label > span,
.scenario-basket header small,
.scenario-basket-result small {
  display: block; color: var(--muted);
  font: 700 var(--fs-2xs)/1.2 var(--font-mono);
  letter-spacing: var(--ls-caps); text-transform: uppercase;
}
.scenario-head h3 { margin: 6px 0; color: var(--text-strong); font-size: var(--fs-xl); line-height: var(--lh-tight); }
.scenario-head p { max-width: 85ch; margin: 0; color: var(--muted-strong); font-size: var(--fs-sm); line-height: var(--lh-snug); }
.scenario-head > em { flex: none; color: var(--muted); font: 600 var(--fs-2xs)/1.2 var(--font-mono); font-style: normal; white-space: nowrap; }
.scenario-transition { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-bottom: 1px solid var(--border); }
.scenario-transition > span { min-width: 0; padding: var(--s-3) var(--s-4); border-right: 1px solid var(--border); }
.scenario-transition > span:last-child { border-right: 0; }
.scenario-transition b { display: block; margin-top: 7px; color: var(--text-strong); font: 800 var(--fs-xl)/1 var(--font-mono); }
.scenario-transition em { display: block; margin-top: 5px; color: var(--muted); font-size: var(--fs-2xs); font-style: normal; }
.scenario-transition b.pos { color: var(--pos); }
.scenario-transition b.neg { color: var(--neg); }
.scenario-history { border-bottom: 1px solid var(--border); background: color-mix(in srgb, var(--surface-3) 28%, transparent); }
.scenario-history > summary {
  display: flex; align-items: center; justify-content: space-between; gap: var(--s-3);
  padding: 11px var(--s-4); cursor: pointer; list-style: none;
}
.scenario-history > summary::-webkit-details-marker { display: none; }
.scenario-history > summary span { display: flex; align-items: baseline; gap: 8px; }
.scenario-history > summary small { color: var(--accent); font: 700 var(--fs-2xs)/1 var(--font-mono); letter-spacing: var(--ls-caps); text-transform: uppercase; }
.scenario-history > summary b { color: var(--text-strong); font-size: var(--fs-sm); }
.scenario-history > summary em { margin-left: auto; color: var(--muted); font: 600 var(--fs-2xs)/1 var(--font-mono); font-style: normal; }
.scenario-history > summary::after { content: '›'; color: var(--accent); font: 800 var(--fs-lg)/1 var(--font-mono); transition: transform .15s ease; }
.scenario-history[open] > summary::after { transform: rotate(90deg); }
.scenario-history-body { padding: 0 var(--s-4) var(--s-3); }
.scenario-history-body > p { margin: 0 0 9px; color: var(--muted); font-size: var(--fs-2xs); line-height: 1.45; }
.scenario-history-scroll { max-width: 100%; overflow-x: auto; border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface); }
.scenario-history table { width: 100%; min-width: 790px; border-collapse: collapse; font: 600 var(--fs-2xs)/1.25 var(--font-mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
.scenario-history th { padding: 7px 9px; border-bottom: 1px solid var(--border); color: var(--muted); font: 700 9px/1.2 var(--font-sans); letter-spacing: .05em; text-align: left; text-transform: uppercase; }
.scenario-history td { padding: 7px 9px; border-bottom: 1px dashed color-mix(in srgb, var(--border) 62%, transparent); color: var(--muted-strong); }
.scenario-history tbody tr:last-child td { border-bottom: 0; }
.scenario-history-state { color: var(--text-strong); text-transform: capitalize; }
.scenario-history-state.is-fragile { color: var(--neg); }
.scenario-history-state.is-watch { color: var(--warn); }
.scenario-history-bars { display: grid; gap: 3px; min-width: 220px; }
.scenario-history-bars > span { position: relative; display: block; height: 13px; overflow: hidden; border-radius: 3px; background: var(--surface-3); }
.scenario-history-bars i { position: absolute; inset: 0 auto 0 0; opacity: .55; }
.scenario-history-bars b { position: relative; z-index: 1; display: block; padding: 2px 5px; color: var(--text-strong); font: 700 9px/1 var(--font-mono); }
.scenario-history-bars i.is-risk, .scenario-history-key i.is-risk { background: var(--neg); }
.scenario-history-bars i.is-cont, .scenario-history-key i.is-cont { background: var(--pos); }
.scenario-history-bars i.is-exhaust, .scenario-history-key i.is-exhaust { background: var(--warn); }
.scenario-history-key { display: inline-flex; align-items: center; gap: 4px; }
.scenario-history-key i { width: 7px; height: 7px; border-radius: 2px; }
.scenario-history-primary { max-width: 230px; overflow: hidden; text-overflow: ellipsis; }
.scenario-history-body > p.scenario-history-collecting { margin: 8px 0 0; color: var(--accent); }
.scenario-warnings {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 7px;
  padding: var(--s-3) var(--s-4); border-bottom: 1px solid var(--border);
  background: color-mix(in srgb, var(--surface-3) 42%, transparent);
}
.scenario-warnings > header { grid-column: 1 / -1; display: flex; align-items: center; justify-content: space-between; gap: var(--s-3); }
.scenario-warnings > header b { color: var(--text-strong); font-size: var(--fs-sm); }
.scenario-warnings > header span { color: var(--muted); font: 600 var(--fs-2xs)/1 var(--font-mono); }
.scenario-warnings > span {
  min-width: 0; display: flex; align-items: flex-start; gap: 7px; padding: 8px 9px;
  border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface);
  color: var(--muted-strong); font-size: var(--fs-xs); line-height: 1.35; overflow-wrap: anywhere;
}
.scenario-warnings i { flex: 0 0 7px; width: 7px; height: 7px; margin-top: 4px; border-radius: 50%; background: var(--muted); }
.scenario-warnings > span.is-warning { color: var(--text); border-color: color-mix(in srgb, var(--warn) 40%, var(--border)); }
.scenario-warnings > span.is-warning i { background: var(--warn); box-shadow: 0 0 0 3px color-mix(in srgb, var(--warn) 15%, transparent); }
.scenario-axis-velocity {
  display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); gap: 5px;
  padding: var(--s-3) var(--s-4); border-bottom: 1px solid var(--border);
}
.scenario-axis-velocity > header {
  grid-column: 1 / -1; display: flex; align-items: center; justify-content: space-between; gap: var(--s-3);
  margin-bottom: 2px;
}
.scenario-axis-velocity > header b { color: var(--text-strong); font-size: var(--fs-sm); }
.scenario-axis-velocity > header span { color: var(--muted); font: 600 var(--fs-2xs)/1 var(--font-mono); }
.scenario-axis-velocity > span {
  min-width: 0; padding: 7px; border: 1px solid var(--border); border-radius: var(--r-1); background: var(--surface);
}
.scenario-axis-velocity small { display: block; color: var(--muted); font-size: 9px; line-height: 1.2; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.scenario-axis-velocity b { display: block; margin-top: 5px; color: var(--text-strong); font: 800 var(--fs-xs)/1 var(--font-mono); }
.scenario-axis-velocity em { display: block; margin-top: 4px; color: var(--muted); font: 600 9px/1.2 var(--font-mono); font-style: normal; white-space: nowrap; }
.scenario-axis-velocity > span.is-deteriorating { border-color: color-mix(in srgb, var(--neg) 38%, var(--border)); }
.scenario-axis-velocity > span.is-deteriorating b { color: var(--neg); }
.scenario-axis-velocity > span.is-improving { border-color: color-mix(in srgb, var(--pos) 38%, var(--border)); }
.scenario-axis-velocity > span.is-improving b { color: var(--pos); }
.scenario-section { min-width: 0; padding: var(--s-4); border-bottom: 1px solid var(--border); }
.scenario-section > header,
.scenario-basket > header { display: flex; align-items: flex-end; justify-content: space-between; gap: var(--s-3); margin-bottom: var(--s-3); }
.scenario-section > header h4,
.scenario-basket header h4 { margin: 4px 0 0; color: var(--text-strong); font-size: var(--fs-base); line-height: var(--lh-tight); }
.scenario-section > header > span,
.scenario-basket > header > span { color: var(--muted); font-size: var(--fs-2xs); text-align: right; }
.scenario-catalysts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.scenario-catalyst {
  min-width: 0; padding: 10px 11px; border: 1px solid var(--border);
  border-left: 3px solid var(--border-strong); border-radius: var(--r-2); background: var(--surface);
}
.scenario-catalyst.is-i5 { border-left-color: var(--neg); }
.scenario-catalyst.is-i4 { border-left-color: var(--warn); }
.scenario-catalyst > header { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.scenario-catalyst time { color: var(--text-strong); font: 700 var(--fs-xs)/1 var(--font-mono); }
.scenario-catalyst header span { color: var(--muted); font: 600 var(--fs-2xs)/1 var(--font-mono); }
.scenario-catalyst h4 { margin: 7px 0 4px; color: var(--text-strong); font-size: var(--fs-sm); line-height: 1.3; overflow-wrap: anywhere; }
.scenario-catalyst h4 button,
.scenario-exposures button,
.scenario-sens-row { appearance: none; border: 0; background: transparent; color: inherit; font: inherit; cursor: pointer; }
.scenario-catalyst h4 button { padding: 0; color: var(--accent); font-family: var(--font-mono); font-weight: 800; }
.scenario-catalyst p { margin: 0; color: var(--muted); font-size: var(--fs-xs); line-height: 1.35; }
.scenario-catalyst > small { display: block; margin-top: 7px; color: var(--muted); font-size: var(--fs-2xs); line-height: 1.4; }
.scenario-catalyst > small b { color: var(--muted-strong); }
.scenario-tabs {
  display: flex; gap: 6px; margin-bottom: var(--s-3); padding-bottom: 3px;
  overflow-x: auto; overscroll-behavior-inline: contain; scrollbar-width: thin;
}
.scenario-tab {
  appearance: none; flex: 0 0 min(240px, 72vw); min-width: 0;
  display: flex; align-items: flex-start; justify-content: space-between; gap: 9px;
  padding: 9px 10px; border: 1px solid var(--border); border-radius: var(--r-2);
  background: var(--surface); color: var(--muted-strong); text-align: left; cursor: pointer;
}
.scenario-tab:hover,
.scenario-tab:focus-visible,
.scenario-tab.active { border-color: var(--accent); background: var(--accent-tint-1); outline: none; }
.scenario-tab.active { color: var(--text-strong); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 24%, transparent); }
.scenario-tab span { min-width: 0; font-size: var(--fs-xs); font-weight: 700; line-height: 1.3; }
.scenario-tab b { flex: none; color: var(--accent); font: 700 var(--fs-2xs)/1.2 var(--font-mono); white-space: nowrap; }
.scenario-driver { min-width: 0; padding: var(--s-3); border: 1px solid var(--border); border-radius: var(--r-3); background: color-mix(in srgb, var(--surface) 86%, transparent); }
.scenario-driver > header { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--s-4); }
.scenario-driver > header h4 { margin: 5px 0; color: var(--text-strong); font-size: var(--fs-lg); line-height: 1.25; }
.scenario-driver > header p { margin: 0; color: var(--muted); font-size: var(--fs-xs); }
.scenario-driver > header strong { flex: none; color: var(--accent); font: 800 var(--fs-lg)/1 var(--font-mono); text-align: right; }
.scenario-driver > header strong small { display: block; margin-top: 5px; color: var(--muted); font: 600 var(--fs-2xs)/1 var(--font-mono); }
.scenario-analog { margin: var(--s-3) 0; padding: 9px 10px; border-radius: var(--r-2); background: var(--surface-2); color: var(--muted); font-size: var(--fs-xs); line-height: 1.45; }
.scenario-analog b { color: var(--text-strong); }
.scenario-paths { display: grid; gap: 7px; }
.scenario-path { min-width: 0; overflow: hidden; border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface); }
.scenario-path summary { display: flex; align-items: center; justify-content: space-between; gap: var(--s-3); padding: 10px 11px; cursor: pointer; list-style: none; }
.scenario-path summary::-webkit-details-marker { display: none; }
.scenario-path summary b { display: block; margin-top: 4px; color: var(--text-strong); font-size: var(--fs-sm); }
.scenario-path summary em { flex: none; color: var(--accent); font: 750 var(--fs-xs)/1.1 var(--font-mono); font-style: normal; text-align: right; }
.scenario-path summary em small { display: block; margin-top: 4px; color: var(--muted); font: 600 var(--fs-2xs)/1 var(--font-mono); }
.scenario-path-body { padding: 0 11px 11px; border-top: 1px solid var(--border); }
.scenario-path-body p { margin: 10px 0 7px; color: var(--muted-strong); font-size: var(--fs-xs); line-height: 1.45; }
.scenario-path-body p b { color: var(--text-strong); }
.scenario-path-body ul { margin: 0 0 9px; padding-left: 18px; color: var(--muted); font-size: var(--fs-xs); line-height: 1.45; }
.scenario-shocks { display: flex; flex-wrap: wrap; gap: 5px; }
.scenario-shocks span { padding: 6px 7px; border: 1px solid var(--border); border-radius: var(--r-1); background: var(--surface-2); }
.scenario-shocks b { display: block; margin-top: 3px; color: var(--text); font: 700 var(--fs-2xs)/1 var(--font-mono); }
.scenario-exposures { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; margin-top: var(--s-3); }
.scenario-exposures section { min-width: 0; padding: 9px; border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface-2); }
.scenario-exposures section > header { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 5px; }
.scenario-exposures header b { color: var(--text-strong); font-size: var(--fs-xs); }
.scenario-exposures header span { color: var(--muted); font-size: var(--fs-2xs); }
.scenario-exposures button { width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 6px; border-radius: var(--r-1); text-align: left; }
.scenario-exposures button:hover { background: var(--accent-tint-1); }
.scenario-exposures button span { min-width: 0; display: flex; align-items: baseline; gap: 7px; }
.scenario-exposures button b { color: var(--text-strong); font: 750 var(--fs-xs)/1 var(--font-mono); }
.scenario-exposures button small { min-width: 0; color: var(--muted); font-size: var(--fs-2xs); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.scenario-exposures button em { flex: none; font: 750 var(--fs-xs)/1 var(--font-mono); font-style: normal; }
.scenario-exposures button em.pos { color: var(--pos); }
.scenario-exposures button em.neg { color: var(--neg); }
.scenario-controls { display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 8px; margin-bottom: var(--s-3); }
.scenario-controls label { min-width: 0; }
.scenario-controls select,
.scenario-controls input,
.scenario-basket input {
  width: 100%; min-width: 0; margin-top: 5px; padding: 8px 9px;
  border: 1px solid var(--border); border-radius: var(--r-2);
  background: var(--surface); color: var(--text); font: 600 var(--fs-xs)/1.2 var(--font-sans);
}
.scenario-sens-cols,
.scenario-sens-row { display: grid; grid-template-columns: .75fr 1.05fr 1.35fr 1.2fr; gap: 10px; align-items: center; }
.scenario-sens-cols { padding: 6px 9px; color: var(--muted); font: 700 var(--fs-2xs)/1 var(--font-mono); letter-spacing: var(--ls-caps); text-transform: uppercase; }
.scenario-sens-list { display: grid; gap: 5px; }
.scenario-sens-row { width: 100%; min-width: 0; padding: 9px; border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface); text-align: left; }
.scenario-sens-row:hover,
.scenario-sens-row:focus-visible { border-color: var(--accent); background: var(--accent-tint-1); outline: none; }
.scenario-sens-row > span { min-width: 0; }
.scenario-sens-row b { color: var(--text-strong); font-size: var(--fs-xs); line-height: 1.3; overflow-wrap: anywhere; }
.scenario-sens-row small { display: block; margin-top: 4px; color: var(--muted); font-size: var(--fs-2xs); line-height: 1.35; overflow-wrap: anywhere; }
.scenario-sens-name > b { color: var(--accent); font: 800 var(--fs-sm)/1 var(--font-mono); }
.scenario-sens-impact > b { font-family: var(--font-mono); }
.scenario-sens-impact > b.pos { color: var(--pos); }
.scenario-sens-impact > b.neg { color: var(--neg); }
.scenario-sens-decision > b { display: inline-flex; padding: 3px 6px; border-radius: 999px; background: var(--surface-2); text-transform: capitalize; }
.scenario-sens-decision > b.is-supportive { color: var(--pos); background: color-mix(in srgb, var(--pos) 12%, transparent); }
.scenario-sens-decision > b.is-adverse { color: var(--neg); background: color-mix(in srgb, var(--neg) 12%, transparent); }
.scenario-show-all {
  display: block; margin: 9px auto 0; padding: 7px 11px;
  border: 1px solid var(--border-strong); border-radius: var(--r-2);
  background: var(--surface); color: var(--text); font: 700 var(--fs-xs)/1 var(--font-sans); cursor: pointer;
}
.scenario-basket { margin-top: var(--s-4); padding: var(--s-3); border: 1px solid var(--border); border-radius: var(--r-3); background: var(--surface-2); }
.scenario-basket > div:not(#scenario-basket-result) { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 7px; }
.scenario-basket input { margin: 0; }
.scenario-basket button { padding: 8px 12px; border: 1px solid var(--accent); border-radius: var(--r-2); background: var(--accent); color: #fff; font-weight: 750; cursor: pointer; }
#scenario-basket-result > p { margin: 9px 0 0; color: var(--muted); font-size: var(--fs-xs); }
.scenario-basket-result { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 7px; margin-top: 9px; }
.scenario-basket-result > span { min-width: 0; padding: 8px; border: 1px solid var(--border); border-radius: var(--r-2); background: var(--surface); }
.scenario-basket-result b { display: block; margin-top: 5px; color: var(--text-strong); font-size: var(--fs-xs); line-height: 1.3; overflow-wrap: anywhere; }
.scenario-basket-result b.pos { color: var(--pos); }
.scenario-basket-result b.neg { color: var(--neg); }
.scenario-basket-result p { grid-column: 1 / -1; margin: 0; color: var(--muted); font-size: var(--fs-2xs); line-height: 1.4; }
.scenario-foot { padding: var(--s-3) var(--s-4); color: var(--muted); font-size: var(--fs-xs); line-height: 1.5; }
.scenario-foot b { color: var(--text-strong); }
.scenario-empty { grid-column: 1 / -1; margin: 0; padding: var(--s-4); color: var(--muted); text-align: center; }
.pick-scenario-overlay {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 7px 12px;
  margin: 0 0 var(--s-3); padding: 9px 10px; border: 1px solid var(--border);
  border-left: 3px solid var(--warn); border-radius: var(--r-2); background: var(--surface-2);
}
.pick-scenario-overlay.is-supportive { border-left-color: var(--pos); }
.pick-scenario-overlay.is-adverse { border-left-color: var(--neg); }
.pick-scenario-overlay span { min-width: 0; }
.pick-scenario-overlay b { color: var(--text-strong); font-size: var(--fs-xs); text-transform: capitalize; }
.pick-scenario-overlay small { display: block; margin-top: 4px; color: var(--muted); font: 600 var(--fs-2xs)/1.3 var(--font-mono); }
.pick-scenario-overlay em { color: var(--text); font: 700 var(--fs-2xs)/1.3 var(--font-mono); font-style: normal; text-align: right; }
.pick-scenario-overlay p { grid-column: 1 / -1; margin: 0; color: var(--muted); font-size: var(--fs-xs); line-height: 1.4; }
.ptc-scenario {
  display: block; padding: 5px 7px; border: 1px solid var(--border); border-radius: var(--r-1);
  background: var(--surface-2); color: var(--warn); font: 700 var(--fs-2xs)/1.2 var(--font-sans); text-transform: capitalize;
}
.ptc-scenario.is-supportive { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 35%, var(--border)); }
.ptc-scenario.is-adverse { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 35%, var(--border)); }
@media (max-width: 760px) {
  .scenario-head { flex-direction: column; padding: var(--s-3); }
  .scenario-head > em { white-space: normal; }
  .scenario-transition { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .scenario-transition > span { padding: var(--s-3); }
  .scenario-transition > span:nth-child(2) { border-right: 0; }
  .scenario-transition > span:nth-child(-n+2) { border-bottom: 1px solid var(--border); }
  .scenario-history > summary { padding: 10px var(--s-3); }
  .scenario-history-body { padding: 0 var(--s-3) var(--s-3); }
  .scenario-warnings { grid-template-columns: minmax(0, 1fr); padding: var(--s-3); }
  .scenario-axis-velocity { grid-template-columns: repeat(4, minmax(0, 1fr)); padding: var(--s-3); }
  .scenario-section { padding: var(--s-3); }
  .scenario-section > header { align-items: flex-start; }
  .scenario-catalysts { grid-template-columns: minmax(0, 1fr); }
  .scenario-driver > header { flex-direction: column; }
  .scenario-driver > header strong { text-align: left; }
  .scenario-exposures { grid-template-columns: minmax(0, 1fr); }
  .scenario-controls { grid-template-columns: minmax(0, 1fr); }
  .scenario-sens-cols { display: none; }
  .scenario-sens-row { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 8px; }
  .scenario-sens-factors,
  .scenario-sens-decision { padding-top: 7px; border-top: 1px solid var(--border); }
  .scenario-basket-result { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .pick-scenario-overlay { grid-template-columns: minmax(0, 1fr); }
  .pick-scenario-overlay em { text-align: left; }
}
@media (max-width: 430px) {
  .scenario-history > summary span { align-items: flex-start; flex-direction: column; gap: 3px; }
  .scenario-section > header,
  .scenario-basket > header { align-items: flex-start; flex-direction: column; }
  .scenario-axis-velocity { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .scenario-section > header > span,
  .scenario-basket > header > span { text-align: left; }
  .scenario-path summary { align-items: flex-start; }
  .scenario-path summary em { max-width: 90px; white-space: normal; }
  .scenario-basket > div:not(#scenario-basket-result) { grid-template-columns: minmax(0, 1fr); }
}

.market-movers { margin: 0 0 var(--s-4); }
.market-movers[hidden] { display: none; }
.market-movers-card {
  overflow: hidden;
  border: 1px solid var(--border);
  border-left: 3px solid var(--border-strong);
  border-radius: var(--r-4);
  background: var(--surface);
  box-shadow: var(--elev-1);
}
.market-movers-risk-on { --market-mover-tone: var(--pos); }
.market-movers-risk-off { --market-mover-tone: var(--neg); }
.market-movers-selective,
.market-movers-dip-buying { --market-mover-tone: var(--warn); }
.market-movers-pending,
.market-movers-mixed,
.market-movers-stale { --market-mover-tone: var(--accent); }
.market-movers-card { border-left-color: var(--market-mover-tone, var(--border-strong)); }
.market-movers-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--s-4);
  padding: var(--s-4);
  border-bottom: 1px solid var(--border);
  background: linear-gradient(135deg, color-mix(in srgb, var(--market-mover-tone, var(--accent)) 6%, var(--surface)), var(--surface));
}
.market-movers-kicker,
.market-movers-axes small,
.market-mover-basket header small,
.market-mover-row small {
  display: block;
  color: var(--muted);
  font: 700 var(--fs-2xs)/1 var(--font-mono);
  letter-spacing: var(--ls-caps);
  text-transform: uppercase;
}
.market-movers-head h3 {
  margin: 5px 0 6px;
  color: var(--market-mover-tone, var(--text-strong));
  font-size: var(--fs-xl);
  line-height: var(--lh-tight);
}
.market-movers-head p {
  max-width: 80ch;
  margin: 0;
  color: var(--text);
  font-size: var(--fs-sm);
  line-height: var(--lh-snug);
}
.market-movers-head > em {
  flex: none;
  padding: 5px 8px;
  border: 1px solid color-mix(in srgb, var(--market-mover-tone, var(--border-strong)) 45%, var(--border));
  border-radius: var(--r-pill);
  color: var(--market-mover-tone, var(--muted));
  font: 700 var(--fs-2xs)/1 var(--font-mono);
  font-style: normal;
  text-transform: uppercase;
  white-space: nowrap;
}
.market-movers-axes {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  border-bottom: 1px solid var(--border);
}
.market-movers-axes > span { padding: var(--s-3) var(--s-4); }
.market-movers-axes > span:first-child { border-right: 1px solid var(--border); }
.market-movers-axes b { display: block; margin-top: 5px; color: var(--text-strong); font-size: var(--fs-md); }
.market-movers-axes em { display: block; margin-top: 3px; color: var(--muted); font: 500 var(--fs-xs)/1.25 var(--font-sans); font-style: normal; }
.market-movers-action { margin: 0; padding: var(--s-3) var(--s-4); border-bottom: 1px solid var(--border); color: var(--text); font-size: var(--fs-sm); line-height: var(--lh-snug); }
.market-movers-action b { color: var(--text-strong); }
.market-movers-baskets {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--s-3);
  padding: var(--s-3);
}
.market-mover-basket { min-width: 0; overflow: hidden; border: 1px solid var(--border); border-radius: var(--r-3); background: var(--surface-2); }
.market-mover-basket header { display: flex; align-items: center; justify-content: space-between; gap: var(--s-2); padding: var(--s-3); border-bottom: 1px solid var(--border); }
.market-mover-basket header b { display: block; margin-top: 4px; color: var(--text-strong); font-size: var(--fs-sm); }
.market-mover-basket header > em { color: var(--muted); font: 600 var(--fs-2xs)/1 var(--font-mono); font-style: normal; }
.market-mover-columns,
.market-mover-row {
  display: grid;
  grid-template-columns: minmax(72px, 1.25fr) repeat(3, minmax(54px, .8fr)) minmax(70px, 1fr);
  gap: 6px;
  align-items: center;
}
.market-mover-columns { padding: 7px var(--s-3); color: var(--muted); font: 700 8px/1 var(--font-mono); letter-spacing: .05em; text-transform: uppercase; }
.market-mover-columns span:not(:first-child) { text-align: right; }
.market-mover-row {
  width: 100%;
  min-height: 47px;
  padding: 8px var(--s-3);
  border: 0;
  border-top: 1px solid var(--border);
  background: transparent;
  color: var(--text);
  text-align: left;
  cursor: pointer;
}
.market-mover-row:hover,
.market-mover-row:focus-visible { background: var(--accent-tint-1); outline: none; }
.market-mover-row > span:not(:first-child) { text-align: right; }
.market-mover-row > span > b { display: block; margin-top: 3px; color: var(--text-strong); font: 700 var(--fs-xs)/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.market-mover-symbol b { color: var(--text-strong); font: 800 var(--fs-sm)/1 var(--font-mono); }
.market-mover-symbol small { margin-top: 5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-transform: none; letter-spacing: 0; }
.market-mover-row b.pos { color: var(--pos); }
.market-mover-row b.neg { color: var(--neg); }
.market-mover-row b.zero { color: var(--muted); }
.market-mover-status { justify-self: end; padding: 4px 6px; border: 1px solid var(--border); border-radius: var(--r-pill); color: var(--muted); font: 700 8px/1 var(--font-mono); font-style: normal; text-transform: uppercase; white-space: nowrap; }
.market-mover-status.is-soared,
.market-mover-status.is-held,
.market-mover-status.is-recovered { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 40%, var(--border)); background: color-mix(in srgb, var(--pos) 7%, transparent); }
.market-mover-status.is-faded,
.market-mover-status.is-reversed,
.market-mover-status.is-worsened { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 40%, var(--border)); background: color-mix(in srgb, var(--neg) 7%, transparent); }
.market-mover-status.is-still-down { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 40%, var(--border)); }
.market-movers-foot { margin: 0; padding: 0 var(--s-4) var(--s-3); color: var(--muted); font-size: var(--fs-2xs); line-height: var(--lh-snug); }
@media (max-width: 900px) {
  .market-movers-baskets { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 600px) {
  .market-movers-head { flex-direction: column; padding: var(--s-3); }
  .market-movers-head > em { align-self: flex-start; }
  .market-movers-head h3 { font-size: var(--fs-lg); }
  .market-movers-axes { grid-template-columns: minmax(0, 1fr); }
  .market-movers-axes > span:first-child { border-right: 0; border-bottom: 1px solid var(--border); }
  .market-mover-columns { display: none; }
  .market-mover-row { grid-template-columns: minmax(78px, 1.1fr) repeat(2, minmax(52px, .7fr)) minmax(76px, .9fr); }
  .market-mover-row > span:nth-child(4) { display: none; }
  .market-movers-baskets { padding: 8px; }
}

.picks-tape { margin: 0 0 14px; }
.picks-tape[hidden] { display: none; }

/* Market Analysis — risk-on / risk-off history calendar (month grid of the daily
   cross-asset macro regime that set the engine's posture). */
.picks-regime-hist { margin: 0 0 14px; }
.picks-regime-hist[hidden] { display: none; }
.regime-wrap {
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface);
  padding: 12px 14px;
}
.regime-summary-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 14px;
  cursor: pointer;
  list-style: none;
}
.regime-summary-bar::-webkit-details-marker { display: none; }
.regime-summary-bar::after {
  content: '▸';
  margin-left: auto;
  color: var(--muted);
  transition: transform .15s;
}
.regime-wrap[open] .regime-summary-bar::after { transform: rotate(90deg); }
.regime-title,
.picks-tape-kicker,
.rob-kicker {
  font: 700 11px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--muted);
}
.regime-hint { margin: 8px 0 12px; color: var(--muted); font-size: 13px; line-height: 1.45; }
.regime-legend {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 6px 12px;
  font: 500 12px/1 var(--font-mono);
  color: var(--muted);
}
.regime-legend-item { display: inline-flex; align-items: center; gap: 5px; }
.regime-swatch {
  display: inline-block;
  width: 11px; height: 11px;
  border-radius: 3px;
  border: 1px solid var(--border);
}
.regime-monthbar { display: flex; align-items: center; gap: var(--s-2); margin: 0 0 10px; }
.regime-month-label { min-width: 9.5em; text-align: center; font: 700 17px/1.1 var(--font-serif); color: var(--text-strong); letter-spacing: -.01em; }
.regime-month-count { margin-left: auto; font: 500 12px/1 var(--font-mono); color: var(--muted); letter-spacing: .04em; text-transform: uppercase; white-space: nowrap; }
.regime-cal { width: 100%; }
.regime-month { width: 100%; }
.regime-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 3px; }
.regime-dow { text-align: center; font: 600 10px/1 var(--font-mono); color: var(--muted); padding-bottom: 2px; }
.regime-cell {
  position: relative;
  min-height: 76px;
  border: 1px solid transparent;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  background: color-mix(in srgb, var(--text) 4%, transparent);
}
.regime-cell-day { font: 500 11px/1 var(--font-mono); color: var(--muted); }
button.regime-cell { cursor: pointer; transition: transform .1s, box-shadow .1s; }
button.regime-cell:hover,
button.regime-cell:focus-visible { transform: scale(1.1); box-shadow: var(--shadow-md); outline: none; z-index: 2; }
.regime-cell.is-blank { background: transparent; border-color: transparent; }
.regime-cell.is-out { background: transparent; border-color: transparent; }
.regime-cell.is-out .regime-cell-day { color: color-mix(in srgb, var(--muted) 55%, transparent); }
.regime-cell.is-empty { background: color-mix(in srgb, var(--text) 3%, transparent); }
.regime-cell.is-on { background: color-mix(in srgb, var(--pos) 32%, var(--surface)); border-color: color-mix(in srgb, var(--pos) 45%, var(--border)); }
.regime-cell.is-on .regime-cell-day { color: var(--text-strong); }
.regime-cell.is-neutral { background: color-mix(in srgb, var(--muted) 24%, var(--surface)); border-color: var(--border); }
.regime-cell.is-fragile { background: color-mix(in srgb, var(--warn) 28%, var(--surface)); border-color: color-mix(in srgb, var(--warn) 42%, var(--border)); }
.regime-cell.is-off { background: color-mix(in srgb, var(--neg) 32%, var(--surface)); border-color: color-mix(in srgb, var(--neg) 45%, var(--border)); }
.regime-cell.is-off .regime-cell-day { color: var(--text-strong); }
.regime-cell.is-severe { background: color-mix(in srgb, var(--neg) 64%, var(--surface)); border-color: var(--neg); }
.regime-cell.is-severe .regime-cell-day { color: #fff; }
.regime-swatch.is-on { background: color-mix(in srgb, var(--pos) 45%, var(--surface)); }
.regime-swatch.is-neutral { background: color-mix(in srgb, var(--muted) 32%, var(--surface)); }
.regime-swatch.is-fragile { background: color-mix(in srgb, var(--warn) 42%, var(--surface)); }
.regime-swatch.is-off { background: color-mix(in srgb, var(--neg) 45%, var(--surface)); }
.regime-swatch.is-severe { background: color-mix(in srgb, var(--neg) 70%, var(--surface)); }
.regime-detail {
  margin-top: 12px;
  padding: 10px 12px;
  border: 1px dashed var(--border);
  border-radius: var(--r-2);
  background: color-mix(in srgb, var(--text) 2%, var(--surface));
  min-height: 44px;
}
.regime-detail-empty { color: var(--muted); font-size: 13px; }
.regime-detail-head { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.regime-badge {
  padding: 2px 8px;
  border-radius: var(--r-pill);
  font: 600 12px/1.4 var(--font-mono);
  border: 1px solid var(--border);
}
.regime-badge.is-on { background: color-mix(in srgb, var(--pos) 16%, var(--surface)); color: var(--pos); border-color: color-mix(in srgb, var(--pos) 35%, var(--border)); }
.regime-badge.is-neutral { background: var(--surface); color: var(--text); }
.regime-badge.is-fragile { background: color-mix(in srgb, var(--warn) 14%, var(--surface)); color: var(--warn); border-color: color-mix(in srgb, var(--warn) 35%, var(--border)); }
.regime-badge.is-off,
.regime-badge.is-severe { background: color-mix(in srgb, var(--neg) 14%, var(--surface)); color: var(--neg); border-color: color-mix(in srgb, var(--neg) 35%, var(--border)); }
.regime-detail-date { font: 600 13px/1 var(--font-mono); color: var(--text-strong); }
.regime-detail-stress { font: 500 12px/1 var(--font-mono); color: var(--muted); }
.regime-detail-summary { margin-top: 6px; font-size: 13px; line-height: 1.45; color: var(--text); }
.regime-detail-drivers { margin-top: 8px; display: flex; flex-wrap: wrap; gap: 6px; }
.regime-driver {
  padding: 2px 7px;
  border-radius: var(--r-pill);
  background: color-mix(in srgb, var(--text) 6%, transparent);
  font: 500 11px/1.4 var(--font-mono);
  color: var(--text);
}
.regime-detail-lean { margin-top: 8px; font-size: 13px; color: var(--text); }
@media (max-width: 560px){
  .regime-monthbar { flex-wrap: wrap; }
  .regime-month-label { min-width: 0; flex: 1; font-size: 16px; }
  .regime-month-count { flex-basis: 100%; margin-left: 0; text-align: right; }
  .regime-cell { min-height: 46px; }
}
.picks-tape-card {
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface);
  box-shadow: var(--elev-1);
  overflow: hidden;
}
.picks-tape-head {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 14px;
  background: none;
  border: 0;
  cursor: pointer;
  text-align: left;
  color: var(--text-strong);
  font: inherit;
}
.picks-tape-head:hover { background: color-mix(in srgb, var(--text-strong) 4%, transparent); }
.picks-tape-state,
.rob-state {
  font: 800 13px/1 var(--font-mono);
  letter-spacing: var(--ls-display);
  padding: 4px 8px;
  border-radius: var(--r-1);
  border: 1px solid var(--border);
}
.picks-tape-state.picks-summary-put { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 30%, var(--border)); background: color-mix(in srgb, var(--neg) 6%, var(--surface)); }
.picks-tape-state.picks-summary-call { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 30%, var(--border)); background: color-mix(in srgb, var(--pos) 6%, var(--surface)); }
.picks-tape-state.picks-summary-warn { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 30%, var(--border)); background: color-mix(in srgb, var(--warn) 6%, var(--surface)); }
.picks-tape-live {
  margin-left: auto;
  font: 600 11px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .06em;
  white-space: nowrap;
}
.picks-tape-live.is-live { color: var(--pos); }
.picks-tape-live.is-baked { color: var(--muted); }
.picks-tape-toggle { color: var(--muted); font-size: 13px; }
.picks-tape-body { display: none; padding: 0 14px 14px; }
.picks-tape-card.is-open .picks-tape-body { display: block; }
.picks-tape-summary { margin: 4px 0 10px; font: 400 13px/1.6 var(--font-sans); color: var(--text); }
.picks-tape-summary b { color: var(--text-strong); font-weight: 700; }
/* Condition-aware "what this means right now" callout. */
.picks-tape-callout {
  margin: 0 0 12px;
  padding: 11px 13px;
  border: 1px solid var(--border);
  border-left-width: 3px;
  border-radius: var(--r-1);
  background: color-mix(in srgb, var(--text-strong) 3%, var(--surface));
}
.picks-tape-callout.tape-callout-on { border-left-color: var(--pos); background: color-mix(in srgb, var(--pos) 5%, var(--surface)); }
.picks-tape-callout.tape-callout-off { border-left-color: var(--neg); background: color-mix(in srgb, var(--neg) 5%, var(--surface)); }
.picks-tape-callout.tape-callout-warn { border-left-color: var(--warn); background: color-mix(in srgb, var(--warn) 5%, var(--surface)); }
.picks-tape-callout.tape-callout-neutral { border-left-color: var(--border); }
.picks-tape-callout-head { margin: 0 0 5px; font: 700 13px/1.4 var(--font-sans); color: var(--text-strong); }
.tape-callout-on .picks-tape-callout-head { color: var(--pos); }
.tape-callout-off .picks-tape-callout-head { color: var(--neg); }
.tape-callout-warn .picks-tape-callout-head { color: var(--warn); }
.picks-tape-callout-body { margin: 0; font: 400 13px/1.65 var(--font-sans); color: var(--text); }
.picks-tape-callout-body b { color: var(--text-strong); font-weight: 700; }
.picks-tape-callout-meta { margin: 7px 0 0; font: 400 12px/1.55 var(--font-sans); color: var(--muted); }
.picks-tape-callout-meta b {
  display: inline-block;
  margin-right: 6px;
  font: 700 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .07em;
  color: var(--text-strong);
}
.picks-tape-metrics {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}
.picks-tape-metrics span {
  font: 600 11px/1.3 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .05em;
  color: var(--muted);
}
.picks-tape-metrics b {
  font: 800 14px/1 var(--font-mono);
  color: var(--text-strong);
  margin-left: 4px;
  font-variant-numeric: tabular-nums;
}
.picks-tape-axes {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(184px, 1fr));
  gap: 8px;
}
.tape-axis {
  border: 1px solid var(--border);
  border-left-width: 3px;
  border-radius: var(--r-1);
  padding: 8px 10px;
  background: color-mix(in srgb, var(--text-strong) 2%, var(--surface));
}
.tape-axis.tape-off { border-left-color: var(--neg); }
.tape-axis.tape-on { border-left-color: var(--pos); }
.tape-axis.tape-flat { border-left-color: var(--border); }
.tape-axis-head { display: flex; align-items: center; gap: 6px; margin-bottom: 3px; }
.tape-axis-name { font: 700 12px/1 var(--font-mono); color: var(--text-strong); text-transform: uppercase; letter-spacing: .04em; }
.tape-axis-score { margin-left: auto; font: 800 13px/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.tape-off .tape-axis-score { color: var(--neg); }
.tape-on .tape-axis-score { color: var(--pos); }
.tape-flat .tape-axis-score { color: var(--muted); }
.tape-axis-badge {
  font: 700 9px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .06em;
  padding: 2px 4px;
  border-radius: 3px;
}
.tape-axis-badge.is-live { color: var(--pos); background: color-mix(in srgb, var(--pos) 14%, transparent); }
.tape-axis-badge.is-baked { color: var(--muted); background: color-mix(in srgb, var(--muted) 14%, transparent); }
.tape-axis-label { font: 500 12px/1.4 var(--font-sans); color: var(--text); }
.tape-axis-desc { font: 400 10px/1.3 var(--font-mono); color: var(--muted); text-transform: uppercase; letter-spacing: .04em; margin-top: 2px; }
/* Per-axis mini-meter: the −2..+2 score as a marker on a risk rail inside each tile. */
.tape-axis-rail { position: relative; height: 8px; margin: 5px 0 6px; }
.tape-axis-rail::before {
  content: ""; position: absolute; inset: 2px 0; border-radius: var(--r-pill);
  background: linear-gradient(90deg,
    color-mix(in srgb, var(--neg) 30%, var(--surface)) 0%,
    color-mix(in srgb, var(--muted) 12%, var(--surface)) 50%,
    color-mix(in srgb, var(--pos) 30%, var(--surface)) 100%);
  border: 1px solid var(--border);
}
.tape-axis-rail-mid { position: absolute; top: 0; bottom: 0; left: 50%; width: 1px; transform: translateX(-.5px); background: color-mix(in srgb, var(--text-strong) 20%, transparent); }
.tape-axis-rail-mark {
  position: absolute; top: 50%; width: 9px; height: 9px; border-radius: 50%;
  transform: translate(-50%, -50%); background: var(--surface); border: 2px solid var(--muted); box-shadow: var(--elev-1);
}
.tape-axis-rail-mark.tape-on { border-color: var(--pos); background: color-mix(in srgb, var(--pos) 22%, var(--surface)); }
.tape-axis-rail-mark.tape-off { border-color: var(--neg); background: color-mix(in srgb, var(--neg) 22%, var(--surface)); }

/* Headline risk meter — the whole tape on one rail (the visual gauge). */
.tape-meter {
  margin: 4px 0 12px;
  padding: 11px 13px 9px;
  border: 1px solid var(--border);
  border-left-width: 3px;
  border-radius: var(--r-1);
  background: color-mix(in srgb, var(--text-strong) 2%, var(--surface));
}
.tape-meter.tape-meter-off { border-left-color: var(--neg); }
.tape-meter.tape-meter-on { border-left-color: var(--pos); }
.tape-meter.tape-meter-warn { border-left-color: var(--warn); }
.tape-meter.tape-meter-flat { border-left-color: var(--border); }
.tape-meter-scale { display: flex; justify-content: space-between; margin-bottom: 5px; }
.tape-meter-scale span { font: 700 10px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .08em; color: var(--muted); }
.tape-meter-scale span:first-child { color: var(--neg); }
.tape-meter-scale span:last-child { color: var(--pos); }
.tape-meter-rail { position: relative; height: 16px; }
.tape-meter-rail::before {
  content: ""; position: absolute; inset: 5px 0; border-radius: var(--r-pill);
  background: linear-gradient(90deg,
    color-mix(in srgb, var(--neg) 38%, var(--surface)) 0%,
    color-mix(in srgb, var(--neg) 16%, var(--surface)) 30%,
    color-mix(in srgb, var(--muted) 12%, var(--surface)) 50%,
    color-mix(in srgb, var(--pos) 16%, var(--surface)) 70%,
    color-mix(in srgb, var(--pos) 38%, var(--surface)) 100%);
  border: 1px solid var(--border);
}
.tape-meter-mid { position: absolute; top: 1px; bottom: 1px; left: 50%; width: 1px; transform: translateX(-.5px); background: color-mix(in srgb, var(--text-strong) 24%, transparent); }
.tape-meter-marker {
  position: absolute; top: 50%; width: 16px; height: 16px; border-radius: 50%;
  transform: translate(-50%, -50%); background: var(--surface); box-shadow: var(--elev-1); border: 3px solid var(--muted);
}
.tape-meter-off .tape-meter-marker { border-color: var(--neg); background: color-mix(in srgb, var(--neg) 24%, var(--surface)); }
.tape-meter-on .tape-meter-marker { border-color: var(--pos); background: color-mix(in srgb, var(--pos) 24%, var(--surface)); }
.tape-meter-warn .tape-meter-marker { border-color: var(--warn); background: color-mix(in srgb, var(--warn) 24%, var(--surface)); }
.tape-meter-caption { margin-top: 7px; font: 500 12px/1.4 var(--font-sans); color: var(--muted); }
.tape-meter-caption b { color: var(--text-strong); font-weight: 700; }
.picks-tape-note { margin: 10px 0 0; font: 500 12px/1.5 var(--font-sans); color: var(--text); }
.picks-tape-note.is-warn { color: var(--warn); }
.picks-tape-note b { font-weight: 700; }
.picks-tape-foot { margin: 10px 0 0; font: 400 12px/1.6 var(--font-sans); color: var(--muted); }

/* --- Risk-on / risk-off barometer (per-asset 0–100 rail) ----------------- */
.picks-barometer { margin: 0 0 14px; }
.picks-barometer[hidden] { display: none; }
.rob-card {
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface);
  box-shadow: var(--elev-1);
  overflow: hidden;
}
.rob-head {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 14px;
  background: none;
  border: 0;
  cursor: pointer;
  text-align: left;
  color: var(--text-strong);
  font: inherit;
}
.rob-head:hover { background: color-mix(in srgb, var(--text-strong) 4%, transparent); }
.rob-state.rob-off { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 30%, var(--border)); background: color-mix(in srgb, var(--neg) 6%, var(--surface)); }
.rob-state.rob-on  { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 30%, var(--border)); background: color-mix(in srgb, var(--pos) 6%, var(--surface)); }
.rob-state.rob-flat { color: var(--muted); }
.rob-asof {
  margin-left: auto;
  font: 600 11px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--muted);
  white-space: nowrap;
}
.rob-asof.is-live { color: var(--pos); }
.rob-asof-dot {
  color: var(--pos);
  font-size: 10px;
  vertical-align: middle;
  animation: rob-live-pulse 2s ease-in-out infinite;
}
.rob-toggle { color: var(--muted); font-size: 13px; }
.rob-body { display: none; padding: 4px 14px 14px; }
.rob-card.is-open .rob-body { display: block; }
.rob-loading { padding: 14px; font: 500 13px/1.4 var(--font-sans); color: var(--muted); }
/* Zone legend, aligned over the rail column. */
.rob-scale {
  display: grid;
  grid-template-columns: var(--rob-name-col, 132px) 1fr;
  align-items: center;
  margin: 2px 0 8px;
  padding-left: 0;
}
.rob-scale::before { content: ""; }
.rob-scale-off, .rob-scale-mid, .rob-scale-on {
  grid-column: 2;
  grid-row: 1;
  font: 700 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
}
.rob-scale-off { justify-self: start;  color: var(--neg); }
.rob-scale-mid { justify-self: center; color: var(--muted); }
.rob-scale-on  { justify-self: end;    color: var(--pos); }
.rob-rows { display: flex; flex-direction: column; gap: 6px; }
.rob-row {
  display: grid;
  grid-template-columns: var(--rob-name-col, 132px) 1fr auto;
  align-items: center;
  gap: 10px;
}
.rob-name {
  font: 600 12px/1.2 var(--font-sans);
  color: var(--text-strong);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.rob-live-dot {
  color: var(--pos);
  font-size: 9px;
  vertical-align: middle;
  margin-right: 4px;
  animation: rob-live-pulse 2s ease-in-out infinite;
}
@keyframes rob-live-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }
@media (prefers-reduced-motion: reduce) { .rob-live-dot, .rob-asof-dot { animation: none; } }
.rob-rail {
  position: relative;
  height: 14px;
  display: block;
}
.rob-rail-track {
  position: absolute;
  inset: 5px 0;
  border-radius: var(--r-pill);
  /* red (risk-off) → neutral → green (risk-on), matching the marker bands. */
  background: linear-gradient(90deg,
    color-mix(in srgb, var(--neg) 32%, var(--surface)) 0%,
    color-mix(in srgb, var(--neg) 14%, var(--surface)) 30%,
    color-mix(in srgb, var(--muted) 12%, var(--surface)) 50%,
    color-mix(in srgb, var(--pos) 14%, var(--surface)) 70%,
    color-mix(in srgb, var(--pos) 32%, var(--surface)) 100%);
  border: 1px solid var(--border);
}
.rob-rail-mid {
  position: absolute;
  top: 1px;
  bottom: 1px;
  left: 50%;
  width: 1px;
  transform: translateX(-.5px);
  background: color-mix(in srgb, var(--text-strong) 22%, transparent);
}
.rob-marker {
  position: absolute;
  top: 50%;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: var(--surface);
  border: 2px solid var(--muted);
  box-shadow: var(--elev-1);
}
.rob-marker.rob-on  { border-color: var(--pos); background: color-mix(in srgb, var(--pos) 22%, var(--surface)); }
.rob-marker.rob-off { border-color: var(--neg); background: color-mix(in srgb, var(--neg) 22%, var(--surface)); }
.rob-marker.rob-flat { border-color: var(--muted); }
.rob-move {
  font: 700 12px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  text-align: right;
  white-space: nowrap;
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
}
.rob-move.ovn-up { color: var(--pos); }
.rob-move.ovn-dn { color: var(--neg); }
.rob-move.ovn-flat { color: var(--muted); }
.rob-lvl { font: 500 10px/1 var(--font-mono); color: var(--muted); }
.rob-foot { margin: 11px 0 0; font: 400 12px/1.6 var(--font-sans); color: var(--muted); }
@media (max-width: 860px) {
  .rob-scale, .rob-row { --rob-name-col: 92px; }
  .rob-lvl { display: none; }
}

/* --- Market tape: expandable axis tiles, sparklines, cross-highlight ------- */
/* The axis tiles are now buttons (click to drill down) — keep the card look. */
.tape-axis {
  display: block;
  width: 100%;
  text-align: left;
  font: inherit;
  color: inherit;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  transition: border-color .12s ease, background .12s ease, box-shadow .12s ease;
}
.tape-axis:hover { background: color-mix(in srgb, var(--text-strong) 5%, var(--surface)); }
.tape-axis:focus-visible { outline: 2px solid color-mix(in srgb, var(--accent) 55%, transparent); outline-offset: 2px; }
.tape-axis.is-open { box-shadow: var(--elev-1); border-color: color-mix(in srgb, var(--text-strong) 16%, var(--border)); }
.tape-axis-foot { display: flex; align-items: center; gap: 8px; justify-content: space-between; margin-top: 2px; }
.tape-axis-foot .tape-axis-desc { margin-top: 0; }
/* Composite-weight chip (×1.25 / ×0.5) — how much this axis's vote counts in the tape. */
.tape-axis-w { flex: 0 0 auto; font: 700 9px/1 var(--font-mono); color: var(--muted); border: 1px solid var(--border); border-radius: var(--r-pill); padding: 2px 5px; opacity: .8; }
.tape-axis-spark { flex: 0 0 auto; display: inline-flex; align-items: center; }
.tape-axis-more {
  display: inline-block; margin-top: 6px;
  font: 700 9px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .06em;
  color: var(--muted);
}
.tape-axis:hover .tape-axis-more, .tape-axis.is-open .tape-axis-more { color: var(--text-strong); }

/* Shared inline sparkline — tone colors the stroke, dashed line marks neutral. */
.tape-spark { display: inline-block; vertical-align: middle; color: var(--muted); }
.tape-spark-on { color: var(--pos); }
.tape-spark-off { color: var(--neg); }
.tape-spark-warn { color: var(--warn); }
.tape-spark-flat { color: var(--muted); }
.tape-spark-base { stroke: color-mix(in srgb, var(--text-strong) 22%, transparent); stroke-width: 1; stroke-dasharray: 2 2; }

/* Axis drill-down drawer. */
.tape-axis-detail { margin-top: 8px; padding-top: 8px; border-top: 1px dashed var(--border); display: grid; gap: 6px; }
.tape-axis-detail-about { margin: 0; font: 400 11.5px/1.5 var(--font-sans); color: var(--text); }
.tape-axis-detail-reading { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.tape-axis-detail-badge {
  font: 800 10px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .05em;
  padding: 3px 6px; border-radius: 4px; border: 1px solid var(--border);
}
.tape-axis-detail-badge.tape-off { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 30%, var(--border)); background: color-mix(in srgb, var(--neg) 7%, var(--surface)); }
.tape-axis-detail-badge.tape-on { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 30%, var(--border)); background: color-mix(in srgb, var(--pos) 7%, var(--surface)); }
.tape-axis-detail-badge.tape-flat { color: var(--muted); }
.tape-axis-detail-label { font: 500 11.5px/1.4 var(--font-sans); color: var(--text); }
.tape-axis-detail-chips { display: flex; flex-wrap: wrap; gap: 5px; }
.tape-chip {
  display: inline-flex; align-items: baseline; gap: 4px;
  padding: 2px 6px; border: 1px solid var(--border); border-radius: 4px;
  background: color-mix(in srgb, var(--text-strong) 3%, var(--surface));
}
.tape-chip-k { font: 700 9px/1.2 var(--font-mono); text-transform: uppercase; letter-spacing: .04em; color: var(--muted); }
.tape-chip-v { font: 700 11px/1.2 var(--font-mono); color: var(--text-strong); font-variant-numeric: tabular-nums; }
.tape-axis-detail-feeds, .tape-axis-detail-flip, .tape-axis-detail-live { font: 400 11px/1.5 var(--font-sans); color: var(--muted); }
.tape-axis-detail-feeds b, .tape-axis-detail-flip b { color: var(--text-strong); font-weight: 700; }
/* Axis-detail popout — a centered modal overlay (mirrors the calendar report
   modal). The drill-down used to render inline inside the tile, which
   stretched every card in that grid row. */
body.tape-axm-open { overflow: hidden; }
.tape-axm-overlay {
  position: fixed; inset: 0; z-index: 1000;
  display: flex; align-items: center; justify-content: center;
  padding: var(--s-3);
  background: rgba(0, 0, 0, 0.6); -webkit-backdrop-filter: blur(2px); backdrop-filter: blur(2px);
}
.tape-axm-overlay[hidden] { display: none; }
.tape-axm-modal {
  position: relative;
  width: min(560px, 96vw); max-height: 88vh; overflow-y: auto;
  background: var(--surface-2); border: 1px solid var(--border-strong); border-left-width: 3px;
  border-radius: var(--r-3); padding: var(--s-4);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}
.tape-axm-modal.tape-off { border-left-color: var(--neg); }
.tape-axm-modal.tape-on { border-left-color: var(--pos); }
.tape-axm-modal.tape-flat { border-left-color: var(--border-strong); }
.tape-axm-close {
  position: absolute; top: 10px; right: 10px;
  width: 30px; height: 30px; border-radius: var(--r-2);
  background: transparent; border: 1px solid var(--border-strong);
  color: var(--text-3); font-size: 1.1rem; line-height: 1; cursor: pointer;
  transition: background 120ms, color 120ms, border-color 120ms;
}
.tape-axm-close:hover { background: var(--neg-tint); border-color: var(--neg); color: var(--neg); }
.tape-axm-head { display: flex; align-items: center; gap: 8px; padding-right: 40px; }
.tape-axm-name { font: 700 14px/1 var(--font-mono); color: var(--text-strong); text-transform: uppercase; letter-spacing: .04em; }
.tape-axm-score { margin-left: auto; font: 800 16px/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.tape-axm-modal.tape-off .tape-axm-score { color: var(--neg); }
.tape-axm-modal.tape-on .tape-axm-score { color: var(--pos); }
.tape-axm-modal.tape-flat .tape-axm-score { color: var(--muted); }

/* Headline meter net-stress trend sparkline. */
.tape-meter-trend { display: flex; align-items: center; gap: 8px; margin-top: 7px; }
.tape-meter-trend-lbl { font: 700 9px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
.tape-meter-trend-spark { display: inline-flex; align-items: center; }

/* Cross-highlight — hover an axis tile <-> its feeding rail rows (and back). */
.tape-axis.is-xhl, .tape-axis.is-xhl-src {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border));
  background: color-mix(in srgb, var(--accent) 9%, var(--surface));
}
.rob-row.is-xhl, .rob-row.is-xhl-src {
  background: color-mix(in srgb, var(--accent) 13%, transparent);
  box-shadow: inset 2px 0 0 color-mix(in srgb, var(--accent) 65%, transparent);
}

/* --- Cross-asset rail: controls + clickable rows + drill-down -------------- */
.rob-controls { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin: 0 0 10px; }
.rob-ctrl { display: inline-flex; align-items: center; gap: 6px; font: 600 11px/1 var(--font-mono); color: var(--muted); text-transform: uppercase; letter-spacing: .05em; }
.rob-ctrl select { font: 600 11px/1 var(--font-mono); color: var(--text-strong); background: var(--surface); border: 1px solid var(--border); border-radius: 4px; padding: 4px 6px; cursor: pointer; }
.rob-group-btn {
  font: 700 10px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .05em;
  padding: 5px 9px; border: 1px solid var(--border); border-radius: 5px;
  background: var(--surface); color: var(--muted); cursor: pointer;
  transition: color .12s ease, border-color .12s ease, background .12s ease;
}
.rob-group-btn:hover { color: var(--text-strong); }
.rob-group-btn[aria-pressed="true"] {
  color: var(--text-strong);
  border-color: color-mix(in srgb, var(--accent) 40%, var(--border));
  background: color-mix(in srgb, var(--accent) 9%, var(--surface));
}
.rob-liveonly { display: inline-flex; align-items: center; gap: 5px; cursor: pointer; font: 600 11px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .05em; color: var(--muted); }
.rob-liveonly input { cursor: pointer; accent-color: var(--accent); }

.rob-group-head {
  font: 700 10px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .08em;
  color: var(--muted); margin: 8px 0 5px; padding-top: 7px; border-top: 1px solid var(--border);
}
.rob-group:first-child .rob-group-head { border-top: 0; padding-top: 0; margin-top: 0; }

.rob-row-wrap { display: block; }
/* Rows are now buttons (click to expand). Keep the grid from the base rule and
   add the resets + a 4th column for the disclosure chevron. */
.rob-row {
  width: 100%;
  background: none;
  border: 0;
  color: inherit;
  font: inherit;
  cursor: pointer;
  padding: 4px 6px;
  border-radius: 6px;
  text-align: left;
  transition: background .12s ease, box-shadow .12s ease;
  grid-template-columns: var(--rob-name-col, 132px) 1fr auto auto;
}
.rob-row:hover { background: color-mix(in srgb, var(--text-strong) 5%, transparent); }
.rob-row:focus-visible { outline: 2px solid color-mix(in srgb, var(--accent) 55%, transparent); outline-offset: 1px; }
.rob-row.is-open { background: color-mix(in srgb, var(--text-strong) 4%, transparent); }
.rob-scale { padding: 0 6px; }
.rob-spark { display: inline-flex; align-items: center; color: var(--muted); margin-right: 2px; }
.rob-row-chev { color: var(--muted); font-size: 10px; padding-left: 2px; }
.rob-row-detail {
  padding: 7px 10px 9px;
  margin: 2px 0;
  border-left: 2px solid color-mix(in srgb, var(--text-strong) 14%, var(--border));
  display: grid;
  gap: 4px;
}
.rob-row-detail-row { font: 400 11.5px/1.5 var(--font-sans); color: var(--muted); }
.rob-row-detail-row b { color: var(--text-strong); font-weight: 700; }
.rob-row-detail-fresh { font: 600 10px/1.3 var(--font-mono); text-transform: uppercase; letter-spacing: .04em; }
.rob-empty { padding: 10px 4px; font: 500 12px/1.5 var(--font-sans); color: var(--muted); }
@media (max-width: 860px) {
  .rob-spark { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .tape-axis, .rob-row, .rob-group-btn { transition: none; }
}

/* Mobile: tighten the rank gutter. The score breakdown is now the in-card
   "Grade" tab (a tabpanel inside .pick-main), so it already flows full-width
   beneath the tabs on narrow viewports — no grid reflow needed. */
@media (max-width: 860px) {
  .pick-card {
    grid-template-columns: 44px minmax(0, 1fr);
    gap: var(--s-2);
    padding: 10px;
  }
  .pick-rank-num { font-size: 22px; }
  .pick-rank-top1 .pick-rank-num { font-size: 24px; }
  .pick-rank-top2 .pick-rank-num,
  .pick-rank-top3 .pick-rank-num { font-size: 22px; }
}

/* --- Recommendation ⇄ Grade toggle -------------------------------------
   A small segmented control under the head row that switches the card body
   between the recommendation and the full 4-pillar score breakdown. */
.pick-tabs {
  display: flex;
  gap: 4px;
  margin: 4px 0 8px;
  padding: 2px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  width: fit-content;
  box-shadow: var(--elev-1);
}
.pick-tab {
  appearance: none;
  background: transparent;
  border: 0;
  padding: 5px 12px;
  border-radius: var(--r-pill);
  font: 600 12px/1 var(--font-mono);
  letter-spacing: .04em;
  color: var(--muted);
  cursor: pointer;
  transition: background .12s var(--ease-out), color .12s var(--ease-out);
}
.pick-tab:hover:not(.is-active) { color: var(--text); }
.pick-tab.is-active {
  background: var(--surface-2);
  color: var(--text-strong);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 30%, var(--border));
}
.pick-tabpanel[hidden] { display: none; }

/* --- 4-pillar tier banner -----------------------------------------------
   Sits directly under the head row and dominates the card. Each tier gets
   its own color and intensity so the user knows at a glance whether this
   pick is Strong Call / Call / Put / Strong Put. */
.pick-tier {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px 12px;
  border-radius: var(--r-3);
  background: color-mix(in srgb, var(--surface) 90%, var(--muted) 10%);
  border: 1px solid var(--border);
  box-shadow: var(--elev-1);
}
.pick-tier-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.pick-tier-label {
  font: 700 14px/1 var(--font-sans);
  letter-spacing: .02em;
  color: var(--text-strong);
}
.pick-tier-score {
  font: var(--fw-display) var(--fs-2xl)/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  letter-spacing: var(--ls-display);
  color: var(--text-strong);
  margin-left: auto;
}
.pick-tier-sub {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 10px;
  font: 500 11px/1.2 var(--font-mono);
  letter-spacing: .04em;
  color: var(--muted);
  text-transform: uppercase;
}
.pick-tier-conv::after {
  content: " ·";
  margin-left: 4px;
  opacity: .4;
}
/* Risk-based sizing line (P3.4): "size ~X% of book · ~N contracts at $Y" — has
   numbers + a $ price, so keep it readable (no uppercase) and let it take the
   remaining width / wrap to its own line on a narrow card. */
.pick-tier-size {
  text-transform: none;
  letter-spacing: .01em;
  color: var(--text);
  cursor: help;
}
.pick-tier-strong-call {
  background-image: linear-gradient(135deg, color-mix(in srgb, var(--pos) 16%, var(--surface)) 0%, var(--surface) 62%);
  border-color: color-mix(in srgb, var(--pos) 45%, var(--border));
  border-left: 3px solid var(--pos);
}
.pick-tier-strong-call .pick-tier-label,
.pick-tier-strong-call .pick-tier-score { color: var(--pos); }
.pick-tier-call {
  background: color-mix(in srgb, var(--pos) 6%, var(--surface));
  border-color: color-mix(in srgb, var(--pos) 30%, var(--border));
}
.pick-tier-call .pick-tier-label,
.pick-tier-call .pick-tier-score { color: color-mix(in srgb, var(--pos) 80%, var(--text-strong)); }
.pick-tier-strong-put {
  background-image: linear-gradient(135deg, color-mix(in srgb, var(--neg) 16%, var(--surface)) 0%, var(--surface) 62%);
  border-color: color-mix(in srgb, var(--neg) 45%, var(--border));
  border-left: 3px solid var(--neg);
}
.pick-tier-strong-put .pick-tier-label,
.pick-tier-strong-put .pick-tier-score { color: var(--neg); }
.pick-tier-put {
  background: color-mix(in srgb, var(--neg) 6%, var(--surface));
  border-color: color-mix(in srgb, var(--neg) 30%, var(--border));
}
.pick-tier-put .pick-tier-label,
.pick-tier-put .pick-tier-score { color: color-mix(in srgb, var(--neg) 80%, var(--text-strong)); }
.pick-tier-no-trade {
  background: color-mix(in srgb, var(--muted) 8%, var(--surface));
  border-color: var(--border);
}

/* --- Execution-timing gate (computeEntryTiming) — "should we execute NOW?" -
   Separate from the grade tier above: the tier says how good the setup is, this
   says whether now is the moment. 'go' tints green (--pos), 'wait' amber (--warn). */
.pick-timing {
  margin: 6px 0 4px;
  padding: 9px 11px;
  border-radius: var(--r-2);
  border: 1px solid var(--border);
  background: color-mix(in srgb, var(--surface) 92%, var(--muted) 8%);
}
.pick-timing-pos { border-left: 3px solid var(--pos); background: color-mix(in srgb, var(--pos) 7%, var(--surface)); }
.pick-timing-fair { border-left: 3px solid var(--warn); background: color-mix(in srgb, var(--warn) 7%, var(--surface)); }
.pick-timing-head { display: flex; align-items: baseline; gap: 8px; }
.pick-timing-verdict {
  font: 700 12px/1 var(--font-mono);
  letter-spacing: .06em;
  padding: 3px 7px;
  border-radius: var(--r-1);
  white-space: nowrap;
}
.pick-timing-v-pos { background: var(--pos); color: var(--bg); }
.pick-timing-v-fair { background: var(--warn); color: var(--bg); }
.pick-timing-title { font: 600 13px/1.3 var(--font-sans); color: var(--text-strong); }
.pick-timing-sub { font-weight: 400; color: var(--muted); }
.pick-timing-reasons {
  margin: 7px 0 0;
  padding-left: 16px;
  font: 400 12.5px/1.5 var(--font-sans);
  color: var(--text);
}
.pick-timing-reasons li { margin: 1px 0; }
.pick-timing-tactical {
  margin-top: 6px;
  font: 500 12px/1.45 var(--font-sans);
  color: color-mix(in srgb, var(--neg) 80%, var(--text-strong));
}
.pick-timing-foot {
  margin-top: 7px;
  font: 400 11.5px/1.4 var(--font-sans);
  color: var(--muted);
}
/* Compact pills on the head row + the scannable grid card. */
.pick-timing-pill, .ptc-tactical, .pick-tactical-tag, .ptc-defer, .pick-defer-tag {
  font: 700 10px/1 var(--font-mono);
  letter-spacing: .05em;
  padding: 3px 6px;
  border-radius: var(--r-1);
  white-space: nowrap;
}
.pick-timing-pos.pick-timing-pill { background: color-mix(in srgb, var(--pos) 18%, var(--surface)); color: var(--pos); border: 1px solid color-mix(in srgb, var(--pos) 40%, var(--border)); }
.pick-timing-fair.pick-timing-pill { background: color-mix(in srgb, var(--warn) 18%, var(--surface)); color: var(--warn); border: 1px solid color-mix(in srgb, var(--warn) 40%, var(--border)); }
.ptc-tactical, .pick-tactical-tag { background: color-mix(in srgb, var(--neg) 16%, var(--surface)); color: var(--neg); border: 1px solid color-mix(in srgb, var(--neg) 38%, var(--border)); }
/* Deferred-entry chip — a scheduled catalyst (earnings/FOMC-class event) parks
   the entry; warn-tinted so a WAIT name can't read as "enter now" while skimming. */
.ptc-defer, .pick-defer-tag { background: color-mix(in srgb, var(--warn) 16%, var(--surface)); color: var(--warn); border: 1px solid color-mix(in srgb, var(--warn) 40%, var(--border)); }
.pick-defer-tag { white-space: normal; line-height: 1.35; }
/* Honest roster note above the picks grid (short list / gated / sector-capped). */
.picks-roster-note {
  grid-column: 1 / -1;
  margin: 0 0 4px;
  padding: 8px 12px;
  border-radius: var(--r-2);
  background: color-mix(in srgb, var(--accent) 6%, var(--surface));
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--border));
  font: 500 13px/1.5 var(--font-sans);
  color: var(--text);
}
.picks-roster-note b { color: var(--text-strong); font-variant-numeric: tabular-nums; }

/* --- Regime-drift banner (bake-timing honesty) -- */
/* The roster is baked hourly; the live cross-asset gauge recomputes ~30s. When
   the live tape turns more defensive than the regime the roster was built under,
   this fires above the grid so the user knows the frozen picks predate the flip. */
.picks-regime-drift-card {
  margin: 0 0 10px;
  padding: 11px 14px;
  border-radius: var(--r-2);
  background: color-mix(in srgb, var(--warn) 9%, var(--surface));
  border: 1px solid color-mix(in srgb, var(--warn) 38%, var(--border));
  border-left: 3px solid var(--warn);
}
.picks-regime-drift-head {
  margin: 0;
  font: 700 13.5px/1.45 var(--font-sans);
  color: var(--warn);
}
.picks-regime-drift-body {
  margin: 5px 0 0;
  font: 500 12.5px/1.55 var(--font-sans);
  color: var(--text);
}
.picks-regime-drift-head b, .picks-regime-drift-body b { color: var(--text-strong); font-weight: 700; }

/* --- Plain-English analysis paragraph -- */
.pick-analysis {
  margin: 4px 0 4px;
  padding: 8px 10px;
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
  border-left: 2px solid color-mix(in srgb, var(--accent) 35%, var(--border));
  border-radius: 0 var(--r-1) var(--r-1) 0;
  font: 400 13px/1.55 var(--font-sans);
  color: var(--text);
}

/* --- Thesis (what makes it work / what would disprove it) --------------- */
.pick-thesis {
  margin: 6px 0;
  padding: 10px 12px;
  background: var(--surface-2, color-mix(in srgb, var(--surface) 96%, var(--text)));
  border: 1px solid var(--border);
  border-radius: var(--r-1);
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.pick-thesis.thesis-bull { border-left: 3px solid var(--pos); }
.pick-thesis.thesis-bear { border-left: 3px solid var(--neg); }
.pick-thesis-head {
  font: 700 12px/1 var(--font-sans);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-strong);
  display: flex;
  align-items: center;
  gap: 8px;
}
.pick-thesis-head .thesis-dir {
  font-weight: 600;
  text-transform: capitalize;
  letter-spacing: 0;
  color: var(--text-muted);
  font-size: 11px;
}
.thesis-col-head { font: 700 11px/1.3 var(--font-sans); color: var(--text-muted); margin-bottom: 3px; }
.thesis-works .thesis-col-head { color: var(--pos); }
.thesis-inval .thesis-col-head { color: var(--neg); }
.pick-thesis .thesis-col ul { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 3px; }
.pick-thesis .thesis-col li {
  font: 400 12.5px/1.45 var(--font-sans);
  color: var(--text);
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
}
.thesis-li-meta { font: 600 10.5px/1 var(--font-mono); color: var(--text-muted); }
.thesis-target {
  font: 400 12px/1.4 var(--font-sans);
  color: var(--text-muted);
  padding-top: 2px;
  border-top: 1px dashed var(--border);
}
.thesis-target-lbl { font-weight: 700; color: var(--text); text-transform: uppercase; font-size: 10px; letter-spacing: 0.04em; margin-right: 4px; }
.thesis-status {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px;
  padding: 5px 8px;
  border-radius: var(--r-1);
  font: 400 12px/1.4 var(--font-sans);
}
.thesis-status-verdict { font-weight: 700; }
.thesis-status.thesis-ontrack { background: color-mix(in srgb, var(--pos) 10%, transparent); }
.thesis-status.thesis-ontrack .thesis-status-verdict { color: var(--pos); }
.thesis-status.thesis-broken { background: color-mix(in srgb, var(--neg) 10%, transparent); }
.thesis-status.thesis-broken .thesis-status-verdict { color: var(--neg); }
.thesis-status.thesis-mixed { background: color-mix(in srgb, var(--text) 6%, transparent); }
.thesis-status.thesis-mixed .thesis-status-verdict { color: var(--text-muted); }
.thesis-status-bits { color: var(--text-muted); }

/* --- Thesis: strategy / conviction / market read / disclosure / AI prose -- */
.thesis-strat {
  display: inline-flex; align-items: center; gap: 5px;
  align-self: flex-start;
  padding: 3px 9px; border-radius: 999px;
  font: 700 11px/1.3 var(--font-sans); letter-spacing: 0.01em;
  border: 1px solid var(--border);
}
.thesis-strat-icon { font-size: 12px; }
.thesis-strat-fb { font-weight: 400; color: var(--text-muted); font-size: 10px; }
.thesis-strat-credit { background: color-mix(in srgb, var(--accent, #5b8def) 14%, transparent); color: var(--accent, #5b8def); border-color: color-mix(in srgb, var(--accent, #5b8def) 35%, transparent); }
.thesis-strat-debit  { background: color-mix(in srgb, var(--text) 8%, transparent); color: var(--text); }
.thesis-strat-naked  { background: color-mix(in srgb, var(--pos) 12%, transparent); color: var(--pos); border-color: color-mix(in srgb, var(--pos) 35%, transparent); }
.thesis-conviction { font: 400 12px/1.4 var(--font-sans); color: var(--text-muted); }
.thesis-conv-lbl { font-weight: 700; color: var(--text); text-transform: uppercase; font-size: 10px; letter-spacing: 0.04em; margin-right: 4px; }
.thesis-market {
  font: 400 12.5px/1.5 var(--font-sans);
  padding: 6px 9px; border-radius: var(--r-1);
  border-left: 3px solid var(--border);
}
.thesis-market-lbl { font-weight: 700; color: var(--text); text-transform: uppercase; font-size: 10px; letter-spacing: 0.04em; margin-right: 5px; }
.thesis-market.thesis-mr-ok { background: color-mix(in srgb, var(--pos) 8%, transparent); border-left-color: var(--pos); }
.thesis-market.thesis-mr-bad { background: color-mix(in srgb, var(--neg) 8%, transparent); border-left-color: var(--neg); }
.thesis-market.thesis-mr-neutral { background: color-mix(in srgb, var(--text) 5%, transparent); }
.thesis-disclosure {
  font: 600 12px/1.5 var(--font-sans); color: var(--warn, #d98a00);
  background: color-mix(in srgb, var(--warn, #d98a00) 10%, transparent);
  border: 1px dashed color-mix(in srgb, var(--warn, #d98a00) 45%, transparent);
  border-radius: var(--r-1); padding: 6px 9px;
}
.pick-thesis.thesis-weak { border-left-color: var(--warn, #d98a00); }
.thesis-weak-tag {
  margin-left: 6px; font: 700 9px/1 var(--font-mono); text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--warn, #d98a00); background: color-mix(in srgb, var(--warn, #d98a00) 14%, transparent);
  padding: 2px 5px; border-radius: 4px; vertical-align: middle;
}
.thesis-prose {
  font: 400 12.5px/1.55 var(--font-sans); color: var(--text);
  background: color-mix(in srgb, var(--text) 4%, transparent);
  border-radius: var(--r-1); padding: 7px 10px;
}
.thesis-prose-tag {
  font: 700 9px/1 var(--font-mono); text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--text-muted); border: 1px solid var(--border); padding: 2px 5px; border-radius: 4px; margin-left: 4px; white-space: nowrap;
}
/* --- AI thesis (everything-aware): the prominent SUMMARY lead, the detailed
   reasoning section, the load-bearing drivers, and the AI's own confidence --- */
.thesis-summary {
  font: 500 13.5px/1.55 var(--font-sans); color: var(--text-strong, var(--text));
  background: color-mix(in srgb, var(--accent, #5b8def) 9%, transparent);
  border-left: 3px solid var(--accent, #5b8def); border-radius: var(--r-1); padding: 8px 11px;
}
.thesis-summary-lbl { font-weight: 800; text-transform: uppercase; font-size: 10px; letter-spacing: 0.05em; color: var(--accent, #5b8def); margin-right: 5px; }
.thesis-sec-reasoning .thesis-sec-ai { color: var(--accent, #5b8def); }
.thesis-reasoning {
  font: 400 12.5px/1.6 var(--font-sans); color: var(--text);
  background: color-mix(in srgb, var(--text) 4%, transparent);
  border-radius: var(--r-1); padding: 7px 10px; margin-top: 3px;
}
/* --- AI thesis STORY: the narrative arc (backdrop / what's changing / early
   confirmation / outlook), each a labelled beat in a flowing briefing --- */
.thesis-narrative {
  background: color-mix(in srgb, var(--text) 4%, transparent);
  border-radius: var(--r-1); padding: 8px 11px; margin-top: 3px;
  display: flex; flex-direction: column; gap: 8px;
}
.thesis-beat { display: flex; flex-direction: column; gap: 2px; }
.thesis-beat-lbl {
  font: 800 9.5px/1.2 var(--font-sans); text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--accent, #5b8def);
}
.thesis-beat-body { font: 400 12.5px/1.6 var(--font-sans); color: var(--text); }
.thesis-confirm-ul { margin: 1px 0 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 3px; }
.thesis-confirm-ul li {
  font: 400 12px/1.45 var(--font-sans); color: var(--text);
  display: flex; align-items: baseline; gap: 6px;
}
.thesis-confirm-ul li::before { content: '✓'; color: var(--pos); font-weight: 800; flex: none; }
.thesis-strat-reason-ai { color: var(--text); margin-bottom: 3px; }
.thesis-ai-drivers { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 6px; }
.thesis-ai-driver {
  font: 600 10.5px/1.2 var(--font-sans); color: var(--accent, #5b8def);
  background: color-mix(in srgb, var(--accent, #5b8def) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent, #5b8def) 28%, transparent);
  padding: 2px 7px; border-radius: 999px; white-space: nowrap;
}
.thesis-ai-conf {
  font: 700 9px/1 var(--font-mono); text-transform: uppercase; letter-spacing: 0.05em;
  padding: 2px 6px; border-radius: 4px; margin-left: 6px; white-space: nowrap; border: 1px solid var(--border);
}
.thesis-ai-conf-high { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 38%, transparent); background: color-mix(in srgb, var(--pos) 10%, transparent); }
.thesis-ai-conf-moderate { color: var(--accent, #5b8def); border-color: color-mix(in srgb, var(--accent, #5b8def) 35%, transparent); background: color-mix(in srgb, var(--accent, #5b8def) 9%, transparent); }
.thesis-ai-conf-low { color: var(--warn, #d98a00); border-color: color-mix(in srgb, var(--warn, #d98a00) 40%, transparent); background: color-mix(in srgb, var(--warn, #d98a00) 10%, transparent); }
.pick-vert.pick-vert-credit { border-left: 3px solid var(--accent, #5b8def); }
.pick-contract-credit .pick-contract-label { color: var(--accent, #5b8def); }
.ptc-con-spread.ptc-con-credit { color: var(--accent, #5b8def); }

/* --- Thesis v2: the edge, six sections, quality checklist, classification --- */
.pick-thesis.thesis-q-strong { border-left-color: var(--pos); }
.pick-thesis.thesis-q-moderate { border-left-color: var(--warn, #d98a00); }
.pick-thesis.thesis-q-weak, .pick-thesis.thesis-norec-card { border-left-color: var(--text-muted); }
/* classification badge in the thesis head + (smaller) on the compact tile */
.pick-class { margin-left: auto; font: 700 9.5px/1 var(--font-mono); text-transform: uppercase; letter-spacing: 0.05em; padding: 3px 7px; border-radius: 999px; white-space: nowrap; border: 1px solid var(--border); }
.pick-class-actionable { color: var(--pos); background: color-mix(in srgb, var(--pos) 12%, transparent); border-color: color-mix(in srgb, var(--pos) 35%, transparent); }
.pick-class-moderate { color: var(--accent, #5b8def); background: color-mix(in srgb, var(--accent, #5b8def) 12%, transparent); border-color: color-mix(in srgb, var(--accent, #5b8def) 35%, transparent); }
.pick-class-weak { color: var(--warn, #d98a00); background: color-mix(in srgb, var(--warn, #d98a00) 12%, transparent); border-color: color-mix(in srgb, var(--warn, #d98a00) 40%, transparent); }
/* wait-for-entry: strong pick whose entry isn't confirmed yet (queued behind a trigger) */
.pick-class-wait { color: var(--warn, #d98a00); background: color-mix(in srgb, var(--warn, #d98a00) 10%, transparent); border-color: color-mix(in srgb, var(--warn, #d98a00) 35%, transparent); }
.pick-class-idea { color: var(--text-muted); background: color-mix(in srgb, var(--text) 6%, transparent); }
/* final-grade chip — the AI grader's tier + score (after the data screen) */
.thesis-final-grade { margin-left: 6px; font: 700 9px/1 var(--font-mono); text-transform: uppercase; letter-spacing: 0.04em; padding: 3px 7px; border-radius: 999px; white-space: nowrap; border: 1px solid var(--border); }
.thesis-final-grade.thesis-q-strong { color: var(--pos); background: color-mix(in srgb, var(--pos) 12%, transparent); border-color: color-mix(in srgb, var(--pos) 35%, transparent); }
.thesis-final-grade.thesis-q-moderate { color: var(--accent, #5b8def); background: color-mix(in srgb, var(--accent, #5b8def) 12%, transparent); border-color: color-mix(in srgb, var(--accent, #5b8def) 35%, transparent); }
.thesis-final-grade.thesis-q-weak { color: var(--warn, #d98a00); background: color-mix(in srgb, var(--warn, #d98a00) 12%, transparent); border-color: color-mix(in srgb, var(--warn, #d98a00) 40%, transparent); }
.ptc-class { font: 700 8.5px/1 var(--font-mono); text-transform: uppercase; letter-spacing: 0.05em; padding: 2px 5px; border-radius: 4px; white-space: nowrap; border: none; margin: 0; }
.ptc-norec { font: 600 11px/1.3 var(--font-sans); color: var(--warn, #d98a00); }
.pick-tab-card.ptc-norec-card { opacity: 0.92; }
/* the EDGE line — the always-visible "why this trade" */
.thesis-edge { font: 500 13px/1.5 var(--font-sans); color: var(--text); background: color-mix(in srgb, var(--accent, #5b8def) 7%, transparent); border-left: 3px solid var(--accent, #5b8def); border-radius: var(--r-1); padding: 7px 10px; }
.thesis-edge.thesis-edge-none { background: color-mix(in srgb, var(--text) 5%, transparent); border-left-color: var(--text-muted); color: var(--text-muted); }
.thesis-edge-lbl { font-weight: 800; text-transform: uppercase; font-size: 10px; letter-spacing: 0.05em; color: var(--accent, #5b8def); margin-right: 5px; }
.thesis-edge-none .thesis-edge-lbl { color: var(--text-muted); }
/* no-strategy-recommendation note */
.thesis-norec { font: 700 12.5px/1.45 var(--font-sans); color: var(--text-strong); background: color-mix(in srgb, var(--warn, #d98a00) 10%, transparent); border: 1px dashed color-mix(in srgb, var(--warn, #d98a00) 45%, transparent); border-radius: var(--r-1); padding: 6px 10px; }
.thesis-norec-why { display: block; font-weight: 400; color: var(--text-muted); margin-top: 2px; }
/* expand / collapse "full reasoning" */
.thesis-expand { border-top: 1px dashed var(--border); padding-top: 6px; }
.thesis-expand > summary { cursor: pointer; list-style: none; font: 700 11px/1.3 var(--font-sans); text-transform: uppercase; letter-spacing: 0.04em; color: var(--accent, #5b8def); padding: 2px 0; user-select: none; }
.thesis-expand > summary::-webkit-details-marker { display: none; }
.thesis-expand > summary::before { content: '▸ '; }
.thesis-expand[open] > summary::before { content: '▾ '; }
.thesis-expand[open] > summary { margin-bottom: 6px; }
.thesis-expand-body { display: flex; flex-direction: column; gap: 9px; }
/* a numbered section inside the expand */
.thesis-sec { display: flex; flex-direction: column; gap: 4px; }
.thesis-sec-head { font: 700 11px/1.3 var(--font-sans); color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.03em; }
.thesis-sec-head.thesis-sec-ok { color: var(--pos); }
.thesis-sec-head.thesis-sec-inval { color: var(--neg); }
.thesis-ul { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 3px; }
.thesis-ul li { font: 400 12.5px/1.45 var(--font-sans); color: var(--text); display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px; }
.thesis-inval-ul li { color: var(--text-muted); }
.thesis-inval-ul li::before { content: '↘'; color: var(--neg); font-weight: 700; }
.thesis-strat-reason { font: 400 12.5px/1.5 var(--font-sans); color: var(--text); }
/* thesis-quality checklist */
.thesis-check-ul { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 3px; }
.thesis-check { font: 400 12px/1.4 var(--font-sans); display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px; }
.thesis-check-mark { font-weight: 800; width: 12px; }
.thesis-check-pass .thesis-check-mark { color: var(--pos); }
.thesis-check-fail .thesis-check-mark { color: var(--neg); }
.thesis-check-fail .thesis-check-lbl { color: var(--text-muted); }
.thesis-check-detail { font: 400 11px/1.3 var(--font-sans); color: var(--text-muted); }
.thesis-q-strong { color: var(--pos); }
.thesis-q-moderate { color: var(--warn, #d98a00); }
.thesis-q-weak { color: var(--text-muted); }
.thesis-q-score { font: 600 10px/1 var(--font-mono); color: var(--text-muted); }
/* roster group headers (Actionable / Ideas·Watch) */
.picks-group-head { grid-column: 1 / -1; width: 100%; flex-basis: 100%; display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; margin: 10px 0 2px; padding-bottom: 5px; border-bottom: 1px solid var(--border); }
.picks-group-title { font: 800 13px/1.2 var(--font-sans); text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-strong); }
.picks-group-actionable .picks-group-title { color: var(--pos); }
.picks-group-watch .picks-group-title { color: var(--text-muted); }
.picks-group-count { font: 700 11px/1 var(--font-mono); color: var(--text-muted); background: color-mix(in srgb, var(--text) 8%, transparent); padding: 2px 7px; border-radius: 999px; }
.picks-group-sub { font: 400 11.5px/1.4 var(--font-sans); color: var(--text-muted); flex-basis: 100%; }
.picks-group-empty { grid-column: 1 / -1; width: 100%; flex-basis: 100%; font: 400 12.5px/1.5 var(--font-sans); color: var(--text-muted); padding: 10px 12px; border: 1px dashed var(--border); border-radius: var(--r-1); }

/* --- Top Picks watchlist (user-saved, localStorage) ---------------------- */
.picks-group-watchlist .picks-group-title { color: var(--warn, #d98a00); }
/* Star toggle riding inside each pick tile (delegated span — the tile is a
   <button>, so it can't nest a real one). Pushed to the head row's right edge. */
.ptc-watch {
  flex: 0 0 auto;
  margin-left: auto;
  font: 700 15px/1 var(--font-sans);
  color: var(--muted);
  padding: 0 2px;
  cursor: pointer;
  transition: color .12s var(--ease-out), transform .12s var(--ease-out);
}
.ptc-watch:hover { color: var(--warn, #d98a00); transform: scale(1.15); }
.ptc-watch.is-watched { color: var(--warn, #d98a00); }
/* Saved-card wrapper: the status bar sits above the standard pick tile; the
   tile stretches so watchlist rows keep the grid's equal-height look. */
.pwl-card { display: flex; flex-direction: column; min-width: 0; }
.pwl-card .pick-tab-card { flex: 1; }
.pwl-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 3px 8px; padding: 0 2px 4px; min-width: 0; }
.pwl-tag { font: 700 9.5px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .05em; padding: 3px 6px; border-radius: 3px; white-space: nowrap; }
.pwl-tag-live { color: var(--pos); background: color-mix(in srgb, var(--pos) 10%, transparent); }
.pwl-tag-stale { color: var(--warn, #d98a00); background: color-mix(in srgb, var(--warn, #d98a00) 12%, transparent); }
.pwl-added { font: 500 10.5px/1 var(--font-mono); color: var(--text-muted); white-space: nowrap; }
.pwl-remove {
  margin-left: auto;
  appearance: none;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-muted);
  font: 600 10.5px/1 var(--font-mono);
  padding: 3px 7px;
  border-radius: 4px;
  cursor: pointer;
  white-space: nowrap;
  transition: color .12s var(--ease-out), border-color .12s var(--ease-out);
}
.pwl-remove:hover { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 45%, var(--border)); }
.pwl-stale .pick-tab-card { opacity: .82; filter: saturate(.75); }
/* Live grade + thesis-health chips (re-scored every build, patched on the 30s poll). */
.pwl-live-chips { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 4px; min-width: 0; max-width: 100%; }
.pwl-grade { color: var(--text-muted); background: color-mix(in srgb, var(--text-muted) 10%, transparent); }
.pwl-grade s { opacity: .6; font-weight: 500; margin-left: 1px; }
.pwl-grade-up { color: var(--pos); background: color-mix(in srgb, var(--pos) 10%, transparent); }
.pwl-grade-down { color: var(--warn, #d98a00); background: color-mix(in srgb, var(--warn, #d98a00) 12%, transparent); }
/* The grade chip is a BUTTON: click expands the card's what-changed panel. */
.pwl-grade-btn { appearance: none; border: 0; cursor: pointer; font: inherit; display: inline-flex; align-items: center; gap: 4px; }
.pwl-grade-btn:hover { filter: brightness(1.18); }
.pwl-grade-btn .pwl-arr { opacity: .55; font-weight: 500; }
.pwl-grade-btn .pwl-x { font-size: 8px; opacity: .7; transition: transform .15s ease; }
.pwl-open .pwl-grade-btn .pwl-x { transform: rotate(180deg); }
/* The expandable "what changed since saved" breakdown under the card bar. */
.pwl-delta {
  font: 400 11.5px/1.5 var(--font-sans);
  color: var(--text);
  background: color-mix(in srgb, var(--text-muted) 5%, transparent);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  padding: 9px 11px 8px;
  margin: 0 2px 6px;
  display: flex; flex-direction: column; gap: 6px;
}
.pwl-delta[hidden] { display: none; }
.pwl-delta-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 3px 10px; }
.pwl-delta-title { font: 700 10px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .06em; color: var(--text-muted); }
.pwl-delta-sum { font: 600 11.5px/1.3 var(--font-mono); color: var(--text); }
.pwl-delta-sum.pwl-up { color: var(--pos); }
.pwl-delta-sum.pwl-down { color: var(--warn, #d98a00); }
.pwl-delta-verdict { font-weight: 600; }
.pwl-dv-broken { color: var(--neg); }
.pwl-dv-ok { color: var(--pos); }
.pwl-dv-mixed { color: var(--warn, #d98a00); }
.pwl-delta-sec { font: 700 9.5px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .06em; color: var(--text-muted); margin-top: 2px; }
.pwl-delta-hint { font-weight: 500; text-transform: none; letter-spacing: 0; opacity: .8; }
.pwl-dp-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 2px 14px; }
.pwl-dp-row { display: flex; align-items: baseline; gap: 6px; font: 500 11px/1.5 var(--font-mono); }
.pwl-dp-row.pwl-dp-big .pwl-dp-name, .pwl-dp-row.pwl-dp-big .pwl-dp-delta { font-weight: 700; }
.pwl-dp-name { color: var(--text-muted); flex: 1; min-width: 0; }
.pwl-dp-vals { white-space: nowrap; }
.pwl-dp-vals .pwl-arr { opacity: .5; }
.pwl-dp-delta { min-width: 30px; text-align: right; white-space: nowrap; }
.pwl-dp-flat { color: var(--text-muted); opacity: .7; }
.pwl-dp-up { color: var(--pos); }
.pwl-dp-down { color: var(--warn, #d98a00); }
.pwl-dd-wrap { display: flex; flex-wrap: wrap; gap: 4px; }
.pwl-dd { font: 600 10px/1 var(--font-mono); padding: 3px 6px; border-radius: 3px; white-space: nowrap; }
.pwl-dd-ok { color: var(--pos); background: color-mix(in srgb, var(--pos) 10%, transparent); }
.pwl-dd-quiet { color: var(--text-muted); background: color-mix(in srgb, var(--text-muted) 10%, transparent); text-decoration: line-through; text-decoration-thickness: 1px; }
.pwl-dd-flip { color: var(--neg); background: color-mix(in srgb, var(--neg) 10%, transparent); }
.pwl-dd-new-for { color: var(--pos); background: color-mix(in srgb, var(--pos) 7%, transparent); border: 1px dashed color-mix(in srgb, var(--pos) 35%, transparent); }
.pwl-dd-new-against { color: var(--warn, #d98a00); background: color-mix(in srgb, var(--warn, #d98a00) 8%, transparent); border: 1px dashed color-mix(in srgb, var(--warn, #d98a00) 40%, transparent); }
.pwl-delta-tape { font: 500 11px/1.5 var(--font-mono); color: var(--text); }
.pwl-delta-note { font: 400 10.5px/1.4 var(--font-sans); color: var(--text-muted); }
.pwl-health-ok { color: var(--pos); background: color-mix(in srgb, var(--pos) 10%, transparent); }
.pwl-health-mixed { color: var(--warn, #d98a00); background: color-mix(in srgb, var(--warn, #d98a00) 12%, transparent); }
.pwl-health-broken { color: #fff; background: var(--neg); animation: pwl-broken-pulse 2.4s ease-in-out infinite; }
@keyframes pwl-broken-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .72; } }
@media (prefers-reduced-motion: reduce) { .pwl-health-broken { animation: none; } }
.pwl-detail-health-broken { color: var(--neg); background: color-mix(in srgb, var(--neg) 8%, transparent); border-color: color-mix(in srgb, var(--neg) 35%, var(--border)); }
.pwl-detail-health-on-track { color: var(--pos); background: color-mix(in srgb, var(--pos) 7%, transparent); border-color: color-mix(in srgb, var(--pos) 30%, var(--border)); }
.pwl-broken { flex: 1; font: 400 12px/1.5 var(--font-sans); color: var(--text-muted); padding: 12px; border: 1px dashed var(--border); border-radius: var(--r-3); }
.pwl-error { grid-column: 1 / -1; font: 500 12px/1.5 var(--font-sans); color: var(--neg); background: color-mix(in srgb, var(--neg) 8%, transparent); border: 1px solid color-mix(in srgb, var(--neg) 30%, var(--border)); border-radius: var(--r-2); padding: 6px 10px; }
.pwl-detail-note {
  font: 500 12px/1.5 var(--font-sans);
  color: var(--warn, #d98a00);
  background: color-mix(in srgb, var(--warn, #d98a00) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--warn, #d98a00) 30%, var(--border));
  border-radius: var(--r-2);
  padding: 8px 12px;
  margin-bottom: 10px;
}
/* Detail-card header watchlist toggle (a real button there). */
.pick-watch-btn {
  appearance: none;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-muted);
  font: 700 11px/1 var(--font-mono);
  letter-spacing: .03em;
  padding: 4px 8px;
  border-radius: 4px;
  cursor: pointer;
  white-space: nowrap;
  transition: color .12s var(--ease-out), border-color .12s var(--ease-out);
}
.pick-watch-btn:hover { color: var(--warn, #d98a00); border-color: color-mix(in srgb, var(--warn, #d98a00) 45%, var(--border)); }
.pick-watch-btn.is-watched {
  color: var(--warn, #d98a00);
  border-color: color-mix(in srgb, var(--warn, #d98a00) 45%, var(--border));
  background: color-mix(in srgb, var(--warn, #d98a00) 8%, transparent);
}

/* --- Sector-peer comparison -------------------------------------------- */
.pick-peers {
  margin-top: 8px;
  padding: 8px 10px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
}
.pick-peers-head {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
  margin-bottom: 6px;
}
.pick-peer-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.pick-peer {
  display: grid;
  grid-template-columns: 70px 50px 1fr;
  align-items: baseline;
  gap: 8px;
  padding: 3px 6px;
  border-radius: var(--r-1);
  font: 500 13px/1.3 var(--font-sans);
}
.pick-peer-sym {
  font: 700 13px/1 var(--font-mono);
  color: var(--text-strong);
  letter-spacing: .02em;
}
.pick-peer-score {
  font: 600 13px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: var(--text);
}
.pick-peer-tier {
  font: 500 12px/1 var(--font-sans);
  color: var(--muted);
}
.pick-peer.pick-peer-strong-call,
.pick-peer.pick-peer-call {
  background: color-mix(in srgb, var(--pos) 6%, var(--surface-2));
}
.pick-peer.pick-peer-strong-call .pick-peer-score,
.pick-peer.pick-peer-call .pick-peer-score { color: var(--pos); }
.pick-peer.pick-peer-strong-put,
.pick-peer.pick-peer-put {
  background: color-mix(in srgb, var(--neg) 6%, var(--surface-2));
}
.pick-peer.pick-peer-strong-put .pick-peer-score,
.pick-peer.pick-peer-put .pick-peer-score { color: var(--neg); }
.pick-peer.pick-peer-no-trade .pick-peer-score { color: var(--muted); }

/* --- 4-pillar score breakdown (the "Grade" tab) ------------------------ */
.pick-pillars-panel {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.pick-pillars-bar {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 4px 6px 8px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 4px;
}
.pick-pillars-title {
  font: 700 11px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
}
.pick-pillars-total {
  font: 700 18px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
}
/* Composition bar — proportional, sign-colored snapshot of how the four
   pillars sum into the score. Segment width = share of total |contribution|;
   the 1-letter code (F/T/M/N) maps each segment to its row below. */
.pick-pillars-viz {
  display: flex;
  gap: 2px;
  height: 16px;
  margin: 2px 6px 4px;
}
.pp-seg {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 3px;
  border-radius: 2px;
  font: 700 10px/1 var(--font-mono);
  color: rgba(8, 10, 14, 0.82);
  overflow: hidden;
}
.pp-seg.sig-pos { background: color-mix(in srgb, var(--pos) 78%, transparent); }
.pp-seg.sig-neg { background: color-mix(in srgb, var(--neg) 78%, transparent); }
.pp-seg.sig-zero { background: color-mix(in srgb, var(--muted) 32%, transparent); }
.pp-seg-l { letter-spacing: .04em; }
.pick-pillars-viz-cap {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
  opacity: .75;
  margin: 0 6px 8px;
}
/* Per-row diverging magnitude bar in each pillar summary. Center line is
   zero; fill extends right (green) for a positive pillar, left (red) for a
   negative one. --pill-mag is the half-width set inline (0–50%). */
.pick-pillar-bar {
  position: relative;
  align-self: center;
  height: 6px;
  border-radius: var(--r-pill);
  background: color-mix(in srgb, var(--text) 7%, transparent);
}
.pick-pillar-bar::before {
  content: "";
  position: absolute;
  left: 50%;
  top: -1px;
  bottom: -1px;
  width: 1px;
  background: color-mix(in srgb, var(--text) 16%, transparent);
}
.pick-pillar-bar i {
  position: absolute;
  top: 0;
  bottom: 0;
  width: var(--pill-mag, 0%);
  border-radius: var(--r-pill);
}
.pick-pillar-bar.sig-pos i { left: 50%; background: var(--pos); }
.pick-pillar-bar.sig-neg i { right: 50%; background: var(--neg); }
.pick-pillar-bar.sig-zero i { display: none; }
.pick-pillar {
  border: 1px solid var(--border);
  border-radius: var(--r-1);
  background: var(--surface);
  overflow: hidden;
}
.pick-pillar > summary.pick-pillar-head {
  list-style: none;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 46px auto;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  cursor: pointer;
  user-select: none;
  transition: background .12s var(--ease-out);
}
.pick-pillar > summary.pick-pillar-head::-webkit-details-marker { display: none; }
.pick-pillar > summary.pick-pillar-head:hover {
  background: color-mix(in srgb, var(--accent) 5%, var(--surface));
}
.pick-pillar[open] > summary.pick-pillar-head {
  border-bottom: 1px solid var(--border);
}
.pick-pillar-name {
  font: 600 13px/1 var(--font-sans);
  color: var(--text-strong);
}
/* Forward-trajectory chip on the Fundamentals pillar header (↗ improving /
   ↘ declining) — the blended "where it's heading" read. */
.pillar-traj {
  margin-left: 6px;
  padding: 1px 6px;
  border-radius: 999px;
  font: 700 10px/1.4 var(--font-sans);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  vertical-align: middle;
}
.pillar-traj.sig-pos { color: var(--pos); background: color-mix(in srgb, var(--pos) 14%, transparent); }
.pillar-traj.sig-neg { color: var(--neg); background: color-mix(in srgb, var(--neg) 14%, transparent); }
.pick-pillar-score {
  font: 700 13px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
}
/* Per-category plain-language explainer shown at the top of each expanded
   pillar (and the timing panel) so the signals below read without prior
   knowledge of the rubric. */
.pick-pillar-desc {
  margin: 0;
  padding: 8px 10px 0;
  font: 400 12px/1.45 var(--font-sans);
  color: var(--muted-strong);
}
.pick-pillar-signals {
  list-style: none;
  margin: 0;
  padding: 6px 10px 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
/* --- Entry-timing pillar: verdict + classified reason list ---------------- */
.pick-timing-verdict {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 8px 10px 0;
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: var(--r-1);
  background: var(--surface);
}
.pick-timing-state {
  flex: 0 0 auto;
  font: 700 11px/1 var(--font-mono);
  letter-spacing: .08em;
  padding: 4px 7px;
  border-radius: var(--r-1);
  color: #fff;
}
.pick-timing-go    .pick-timing-state { background: var(--pos); }
.pick-timing-wait  .pick-timing-state { background: var(--warn); }
.pick-timing-avoid .pick-timing-state { background: var(--neg); }
.pick-timing-go    { border-color: color-mix(in srgb, var(--pos) 40%, var(--border)); }
.pick-timing-wait  { border-color: color-mix(in srgb, var(--warn) 40%, var(--border)); }
.pick-timing-avoid { border-color: color-mix(in srgb, var(--neg) 40%, var(--border)); }
.pick-timing-headline {
  font: 600 12px/1.35 var(--font-sans);
  color: var(--text-strong);
}
.pick-timing-hint {
  margin: 6px 10px 0;
  font: 400 11px/1.4 var(--font-sans);
  color: var(--muted);
}
.pick-timing-group {
  margin: 8px 10px 0;
}
.pick-timing-group:last-child { margin-bottom: 8px; }
.pick-timing-group-head {
  font: 600 11px/1 var(--font-mono);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 4px;
}
.pick-timing-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.pick-timing-list li {
  position: relative;
  padding-left: 14px;
  font: 400 12px/1.4 var(--font-sans);
  color: var(--text);
}
.pick-timing-list li::before {
  position: absolute;
  left: 0;
  top: 0;
  font: 700 12px/1.4 var(--font-mono);
}
.pick-timing-group.is-pro  .pick-timing-list li::before { content: "+"; color: var(--pos); }
.pick-timing-group.is-con  .pick-timing-list li::before { content: "−"; color: var(--neg); }
.pick-timing-group.is-flag .pick-timing-list li::before { content: "⚠"; color: var(--neg); font-size: 11px; }
.pick-timing-group.is-flag .pick-timing-group-head { color: var(--neg); }
.pick-timing-group.is-flag .pick-timing-list li { color: var(--text-strong); font-weight: 500; }
.pick-timing-empty {
  margin: 8px 10px;
  font: 400 12px/1.4 var(--font-sans);
  color: var(--muted);
}
/* Research/unproven footnote on the Entry-timing panel (P0.2): the gate's
   thresholds are fit in-sample and not yet validated on forward picks. Muted +
   a subtle top rule so it reads as a caveat, not a signal. */
.pick-timing-research {
  margin: 8px 10px 4px;
  padding-top: 6px;
  border-top: 1px dashed var(--border, rgba(255,255,255,0.12));
  font: 400 11.5px/1.4 var(--font-sans);
  color: var(--muted);
  font-style: italic;
}
/* Dated-catalysts sub-section inside the Narrative pillar (Top Picks / Grade
   breakdown). Chips reuse the Calendar tab's .cal-chip / .cal-catalyst styling;
   these rules only add the labeled wrapper + let the title wrap in the narrow
   panel (scoped under .pick-catalysts so the Calendar tab's one-line chips are
   untouched). Purely additive — new class names not used elsewhere. */
.pick-catalysts {
  margin: 0 10px 8px;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}
.pick-catalysts-head {
  font: 600 11px/1 var(--font-mono);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 6px;
}
.pick-catalysts .cal-chip-text {
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
}
.pillar-signal {
  display: grid;
  grid-template-columns: 1fr auto;
  column-gap: 8px;
  row-gap: 2px;
  align-items: baseline;
  padding: 2px 0;
  border-radius: var(--r-1);
}
.pillar-signal-label {
  font: 500 12px/1.3 var(--font-sans);
  color: var(--text);
}
.pillar-signal-score {
  font: 700 12px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  text-align: right;
}
.pillar-signal-value {
  font: 500 11px/1.2 var(--font-mono);
  color: var(--muted);
  grid-column: 1 / -1;
}
.pillar-signal-note {
  font: 400 11px/1.3 var(--font-sans);
  color: var(--muted);
  grid-column: 1 / -1;
  opacity: .8;
}
.pillar-signal.sig-pos .pillar-signal-score { color: var(--pos); }
.pillar-signal.sig-neg .pillar-signal-score { color: var(--neg); }
.pillar-signal.sig-zero .pillar-signal-score { color: var(--muted); opacity: .7; }
.pillar-signal-nodata {
  opacity: .55;
}
.pillar-signal-nodata .pillar-signal-label::after {
  content: " · no data";
  font-style: italic;
  color: var(--muted);
}
/* Sign-coded helpers used by other elements (analysis, peers, totals). */
.sig-pos { color: var(--pos); }
.sig-neg { color: var(--neg); }
.sig-zero { color: var(--muted); }

/* "In plain English" explainer block — translates the Greek/IV row above
   into beginner-friendly bullets. Subtle bordered panel, mono digits, so
   it reads as a sibling of the contract block rather than a callout. */
.pick-plain {
  margin-top: 8px;
  padding: 8px 10px;
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--border));
  border-radius: var(--r-2);
}
.pick-plain-head {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
  margin-bottom: 6px;
}
.pick-plain-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.pick-plain-list li {
  font: 400 13px/1.5 var(--font-sans);
  color: var(--text);
  padding-left: 14px;
  position: relative;
}
.pick-plain-list li::before {
  content: "›";
  position: absolute;
  left: 2px;
  top: 0;
  color: var(--muted);
  font-weight: 700;
}
.pick-plain-list b {
  color: var(--text-strong);
  font-weight: 600;
}
.pick-card.call .pick-plain {
  background: color-mix(in srgb, var(--pos) 4%, var(--surface));
  border-color: color-mix(in srgb, var(--pos) 20%, var(--border));
}
.pick-card.put .pick-plain {
  background: color-mix(in srgb, var(--neg) 4%, var(--surface));
  border-color: color-mix(in srgb, var(--neg) 20%, var(--border));
}

/* Exit plan — two price targets (take-profit + cut/reduce) plus contextual
   exit triggers. Sits under the contract block. */
/* ----- Entry plan (mirror of the exit ladder) ------------------------------ */
.pick-entry {
  margin-top: 8px;
  padding: 8px 10px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
}
.pick-entry-head {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
  margin-bottom: 6px;
}
.pick-entry-alert, .pick-entry-defer {
  font: 400 12.5px/1.45 var(--font-sans);
  color: var(--text-strong);
  padding: 7px 9px;
  margin-bottom: 7px;
  border: 1px solid color-mix(in srgb, var(--warn) 45%, var(--border));
  border-left-width: 3px;
  border-left-color: var(--warn);
  border-radius: var(--r-1);
  background: color-mix(in srgb, var(--warn) 9%, var(--surface));
}
.pick-entry-defer b { color: var(--warn); }
.pick-entry-strat {
  padding: 7px 9px;
  margin-bottom: 7px;
  border: 1px solid var(--border);
  border-left-width: 3px;
  border-left-color: var(--accent);
  border-radius: var(--r-1);
  background: color-mix(in srgb, var(--accent) 5%, var(--surface));
}
.pick-entry-strat-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
}
.pick-entry-strat-name {
  font: 700 13.5px/1.2 var(--font-sans);
  color: var(--text-strong);
}
.pick-entry-strat-strength {
  font: 700 9.5px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .05em;
  padding: 3px 6px;
  border-radius: var(--r-pill);
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 14%, var(--surface));
}
.pick-entry-strat-blurb {
  font: 400 12.5px/1.45 var(--font-sans);
  color: var(--text);
  margin-top: 3px;
}
.pick-entry-sizing {
  display: flex;
  align-items: baseline;
  gap: 7px;
  flex-wrap: wrap;
  margin-bottom: 7px;
}
.pick-entry-stance {
  flex: none;
  font: 700 9.5px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .05em;
  padding: 3px 7px;
  border-radius: var(--r-pill);
  white-space: nowrap;
}
.pick-entry-stance-full {
  color: var(--pos);
  background: color-mix(in srgb, var(--pos) 14%, var(--surface));
}
.pick-entry-stance-scale {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 14%, var(--surface));
}
.pick-entry-sizing-txt {
  font: 400 12.5px/1.45 var(--font-sans);
  color: var(--text);
}
.pick-entry-ladder {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.pick-entry-rung {
  padding: 5px 9px;
  border: 1px solid var(--border);
  border-left-width: 3px;
  border-left-color: var(--accent);
  border-radius: var(--r-1);
  background: var(--surface);
}
.pick-entry-rung-starter {
  border-left-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 5%, var(--surface));
}
.pick-entry-rung-add { border-left-color: color-mix(in srgb, var(--accent) 60%, var(--muted)); }
.pick-entry-rung-final { border-left-color: var(--muted); border-left-style: dashed; }
.pick-entry-rung-main {
  display: flex;
  align-items: baseline;
  gap: 7px;
  flex-wrap: wrap;
}
.pick-entry-size {
  flex: none;
  font: 700 10px/1 var(--font-mono);
  letter-spacing: .03em;
  padding: 3px 6px;
  border-radius: var(--r-pill);
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 14%, var(--surface));
}
.pick-entry-price {
  font: 700 14px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--text-strong);
}
.pick-entry-move {
  font: 600 12px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--muted);
}
.pick-entry-rung-label {
  font: 400 12px/1.3 var(--font-sans);
  color: var(--muted-strong);
}
.pick-entry-trigger {
  font: 400 12.5px/1.4 var(--font-sans);
  color: var(--text);
  margin-top: 2px;
  padding-left: 13px;
  position: relative;
}
.pick-entry-trigger::before {
  content: "▸";
  position: absolute;
  left: 2px;
  top: 0;
  color: var(--accent);
  font-weight: 700;
}
/* "±20 grade at 50D SMA" alert chips (detail header + grid card) */
.pick-fifty-alert {
  font: 700 10px/1 var(--font-mono);
  letter-spacing: .04em;
  padding: 3px 7px;
  border-radius: var(--r-pill);
  color: var(--warn);
  background: color-mix(in srgb, var(--warn) 15%, var(--surface));
  border: 1px solid color-mix(in srgb, var(--warn) 40%, transparent);
  white-space: nowrap;
}
.ptc-alert {
  font: 700 9px/1 var(--font-mono);
  letter-spacing: .03em;
  padding: 2px 5px;
  border-radius: var(--r-pill);
  color: var(--warn);
  background: color-mix(in srgb, var(--warn) 15%, var(--surface));
  white-space: nowrap;
}

.pick-exit {
  margin-top: 8px;
  padding: 8px 10px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
}
.pick-exit-head {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
  margin-bottom: 6px;
}
.pick-exit-targets {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 6px;
}
.pick-exit-target {
  padding: 7px 9px;
  border: 1px solid var(--border);
  border-radius: var(--r-1);
  background: var(--surface);
  border-left-width: 3px;
}
.pick-exit-tp {
  border-left-color: var(--pos);
  background: color-mix(in srgb, var(--pos) 4%, var(--surface));
}
.pick-exit-cut {
  border-left-color: var(--neg);
  background: color-mix(in srgb, var(--neg) 4%, var(--surface));
}
.pick-exit-target-head {
  display: flex;
  align-items: baseline;
  gap: 6px;
  margin-bottom: 3px;
}
.pick-exit-kind {
  font: 600 11px/1.2 var(--font-sans);
  text-transform: uppercase;
  letter-spacing: .04em;
  color: var(--text-strong);
}
.pick-exit-tp .pick-exit-kind { color: var(--pos); }
.pick-exit-cut .pick-exit-kind { color: var(--neg); }
.pick-exit-price {
  font: 700 14px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--text-strong);
  margin-left: auto;
}
.pick-exit-move {
  font: 600 12px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--muted);
}
.pick-exit-reason {
  font: 400 12.5px/1.45 var(--font-sans);
  color: var(--text);
}
.pick-exit-pillars { margin-top: 9px; }
.pick-exit-pillars-head {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
  margin-bottom: 5px;
}
.pick-exit-pillar {
  padding: 6px 0;
  border-top: 1px solid var(--border);
}
.pick-exit-pillar:first-of-type { border-top: 0; padding-top: 0; }
.pick-exit-pillar-head {
  display: flex;
  align-items: baseline;
  gap: 6px;
  margin-bottom: 2px;
}
.pick-exit-pillar-label {
  font: 600 11px/1.2 var(--font-sans);
  text-transform: uppercase;
  letter-spacing: .04em;
  color: var(--text-strong);
}
.pick-exit-strength {
  font: 700 9.5px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .06em;
  padding: 2px 5px;
  border-radius: var(--r-1);
  color: var(--muted-strong);
  background: color-mix(in srgb, var(--muted) 14%, var(--surface));
}
.pick-exit-strength-very-high {
  color: var(--neg);
  background: color-mix(in srgb, var(--neg) 12%, var(--surface));
}
.pick-exit-pillar-reason {
  font: 400 12.5px/1.45 var(--font-sans);
  color: var(--text);
}
.pick-exit-triggers { margin-top: 7px; }
.pick-exit-triggers-head {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
  margin-bottom: 4px;
}
.pick-exit-trigger-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.pick-exit-trigger-list li {
  font: 400 12.5px/1.45 var(--font-sans);
  color: var(--text);
  padding-left: 14px;
  position: relative;
}
.pick-exit-trigger-list li::before {
  content: "›";
  position: absolute;
  left: 2px;
  top: 0;
  color: var(--muted);
  font-weight: 700;
}

/* Layered exit ladder — a vertical price ladder (high → low) with an action,
   prose line, per-pillar "why this level" disclosure, and watch-for cue per
   rung. Role accents map to the chart: take-profit/runner green, cut red,
   reduce amber, spot a muted dashed marker. */
.pick-exit-overview {
  font: 500 12.5px/1.45 var(--font-sans);
  color: var(--text-strong);
  margin: 0 0 8px;
  padding: 6px 8px;
  background: color-mix(in srgb, var(--accent) 6%, var(--surface));
  border-left: 2px solid var(--accent);
  border-radius: var(--r-1);
}
/* Two side-by-side ladders: scale-out (above entry) left, defend & cut
   (entry + below) right. Stacks back to one column on narrow viewports. */
.pick-exit-cols {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  align-items: start;
}
@media (max-width: 720px) {
  .pick-exit-cols { grid-template-columns: minmax(0, 1fr); }
}
.pick-exit-col-head {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  margin-bottom: 5px;
}
.pick-exit-col-head-up { color: var(--pos); }
.pick-exit-col-head-down { color: var(--neg); }
.pick-exit-ladder {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.pick-exit-level {
  padding: 5px 9px;
  border: 1px solid var(--border);
  border-left-width: 3px;
  border-radius: var(--r-1);
  background: var(--surface);
}
.pick-exit-level-tp {
  border-left-color: var(--pos);
  background: color-mix(in srgb, var(--pos) 5%, var(--surface));
}
.pick-exit-level-runner { border-left-color: var(--pos); border-left-style: dashed; }
.pick-exit-level-trim { border-left-color: color-mix(in srgb, var(--pos) 55%, var(--muted)); }
.pick-exit-level-spot {
  border-left-color: var(--muted);
  border-left-style: dashed;
  background: var(--surface-2);
}
.pick-exit-level-reduce { border-left-color: var(--warn); }
.pick-exit-level-cut {
  border-left-color: var(--neg);
  background: color-mix(in srgb, var(--neg) 5%, var(--surface));
}
.pick-exit-level-main {
  display: flex;
  align-items: baseline;
  gap: 7px;
  flex-wrap: wrap;
}
.pick-exit-level-price {
  font: 700 14px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--text-strong);
}
.pick-exit-action {
  margin-left: auto;
  font: 700 9.5px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .05em;
  padding: 3px 6px;
  border-radius: var(--r-pill);
  color: var(--muted-strong);
  background: color-mix(in srgb, var(--muted) 14%, var(--surface));
}
.pick-exit-level-tp .pick-exit-action,
.pick-exit-level-runner .pick-exit-action {
  color: var(--pos);
  background: color-mix(in srgb, var(--pos) 13%, var(--surface));
}
.pick-exit-level-cut .pick-exit-action {
  color: var(--neg);
  background: color-mix(in srgb, var(--neg) 13%, var(--surface));
}
.pick-exit-level-reduce .pick-exit-action {
  color: var(--warn);
  background: color-mix(in srgb, var(--warn) 16%, var(--surface));
}
/* Concrete contract (option) price to set the take-profit / stop at, shown
   next to the underlying stock level. */
.pick-exit-opt {
  font: 700 9.5px/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  text-transform: uppercase;
  letter-spacing: .04em;
  padding: 3px 6px;
  border-radius: var(--r-pill);
  white-space: nowrap;
  border: 1px solid transparent;
}
.pick-exit-opt-stop {
  color: var(--neg);
  background: color-mix(in srgb, var(--neg) 10%, var(--surface));
  border-color: color-mix(in srgb, var(--neg) 30%, transparent);
}
.pick-exit-opt-tp {
  color: var(--pos);
  background: color-mix(in srgb, var(--pos) 10%, var(--surface));
  border-color: color-mix(in srgb, var(--pos) 30%, transparent);
}
.pick-exit-opt-pct { opacity: .8; }
.pick-exit-level-prose {
  font: 400 12.5px/1.4 var(--font-sans);
  color: var(--text);
  margin-top: 2px;
}
.pick-exit-watch {
  font: 400 12px/1.4 var(--font-sans);
  color: var(--muted-strong);
  margin-top: 2px;
  padding-left: 13px;
  position: relative;
}
.pick-exit-watch::before {
  content: "▸";
  position: absolute;
  left: 2px;
  top: 0;
  color: var(--warn);
  font-weight: 700;
}
.pick-exit-why { margin-top: 3px; }
.pick-exit-why > summary {
  cursor: pointer;
  list-style: none;
  display: inline-block;
  font: 600 9.5px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .07em;
  color: var(--muted);
  transition: color .12s var(--ease-out);
}
.pick-exit-why > summary:hover { color: var(--accent); }
.pick-exit-why[open] > summary { color: var(--accent); margin-bottom: 4px; }
.pick-exit-why > summary::-webkit-details-marker { display: none; }
.pick-exit-rsn-list {
  list-style: none;
  margin: 6px 0 2px;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.pick-exit-rsn {
  display: grid;
  grid-template-columns: 16px 1fr;
  gap: 7px;
  align-items: start;
}
.pick-exit-rsn-tag {
  font: 700 10px/16px var(--font-mono);
  text-align: center;
  width: 16px;
  height: 16px;
  border-radius: var(--r-1);
  color: var(--surface);
  background: var(--muted-strong);
}
.pick-exit-rsn-technical .pick-exit-rsn-tag { background: var(--accent); }
.pick-exit-rsn-fundamental .pick-exit-rsn-tag { background: var(--pos); }
.pick-exit-rsn-mechanical .pick-exit-rsn-tag { background: var(--muted-strong); }
.pick-exit-rsn-narrative .pick-exit-rsn-tag { background: var(--warn); }
.pick-exit-rsn-txt {
  font: 400 12px/1.4 var(--font-sans);
  color: var(--text);
}

/* Audit-panel lead caption — names the dominant pillar up top. */
.pick-pillars-lead {
  font: 600 12px/1.3 var(--font-sans);
  margin: 0 0 7px;
}
.pick-pillars-lead b { font-variant-numeric: tabular-nums; }
.pick-pillars-lead.sig-pos { color: var(--pos); }
.pick-pillars-lead.sig-neg { color: var(--neg); }
.pick-pillars-lead.sig-zero { color: var(--muted-strong); }

/* Regime-weighting banner (§3.5.1) — explains how the live market tape is
   re-weighting the grade (slow pillars discounted in risk-off, boosted in
   risk-on). Hidden in the neutral tape (no element emitted). */
.pick-pillars-regime {
  display: flex;
  gap: 6px;
  align-items: flex-start;
  font: 500 11.5px/1.4 var(--font-sans);
  padding: 6px 8px;
  margin: 0 0 8px;
  border-radius: 7px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--muted-strong);
}
.pick-pillars-regime .ppr-ico { flex: 0 0 auto; font-size: 12px; line-height: 1.3; }
.pick-pillars-regime.pp-regime-off,
.pick-pillars-regime.pp-regime-severe {
  border-color: color-mix(in srgb, var(--neg) 35%, var(--border));
  background: color-mix(in srgb, var(--neg) 9%, var(--surface));
}
.pick-pillars-regime.pp-regime-off .ppr-ico,
.pick-pillars-regime.pp-regime-severe .ppr-ico { color: var(--neg); }
.pick-pillars-regime.pp-regime-severe { background: color-mix(in srgb, var(--neg) 15%, var(--surface)); }
.pick-pillars-regime.pp-regime-on {
  border-color: color-mix(in srgb, var(--pos) 35%, var(--border));
  background: color-mix(in srgb, var(--pos) 9%, var(--surface));
}
.pick-pillars-regime.pp-regime-on .ppr-ico { color: var(--pos); }

/* ===== Track record (pick accuracy) tab ============================== */
.acc-ok { color: var(--pos); font-weight: 600; }
.acc-bad { color: var(--neg); font-weight: 600; }
/* === Track-record sub-tabs (Scorecard / Top 10 / Activity / Picks) ===
   One short view at a time instead of the old single long scroll. The tab
   strip mirrors .opt-tabs (Grade tab) so the two read consistently. */
.accuracy-how {
  margin: -2px 0 4px;
}
.accuracy-how > summary {
  cursor: pointer;
  list-style: none;
  width: max-content;
  padding: 2px 0;
  color: var(--accent);
  font: 600 11px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .07em;
}
.accuracy-how > summary::-webkit-details-marker { display: none; }
.accuracy-how > summary::before { content: "▸ "; }
.accuracy-how[open] > summary::before { content: "▾ "; }
.accuracy-how > p {
  margin: 8px 0 0;
  color: var(--muted-strong);
  font: 400 13px/1.5 var(--font-sans);
}
.acc-tabs {
  display: flex; flex-wrap: wrap; gap: 0;
  margin: var(--s-4) 0 0;
  border-bottom: 1px solid var(--border);
}
.acc-tab {
  position: relative;
  appearance: none; background: transparent;
  border: none; border-bottom: 2px solid transparent;
  padding: 10px 16px;
  font-family: var(--font-mono);
  font-size: var(--fs-sm); font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--muted);
  cursor: pointer;
  margin-bottom: -1px;
  border-radius: var(--r-1) var(--r-1) 0 0;
}
.acc-tab:hover {
  color: var(--text);
  background: color-mix(in srgb, var(--accent) 4%, transparent);
}
.acc-tab[aria-selected="true"] {
  color: var(--accent);
  border-bottom-color: var(--accent);
}
.acc-tab[aria-selected="true"]::after {
  content: "";
  position: absolute;
  inset: auto 0 -2px 0;
  height: 2px;
  background: linear-gradient(90deg,
    transparent 0%,
    color-mix(in srgb, var(--accent) 60%, transparent) 50%,
    transparent 100%);
  filter: blur(3px);
  pointer-events: none;
}
.acc-tab-n {
  margin-left: 6px;
  padding: 1px 6px;
  border-radius: var(--r-pill);
  font: 700 10px/1.5 var(--font-mono);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0;
  color: var(--muted-strong);
  background: color-mix(in srgb, var(--muted) 16%, var(--surface));
}
.acc-tab[aria-selected="true"] .acc-tab-n {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 14%, transparent);
}
.acc-pane { padding-top: var(--s-4); }
.acc-pane[hidden] { display: none; }
.acc-pane-empty {
  color: var(--muted);
  font: 400 13px/1.5 var(--font-sans);
  padding: 12px 0;
}
.acc-pane-empty[hidden] { display: none; }
/* "At a glance" pane summary strip — the acc-sum-* slots at the top of every
   Track Record sub-tab, filled by accPaneSummary() in app.js: a few key
   numbers + a one-line takeaway before the pane's detail. */
.acc-pane-sum-slot:empty { display: none; }
.acc-glance {
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--border));
  border-left: 3px solid var(--accent);
  border-radius: var(--r-2);
  background: color-mix(in srgb, var(--accent) 5%, var(--surface));
  padding: 10px 12px;
  margin-bottom: var(--s-3);
}
.acc-glance-head {
  display: block;
  font: 700 10px/1 var(--font-mono);
  text-transform: uppercase; letter-spacing: .09em;
  color: var(--accent);
  margin-bottom: 8px;
}
.acc-glance-items { display: flex; flex-wrap: wrap; gap: 8px 20px; }
.acc-glance-item { display: inline-flex; align-items: baseline; gap: 6px; }
.acc-glance-val {
  font: 700 var(--fs-md)/1.2 var(--font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--text-strong);
  white-space: nowrap;
}
.acc-glance-lbl { font-size: var(--fs-xs); color: var(--muted); }
.acc-glance-take {
  margin: 8px 0 0;
  font-size: var(--fs-sm); line-height: 1.45;
  color: var(--text-strong);
}
.acc-glance-take b { color: var(--accent); }
/* Advanced / research disclosure inside the Scorecard pane — demotes the
   sector / regime / A-B cohort bars + fade-the-grade / grade-IC chips. */
.accuracy-advanced {
  margin-top: 12px;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface);
}
.accuracy-advanced > summary {
  cursor: pointer;
  list-style: none;
  padding: 9px 12px;
  font: 600 11px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted-strong);
}
.accuracy-advanced > summary::-webkit-details-marker { display: none; }
.accuracy-advanced > summary::before { content: "▸ "; color: var(--muted); }
.accuracy-advanced[open] > summary::before { content: "▾ "; }
.accuracy-advanced[open] > summary { border-bottom: 1px solid var(--border); }
.accuracy-advanced-body {
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
/* Flatten the cohort blocks inside the advanced card — the disclosure already
   frames them, so drop their own surface chrome to avoid nested boxes. */
.accuracy-advanced-body .accuracy-tiers { background: transparent; border: none; padding: 0; }
.accuracy-chips-research { margin-bottom: 0; }

/* ── Track Record analytics: Scorecard $-lens + Equity / Breakdowns /
      Simulator / Monte-Carlo sub-tabs ────────────────────────────────────── */
.acc-analytics { margin-top: 10px; }
.acc-an-lead { margin: 2px 0 10px; }
.acc-an-note { margin: 8px 0; }
.acc-an-subhead {
  font-size: var(--fs-sm); font-weight: 700; color: var(--text-strong);
  margin: 16px 0 8px; display: flex; align-items: center; gap: 8px;
}
.acc-an-tag, .acc-xtab-hint {
  font-size: 11px; font-weight: 600; color: var(--muted);
  background: var(--surface-2); border: 1px solid var(--border);
  border-radius: 999px; padding: 1px 8px; letter-spacing: .02em;
}
.acc-pctlens-head { margin-top: 20px; }
.accuracy-profit { margin-bottom: 6px; }
.acc-controls { display: flex; flex-wrap: wrap; gap: 12px 20px; align-items: center; margin: 4px 0 12px; }
.acc-ctl { display: flex; align-items: center; gap: 8px; }
.acc-ctl-lbl { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); }
.acc-seg label { padding: 5px 12px; font-size: 12px; }
.acc-check { display: inline-flex; align-items: center; gap: 7px; font-size: var(--fs-sm); color: var(--text-strong); cursor: pointer; }
.acc-check input { accent-color: var(--accent); width: 15px; height: 15px; }
.acc-hypo {
  display: inline-block; font-size: 11px; font-weight: 700; letter-spacing: .04em;
  color: var(--neg); background: color-mix(in srgb, var(--neg) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--neg) 35%, transparent);
  border-radius: 6px; padding: 4px 10px; margin-bottom: 10px;
}
.acc-an-rules { margin-top: 14px; font-size: var(--fs-sm); color: var(--muted); }
.acc-an-rules summary { cursor: pointer; font-weight: 600; color: var(--text-strong); }
.acc-an-rules ul { margin: 8px 0 0; padding-left: 18px; }
.acc-an-rules li { margin: 4px 0; }
/* metric tables (one CSS grid; header + label + numeric cells flow as items) */
.acc-tscroll { overflow-x: auto; -webkit-overflow-scrolling: touch; }
.acc-mtable { display: grid; gap: 1px; background: var(--border); border: 1px solid var(--border); border-radius: 8px; overflow: hidden; min-width: 520px; }
.acc-mh, .acc-ml, .acc-mc { background: var(--surface); padding: 7px 9px; font-size: 12px; font-variant-numeric: tabular-nums; }
.acc-mh { background: var(--surface-2); font-weight: 700; color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: .03em; text-align: right; }
.acc-mh.acc-ml { text-align: left; }
.acc-ml { font-weight: 600; color: var(--text-strong); text-align: left; }
.acc-mc { text-align: right; color: var(--text-strong); }
.acc-mrow-total { background: var(--surface-2); font-weight: 700; }
/* cross-tab heatmap */
.acc-xtab-ctl { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-bottom: 8px; }
.acc-xsel { background: var(--surface-2); color: var(--text-strong); border: 1px solid var(--border); border-radius: 6px; padding: 5px 8px; font-size: 12px; }
.acc-xtab-x { color: var(--muted); font-weight: 700; }
.acc-xtab { display: grid; gap: 1px; background: var(--border); border: 1px solid var(--border); border-radius: 8px; overflow: hidden; min-width: 420px; }
.acc-xh, .acc-xrh, .acc-xc, .acc-xcorner { background: var(--surface); padding: 6px 8px; font-size: 11px; }
.acc-xh { background: var(--surface-2); font-weight: 700; color: var(--muted); text-align: center; }
.acc-xrh { background: var(--surface-2); font-weight: 700; color: var(--text-strong); }
.acc-xc { text-align: center; display: flex; flex-direction: column; gap: 1px; font-variant-numeric: tabular-nums; }
.acc-xc-wr { font-weight: 700; color: var(--text-strong); }
.acc-xc-sub { font-size: 10px; color: var(--muted); }
.acc-xc-empty { color: var(--muted); opacity: .5; align-items: center; justify-content: center; }
/* equity / fan / histogram svg */
.acc-eq-svg, .acc-hist-svg, .acc-fan-svg { width: 100%; height: auto; display: block; margin: 6px 0 2px; }
.acc-eq-grid { stroke: var(--border); stroke-width: 1; }
.acc-eq-yl, .acc-hist-xl { fill: var(--muted); font-size: 10px; }
.acc-eq-yl { text-anchor: end; }
.acc-hist-xl { text-anchor: middle; }
.acc-eq-base { stroke: var(--muted); stroke-width: 1; stroke-dasharray: 3 3; opacity: .6; }
.acc-eq-area.up { fill: color-mix(in srgb, var(--pos) 14%, transparent); }
.acc-eq-area.down { fill: color-mix(in srgb, var(--neg) 14%, transparent); }
.acc-eq-line { fill: none; stroke-width: 2; }
.acc-eq-line.up { stroke: var(--pos); }
.acc-eq-line.down { stroke: var(--neg); }
.acc-eq-dot.up { fill: var(--pos); }
.acc-eq-dot.down { fill: var(--neg); }
.acc-hist-bar { fill: var(--accent); }
.acc-hist-bar.is-neg { fill: var(--neg); }
.acc-hist-mark { stroke: var(--muted); stroke-width: 1.5; stroke-dasharray: 4 3; }
.acc-fan-path { fill: none; stroke: var(--accent); stroke-width: .6; opacity: .14; }
.acc-fan-env { fill: color-mix(in srgb, var(--accent) 12%, transparent); stroke: none; }
.acc-fan-median { fill: none; stroke: var(--accent); stroke-width: 2.5; }
.acc-fan-hi { fill: none; stroke-width: 1.6; opacity: .9; }
.acc-fan-hi-best { stroke: var(--pos); }
.acc-fan-hi-worst { stroke: var(--neg); }
/* monte carlo cards + run button */
.acc-mc-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin: 10px 0; }
.acc-mc-card { background: var(--surface-2); border: 1px solid var(--border); border-radius: 10px; padding: 12px; display: flex; flex-direction: column; gap: 3px; }
.acc-mc-num { font-size: 20px; font-weight: 800; color: var(--text-strong); font-variant-numeric: tabular-nums; }
.acc-mc-card.sig-pos .acc-mc-num { color: var(--pos); }
.acc-mc-card.sig-neg .acc-mc-num { color: var(--neg); }
.acc-mc-lbl { font-size: 11px; color: var(--muted); }
.acc-mc-run { cursor: pointer; background: var(--accent); color: #fff; border: none; border-radius: var(--r-pill); padding: 8px 18px; font-size: 13px; font-weight: 700; }
.acc-mc-run:disabled { opacity: .5; cursor: not-allowed; }
/* rare-anomaly dissection cards */
.acc-mc-anom { background: var(--surface-2); border: 1px solid var(--border); border-left: 3px solid var(--neg); border-radius: 10px; padding: 12px 14px; margin: 10px 0; }
.acc-mc-anom.is-pos { border-left-color: var(--pos); }
.acc-mc-anom-head { display: flex; flex-wrap: wrap; gap: 4px 12px; align-items: baseline; }
.acc-mc-anom-kind { font-size: 11px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; color: var(--neg); }
.acc-mc-anom.is-pos .acc-mc-anom-kind { color: var(--pos); }
.acc-mc-anom-sim { font-size: 12px; color: var(--muted); }
.acc-mc-anom-val { font-size: 14px; font-variant-numeric: tabular-nums; margin-left: auto; }
.acc-mc-anom-val.sig-pos { color: var(--pos); }
.acc-mc-anom-val.sig-neg { color: var(--neg); }
.acc-mc-anom-rar { margin: 6px 0 0; font-size: 12px; color: var(--muted); }
.acc-mc-anom-how { margin: 6px 0 0; font-size: 12px; line-height: 1.55; }
/* engine summary (Summary sub-tab) */
.acc-sum-verdict {
  display: flex; align-items: flex-start; gap: 12px;
  background: var(--surface-2); border: 1px solid var(--border);
  border-left: 3px solid var(--muted); border-radius: 10px; padding: 12px 14px; margin: 6px 0 14px;
}
.acc-sum-badge {
  flex: none; font-size: 11px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase;
  border-radius: 999px; padding: 4px 10px; margin-top: 1px;
  color: var(--muted-strong); background: var(--surface-3);
}
.acc-sum-verdict.acc-sum-healthy { border-left-color: var(--pos); }
.acc-sum-verdict.acc-sum-healthy .acc-sum-badge { color: var(--pos); background: color-mix(in srgb, var(--pos) 14%, transparent); }
.acc-sum-verdict.acc-sum-mixed { border-left-color: var(--warn); }
.acc-sum-verdict.acc-sum-mixed .acc-sum-badge { color: var(--warn); background: color-mix(in srgb, var(--warn) 14%, transparent); }
.acc-sum-verdict.acc-sum-struggling { border-left-color: var(--neg); }
.acc-sum-verdict.acc-sum-struggling .acc-sum-badge { color: var(--neg); background: color-mix(in srgb, var(--neg) 14%, transparent); }
.acc-sum-verdict.acc-sum-early { border-left-color: var(--info); }
.acc-sum-verdict.acc-sum-early .acc-sum-badge { color: var(--info); background: color-mix(in srgb, var(--info) 14%, transparent); }
.acc-sum-story { margin: 0; font-size: var(--fs-sm); color: var(--text-strong); line-height: 1.55; }
.acc-sum-note { margin: 8px 0; font-size: var(--fs-sm); color: var(--text-strong); line-height: 1.55; }
.acc-audit { --acc-audit-tone: var(--info); display: flex; flex-direction: column; gap: 10px; margin: 0 0 16px; padding: 13px 14px; border: 1px solid color-mix(in srgb, var(--acc-audit-tone) 38%, var(--border)); border-left: 3px solid var(--acc-audit-tone); border-radius: 10px; background: linear-gradient(135deg, color-mix(in srgb, var(--acc-audit-tone) 5%, var(--surface)), var(--surface) 62%); }
.acc-audit-thesis, .acc-audit-exit { --acc-audit-tone: var(--neg); }
.acc-audit-entry, .acc-audit-vehicle { --acc-audit-tone: var(--warn); }
.acc-audit-balanced { --acc-audit-tone: var(--pos); }
.acc-audit-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.acc-audit-head > div { min-width: 0; }
.acc-audit-kicker { display: block; margin-bottom: 4px; color: var(--acc-audit-tone); font: 700 9px/1 var(--font-mono); letter-spacing: .08em; text-transform: uppercase; }
.acc-audit h3 { margin: 0; color: var(--text-strong); font: 760 16px/1.25 var(--font-sans); }
.acc-audit-n { flex: 0 0 auto; padding: 4px 7px; border: 1px solid color-mix(in srgb, var(--acc-audit-tone) 38%, var(--border)); border-radius: 999px; background: var(--surface); color: var(--acc-audit-tone); font: 700 9px/1 var(--font-mono); white-space: nowrap; }
.acc-audit-read { margin: 0; color: var(--muted-strong); font: 500 11.5px/1.5 var(--font-sans); }
.acc-audit-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); overflow: hidden; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); }
.acc-audit-metric { display: flex; flex-direction: column; gap: 4px; min-width: 0; padding: 9px 10px; border-right: 1px solid var(--border); }
.acc-audit-metric:last-child { border-right: 0; }
.acc-audit-metric small, .acc-audit-cohorts small { color: var(--muted); font: 700 8px/1 var(--font-mono); letter-spacing: .06em; text-transform: uppercase; }
.acc-audit-metric b { color: var(--text-strong); font: 760 16px/1.1 var(--font-mono); font-variant-numeric: tabular-nums; }
.acc-audit-metric b.sig-pos, .acc-audit-cohorts b.sig-pos { color: var(--pos); }
.acc-audit-metric b.sig-neg, .acc-audit-cohorts b.sig-neg { color: var(--neg); }
.acc-audit-metric span { color: var(--muted); font: 500 9.5px/1.3 var(--font-sans); overflow-wrap: anywhere; }
.acc-audit-cohorts { display: grid; grid-template-columns: minmax(110px, .8fr) repeat(2, minmax(0, 1fr)); align-items: stretch; overflow: hidden; border: 1px solid var(--border); border-radius: 8px; background: var(--surface-2); }
.acc-audit-cohorts > strong, .acc-audit-cohorts > span { display: flex; flex-direction: column; justify-content: center; gap: 3px; min-width: 0; padding: 8px 10px; border-right: 1px solid var(--border); }
.acc-audit-cohorts > span:last-child { border-right: 0; }
.acc-audit-cohorts > strong { color: var(--muted-strong); font: 700 10px/1.25 var(--font-sans); }
.acc-audit-cohorts b { color: var(--text-strong); font: 730 12px/1.15 var(--font-mono); }
.acc-audit-cohorts em { color: var(--muted); font: 500 9.5px/1.25 var(--font-sans); font-style: normal; }
.acc-audit-method { margin: 0; color: var(--muted); font: 500 10px/1.45 var(--font-sans); }
.acc-audit-method b { color: var(--muted-strong); }
.acc-audit-actions { display: flex; flex-wrap: wrap; gap: 6px; }
.acc-sum-exits { margin: 6px 0 2px; }
.acc-attr-bar { display: flex; gap: 2px; border-radius: 6px; overflow: hidden; margin: 4px 0 6px; }
.acc-attr-seg { min-width: 26px; text-align: center; font-size: 11px; font-weight: 800; padding: 5px 0; color: #fff; }
.acc-attr-seg.acc-attr-dir, .acc-attr-dot.acc-attr-dir { background: var(--neg); }
.acc-attr-seg.acc-attr-mix, .acc-attr-dot.acc-attr-mix { background: var(--warn); }
.acc-attr-seg.acc-attr-theta, .acc-attr-dot.acc-attr-theta { background: var(--info); }
.acc-attr-seg.acc-attr-churn, .acc-attr-dot.acc-attr-churn { background: var(--muted); }
.acc-attr-legend { display: flex; flex-wrap: wrap; gap: 6px 16px; font-size: 11px; color: var(--muted); margin-bottom: 4px; }
.acc-attr-legend span { display: inline-flex; align-items: center; gap: 6px; }
.acc-attr-dot { width: 9px; height: 9px; border-radius: 3px; display: inline-block; }
.acc-sum-cols { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 0 22px; }
.acc-sum-list { list-style: none; margin: 0; padding: 0; }
.acc-sum-seg {
  display: grid; grid-template-columns: 1fr auto; gap: 0 10px; align-items: baseline;
  padding: 7px 2px; border-bottom: 1px solid var(--border);
}
.acc-sum-seg-lbl { font-size: var(--fs-sm); font-weight: 600; color: var(--text-strong); display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.acc-sum-seg-dim { font-size: 10px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
.acc-sum-seg-val { font-size: var(--fs-sm); font-weight: 800; font-variant-numeric: tabular-nums; }
.acc-sum-seg-sub { grid-column: 1 / -1; font-size: 11px; color: var(--muted); }
.acc-sum-diags { margin: 6px 0 10px; padding-left: 20px; }
.acc-sum-diags li { margin: 7px 0; font-size: var(--fs-sm); color: var(--text-strong); line-height: 1.55; }
.acc-why-list { list-style: none; margin: 4px 0 0; padding: 0; }
.acc-why-row { border: 1px solid var(--border); border-left: 3px solid var(--muted); border-radius: 8px; padding: 9px 12px; margin: 8px 0; background: var(--surface); }
.acc-why-row.acc-why-win { border-left-color: var(--pos); }
.acc-why-row.acc-why-loss { border-left-color: var(--neg); }
.acc-why-head { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.acc-why-outcome { font-size: 12px; font-weight: 800; font-variant-numeric: tabular-nums; }
.acc-why-meta { font-size: 11px; color: var(--muted); margin-left: auto; }
.acc-why-text { margin: 6px 0 0; font-size: var(--fs-sm); color: var(--text-strong); line-height: 1.5; }
.acc-why-more { margin-top: 8px; font-size: var(--fs-sm); }
.acc-why-more summary { cursor: pointer; font-weight: 600; color: var(--muted-strong); }

@media (max-width: 760px) {
  .acc-audit-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .acc-audit-metric { border-bottom: 1px solid var(--border); }
  .acc-audit-metric:nth-child(2n) { border-right: 0; }
  .acc-audit-metric:nth-last-child(-n+2) { border-bottom: 0; }
}
@media (max-width: 480px) {
  .acc-audit { padding: 11px; }
  .acc-audit-head { flex-direction: column; }
  .acc-audit-cohorts { grid-template-columns: minmax(0, 1fr); }
  .acc-audit-cohorts > strong, .acc-audit-cohorts > span { border-right: 0; border-bottom: 1px solid var(--border); }
  .acc-audit-cohorts > span:last-child { border-bottom: 0; }
  .acc-audit-actions { display: grid; grid-template-columns: minmax(0, 1fr); }
  .acc-audit-actions .flow-decision-action { width: 100%; min-height: 42px; justify-content: center; }
}

.accuracy-stats { margin: 10px 0 14px; }
