.acc-pc-wrap[open] > summary { border-bottom: 1px solid var(--border); }
.acc-pc-list { display: flex; flex-direction: column; }
.acc-pc-row {
  display: grid;
  grid-template-columns: 58px auto auto auto minmax(0, 1fr) auto;
