  .acc-gc-score { grid-column: 2 / -1; }
  .acc-gc-why, .acc-gc-date { grid-column: 1 / -1; justify-self: start; white-space: normal; }
  .acc-pc-row { grid-template-columns: 52px auto auto 1fr; }
