  .acc-pc-reason { grid-column: 1 / -1; }
  .acc-pc-why { white-space: normal; }
  .acc-pc-date { grid-column: 1 / -1; justify-self: start; }
  .acc-cp-row { grid-template-columns: 58px 1fr 60px 64px; }
