.fng-spark-tip-score.fng-band-fear          { color: var(--fng-fear); }
.fng-spark-tip-score.fng-band-neutral       { color: var(--fng-neutral); }
.fng-spark-tip-score.fng-band-greed         { color: var(--fng-greed); }
.fng-spark-tip-score.fng-band-extreme-greed { color: var(--fng-extreme-greed); }
.fng-spark-tip-band {
  font-size: var(--fs-2xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: var(--ls-caps);
  color: var(--muted);
}
.fng-spark-tip-date {
  font-family: var(--font-mono);
  font-size: var(--fs-2xs);
  color: var(--muted);
}
.fng-spark-band { opacity: 0.10; }
.fng-spark-band.fng-band-extreme-fear  { fill: var(--fng-extreme-fear); }
.fng-spark-band.fng-band-fear          { fill: var(--fng-fear); }
.fng-spark-band.fng-band-neutral       { fill: var(--fng-neutral); }
.fng-spark-band.fng-band-greed         { fill: var(--fng-greed); }
.fng-spark-band.fng-band-extreme-greed { fill: var(--fng-extreme-greed); }
.fng-spark-line {
  stroke: var(--text);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}
.fng-spark-axis {
  display: flex; justify-content: space-between;
  font-family: var(--font-mono);
  font-size: var(--fs-2xs);
  color: var(--muted);
}
.fng-cards {
  display: flex;
  flex-direction: column;
  gap: var(--s-2);
}
.fng-card {
  display: block;
  overflow: clip;
  border: 1px solid var(--border);
  border-left-width: 3px;
  border-radius: var(--r-3);
  background: var(--surface-2);
}
.fng-card.fng-band-extreme-fear  { border-left-color: var(--fng-extreme-fear); }
.fng-card.fng-band-fear          { border-left-color: var(--fng-fear); }
.fng-card.fng-band-neutral       { border-left-color: var(--fng-neutral); }
.fng-card.fng-band-greed         { border-left-color: var(--fng-greed); }
.fng-card.fng-band-extreme-greed { border-left-color: var(--fng-extreme-greed); }
.fng-card-title {
  font-size: var(--fs-md);
  font-weight: 600;
  margin: 0;
  color: var(--text);
}
.fng-card-summary {
  display: grid;
  grid-template-columns: minmax(160px, .8fr) minmax(170px, 1fr) auto 14px;
  gap: var(--s-3);
  align-items: center;
  min-height: 48px;
  padding: var(--s-2) var(--s-3);
}
.fng-card-meter { min-width: 0; }
.fng-card-missing {
  grid-column: 2 / 4;
  font-size: var(--fs-xs);
  color: var(--muted);
}
.fng-card-body {
  padding: 0 var(--s-3) var(--s-3);
  border-top: 1px solid color-mix(in srgb, var(--border) 72%, transparent);
}
.fng-card-blurb {
  font-size: var(--fs-sm);
  color: var(--muted);
  margin: var(--s-3) 0 0;
  line-height: var(--lh-snug);
}
.fng-card-rating {
  font-family: var(--font-mono);
  font-size: var(--fs-2xs);
  text-transform: uppercase;
  letter-spacing: var(--ls-caps);
  color: var(--muted);
}
.fng-bar { display: flex; align-items: center; gap: var(--s-2); flex: 1 1 auto; }
.fng-bar-track {
  position: relative;
  flex: 1 1 auto;
  height: 6px;
  background: var(--surface-3);
  border-radius: var(--r-pill);
  overflow: hidden;
}
.fng-bar-fill {
  position: absolute; left: 0; top: 0; bottom: 0;
  border-radius: var(--r-pill);
  background: var(--muted);
  transition: width .2s ease;
}
.fng-bar.fng-band-extreme-fear  .fng-bar-fill { background: var(--fng-extreme-fear); }
.fng-bar.fng-band-fear          .fng-bar-fill { background: var(--fng-fear); }
.fng-bar.fng-band-neutral       .fng-bar-fill { background: var(--fng-neutral); }
.fng-bar.fng-band-greed         .fng-bar-fill { background: var(--fng-greed); }
.fng-bar.fng-band-extreme-greed .fng-bar-fill { background: var(--fng-extreme-greed); }
.fng-bar-num {
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--muted);
  min-width: 26px; text-align: right;
}
.fng-card-empty { opacity: 0.7; }
@media (max-width: 720px) {
  .fng-decision { padding: var(--s-3); }
  .fng-decision-lead { grid-template-columns: 82px minmax(0, 1fr); gap: var(--s-3); }
  .fng-decision-kicker { align-items: flex-start; flex-direction: column; gap: 3px; }
  .fng-score-lockup { padding-right: var(--s-3); }
  .fng-score-value { font-size: 36px; }
  .fng-decision-copy h3 { font-size: var(--fs-lg); }
  .fng-decision-copy p { font-size: var(--fs-xs); }
  .fng-trade-plan { grid-template-columns: minmax(0, 1fr); }
  .fng-decision-actions { display: grid; grid-template-columns: minmax(0, 1fr); }
  .fng-decision-actions .flow-decision-action { width: 100%; min-height: 42px; }
  .fng-decision-grid { gap: 5px; }
  .fng-read-card { padding: 7px; }
  .fng-read-card strong {
    overflow: visible;
    white-space: normal;
    font-size: var(--fs-xs);
    line-height: var(--lh-tight);
  }
  .fng-read-card > span:last-child { display: none; }
  .fng-change-strip small { font-size: 9px; }
  .fng-change-strip > span { flex-direction: column; align-items: center; gap: 0; }
  .fng-strip {
    display: flex;
    gap: 6px;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scroll-snap-type: inline proximity;
    padding-bottom: 2px;
  }
  .fng-chip { flex: 0 0 88px; scroll-snap-align: start; }
  .fng-disclosure > summary {
    grid-template-columns: minmax(0, 1fr) 14px;
    gap: 2px var(--s-2);
  }
  .fng-disclosure-meta { grid-column: 1; grid-row: 2; }
  .fng-disclosure > summary .fng-disclosure-chevron { grid-column: 2; grid-row: 1 / 3; }
  .fng-headline { grid-template-columns: 1fr; gap: var(--s-3); }
  .fng-gauge { max-width: 180px; }
  .fng-headline-meta { align-items: center; text-align: center; }
  .fng-card-summary {
    grid-template-columns: minmax(0, 1fr) auto 14px;
    gap: 4px var(--s-2);
    padding: var(--s-2);
  }
  .fng-card-title { font-size: var(--fs-sm); }
  .fng-card-meter { grid-column: 1 / 3; grid-row: 2; }
  .fng-card-rating { grid-column: 2; grid-row: 1; }
  .fng-card-summary .fng-disclosure-chevron { grid-column: 3; grid-row: 1 / 3; }
  .fng-card-missing { grid-column: 2; }
}

/* ==========================================================================
   Visual polish pass — additive refinements layered on top of the base
   component CSS above. Kept in one block so the diff is easy to read /
   revert. All changes are pure CSS, gated under prefers-reduced-motion
   where they animate, and degrade gracefully on browsers without
   color-mix / backdrop-filter.
   ========================================================================== */

/* Brand mark — the dashed aperture ring is a static printer's mark, not a
   perpetually-breathing "live" LED (that constant glow-pulse is exactly the
   generated-dashboard tell we're moving away from). It comes alive only on
   interaction: hovering the wordmark sweeps the ring open (the rotate lives
   on .brand:hover .brand-mark) and gives the dot one quiet pulse. */
@keyframes brand-mark-pulse {
  0%   { opacity: 1; }
  50%  { opacity: 0.6; }
  100% { opacity: 1; }
}
@media (prefers-reduced-motion: no-preference) {
  .brand:hover .brand-mark circle {
    animation: brand-mark-pulse 1.4s var(--ease-in-out);
  }
}

/* Site-header — a 1px inset top highlight reads the solid masthead band as
   a raised surface, and the brass keyline (--accent-line) rules it off from
   the page below, the way a printed masthead is separated from the body. */
.site-header {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--text-strong) 6%, transparent),
    0 1px 0 var(--accent-line),
    0 6px 18px -12px rgba(0,0,0,0.7);
}
:root[data-theme="light"] .site-header {
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.7),
    0 1px 0 var(--accent-line),
    0 6px 18px -12px rgba(15,23,42,0.10);
}

/* Brand tag pill — currently transparent, give it a faint surface so the
   "Option Rater" badge reads as a chip not stray text. */
.brand-tag {
  background: color-mix(in srgb, var(--accent) 6%, transparent);
  border-color: color-mix(in srgb, var(--accent) 22%, var(--border));
  color: var(--muted-strong);
}

/* Icon-btn — explicit focus-visible ring so keyboard users see the
   target. The :focus-visible global rule already adds a ring but
   buttons with their own border need it tuned. */
.icon-btn:focus-visible {
  outline: none;
  border-color: var(--accent);
  color: var(--text-strong);
  background: var(--accent-soft);
  box-shadow: var(--focus-ring);
}

/* Cmd-palette-trigger — subtle accent-tinted hover + focus that signals
   "press ⌘K". The kbd chip inside also brightens to reinforce the cue. */
.cmd-palette-trigger {
  transition: background var(--dur-1) var(--ease-out),
              border-color var(--dur-1) var(--ease-out),
              color var(--dur-1) var(--ease-out),
              box-shadow var(--dur-1) var(--ease-out);
}
.cmd-palette-trigger:hover .cmd-palette-trigger-kbd,
.cmd-palette-trigger:focus-visible .cmd-palette-trigger-kbd {
  color: var(--accent-strong);
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border));
}
.cmd-palette-trigger:focus-visible {
  outline: none;
  border-color: var(--accent);
  color: var(--text-strong);
  box-shadow: var(--focus-ring);
}

/* Cmd-palette modal entrance — backdrop fades, modal scales up slightly.
   Pure CSS, fires on every open since the [hidden] attribute toggles. */
@media (prefers-reduced-motion: no-preference) {
  .cmd-palette:not([hidden]) .cmd-palette-backdrop {
    animation: cmdp-backdrop-in 180ms var(--ease-out) both;
  }
  .cmd-palette:not([hidden]) .cmd-palette-modal {
    animation: cmdp-modal-in 220ms var(--ease-out) both;
    transform-origin: 50% 0;
  }
}
@keyframes cmdp-backdrop-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes cmdp-modal-in {
  from { opacity: 0; transform: translateY(-8px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* Landing-card arrow — currently slides right on hover; add a tiny
   scale so the affordance reads stronger. */
.landing-card:hover .landing-card-arrow {
  transform: translateX(4px) scale(1.1);
}

/* Pick card — push the call/put differentiation past a 3px left bar.
   Add a left-anchored gradient tint so cards are scannable at a glance,
   and lift on hover so they feel interactive. */
.pick-card.call {
  background-image: linear-gradient(
    90deg,
    color-mix(in srgb, var(--pos) 6%, transparent) 0%,
    transparent 22%);
}
.pick-card.put {
  background-image: linear-gradient(
    90deg,
    color-mix(in srgb, var(--neg) 6%, transparent) 0%,
    transparent 22%);
}
@media (prefers-reduced-motion: no-preference) {
  .pick-card {
    transition: border-color .15s var(--ease-out),
                background .15s var(--ease-out),
                transform .18s var(--ease-out),
                box-shadow .18s var(--ease-out);
  }
  .pick-card:hover {
    transform: translateY(-1px);
    box-shadow: var(--elev-2);
  }
  .pick-card.call:hover {
    box-shadow: var(--elev-1),
                0 0 18px -4px color-mix(in srgb, var(--pos) 28%, transparent);
  }
  .pick-card.put:hover {
    box-shadow: var(--elev-1),
                0 0 18px -4px color-mix(in srgb, var(--neg) 28%, transparent);
  }
}

/* Hero surface refinement — add a hair-thin top accent line to the
   landing hero so it visually anchors as the page entry point. The
   existing ::before pseudo is the left accent rail; we use box-shadow
   inset for the top hairline to avoid stacking ::after on top of the
   gradient. */
.landing-hero {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--accent) 25%, transparent),
    var(--elev-2),
    var(--elev-glow);
}
:root[data-theme="light"] .landing-hero {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--accent) 35%, transparent),
    var(--elev-2),
    var(--elev-glow);
}

/* Landing-card-stat — the gradient-clipped text can render as a thin
   sliver in light mode because text-strong → accent at the same
   luminance loses contrast. Add a fallback solid color and only apply
   the gradient where it'll read. */
.landing-card-stat {
  color: var(--text-strong);
}
@supports (background-clip: text) or (-webkit-background-clip: text) {
  .landing-card:hover .landing-card-stat {
    background: linear-gradient(180deg,
      var(--text-strong) 0%,
      var(--accent-strong) 120%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
  }
}

/* Card hover refinement — when a .card opts into .is-hoverable, swap the
   subtle solid border for an accent-tinted hairline so the hover state
   reads as "this is the one you're aiming at". */
.card.is-hoverable:hover {
  border-color: color-mix(in srgb, var(--accent) 30%, var(--border-strong));
}

/* Narrative card — accent the left rail on hover with a soft outer glow
   that matches the sentiment. Reinforces the bullish/bearish read. */
@media (prefers-reduced-motion: no-preference) {
  .narr:hover .narr-accent {
    box-shadow: 0 0 10px color-mix(in srgb, var(--pos) 55%, transparent),
                0 0 1px color-mix(in srgb, var(--pos) 80%, transparent);
  }
  .narr[data-sent="bearish"]:hover .narr-accent {
    box-shadow: 0 0 10px color-mix(in srgb, var(--neg) 55%, transparent),
                0 0 1px color-mix(in srgb, var(--neg) 80%, transparent);
  }
}

/* Freshness banner — when a stale-state pill is shown, give it a subtle
   inner highlight so it reads as a chip not flat text. */
.freshness.warn::after,
.freshness.bad::after {
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--text-strong) 5%, transparent);
}

/* Skeleton loader — current shimmer travels through the whole gradient
   in 1.4s; tighten the highlight band so it reads as a sweep, not a
   wash. The opacity stop in the middle makes the moving band sharper. */
.skel {
  background-image: linear-gradient(
    90deg,
    var(--surface-2) 0%,
    var(--surface-2) 38%,
    color-mix(in srgb, var(--text-strong) 9%, var(--surface-2)) 50%,
    var(--surface-2) 62%,
    var(--surface-2) 100%);
}

/* Empty-state — give the icon a slow breath so a totally empty section
   doesn't feel dead. Capped iteration count to keep it from being
   distracting on long sessions. */
@keyframes empty-state-breathe {
  0%, 100% { opacity: 0.45; transform: scale(1); }
  50%      { opacity: 0.65; transform: scale(1.03); }
}
@media (prefers-reduced-motion: no-preference) {
  .empty-state-icon {
    animation: empty-state-breathe 3.2s var(--ease-in-out) infinite;
  }
}

/* Calendar chip — current hover translates right 2px; add a tiny accent
   shadow on the right edge so the slide reads as "entering the day's
   detail" rather than just shifting in place. */
@media (prefers-reduced-motion: no-preference) {
  .cal-chip:hover {
    box-shadow: 1px 0 0 color-mix(in srgb, var(--accent) 35%, transparent);
  }
}

/* Scrollbar — match the desk-chrome feel. Thin, neutral, only visible
   when hovered. Applies to the few scrollable strips (.narr-ended-strip,
   cmd-palette results, calendar day list, etc.). */
.narr-ended-strip,
.cmd-palette-results,
.opt-pinned-strip {
  scrollbar-width: thin;
  scrollbar-color: var(--border-strong) transparent;
}
.narr-ended-strip::-webkit-scrollbar,
.cmd-palette-results::-webkit-scrollbar,
.opt-pinned-strip::-webkit-scrollbar { height: 8px; width: 8px; }
.narr-ended-strip::-webkit-scrollbar-thumb,
.cmd-palette-results::-webkit-scrollbar-thumb,
.opt-pinned-strip::-webkit-scrollbar-thumb {
  background: var(--border-strong);
  border-radius: var(--r-pill);
  border: 2px solid transparent;
  background-clip: padding-box;
}
.narr-ended-strip::-webkit-scrollbar-thumb:hover,
.cmd-palette-results::-webkit-scrollbar-thumb:hover,
.opt-pinned-strip::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb, var(--accent) 35%, var(--border-strong));
  background-clip: padding-box;
}

/* Tighter selection — the default browser highlight clashes with the
   green accent. Replace with an accent-soft surface so selected
   numbers + tickers stay readable. */
::selection {
  background: color-mix(in srgb, var(--accent) 32%, transparent);
  color: var(--text-strong);
}

/* Keyboard hint — every <kbd> gets the same chip treatment so shortcuts
   read as a system, not ad-hoc. Specific rules (.cmd-palette-kbd,
   .landing-foot kbd, etc.) keep their own paint via higher specificity.
   Uses individual font props (not the shorthand) so the existing
   .mono, code, kbd, samp font-feature-settings rule still applies. */
kbd {
  display: inline-block;
  padding: 2px 7px;
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-radius: var(--r-2);
  background: var(--surface-2);
  color: var(--text);
  font-weight: 600;
  font-size: 11px;
  line-height: 1.4;
  letter-spacing: 0;
  vertical-align: 1px;
  box-shadow: 0 1px 0 var(--border-strong);
}

/* Global scrollbar — thin, tinted track so the browser chrome matches
   the institutional palette instead of defaulting to OS gray. */
html {
  scrollbar-width: thin;
  scrollbar-color: var(--border-strong) transparent;
}
html::-webkit-scrollbar { width: 10px; }
html::-webkit-scrollbar-track { background: transparent; }
html::-webkit-scrollbar-thumb {
  background: var(--border-strong);
  border-radius: var(--r-pill);
  border: 3px solid transparent;
  background-clip: padding-box;
}
html::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb, var(--accent) 35%, var(--border-strong));
  background-clip: padding-box;
}

/* ---- Stock volume calendar ------------------------------------------ */
.vol-cal-card { margin-bottom: var(--s-4); }
.vol-cal-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--s-3);
  margin-bottom: var(--s-3);
}
.vol-cal-symbol-field {
  display: grid;
  grid-template-columns: auto auto;
  align-items: center;
  gap: 9px;
  font: 700 10px/1 var(--font-mono);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--muted);
}
.vol-cal-symbol-search {
  display: inline-flex;
  align-items: stretch;
}
.vol-cal-symbol-search input {
  width: 150px;
  min-height: 38px;
  padding: 7px 11px;
  border: 1px solid var(--border);
  border-right: 0;
  border-radius: var(--r-2) 0 0 var(--r-2);
  appearance: none;
  background: var(--surface-2);
  color: var(--text-strong);
  font: 700 13px/1 var(--font-mono);
  text-transform: uppercase;
}
.vol-cal-symbol-search input::placeholder { color: var(--muted); text-transform: none; }
.vol-cal-symbol-search input::-webkit-search-cancel-button { cursor: pointer; }
.vol-cal-symbol-search input[aria-invalid="true"] { border-color: var(--neg); }
.vol-cal-symbol-search button {
  min-height: 38px;
  padding: 7px 12px;
  border: 1px solid var(--accent);
  border-radius: 0 var(--r-2) var(--r-2) 0;
  background: var(--accent);
  color: var(--accent-fg);
  cursor: pointer;
  font: 750 10px/1 var(--font-sans);
  letter-spacing: .04em;
  text-transform: uppercase;
}
.vol-cal-symbol-search input:focus-visible, .vol-cal-symbol-search button:focus-visible { outline: none; box-shadow: var(--focus-ring); position: relative; z-index: 1; }
.vol-cal-symbol-search input:focus-visible { border-color: var(--accent); }
.vol-cal-symbol-search button:hover { filter: brightness(1.06); }
.vol-cal-symbol-status {
  grid-column: 2;
  min-height: 11px;
  color: var(--neg);
  font: 600 9px/1.2 var(--font-sans);
  letter-spacing: 0;
  text-transform: none;
}
.vol-cal-legend { display: flex; flex-wrap: wrap; gap: 12px; color: var(--muted); font: 600 10px/1.2 var(--font-sans); }
.vol-cal-legend span { display: inline-flex; align-items: center; gap: 5px; }
.vol-cal-legend i { width: 9px; height: 9px; border-radius: 3px; border: 1px solid var(--border); }
.vol-cal-legend i.is-above { background: color-mix(in srgb, var(--pos) 25%, var(--surface)); border-color: color-mix(in srgb, var(--pos) 55%, var(--border)); }
.vol-cal-legend i.is-below { background: color-mix(in srgb, var(--accent) 20%, var(--surface)); border-color: color-mix(in srgb, var(--accent) 55%, var(--border)); }
.vol-cal-legend i.is-strong { background: var(--surface); border-color: var(--warn); box-shadow: inset 0 0 0 1px var(--warn); }
.vol-cal-root { display: flex; flex-direction: column; gap: var(--s-3); min-width: 0; }
.vol-cal-monthbar { margin: 0; }
.vol-cal-month-read {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: var(--r-3);
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 5%, var(--surface)), var(--surface));
}
.vol-cal-month-read > div:first-child { min-width: 0; }
.vol-cal-month-read span, .vol-cal-detail-head span, .vol-cal-catalyst span {
  display: block;
  font: 700 8.5px/1.2 var(--font-sans);
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--muted);
}
.vol-cal-month-read h3, .vol-cal-detail-head h3 { margin: 3px 0 0; font: 750 17px/1.2 var(--font-sans); color: var(--text-strong); }
.vol-cal-month-read p, .vol-cal-detail-head p { margin: 4px 0 0; max-width: 76ch; font: 450 11.5px/1.45 var(--font-sans); color: var(--muted-strong); }
.vol-cal-month-stats { display: flex; flex: 0 0 auto; gap: 7px; }
.vol-cal-month-stats > span {
  min-width: 82px;
  padding: 8px 9px;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-2);
  text-align: center;
}
.vol-cal-month-stats small { display: block; font: 650 8px/1.2 var(--font-sans); color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
.vol-cal-month-stats b { display: block; margin-top: 4px; font: 750 15px/1 var(--font-mono); color: var(--text-strong); }
.vol-cal-grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 4px; }
.vol-cal-cell {
  appearance: none;
  min-width: 0;
  min-height: 76px;
  padding: 6px 7px;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-2);
  color: inherit;
  text-align: left;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 3px;
  overflow: hidden;
}
button.vol-cal-cell { cursor: pointer; transition: transform .12s, border-color .12s, box-shadow .12s; }
button.vol-cal-cell:hover { transform: translateY(-1px); border-color: var(--accent); }
button.vol-cal-cell:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.vol-cal-cell.is-selected { box-shadow: inset 0 0 0 2px var(--accent); border-color: var(--accent); }
.vol-cal-cell.is-above { background: color-mix(in srgb, var(--pos) 10%, var(--surface)); border-color: color-mix(in srgb, var(--pos) 42%, var(--border)); }
.vol-cal-cell.is-below { background: color-mix(in srgb, var(--accent) 9%, var(--surface)); border-color: color-mix(in srgb, var(--accent) 38%, var(--border)); }
.vol-cal-cell.is-strong { box-shadow: inset 0 0 0 1px var(--warn); }
.vol-cal-cell.is-strong.is-selected { box-shadow: inset 0 0 0 2px var(--accent), inset 0 0 0 4px color-mix(in srgb, var(--warn) 70%, transparent); }
.vol-cal-cell.is-live { border-style: dashed; background: color-mix(in srgb, var(--warn) 7%, var(--surface)); }
.vol-cal-cell.is-empty { background: var(--surface); opacity: .55; }
.vol-cal-cell.is-out { min-height: 0; border-color: transparent; background: transparent; opacity: .35; }
.vol-cal-num { font: 650 11px/1 var(--font-mono); color: var(--muted); }
.vol-cal-cell b { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 750 12px/1.1 var(--font-mono); color: var(--text-strong); }
.vol-cal-cell.is-above b { color: var(--pos); }
.vol-cal-cell.is-below b { color: var(--accent-strong); }
.vol-cal-cell small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 600 9px/1.1 var(--font-mono); color: var(--muted-strong); }
.vol-cal-detail {
  padding: 14px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--muted);
  border-radius: var(--r-3);
  background: var(--surface);
}
.vol-cal-detail.is-leader { border-left-color: var(--pos); }
.vol-cal-detail.is-laggard { border-left-color: var(--neg); }
.vol-cal-detail.is-inline { border-left-color: var(--warn); }
.vol-cal-detail-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.vol-cal-detail-head > div { min-width: 0; }
.vol-cal-detail-head > b {
  flex: 0 0 auto;
  min-width: 76px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-2);
  color: var(--text-strong);
  text-align: center;
  font: 750 13px/1 var(--font-mono);
}
.vol-cal-detail.is-leader .vol-cal-detail-head > b { color: var(--pos); }
.vol-cal-detail.is-laggard .vol-cal-detail-head > b { color: var(--neg); }
.vol-cal-metrics { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 7px; margin-top: 11px; }
.vol-cal-metrics > div, .vol-cal-index-tile {
  min-width: 0;
  padding: 8px 9px;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-2);
}
.vol-cal-metrics small { display: block; font: 650 8px/1.2 var(--font-sans); letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
.vol-cal-metrics b { display: block; margin-top: 5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 750 13px/1.1 var(--font-mono); color: var(--text-strong); }
.vol-cal-metrics b.idx-up, .vol-cal-index-tile b.idx-up { color: var(--pos); }
.vol-cal-metrics b.idx-dn, .vol-cal-index-tile b.idx-dn { color: var(--neg); }
.vol-cal-indexes { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 7px; margin-top: 7px; }
.vol-cal-index-tile span { display: block; font: 700 8.5px/1 var(--font-mono); color: var(--muted); }
.vol-cal-index-tile b { display: block; margin-top: 5px; font: 750 12px/1.1 var(--font-mono); color: var(--text-strong); }
.vol-cal-catalyst { margin-top: 8px; padding: 10px 11px; border: 1px solid color-mix(in srgb, var(--warn) 35%, var(--border)); border-radius: var(--r-2); background: color-mix(in srgb, var(--warn) 5%, var(--surface)); }
.vol-cal-catalyst b { display: block; margin-top: 4px; font: 650 11px/1.4 var(--font-sans); color: var(--text-strong); }
.vol-cal-catalyst small { display: block; margin-top: 3px; font: 500 9px/1.2 var(--font-sans); color: var(--muted); }
.vol-cal-empty { padding: 24px; border: 1px dashed var(--border); border-radius: var(--r-2); text-align: center; color: var(--muted); }

@media (max-width: 640px) {
  .vol-cal-card { padding: var(--s-3); }
  .vol-cal-card > .hint { display: none; }
  .vol-cal-controls { align-items: stretch; }
  .vol-cal-symbol-field { width: 100%; grid-template-columns: auto minmax(0, 220px); justify-content: space-between; }
  .vol-cal-symbol-search { min-width: 0; }
  .vol-cal-symbol-search input { width: 100%; min-width: 0; min-height: 42px; }
  .vol-cal-symbol-search button { min-height: 42px; }
  .vol-cal-legend { gap: 8px 10px; }
  .vol-cal-month-read { align-items: flex-start; flex-direction: column; padding: 11px; }
  .vol-cal-month-stats { width: 100%; }
  .vol-cal-month-stats > span { flex: 1; min-width: 0; }
  .vol-cal-grid { gap: 3px; }
  .vol-cal-cell { min-height: 58px; padding: 4px; }
  .vol-cal-cell b { font-size: 10px; }
  .vol-cal-cell small { font-size: 7.5px; }
  .vol-cal-detail { padding: 11px; }
  .vol-cal-detail-head { flex-direction: column; gap: 8px; }
  .vol-cal-detail-head > b { min-width: 0; }
  .vol-cal-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .vol-cal-indexes { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}

/* ---- Volume + S/R break tab ----------------------------------------- */
.vol-card { padding: var(--s-4); }
.vol-controls {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-3);
  align-items: center;
  margin-bottom: var(--s-3);
}
.vol-search {
  display: inline-flex;
  align-items: center;
  gap: var(--s-2);
  padding: var(--s-2) var(--s-3);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  color: var(--text-2);
  min-width: 240px;
}
.vol-search:focus-within {
  border-color: var(--accent);
  box-shadow: var(--focus-ring);
}
.vol-search input {
  background: transparent;
  border: none;
  outline: none;
  color: var(--text);
  flex: 1;
  font: inherit;
  min-width: 0;
}
.vol-search-clear {
  background: none;
  border: none;
  color: var(--text-2);
  cursor: pointer;
  padding: 0 var(--s-1);
  font-size: 1.1em;
  line-height: 1;
}
.vol-filter {
  display: inline-flex;
  gap: 4px;
  padding: 3px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
}
.vol-pill {
  background: transparent;
  border: none;
  color: var(--text-2);
  padding: var(--s-2) var(--s-3);
  border-radius: var(--r-pill);
  font: inherit;
  cursor: pointer;
  transition: background-color var(--xt), color var(--xt);
}
.vol-pill:hover { color: var(--text); }
.vol-pill.is-on {
  background: var(--accent);
  color: var(--accent-on);
}
.vol-pill:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.vol-toggles { display: inline-flex; gap: var(--s-2); }
.vol-toggle-pill { border: 1px solid var(--border); }
.vol-toggle-pill.is-on { border-color: transparent; }

/* Phone layout for the Volume tab. */
@media (max-width: 640px) {
  /* The Volume tab's intro explainer paragraphs are desktop reference
     prose — on a phone they push the actual scan a full screen down. */
  .vol-card > .hint { display: none; }
  /* Controls: full-width search on its own row, wrappable pill groups with
     thumb-sized targets, and the sort select stretched to the row width. */
  .vol-card { padding: var(--s-3); }
  .vol-controls { gap: var(--s-2); }
  .vol-search { flex: 1 1 100%; min-width: 0; }
  .vol-filter { flex-wrap: wrap; }
  .vol-pill { padding: var(--s-2) 10px; min-height: 36px; }
  .vol-sort { flex: 1 1 100%; }
  .vol-sort select { flex: 1; min-width: 0; }
  /* Flag cards: ticker + spot on the first line, the chips/stats summary on
     its own full-width line below (margin-left:auto right-ragged wrapping
     reads broken at ~390px), with taller tap targets throughout. */
  .vol-row { padding: var(--s-3); }
  .vol-row-head { row-gap: var(--s-1); padding: var(--s-1) 0; }
  .vol-row-summary { flex-basis: 100%; margin-left: 0; }
  .vol-sector-head { padding: var(--s-2) 0; min-height: 40px; }
  /* Hour buckets: label + price move share the first line, the volume
     actual/expected detail drops to its own line (same pattern as the live
     board's phone rows). */
  .vol-bucket-row { row-gap: 2px; }
  .vol-bucket-label { min-width: 0; }
  .vol-bucket-move { margin-left: auto; }
  .vol-bucket-vol { flex-basis: 100%; order: 3; font-size: 0.85em; }
  /* Breadth banner: tighter, and the ticker-breadth stat wraps under the
     legend instead of fighting margin-left:auto for space. */
  .vol-summary { padding: var(--s-2) var(--s-3); }
  .vol-summary-tickers { margin-left: 0; flex-basis: 100%; }
}

/* ---- Shared auto-live overlays (Tickers grid / Top Picks / OI tab) ----- */
/* Small "Live · 10:42 AM" status next to a card header's eyebrow. */
.tab-live-state {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
  white-space: nowrap;
}
.tab-live-state:empty { display: none; }
.tab-live-state.is-live { color: var(--accent); }
.tab-live-state.is-error { color: var(--neg); }
/* Tickers grid: live day-change badge next to the card's spot. */
.ticker-chg {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: var(--fs-xs);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.ticker-chg.is-up { color: var(--pos); }
.ticker-chg.is-dn { color: var(--neg); }
/* Top Picks: "live since pick" board above the grid. */
.picks-live-board {
  display: grid;
  gap: 2px;
  margin-bottom: var(--s-3);
  padding: var(--s-2) var(--s-3);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
}
.picks-live-title {
  color: var(--text-3);
  font-size: 0.78em;
  text-transform: uppercase;
  letter-spacing: .05em;
  padding: 2px var(--s-2);
}
.picks-live-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--s-2);
  padding: 3px var(--s-2);
  border-radius: var(--r-2);
  font-variant-numeric: tabular-nums;
}
.picks-live-sym { font-weight: 700; min-width: 4em; }
.picks-live-side {
  font-size: 0.75em;
  font-weight: 700;
  letter-spacing: .04em;
  padding: 1px 6px;
  border-radius: var(--r-pill);
  border: 1px solid var(--border-strong);
}
.picks-live-side.is-call { color: var(--pos); border-color: color-mix(in srgb, var(--pos) 45%, transparent); }
.picks-live-side.is-put { color: var(--neg); border-color: color-mix(in srgb, var(--neg) 45%, transparent); }
.picks-live-spot { color: var(--text-2); min-width: 5.5em; }
.picks-live-since.is-pos { color: var(--pos); }
.picks-live-since.is-neg { color: var(--neg); }
.picks-live-lvls { color: var(--text-3); font-size: 0.88em; }
.picks-live-hit {
  font-weight: 700;
  font-size: 0.85em;
  padding: 1px 8px;
  border-radius: var(--r-pill);
}
.picks-live-hit.is-tp { background: var(--pos-soft); color: var(--pos); }
.picks-live-hit.is-cut { background: var(--neg-soft); color: var(--neg); }
/* Top Picks live board on phones: each pick's level distances get their
   own line so the row doesn't squeeze into an unreadable single string. */
@media (max-width: 640px) {
  .picks-live-row { padding: 6px var(--s-2); row-gap: 2px; }
  .picks-live-sym { min-width: 3.5em; }
  .picks-live-spot { min-width: 0; }
  .picks-live-lvls { flex-basis: 100%; }
}
/* OI tab: live spot-vs-walls distance in each row head. */
.oi-live { display: inline-flex; flex-wrap: wrap; gap: 2px var(--s-2); }
.oi-live-gap {
  color: var(--text-3);
  font-size: 0.85em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.oi-live-gap.is-breach-up { color: var(--pos); font-weight: 600; }
.oi-live-gap.is-breach-dn { color: var(--neg); font-weight: 600; }

.vol-summary {
  display: grid;
  gap: var(--s-2);
  padding: var(--s-3) var(--s-4);
  margin-bottom: var(--s-4);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-left: 3px solid var(--border-strong);
  border-radius: var(--r-md);
}
.vol-summary.is-bear { border-left-color: var(--neg); }
.vol-summary.is-bull { border-left-color: var(--pos); }
.vol-summary.is-mixed { border-left-color: var(--text-3); }
.vol-summary-head { display: flex; align-items: baseline; gap: var(--s-3); flex-wrap: wrap; }
.vol-summary-tone { font-weight: 700; font-size: 1.05em; letter-spacing: 0.01em; color: var(--text); }
.vol-summary.is-bear .vol-summary-tone { color: var(--neg); }
.vol-summary.is-bull .vol-summary-tone { color: var(--pos); }
.vol-summary-sub { color: var(--text-2); font-size: 0.9em; }
.vol-summary-bar {
  display: flex;
  height: 8px;
  border-radius: var(--r-pill);
  overflow: hidden;
  background: var(--surface-3);
}
.vol-summary-seg { display: block; height: 100%; }
.vol-summary-seg.bear { background: var(--neg); }
.vol-summary-seg.bull { background: var(--pos); }
.vol-summary-legend {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-3);
  align-items: baseline;
  font-size: 0.85em;
  color: var(--text-2);
}
.vol-summary-stat b { font-variant-numeric: tabular-nums; }
.vol-summary-stat.muted { color: var(--text-3); }
.vol-summary-legend .neg { color: var(--neg); }
.vol-summary-legend .pos { color: var(--pos); }
.vol-summary-tickers { color: var(--text-3); margin-left: auto; }

.vol-list {
  display: grid;
  gap: var(--s-3);
}
.vol-sector-group { display: grid; gap: var(--s-3); }
.vol-sector-group + .vol-sector-group { margin-top: var(--s-5); }
.vol-sector-head {
  display: flex;
  align-items: center;
  gap: var(--s-2);
  width: 100%;
  background: none;
  border: none;
  border-bottom: 1px solid var(--border);
  padding: 0 0 var(--s-2) 0;
  margin: 0;
  font: inherit;
  color: var(--text);
  text-align: left;
  cursor: pointer;
}
.vol-sector-head:hover { border-color: var(--border-strong); }
.vol-sector-head:focus-visible { outline: none; box-shadow: var(--focus-ring); border-radius: var(--r-sm); }
.vol-sector-caret { color: var(--text-3); font-size: 0.8em; width: 1em; flex: none; }
.vol-sector-name {
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  font-size: 0.9em;
}
.vol-sector-count {
  background: var(--surface-3);
  color: var(--text-2);
  border-radius: var(--r-pill);
  padding: 1px var(--s-2);
  font-size: 0.8em;
  font-variant-numeric: tabular-nums;
}
.vol-sector-bias { margin-left: auto; font-size: 0.82em; color: var(--text-3); }
.vol-sector-bias.pos { color: var(--pos); }
.vol-sector-bias.neg { color: var(--neg); }
.vol-sector-cards { display: grid; gap: var(--s-3); margin-top: var(--s-3); }
/* Pinned "★ Top Picks" group — the build's current picks, lifted above the
   sector groups and visually set apart with the accent. */
.vol-picks-group {
  background: var(--accent-tint-1);
  border: 1px solid var(--accent-line);
  border-radius: var(--r-md, 10px);
  padding: var(--s-3) var(--s-3) var(--s-2);
  margin-bottom: var(--s-4);
}
.vol-picks-group .vol-sector-head { border-bottom-color: var(--accent-line); }
.vol-picks-group .vol-sector-name { color: var(--accent-strong); }
/* Top-Picks side badge shown on each pinned card. */
.vol-pick-side { font-weight: 600; }
.vol-pick-call { background: var(--accent-soft); color: var(--accent-strong); border: 1px solid var(--accent-line); }
.vol-pick-put { background: color-mix(in srgb, var(--neg) 14%, transparent); color: var(--neg); border: 1px solid color-mix(in srgb, var(--neg) 35%, var(--border)); }
.vol-row {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: var(--s-3) var(--s-4);
  display: flex;
  flex-direction: column;
  gap: var(--s-2);
}
.vol-row:hover {
  background: color-mix(in srgb, var(--accent) 3%, var(--surface-2));
  border-color: var(--border-strong);
}
.vol-row-head {
  display: flex;
  align-items: baseline;
  gap: var(--s-3);
  flex-wrap: wrap;
  width: 100%;
  background: none;
  border: none;
  padding: 0;
  margin: 0;
  font: inherit;
  color: inherit;
  text-align: left;
  cursor: pointer;
}
.vol-row-head:focus-visible { outline: none; box-shadow: var(--focus-ring); border-radius: var(--r-sm); }
.vol-row-caret { color: var(--text-3); font-size: 0.8em; width: 1em; flex: none; align-self: center; }
.vol-symbol {
  font-weight: 600;
  font-size: 1.05em;
  letter-spacing: 0.02em;
  color: var(--text);
}
/* ↗ jump next to the symbol — opens the ticker in the Grade tab. A focusable
   span (not a button: it nests inside the row-head toggle button). */
.vol-sym-go { font: 600 10px/1 var(--font-sans); color: var(--muted); cursor: pointer; align-self: center; }
.vol-sym-go:hover, .vol-sym-go:focus-visible { color: var(--accent); outline: none; }
.vol-spot { color: var(--text-2); font-variant-numeric: tabular-nums; }
.vol-row-summary {
  display: flex;
  align-items: center;
  gap: var(--s-2);
  flex-wrap: wrap;
  margin-left: auto;
}
.vol-row-stats { color: var(--text-3); font-size: 0.85em; font-variant-numeric: tabular-nums; }
.vol-row-body {
  margin-top: var(--s-2);
  padding-top: var(--s-2);
  border-top: 1px solid var(--border);
}
.vol-row-meta { color: var(--text-3); font-size: 0.85em; margin-bottom: var(--s-2); }
.vol-avg20 { color: var(--text-3); font-size: 0.85em; margin-left: auto; }

/* Intraday volume-profile strip — a six-column micro bar chart (one per
   session hour bucket) shown on every collapsed card. Column height tracks
   that hour's volume ratio (relative to the card's peak), hue tracks the price
   direction that hour, and flagged / S-R / scan-missed hours read distinctly.
   Surfaces the SHAPE of the session's volume — front-loaded vs back-loaded vs
   steady — at a glance, without expanding the hour-by-hour breakdown. */
.vol-profile { display: flex; flex-direction: column; gap: 2px; margin-top: var(--s-1); }
.vol-profile-track { display: flex; align-items: flex-end; gap: 3px; height: 24px; }
.vol-profile-cell {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
  height: 100%;
  display: flex;
  align-items: flex-end;
  border-radius: var(--r-2, 3px);
  background: var(--surface-3);
}
.vol-profile-cell.is-empty { background: color-mix(in srgb, var(--border) 45%, transparent); }
.vol-profile-cell.is-missed {
  background: repeating-linear-gradient(45deg, var(--surface-3) 0, var(--surface-3) 3px, transparent 3px, transparent 6px);
}
.vol-profile-bar {
  width: 100%;
  min-height: 2px;
  border-radius: var(--r-2, 3px);
  background: var(--text-3);
}
.vol-profile-cell.is-up .vol-profile-bar { background: var(--pos); }
.vol-profile-cell.is-dn .vol-profile-bar { background: var(--neg); }
.vol-profile-cell.is-flat .vol-profile-bar { background: var(--text-3); }
/* Quiet (scanned but unflagged) hours are dimmed so the flagged hours read as
   the loud ones; flagged hours stay fully saturated. */
.vol-profile-cell.is-quiet .vol-profile-bar { opacity: 0.4; }
.vol-profile-cell.is-flagged .vol-profile-bar { opacity: 1; }
/* S/R break marker — a small triangle notch riding the column (up at the top
   for a resistance break, down at the base for a support break). */
.vol-profile-sr {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: 0; height: 0;
  border-left: 3px solid transparent;
  border-right: 3px solid transparent;
}
.vol-profile-sr-upper { top: -2px; border-bottom: 4px solid var(--pos); }
.vol-profile-sr-lower { bottom: -2px; border-top: 4px solid var(--neg); }
.vol-profile-axis {
  display: flex;
  justify-content: space-between;
  font-size: 0.6em;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-3);
  opacity: 0.75;
}

.vol-bucket {
  display: flex;
  flex-direction: column;
  gap: var(--s-2);
  padding: var(--s-2) 0;
  border-top: 1px dashed var(--border);
}
.vol-bucket:first-of-type { border-top: none; padding-top: 0; }
.vol-bucket-row {
  display: flex;
  align-items: baseline;
  gap: var(--s-3);
  flex-wrap: wrap;
  font-variant-numeric: tabular-nums;
}
.vol-bucket-label {
  font-weight: 500;
  color: var(--text);
  min-width: 8.5em;
}
.vol-bucket-vol { color: var(--text-2); font-size: 0.95em; }
.vol-bucket-vol.is-flagged {
  color: var(--text);
  font-weight: 500;
}
.vol-bucket-move { color: var(--text-2); font-size: 0.95em; }
.vol-bucket-move.is-up { color: var(--up); }
.vol-bucket-move.is-dn { color: var(--dn); }
.vol-why {
  font-size: 0.85em;
  line-height: 1.45;
  color: var(--text-3);
  max-width: 64ch;
}

.vol-badges {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-2);
}
.vol-pill-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px var(--s-2);
  border-radius: var(--r-pill);
  font-size: 0.82em;
  font-weight: 500;
  letter-spacing: 0.01em;
  background: var(--surface-3);
  color: var(--text-2);
  border: 1px solid var(--border);
}
.vol-pill-badge.vol-conv-very-high {
  background: color-mix(in srgb, var(--up) 18%, var(--surface-2));
  color: var(--up);
  border-color: color-mix(in srgb, var(--up) 45%, transparent);
}
.vol-pill-badge.vol-conv-high {
  background: color-mix(in srgb, var(--accent) 18%, var(--surface-2));
  color: var(--accent);
  border-color: color-mix(in srgb, var(--accent) 45%, transparent);
}
.vol-pill-badge.vol-conv-medium {
  background: color-mix(in srgb, var(--text-2) 12%, var(--surface-2));
  color: var(--text);
  border-color: var(--border-strong);
}
.vol-pill-badge.vol-conv-low {
  background: color-mix(in srgb, var(--dn) 18%, var(--surface-2));
  color: var(--dn);
  border-color: color-mix(in srgb, var(--dn) 45%, transparent);
}
.vol-pill-badge.vol-sr-lower.vol-conv-very-high {
  background: color-mix(in srgb, var(--dn) 18%, var(--surface-2));
  color: var(--dn);
  border-color: color-mix(in srgb, var(--dn) 45%, transparent);
}
.vol-pill-badge.vol-direction-up {
  background: var(--pos-soft);
  color: var(--pos);
  border-color: color-mix(in srgb, var(--pos) 45%, transparent);
}
.vol-pill-badge.vol-direction-dn {
  background: var(--neg-soft);
  color: var(--neg);
  border-color: color-mix(in srgb, var(--neg) 45%, transparent);
}
/* "Would you follow it?" verdict pill — follow (green/red by side),
   wait (amber), avoid (muted + dashed, like the scan-gap pills). */
.vol-pill-badge.vol-verdict { font-weight: 600; }
.vol-pill-badge.vol-verdict-follow.is-bull {
  background: var(--pos-soft);
  color: var(--pos);
  border-color: color-mix(in srgb, var(--pos) 55%, transparent);
}
.vol-pill-badge.vol-verdict-follow.is-bear {
  background: var(--neg-soft);
  color: var(--neg);
  border-color: color-mix(in srgb, var(--neg) 55%, transparent);
}
.vol-pill-badge.vol-verdict-wait {
  background: var(--warn-soft);
  color: var(--warn);
  border-color: color-mix(in srgb, var(--warn) 45%, transparent);
}
.vol-pill-badge.vol-verdict-avoid {
  background: color-mix(in srgb, var(--text-3) 14%, var(--surface-2));
  color: var(--text-2);
  border-style: dashed;
  border-color: var(--border-strong);
}
/* Expanded-body verdict row — the pill's reasoning in full. */
.vol-verdict-row {
  display: flex;
  flex-direction: column;
  gap: var(--s-1);
  padding: var(--s-2) var(--s-3);
  border-radius: var(--r-sm);
  border: 1px solid var(--border);
  border-left-width: 3px;
  background: var(--surface-2);
}
.vol-verdict-row.vol-verdict-follow.is-bull { border-left-color: var(--pos); }
.vol-verdict-row.vol-verdict-follow.is-bear { border-left-color: var(--neg); }
.vol-verdict-row.vol-verdict-wait { border-left-color: var(--warn); }
.vol-verdict-row.vol-verdict-avoid { border-left-color: var(--text-3); }
.vol-verdict-label { font-weight: 600; font-size: 0.92em; color: var(--text); }
.vol-verdict-row.vol-verdict-follow.is-bull .vol-verdict-label { color: var(--pos); }
.vol-verdict-row.vol-verdict-follow.is-bear .vol-verdict-label { color: var(--neg); }
.vol-verdict-row.vol-verdict-wait .vol-verdict-label { color: var(--warn); }
.vol-verdict-why {
  font-size: 0.85em;
  line-height: 1.45;
  color: var(--text-3);
  max-width: 64ch;
}
.vol-card .vol-key-up { color: var(--pos); font-weight: 500; }
.vol-card .vol-key-dn { color: var(--neg); font-weight: 500; }
.vol-bucket.is-scan-missed { opacity: 0.7; }
.vol-bucket-vol.is-muted {
  color: var(--text-3);
  font-style: italic;
}
.vol-pill-badge.vol-scan-missed,
.vol-pill-badge.vol-scan-gap {
  background: color-mix(in srgb, var(--text-3) 18%, var(--surface-2));
  color: var(--text-2);
  border-color: var(--border-strong);
  border-style: dashed;
}

.vol-eod {
  display: flex;
  gap: var(--s-3);
  align-items: baseline;
  flex-wrap: wrap;
  padding: var(--s-2) var(--s-3);
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-2));
  border: 1px solid color-mix(in srgb, var(--accent) 35%, transparent);
  border-radius: var(--r-sm);
  font-variant-numeric: tabular-nums;
}
.vol-eod-why {
  flex-basis: 100%;
  margin-top: var(--s-1);
  font-size: 0.85em;
  line-height: 1.45;
  color: var(--text-3);
  font-variant-numeric: normal;
}
.vol-eod-label {
  font-weight: 600;
  color: var(--accent);
  letter-spacing: 0.05em;
  font-size: 0.85em;
}
.vol-eod-vol { color: var(--text); }
.vol-eod-move.is-up { color: var(--up); }
.vol-eod-move.is-dn { color: var(--dn); }

.vol-empty {
  padding: var(--s-4);
  text-align: center;
  color: var(--muted);
}

/* ---- Strategies tab ----------------------------------------------------- */
.strat-card { padding: var(--s-4); }
.strat-section-title {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-strong);
  margin: 0;
}
.strat-leg-counter {
  color: var(--text-3);
  font-weight: 400;
  font-size: 0.9em;
}
.strat-controls {
  display: flex;
  gap: var(--s-3);
  align-items: center;
  margin-bottom: var(--s-3);
  flex-wrap: wrap;
}
.strat-controls .combo {
  flex: 1 1 280px;
  min-width: 0;
}
.strat-starter {
  margin: 0 0 var(--s-4);
  padding: var(--s-4);
  border: 1px solid color-mix(in srgb, var(--accent) 30%, var(--border));
  border-radius: var(--r-4);
  background: linear-gradient(145deg, color-mix(in srgb, var(--accent) 6%, var(--surface)), var(--surface) 58%);
}
.strat-starter[hidden] { display: none; }
.strat-starter-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--s-4);
  margin-bottom: var(--s-3);
}
.strat-starter-kicker {
  display: block;
  margin-bottom: 4px;
  color: var(--accent);
  font: 700 0.7rem/1.2 var(--font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.strat-starter-head h3 {
  margin: 0;
  color: var(--text-strong);
  font-size: var(--fs-lg);
}
.strat-starter-head p {
  max-width: 760px;
  margin: 6px 0 0;
  color: var(--text-2);
  font-size: var(--fs-sm);
  line-height: 1.5;
}
.strat-starter-step {
  flex: 0 0 auto;
  padding: 6px 9px;
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  background: var(--surface-2);
  color: var(--text-3);
  font: 650 0.68rem/1 var(--font-mono);
  white-space: nowrap;
}
.strat-start-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--s-2);
}
.strat-start-card {
  appearance: none;
  min-width: 0;
  min-height: 124px;
  padding: var(--s-3);
  border: 1px solid var(--border);
  border-top: 3px solid var(--border-strong);
  border-radius: var(--r-3);
  background: var(--surface);
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: transform 120ms, border-color 120ms, background 120ms;
}
.strat-start-card:hover {
  transform: translateY(-1px);
  border-color: var(--accent);
  background: var(--accent-tint-1);
}
.strat-start-card.is-selected {
  border-color: var(--accent);
  background: var(--accent-tint-1);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 28%, transparent);
}
.strat-start-card span,
.strat-start-card b,
.strat-start-card small { display: block; }
.strat-start-card span {
  margin-bottom: var(--s-3);
  color: var(--text-3);
  font: 700 0.68rem/1.2 var(--font-mono);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.strat-start-card b {
  color: var(--text-strong);
  font-size: 0.9rem;
  line-height: 1.25;
}
.strat-start-card small {
  margin-top: 5px;
  color: var(--text-3);
  font-size: 0.75rem;
  line-height: 1.3;
}
.strat-start-bull { border-top-color: var(--pos); }
.strat-start-bear { border-top-color: var(--neg); }
.strat-start-move { border-top-color: var(--accent); }
.strat-start-range { border-top-color: var(--warn); }
.strat-start-next {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  margin-top: var(--s-3);
  padding-top: var(--s-3);
  border-top: 1px solid var(--hairline);
}
.strat-start-next > div {
  display: flex;
  align-items: center;
  gap: var(--s-2);
}
.strat-start-next > div > span {
  color: var(--text-3);
  font: 650 0.72rem/1 var(--font-mono);
  white-space: nowrap;
}
.strat-quick-symbols { display: flex; flex-wrap: wrap; gap: 5px; }
.strat-quick-symbols button {
  appearance: none;
  min-height: 32px;
  padding: 5px 9px;
  border: 1px solid var(--border-strong);
  border-radius: var(--r-pill);
  background: var(--surface-2);
  color: var(--text-strong);
  font: 700 0.72rem/1 var(--font-mono);
  cursor: pointer;
}
.strat-quick-symbols button:hover {
  border-color: var(--accent);
  color: var(--accent);
}
.strat-start-next p {
  margin: 0;
  color: var(--text-2);
  font-size: var(--fs-xs);
  text-align: right;
}
.strat-start-rule {
  margin: var(--s-3) 0 0;
  color: var(--text-3);
  font-size: 0.74rem;
  line-height: 1.45;
}
.strat-start-rule b { color: var(--warn); }
.strat-btn-ghost {
  appearance: none;
  background: transparent;
  border: 1px solid var(--border-strong);
  color: var(--text-2);
  padding: var(--s-2) var(--s-3);
  border-radius: var(--r-pill);
  font-size: 0.85rem;
  cursor: pointer;
  transition: background 120ms, color 120ms, border-color 120ms;
}
.strat-btn-ghost:hover {
  border-color: var(--accent);
  color: var(--text-strong);
  background: var(--accent-tint-1);
}
.strat-ticker-meta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-3);
  padding: var(--s-2) var(--s-3);
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: var(--r-3);
  color: var(--text-2);
  font-size: 0.85rem;
  font-variant-numeric: tabular-nums;
  margin-bottom: var(--s-3);
}
.strat-meta-sym {
  color: var(--text-strong);
  font-weight: 600;
}
.strat-guidance { margin-bottom: var(--s-3); }
.strat-guide {
  display: flex;
  flex-direction: column;
  gap: var(--s-3);
  padding: var(--s-4);
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: var(--r-4);
  background: var(--surface-2);
}
.strat-guide-bull { border-left-color: var(--pos); }
.strat-guide-bear { border-left-color: var(--neg); }
.strat-guide-wait { border-left-color: var(--warn); }
.strat-guide-avoid { border-left-color: var(--neg); }
.strat-guide-kicker,
.strat-guide-grid small,
.strat-guide-start small,
.strat-verdict-head > span,
.strat-verdict-grid small {
  display: block;
  font-size: var(--fs-2xs);
  font-weight: 700;
  color: var(--muted);
  letter-spacing: var(--ls-caps);
  text-transform: uppercase;
}
.strat-guide-head h3 {
  margin: 4px 0 5px;
  font-size: var(--fs-xl);
  line-height: var(--lh-tight);
}
.strat-guide-head p {
  max-width: 80ch;
  margin: 0;
  color: var(--muted);
  font-size: var(--fs-sm);
  line-height: var(--lh-snug);
}
.strat-guide-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--s-2);
}
.strat-guide-grid > span {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  padding: var(--s-2) var(--s-3);
  border: 1px solid var(--border);
  border-top: 2px solid var(--accent);
  border-radius: var(--r-3);
  background: var(--surface-1);
}
.strat-guide-bull .strat-guide-grid > span:first-child { border-top-color: var(--pos); }
.strat-guide-bear .strat-guide-grid > span:first-child { border-top-color: var(--neg); }
.strat-guide-grid > span.is-risk { border-top-color: var(--neg); }
.strat-guide-timing-ready { border-top-color: var(--pos) !important; }
.strat-guide-timing-watch,
.strat-guide-timing-wait { border-top-color: var(--warn) !important; }
.strat-guide-timing-avoid { border-top-color: var(--neg) !important; }
.strat-guide-grid b { font-size: var(--fs-sm); color: var(--text); }
.strat-guide-grid em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--fs-2xs);
  color: var(--muted);
}
.strat-guide-start {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  padding: var(--s-3);
  border: 1px solid var(--border);
  border-radius: var(--r-3);
  background: color-mix(in srgb, var(--surface-3) 70%, transparent);
}
.strat-guide-start > span { display: flex; flex-direction: column; gap: 2px; }
.strat-guide-start > span b { font-size: var(--fs-xs); color: var(--text); }
.strat-guide-start > div { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: var(--s-2); }
.strat-rec {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 144px;
  padding: var(--s-2) var(--s-3);
  border: 1px solid var(--accent);
  border-radius: var(--r-3);
  background: var(--accent-tint-1);
  color: var(--text);
  text-align: left;
  cursor: pointer;
}
.strat-rec:hover { background: var(--accent-tint-2); }
.strat-rec span { font-size: var(--fs-sm); font-weight: 700; }
.strat-rec small { color: var(--muted); font-size: var(--fs-2xs); }
.strat-guide-avoid {
  margin: 0;
  color: var(--muted);
  font-size: var(--fs-xs);
  line-height: var(--lh-snug);
}
.strat-guide-avoid b { color: var(--warn); }
.strat-disclosure {
  overflow: clip;
  border: 1px solid var(--border);
  border-radius: var(--r-3);
  background: var(--surface-2);
}
.strat-disclosure > summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto 14px;
  gap: var(--s-3);
  align-items: center;
  min-height: 48px;
  padding: var(--s-2) var(--s-3);
  list-style: none;
  cursor: pointer;
}
.strat-disclosure > summary::-webkit-details-marker { display: none; }
.strat-disclosure > summary:hover { background: color-mix(in srgb, var(--surface-3) 64%, transparent); }
.strat-disclosure-summary > span { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.strat-disclosure-summary b { font-size: var(--fs-sm); color: var(--text); }
.strat-disclosure-summary small { font-size: var(--fs-2xs); color: var(--muted); }
.strat-disclosure-summary em {
  font: 400 var(--fs-2xs)/1.2 var(--font-mono);
  color: var(--muted);
}
.strat-chevron {
  display: block;
  width: 7px;
  height: 7px;
  border-right: 1.5px solid var(--muted);
  border-bottom: 1.5px solid var(--muted);
  transform: rotate(45deg) translate(-1px, -1px);
  transition: transform .15s ease;
}
.strat-disclosure[open] > summary .strat-chevron { transform: rotate(225deg) translate(-1px, -1px); }
.strat-disclosure-body { padding: var(--s-3); border-top: 1px solid var(--border); }

/* --- Templates gallery ---- */
.strat-templates {
  margin-bottom: var(--s-3);
}
.strat-tpl-groups {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--s-3);
  margin-top: var(--s-2);
}
.strat-tpl-group {
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: var(--r-4);
  padding: var(--s-3);
}
.strat-tpl-group-head {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  margin-bottom: var(--s-2);
}
.strat-tpl-chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-2);
}
.strat-tpl-chip {
  appearance: none;
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: var(--r-3);
  padding: var(--s-2) var(--s-3);
  cursor: pointer;
  text-align: left;
  min-width: 120px;
  transition: background 120ms, border-color 120ms, transform 80ms;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.strat-tpl-chip:hover {
  border-color: var(--accent);
  background: var(--accent-tint-1);
}
.strat-tpl-chip:active { transform: translateY(1px); }
.strat-tpl-chip.is-on {
  border-color: var(--accent);
  background: var(--accent-tint-2);
  box-shadow: 0 0 0 1px var(--accent-glow-soft) inset;
}
.strat-tpl-chip-name {
  color: var(--text-strong);
  font-weight: 600;
  font-size: 0.9rem;
}
.strat-tpl-chip-label {
  color: var(--text-3);
  font-size: 0.78rem;
}
.strat-tpl-foot {
  color: var(--text-3);
  font-size: 0.78rem;
  margin: var(--s-3) 0 0;
}

/* --- Legs panel ---- */
.strat-legs { margin-top: var(--s-3); }
.strat-legs-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--s-2);
}
.strat-legs-actions { display: flex; gap: var(--s-2); }
.strat-legs-body > .strat-legs-actions { justify-content: flex-end; margin-bottom: var(--s-2); }
.strat-legs-list {
  display: flex;
  flex-direction: column;
  gap: var(--s-2);
}
.strat-legs-foot {
  color: var(--text-3);
  font-size: 0.78rem;
  margin: var(--s-2) 0 0;
}
.strat-legs-foot b { color: var(--text-2); font-weight: 600; }
.strat-legs-empty {
  padding: var(--s-4);
  text-align: center;
  color: var(--text-3);
  background: var(--surface-2);
  border: 1px dashed var(--border-strong);
  border-radius: var(--r-3);
}
.strat-leg {
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-left: 3px solid var(--border-strong);
  border-radius: var(--r-3);
  padding: var(--s-3);
  transition: border-color 120ms;
}
.strat-leg.is-buy  { border-left-color: var(--pos); }
.strat-leg.is-sell { border-left-color: var(--neg); }
.strat-leg-grid {
  display: grid;
  grid-template-columns: auto auto minmax(120px, 1.3fr) minmax(92px, 1fr) 62px 82px auto;
  gap: var(--s-2);
  align-items: end;
}
.strat-leg-toggle {
  display: inline-flex;
  background: var(--surface-3);
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  padding: 2px;
}
.strat-leg-toggle button {
  appearance: none;
  background: transparent;
  border: none;
  color: var(--text-2);
  padding: 6px 12px;
  font-size: 0.82rem;
  cursor: pointer;
  border-radius: var(--r-pill);
  font-weight: 500;
  transition: background 120ms, color 120ms;
}
.strat-leg-toggle button:hover { color: var(--text-strong); }
.strat-leg-side button.is-on[data-leg-val="buy"]  { background: var(--pos); color: #06231a; }
.strat-leg-side button.is-on[data-leg-val="sell"] { background: var(--neg); color: #fff; }
.strat-leg-type button.is-on { background: var(--accent); color: var(--accent-fg); }
.strat-leg-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.strat-leg-flabel {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
}
.strat-leg-field select,
.strat-leg-field input {
  appearance: none;
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: var(--r-2);
  color: var(--text);
  padding: 6px 8px;
  font-size: 0.88rem;
  font-variant-numeric: tabular-nums;
  width: 100%;
}
.strat-leg-field select:focus,
.strat-leg-field input:focus {
  outline: none;
  border-color: var(--accent);
}
.strat-leg-qty input { text-align: right; }
.strat-leg-price input { text-align: right; }
.strat-leg-price input::placeholder { color: var(--text-3); opacity: 0.7; }
.strat-leg-price input.is-manual {
  border-color: var(--accent);
  color: var(--text-strong);
  font-weight: 600;
}
.strat-leg-remove {
  appearance: none;
  background: transparent;
  border: 1px solid var(--border-strong);
  color: var(--text-3);
  width: 32px;
  height: 32px;
  border-radius: var(--r-2);
  font-size: 1.1rem;
  cursor: pointer;
  align-self: end;
  transition: background 120ms, color 120ms, border-color 120ms;
}
.strat-leg-remove:hover {
  background: var(--neg-tint);
  border-color: var(--neg);
  color: var(--neg);
}
.strat-leg-detail {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-3);
  margin-top: var(--s-2);
  padding-top: var(--s-2);
  border-top: 1px dashed var(--hairline);
  color: var(--text-3);
  font-size: 0.8rem;
  font-variant-numeric: tabular-nums;
  align-items: center;
}
.strat-leg-detail b { color: var(--text); font-weight: 600; }
.strat-leg-cost { margin-left: auto; font-weight: 600; }
.strat-leg-cost.is-debit  { color: var(--neg); }
.strat-leg-cost.is-credit { color: var(--pos); }
.strat-leg-manual { color: var(--accent); font-weight: 600; }
.strat-leg-detail-note { color: var(--muted); }
.strat-leg-dte {
  color: var(--muted);
  background: var(--surface-3);
  padding: 2px 8px;
  border-radius: var(--r-pill);
  font-size: 0.72rem;
}
.strat-leg-warn {
  color: var(--warn);
}

@media (max-width: 900px) {
  /* 3 rows: toggles + remove · expiry + strike · qty + price */
  .strat-leg-grid {
    grid-template-columns: 1fr 1fr 64px 84px;
  }
  .strat-leg-side   { grid-row: 1; grid-column: 1; }
  .strat-leg-type   { grid-row: 1; grid-column: 2; }
  .strat-leg-remove { grid-row: 1; grid-column: 4; justify-self: end; }
  .strat-leg-field:nth-of-type(1) { grid-row: 2; grid-column: 1 / 3; } /* Expiry */
  .strat-leg-field:nth-of-type(2) { grid-row: 2; grid-column: 3 / 5; } /* Strike */
  .strat-leg-qty    { grid-row: 3; grid-column: 1; }
  .strat-leg-price  { grid-row: 3; grid-column: 2; }
}
@media (max-width: 560px) {
  /* Single stack, two-up where it reads well (toggles, then qty + price) */
  .strat-leg-grid {
    grid-template-columns: 1fr 1fr;
  }
  .strat-leg-side   { grid-row: auto; grid-column: 1; }
  .strat-leg-type   { grid-row: auto; grid-column: 2; justify-self: start; }
  .strat-leg-field:nth-of-type(1) { grid-row: auto; grid-column: 1 / -1; } /* Expiry */
  .strat-leg-field:nth-of-type(2) { grid-row: auto; grid-column: 1 / -1; } /* Strike */
  .strat-leg-qty    { grid-row: auto; grid-column: 1; }
  .strat-leg-price  { grid-row: auto; grid-column: 2; }
  .strat-leg-remove { grid-row: auto; grid-column: 1 / -1; justify-self: end; }
}

/* --- Results panel ---- */
.strat-results {
  margin-top: var(--s-3);
}
.strat-results-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--s-3);
  margin-bottom: var(--s-3);
}
.strat-results-head-left {
  display: flex;
  align-items: center;
  gap: var(--s-3);
}
.strat-bias {
  font-size: 0.78rem;
  padding: 2px 10px;
  border-radius: var(--r-pill);
  background: var(--surface-3);
  color: var(--text-2);
  border: 1px solid var(--border-strong);
}
.strat-score-wrap {
  display: flex;
  align-items: center;
  gap: var(--s-2);
}
.strat-score-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
}
.strat-score-chip {
  font-size: 1rem;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: var(--r-3);
  border: 1px solid var(--border-strong);
  background: var(--surface-3);
  color: var(--text-strong);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
}
.strat-score-chip.strat-grade-aplus,
.strat-score-chip.strat-grade-a {
  background: var(--pos-soft);
  border-color: var(--pos);
  color: var(--pos);
}
.strat-score-chip.strat-grade-b {
  background: var(--accent-tint-1);
  border-color: var(--accent);
  color: var(--accent);
}
.strat-score-chip.strat-grade-c {
  background: var(--warn-tint);
  border-color: var(--warn);
  color: var(--warn);
}
.strat-score-chip.strat-grade-d {
  background: var(--neg-tint);
  border-color: var(--neg);
  color: var(--neg);
}
.strat-verdict { margin-bottom: var(--s-3); }
.strat-verdict-card {
  display: flex;
  flex-direction: column;
  gap: var(--s-3);
  padding: var(--s-3);
  border: 1px solid var(--border);
  border-left: 3px solid var(--warn);
  border-radius: var(--r-3);
  background: var(--surface-2);
}
.strat-verdict-ready { border-left-color: var(--pos); }
.strat-verdict-wait { border-left-color: var(--warn); }
.strat-verdict-pass { border-left-color: var(--neg); }
.strat-verdict-head h4 {
  margin: 3px 0 4px;
  font-size: var(--fs-lg);
  line-height: var(--lh-tight);
  color: var(--text);
}
.strat-verdict-head p {
  margin: 0;
  color: var(--muted);
  font-size: var(--fs-xs);
  line-height: var(--lh-snug);
}
.strat-verdict-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--s-2);
}
.strat-verdict-grid > span {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  padding: var(--s-2) var(--s-3);
  border: 1px solid var(--border);
  border-radius: var(--r-3);
  background: var(--surface-1);
}
.strat-verdict-grid b {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: var(--fs-md);
  color: var(--text);
}
.strat-verdict-timing-ready b { color: var(--pos); }
.strat-verdict-timing-watch b,
.strat-verdict-timing-wait b { color: var(--warn); }
.strat-verdict-timing-avoid b { color: var(--neg); }
.strat-risk-controls {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-3);
  align-items: end;
}
.strat-risk-controls label {
  display: flex;
  align-items: center;
  gap: var(--s-2);
  font-size: var(--fs-xs);
  color: var(--muted);
}
.strat-risk-controls input {
  width: 96px;
  padding: 6px 8px;
  border: 1px solid var(--border-strong);
  border-radius: var(--r-2);
  background: var(--surface-1);
  color: var(--text);
  font-family: var(--font-mono);
}
.strat-risk-controls label:last-child input { width: 64px; }
.strat-verdict-note {
  margin: 0;
  padding-top: var(--s-2);
  border-top: 1px solid var(--border);
  color: var(--muted);
  font-size: var(--fs-2xs);
  line-height: var(--lh-snug);
}
.strat-verdict-note b { color: var(--text); }
.strat-verdict-note.is-risk b { color: var(--neg); }

.strat-summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: var(--s-2);
  margin-bottom: var(--s-3);
}
.strat-analysis { margin-top: var(--s-3); }
.strat-summary-cell {
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: var(--r-3);
  padding: var(--s-2) var(--s-3);
}
.strat-summary-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  margin-bottom: 4px;
}
.strat-summary-val {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-strong);
  font-variant-numeric: tabular-nums;
}
.strat-summary-val.is-debit { color: var(--neg); }
.strat-summary-val.is-credit { color: var(--pos); }
.strat-summary-val.is-profit { color: var(--pos); }
.strat-summary-val.is-loss { color: var(--neg); }
.strat-summary-unlim {
  font-style: italic;
  color: var(--pos);
}
.strat-summary-unlim.is-loss { color: var(--neg); }

.strat-results-body {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
  gap: var(--s-4);
}
@media (max-width: 860px) {
  .strat-results-body { grid-template-columns: 1fr; }
}

.strat-payoff-wrap {
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: var(--r-3);
  padding: var(--s-3);
}
.strat-payoff-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: var(--s-2);
}
.strat-payoff-title {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text);
}
.strat-payoff-axis { color: var(--text-3); font-size: 0.78rem; }
.strat-payoff-svg { width: 100%; height: auto; display: block; }
.strat-payoff-zero {
  stroke: var(--border-strong);
  stroke-width: 1;
  stroke-dasharray: 3 3;
}
.strat-payoff-area-profit { fill: var(--pos-soft); }
.strat-payoff-area-loss   { fill: var(--neg-soft); }
.strat-payoff-line {
  stroke: var(--accent);
  stroke-width: 2;
  fill: none;
}
.strat-payoff-spot {
  stroke: var(--text-2);
  stroke-width: 1;
  stroke-dasharray: 2 4;
  opacity: 0.7;
}
.strat-payoff-spot-lbl { fill: var(--text-2); }
.strat-payoff-be {
  stroke: var(--accent);
  stroke-width: 1;
  stroke-dasharray: 4 3;
  opacity: 0.5;
}
.strat-payoff-axislbl {
  fill: var(--text-3);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}

.strat-greeks-wrap {
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: var(--r-3);
  padding: var(--s-3);
}
.strat-greeks-title {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: var(--s-2);
}
.strat-greeks {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--s-2);
}
.strat-greek-cell {
  background: var(--surface-3);
  border: 1px solid var(--hairline);
  border-radius: var(--r-2);
  padding: var(--s-2);
}
.strat-greek-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
}
.strat-greek-val {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-strong);
  font-variant-numeric: tabular-nums;
  margin-top: 2px;
}

.strat-score-explain {
  margin-top: var(--s-3);
  padding-top: var(--s-2);
  border-top: 1px dashed var(--hairline);
}
.strat-score-parts {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--s-2);
}
.strat-score-parts li {
  display: grid;
  grid-template-columns: 110px 1fr auto;
  gap: var(--s-2);
  align-items: center;
  font-size: 0.78rem;
}
.strat-score-part-label { color: var(--text-2); }
.strat-score-part-bar {
  background: var(--surface-3);
  height: 6px;
  border-radius: var(--r-pill);
  overflow: hidden;
  border: 1px solid var(--hairline);
}
.strat-score-part-bar span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--accent-strong));
}
.strat-score-part-val {
  color: var(--text-3);
  font-variant-numeric: tabular-nums;
  font-size: 0.78rem;
}
.strat-score-part-note {
  grid-column: 1 / -1;
  color: var(--text-3);
  font-size: 0.74rem;
  margin-top: 2px;
}

.strat-foot {
  margin-top: var(--s-3);
  color: var(--text-3);
  font-size: 0.78rem;
}
@media (max-width: 720px) {
  .strat-card { padding: var(--s-3); }
  .strat-starter { padding: var(--s-3); }
  .strat-starter-head { flex-direction: column; gap: var(--s-2); }
  .strat-start-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .strat-start-next { align-items: flex-start; flex-direction: column; }
  .strat-start-next p { text-align: left; }
  .strat-guide { padding: var(--s-3); }
  .strat-guide-head h3 { font-size: var(--fs-lg); }
  .strat-guide-head p { font-size: var(--fs-xs); }
  .strat-guide-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 5px; }
  .strat-guide-grid > span { padding: 7px; }
  .strat-guide-grid b { font-size: var(--fs-xs); line-height: var(--lh-tight); }
  .strat-guide-grid em { display: none; }
  .strat-guide-start { align-items: stretch; flex-direction: column; padding: var(--s-2); }
  .strat-guide-start > div { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .strat-rec { min-width: 0; padding: 7px; }
  .strat-rec span { font-size: var(--fs-xs); }
  .strat-disclosure > summary {
    grid-template-columns: minmax(0, 1fr) 14px;
    gap: 3px var(--s-2);
  }
  .strat-disclosure-summary > em { grid-column: 1; grid-row: 2; }
  .strat-disclosure-summary .strat-chevron { grid-column: 2; grid-row: 1 / 3; }
  .strat-results-head { align-items: flex-start; }
  .strat-results-head-left { flex-direction: column; align-items: flex-start; gap: 5px; }
  .strat-verdict-card { padding: var(--s-2); }
  .strat-verdict-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 5px; }
  .strat-verdict-grid > span { padding: 7px; }
  .strat-verdict-grid b { font-size: var(--fs-xs); overflow: visible; white-space: normal; }
  .strat-risk-controls { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--s-2); }
  .strat-risk-controls label { flex-direction: column; align-items: flex-start; gap: 4px; }
  .strat-risk-controls input,
  .strat-risk-controls label:last-child input { width: 100%; }
  .strat-summary-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .strat-summary-cell { padding: var(--s-2); }
}
@media (max-width: 480px) {
  .strat-starter { padding: var(--s-2); }
  .strat-start-card { min-height: 140px; padding: var(--s-2); }
  .strat-start-card span { margin-bottom: var(--s-2); }
  .strat-quick-symbols button { min-height: 40px; padding-inline: 11px; }
}

/* ---------------- Heatmap (Finviz-style market map) ----------------------
   Treemap rendered as absolutely-positioned tiles inside .heatmap-root.
   The layout JS sets each tile's --x/--y/--w/--h custom props as
   percentages; CSS just turns them into left/top/width/height. Color is
   driven by --hm-c (a 0..1 number where 0 = max-red, 0.5 = neutral, 1 =
   max-green) via a divergent red→gray→green gradient blend. */
.heatmap-decision {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(0, .92fr);
  gap: 10px;
  margin: 0 0 12px;
  padding: 13px;
  border: 1px solid color-mix(in srgb, var(--info) 34%, var(--border));
  border-left: 3px solid var(--info);
  border-radius: 11px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--info) 5%, var(--surface)), var(--surface) 55%);
  min-width: 0;
}
.heatmap-decision:empty { display: none; }
.heatmap-decision-risk-on { border-color: color-mix(in srgb, var(--pos) 38%, var(--border)); border-left-color: var(--pos); background: linear-gradient(135deg, color-mix(in srgb, var(--pos) 5%, var(--surface)), var(--surface) 55%); }
.heatmap-decision-risk-off { border-color: color-mix(in srgb, var(--neg) 38%, var(--border)); border-left-color: var(--neg); background: linear-gradient(135deg, color-mix(in srgb, var(--neg) 5%, var(--surface)), var(--surface) 55%); }
.heatmap-decision-narrow { border-color: color-mix(in srgb, var(--warn) 38%, var(--border)); border-left-color: var(--warn); background: linear-gradient(135deg, color-mix(in srgb, var(--warn) 5%, var(--surface)), var(--surface) 55%); }
.heatmap-decision-stale { border-color: color-mix(in srgb, var(--warn) 45%, var(--border)); border-left-color: var(--warn); background: linear-gradient(135deg, color-mix(in srgb, var(--warn) 7%, var(--surface)), var(--surface) 55%); }
.heatmap-decision-empty { grid-template-columns: minmax(0, 1fr); border-style: dashed; }
.heatmap-decision-empty b { color: var(--text-strong); font: 700 12px/1.3 var(--font-sans); }
.heatmap-decision-empty span { color: var(--muted-strong); font: 400 11px/1.4 var(--font-sans); }
.heatmap-decision-read,
.heatmap-decision-side { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.heatmap-decision-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; min-width: 0; }
.heatmap-decision-head > span { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.heatmap-decision-head small,
.heatmap-decision-metrics small,
.heatmap-decision-rules small {
  color: var(--muted);
  font: 700 8.5px/1.1 var(--font-mono);
  letter-spacing: .065em;
  text-transform: uppercase;
}
.heatmap-decision-head b { color: var(--text-strong); font: 780 18px/1.15 var(--font-sans); }
.heatmap-decision-head em { flex: 0 0 auto; padding: 4px 7px; border-radius: var(--r-pill); background: var(--surface-2); color: var(--muted-strong); font: 650 8.5px/1 var(--font-mono); font-style: normal; text-transform: uppercase; letter-spacing: .04em; }
.heatmap-decision-stale .heatmap-decision-head em { color: var(--warn); background: var(--warn-soft); }
.heatmap-decision-read h3 { margin: 0; color: var(--text); font: 700 12.5px/1.35 var(--font-sans); }
.heatmap-decision-read > p { margin: 0; color: var(--muted-strong); font: 400 11px/1.45 var(--font-sans); }
.heatmap-decision-rules { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; margin-top: auto; }
.heatmap-decision-rules > span { display: flex; flex-direction: column; gap: 4px; min-width: 0; padding: 7px 8px; border: 1px solid var(--border); border-radius: 7px; background: color-mix(in srgb, var(--surface-2) 78%, transparent); }
.heatmap-decision-rules b { color: var(--text); font: 570 10px/1.35 var(--font-sans); }
.heatmap-decision-metrics { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; }
.heatmap-decision-metrics > div { display: flex; flex-direction: column; gap: 3px; min-width: 0; padding: 7px 8px; border: 1px solid var(--border); border-radius: 7px; background: var(--surface-2); }
.heatmap-decision-metrics b { color: var(--text-strong); font: 730 12px/1.15 var(--font-mono); font-variant-numeric: tabular-nums; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.heatmap-decision-metrics b.pos { color: var(--pos); }
.heatmap-decision-metrics b.neg { color: var(--neg); }
.heatmap-decision-metrics b.zero { color: var(--muted-strong); }
.heatmap-decision-metrics span { color: var(--muted); font: 520 9px/1.25 var(--font-sans); overflow-wrap: anywhere; }
.heatmap-decision-actions { display: flex; flex-wrap: wrap; gap: 6px; margin-top: auto; }
.heatmap-decision-actions button { appearance: none; min-height: 34px; flex: 1 1 145px; padding: 7px 9px; border: 1px solid var(--border-strong); border-radius: 7px; background: var(--surface); color: var(--text); font: 700 10px/1.2 var(--font-sans); cursor: pointer; }
.heatmap-decision-actions button:first-child { border-color: color-mix(in srgb, var(--accent) 46%, var(--border)); background: var(--accent-soft); color: var(--accent); }
.heatmap-decision-actions button:hover { border-color: var(--accent); color: var(--accent); }
@media (max-width: 760px) {
  .heatmap-decision { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 480px) {
  .heatmap-decision { padding: 10px; }
  .heatmap-decision-head { flex-direction: column; }
  .heatmap-decision-rules { grid-template-columns: minmax(0, 1fr); }
  .heatmap-decision-actions button { min-height: 42px; flex-basis: 100%; }
}
.heatmap-controls {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 8px;
  align-items: end;
  margin: 0 0 12px;
}
.heatmap-control {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 5px;
  min-width: 0;
  font-size: 0.85rem;
  color: var(--muted-strong);
}
.heatmap-group-control { grid-column: span 2; }
.heatmap-color-control { grid-column: span 2; }
.heatmap-search-control { grid-column: span 3; }
.heatmap-live-toggle { grid-column: span 2; }
.heatmap-zoom { grid-column: span 3; }
.heatmap-control-label {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
}
.heatmap-control select {
  width: 100%;
  min-height: 40px;
  background: var(--surface-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  padding: 6px 10px;
  font: inherit;
}
.heatmap-live-toggle {
  min-height: 40px;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  user-select: none;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-2);
}
.heatmap-live-toggle input { accent-color: var(--accent); }
.heatmap-live-state {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
  grid-column: 1 / -1;
  justify-self: end;
}
.heatmap-live-state.is-live { color: var(--accent); }
.heatmap-live-state.is-error { color: var(--neg); }

.heatmap-zoom {
  min-height: 40px;
  flex-direction: row;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
}
.heatmap-zoom-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 26px;
  height: 26px;
  padding: 0 8px;
  background: var(--surface-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  font: 700 13px/1 var(--font-mono);
  cursor: pointer;
}
.heatmap-zoom-btn:hover:not(:disabled) { border-color: var(--accent); }
.heatmap-zoom-btn:disabled { opacity: 0.4; cursor: default; }
.heatmap-zoom-reset { font-size: 10px; text-transform: uppercase; letter-spacing: .08em; }
.heatmap-zoom-level {
  min-width: 40px;
  text-align: center;
  font: 600 12px/1 var(--font-mono);
  color: var(--muted-strong);
}

.heatmap-search-input {
  background: var(--surface-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  padding: 6px 10px;
  font: inherit;
  width: 100%;
  min-width: 0;
  min-height: 40px;
}
.heatmap-search-input:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: var(--focus-ring);
}

/* Advancers / decliners ribbon between the controls and the map. */
/* Persistent breadth-participation alert. This is deliberately distinct from
   the Owner Sector Rotation rebound model and never implies ETF/fund flow. */
.heatmap-streaks {
  display: grid;
  gap: 9px;
  margin: 0 0 12px;
  padding: 12px 13px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent) 7%, var(--surface-2));
}
.heatmap-streaks[hidden] { display: none; }
.heatmap-streak-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px 12px;
}
.heatmap-streak-head {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
}
.heatmap-streak-icon { color: var(--accent); font: 800 1rem/1 var(--font-mono); }
.heatmap-streak-title {
  font: 700 0.82rem/1 var(--font-sans);
  color: var(--text-strong);
  letter-spacing: 0.01em;
}
.heatmap-streak-sub {
  font: 500 0.7rem/1 var(--font-mono);
  color: var(--muted);
}
.heatmap-streak-scope {
  flex: 0 0 auto;
  padding: 4px 7px;
  border-radius: var(--r-pill);
  color: var(--muted);
  background: var(--surface);
  font: 700 8.5px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .06em;
  white-space: nowrap;
}
.heatmap-streak-read { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 8px; }
.heatmap-streak-read b { color: var(--text-strong); font: 700 12px/1.3 var(--font-sans); }
.heatmap-streak-read span { color: var(--text); font: 400 11.5px/1.4 var(--font-sans); }
.heatmap-streak-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.heatmap-streak-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 9px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  font: 600 0.74rem/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  cursor: default;
}
.heatmap-streak-chip.is-green {
  border-color: color-mix(in srgb, var(--up) 45%, var(--border));
  background: color-mix(in srgb, var(--up) 12%, var(--surface-2));
}
.heatmap-streak-chip.is-red {
  border-color: color-mix(in srgb, var(--dn) 45%, var(--border));
  background: color-mix(in srgb, var(--dn) 12%, var(--surface-2));
}
.heatmap-streak-chip.is-green .heatmap-streak-arrow { color: var(--up); }
.heatmap-streak-chip.is-red .heatmap-streak-arrow { color: var(--dn); }
.heatmap-streak-sector { color: var(--text-strong); font-weight: 700; }
.heatmap-streak-detail { color: var(--muted-strong); }
@media (max-width: 640px) {
  .heatmap-streak-top { align-items: flex-start; }
  .heatmap-streak-head { flex-wrap: wrap; row-gap: 4px; }
  .heatmap-streak-sub { flex-basis: 100%; padding-left: 22px; }
  .heatmap-streak-scope { font-size: 7.5px; }
  .heatmap-streak-list { display: grid; grid-template-columns: minmax(0, 1fr); }
  .heatmap-streak-chip { white-space: normal; line-height: 1.25; }
}

.heatmap-breadth {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 14px;
  margin: 0 0 10px;
}
.heatmap-breadth:empty { display: none; }
.heatmap-breadth-bar {
  display: flex;
  flex: 1 1 220px;
  height: 8px;
  min-width: 180px;
  border-radius: 999px;
  overflow: hidden;
  border: 1px solid var(--border);
  background: var(--surface-2);
}
.heatmap-breadth-seg { height: 100%; display: block; }
.heatmap-breadth-seg.pos { background: var(--pos); }
.heatmap-breadth-seg.neg { background: var(--neg); }
.heatmap-breadth-seg.flat { background: var(--surface-3); }
.heatmap-breadth-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  font: 600 0.72rem/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--muted-strong);
}
.heatmap-breadth-stat.pos { color: var(--pos); }
.heatmap-breadth-stat.neg { color: var(--neg); }
.heatmap-breadth-stat.flat { color: var(--muted); }
.heatmap-breadth-stat.zero { color: var(--muted); }

.heatmap-root {
  position: relative;
  width: 100%;
  height: 78vh;
  min-height: 520px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  overflow: hidden;
}
.heatmap-root.is-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--muted);
  font-size: 0.85rem;
  padding: var(--s-3);
  text-align: center;
}
/* Zoom/pan target. Sized to zoom*100% of the root (so tiles laid out as % of
   the canvas grow with zoom) and offset by a translate for panning — both set
   inline by applyHeatmapView(). Not CSS-scaled, so text stays crisp. */
.heatmap-canvas {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  will-change: transform;
}
.heatmap-root.is-zoomed { cursor: grab; }
.heatmap-root.is-panning { cursor: grabbing; }
.heatmap-root.is-panning .heatmap-canvas { transition: none; }

.heatmap-sector {
  position: absolute;
  left: calc(var(--x, 0) * 1%);
  top: calc(var(--y, 0) * 1%);
  width: calc(var(--w, 0) * 1%);
  height: calc(var(--h, 0) * 1%);
  border: 1px solid var(--surface-3);
  background: var(--surface);
  box-sizing: border-box;
}
.heatmap-sector-label {
  position: absolute;
  top: 1px;
  left: 4px;
  right: 4px;
  font: 600 11px/1.2 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted-strong);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  pointer-events: none;
}

.heatmap-tile {
  position: absolute;
  left: calc(var(--x, 0) * 1%);
  top: calc(var(--y, 0) * 1%);
  width: calc(var(--w, 0) * 1%);
  height: calc(var(--h, 0) * 1%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  padding: 2px;
  border: 1px solid rgba(0, 0, 0, 0.35);
  background: var(--hm-bg, var(--surface-2));
  color: var(--hm-fg, #fff);
  font: 700 13px/1 var(--font-mono);
  letter-spacing: .02em;
  cursor: pointer;
  overflow: hidden;
  box-sizing: border-box;
  transition: filter 120ms ease, transform 120ms ease;
}
.heatmap-tile:hover {
  filter: brightness(1.12);
  z-index: 2;
}
.heatmap-tile:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
  z-index: 3;
}
.heatmap-tile-sym {
  font: 700 var(--hm-sym-size, 14px)/1 var(--font-mono);
  letter-spacing: .02em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}
.heatmap-tile-pct {
  font: 500 var(--hm-pct-size, 11px)/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
  opacity: .92;
  white-space: nowrap;
  overflow: hidden;
}
/* Hide the % line on tiny tiles where it'd just be visual noise. */
.heatmap-tile.is-tiny .heatmap-tile-pct { display: none; }
.heatmap-tile.is-tiny .heatmap-tile-sym { font-size: 11px; }
/* Micro tiles are too small (<16px tall or <22px wide) to render any text
   legibly — a 10px symbol in a 6px box just looks like a graphical glitch.
   Drop to a bare colored square. */
.heatmap-tile.is-micro .heatmap-tile-sym,
.heatmap-tile.is-micro .heatmap-tile-pct { display: none; }
.heatmap-tile.is-micro { padding: 0; }

/* Divergent red → gray → green color scale. The renderer sets --hm-c on
   each tile (0 = -3% or worse, 0.5 = flat, 1 = +3% or better). We use
   color-mix to blend toward the surface color at the midpoint so flat
   tickers stay readable against the dark canvas instead of going neon. */
.heatmap-tile {
  --hm-neg: var(--neg);
  --hm-pos: var(--pos);
  --hm-neutral: var(--surface-3);
}
.heatmap-tile[data-dir="neg"] {
  background: color-mix(in srgb, var(--hm-neg) calc(var(--hm-intensity, 0) * 100%), var(--hm-neutral));
}
.heatmap-tile[data-dir="pos"] {
  background: color-mix(in srgb, var(--hm-pos) calc(var(--hm-intensity, 0) * 100%), var(--hm-neutral));
}
.heatmap-tile[data-dir="zero"] { background: var(--hm-neutral); }

.heatmap-tile.is-live-up { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 55%, transparent); }
.heatmap-tile.is-live-down { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--neg) 55%, transparent); }

/* "Hot" corner dot for heavy-volume names in performance mode. Redundant in
   rvol mode (the whole tile already encodes volume) so it's hidden there, and
   on micro tiles where there's no room. */
.heatmap-tile.is-hot::after {
  content: "";
  position: absolute;
  top: 3px;
  right: 3px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #ffd24a;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.45);
  pointer-events: none;
}
.heatmap-root.hm-mode-rvol .heatmap-tile.is-hot::after,
.heatmap-tile.is-micro.is-hot::after { display: none; }

/* Stale tile — the hourly refresh couldn't get a fresh quote, so the % shown
   is the last good print. Dim it and hatch faintly so it doesn't read as
   current. */
.heatmap-tile.is-stale {
  opacity: 0.5;
  background-image: repeating-linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.07) 0,
    rgba(255, 255, 255, 0.07) 2px,
    transparent 2px,
    transparent 6px
  );
}

/* Search highlight — dim everything, pop the matches. */
.heatmap-root.is-searching .heatmap-tile { opacity: 0.22; }
.heatmap-root.is-searching .heatmap-tile.is-search-hit {
  opacity: 1;
  z-index: 4;
  box-shadow: 0 0 0 2px var(--accent), 0 0 14px 2px color-mix(in srgb, var(--accent) 55%, transparent);
}
.heatmap-root.is-searching .heatmap-tile.is-stale.is-search-hit { opacity: 1; }

.heatmap-legend {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
}
.heatmap-legend-bar {
  flex: 0 0 220px;
  height: 8px;
  border-radius: 999px;
  background: linear-gradient(to right, var(--neg) 0%, var(--surface-3) 50%, var(--pos) 100%);
  border: 1px solid var(--border);
}
.heatmap-legend-label {
  font-variant-numeric: tabular-nums;
}
.heatmap-legend-note {
  flex-basis: 100%;
  margin-top: 2px;
  font: 500 0.68rem/1.3 var(--font-sans);
  text-transform: none;
  letter-spacing: 0;
  color: var(--muted);
}

/* Floating tooltip — positioned via JS using --tip-x / --tip-y (px). */
.heatmap-tooltip {
  position: absolute;
  left: 0;
  top: 0;
  transform: translate(var(--tip-x, 0), var(--tip-y, 0));
  pointer-events: none;
  background: var(--surface-3);
  color: var(--text);
  border: 1px solid var(--border-strong);
  border-radius: var(--r-2);
  padding: 8px 10px;
  font-size: 0.8rem;
  line-height: 1.35;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  z-index: 10;
  max-width: 240px;
}
.heatmap-tooltip[hidden] { display: none; }
.heatmap-tooltip-head {
  font: 700 13px/1.2 var(--font-mono);
  color: var(--text-strong);
  letter-spacing: .02em;
  margin-bottom: 2px;
}
.heatmap-tooltip-name {
  color: var(--muted-strong);
  font-size: 0.74rem;
  margin-bottom: 6px;
}
.heatmap-tooltip-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.heatmap-tooltip-row span:first-child { color: var(--muted); }
.heatmap-tooltip-row span:last-child {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}
.heatmap-tooltip-pct-pos { color: var(--pos); }
.heatmap-tooltip-pct-neg { color: var(--neg); }
.heatmap-tooltip-rv-hot { color: #ffd24a; }
.heatmap-tooltip-stale {
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid var(--border);
  font: 600 0.68rem/1.3 var(--font-mono);
  color: var(--warn, #e0a44a);
}

/* ---------------- EOD recap (heatmap) -----------------------------------
   Painted below the legend once scripts/refresh-heatmap.mjs has stamped an
   eodSummary onto data/heatmap.json. Headline up top, per-sector cards in
   a responsive grid below. Leader / laggard chips reuse the tickers tab's
   navigation handler. */
.heatmap-eod-summary {
  margin-top: 16px;
  border-top: 1px solid var(--border);
  padding-top: 16px;
}
.heatmap-eod-summary[hidden] { display: none; }
.heatmap-eod-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--s-2);
  margin-bottom: 6px;
}
.heatmap-eod-titles {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px;
  margin-right: auto;
}
.heatmap-eod-title {
  margin: 0;
  font: 700 0.95rem/1.2 var(--font-sans);
  color: var(--text-strong);
  letter-spacing: .01em;
}
.heatmap-eod-stamp {
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
}
.heatmap-eod-tape {
  font: 600 0.75rem/1.2 var(--font-mono);
  color: var(--muted-strong);
}
.heatmap-eod-pos { color: var(--pos); }
.heatmap-eod-neg { color: var(--neg); }
.heatmap-eod-flat { color: var(--muted); }
.heatmap-eod-headline {
  margin: 4px 0 14px;
  font: 600 0.95rem/1.4 var(--font-sans);
  color: var(--text);
}
.heatmap-eod-decision {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin: 10px 0 12px;
}
.heatmap-eod-rank {
  min-width: 0;
  padding: 11px 12px;
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-2);
}
.heatmap-eod-rank-leaders { border-left: 3px solid var(--pos); }
.heatmap-eod-rank-laggards { border-left: 3px solid var(--neg); }
.heatmap-eod-rank-label {
  display: block;
  margin-bottom: 8px;
  color: var(--muted);
  font: 700 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
}
.heatmap-eod-rank-list { display: flex; flex-wrap: wrap; gap: 6px; }
.heatmap-eod-group-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 30px;
  padding: 5px 9px;
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
  font: 650 0.72rem/1 var(--font-mono);
}
.heatmap-eod-group-chip:hover { border-color: var(--border-strong); background: var(--surface-3); }
.heatmap-eod-group-chip:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.heatmap-eod-group-chip span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.heatmap-eod-group-chip b { font-variant-numeric: tabular-nums; }
.heatmap-eod-group-chip.pos b { color: var(--pos); }
.heatmap-eod-group-chip.neg b { color: var(--neg); }
.heatmap-eod-details {
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  background: var(--surface-1);
  overflow: clip;
}
.heatmap-eod-details > summary {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 10px 12px;
  cursor: pointer;
  color: var(--text-strong);
  font: 700 0.8rem/1.2 var(--font-sans);
  list-style: none;
}
.heatmap-eod-details > summary::-webkit-details-marker { display: none; }
.heatmap-eod-details > summary::before {
  content: "›";
  color: var(--accent);
  font: 700 1rem/1 var(--font-mono);
  transform: rotate(0deg);
  transition: transform .15s ease;
}
.heatmap-eod-details[open] > summary::before { transform: rotate(90deg); }
.heatmap-eod-details > summary:hover { background: var(--surface-2); }
.heatmap-eod-details > summary small {
  margin-left: auto;
  color: var(--muted);
  font: 600 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .06em;
}
.heatmap-eod-sectors {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--s-3);
  padding: 0 12px 12px;
}
.heatmap-eod-sector {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-2);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-left-width: 3px;
}
.heatmap-eod-sector[data-dir="pos"] { border-left-color: var(--pos); }
.heatmap-eod-sector[data-dir="neg"] { border-left-color: var(--neg); }
.heatmap-eod-sector[data-dir="zero"] { border-left-color: var(--border-strong); }
.heatmap-eod-sector-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}
.heatmap-eod-sector-name {
  margin: 0;
  font: 700 0.85rem/1.2 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .04em;
  color: var(--text-strong);
}
.heatmap-eod-sector-avg {
  font: 700 0.85rem/1 var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.heatmap-eod-sector-avg.pos { color: var(--pos); }
.heatmap-eod-sector-avg.neg { color: var(--neg); }
.heatmap-eod-sector-avg.zero { color: var(--muted); }
.heatmap-eod-sector-text {
  margin: 0;
  font: 400 0.85rem/1.5 var(--font-sans);
  color: var(--text);
}
.heatmap-eod-movers {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.heatmap-eod-movers-row {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.heatmap-eod-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 3px 8px;
  font: 600 0.7rem/1 var(--font-mono);
  color: var(--text);
  cursor: pointer;
  font-variant-numeric: tabular-nums;
}
.heatmap-eod-chip:hover {
  border-color: var(--border-strong);
  background: var(--surface-3);
}
.heatmap-eod-chip.pos { color: var(--pos); }
.heatmap-eod-chip.neg { color: var(--neg); }
.heatmap-eod-chip span {
  color: var(--muted);
  font-weight: 500;
}
.heatmap-eod-chip.pos span { color: color-mix(in srgb, var(--pos) 80%, var(--text)); }
.heatmap-eod-chip.neg span { color: color-mix(in srgb, var(--neg) 80%, var(--text)); }

/* ── Market brief tab ─────────────────────────────────────────────────── */
.brief-root { display: flex; flex-direction: column; gap: var(--s-3); }
.brief-empty {
  margin: 8px 0;
  font: 400 0.9rem/1.5 var(--font-sans);
  color: var(--muted);
}
.brief-card {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-3);
  padding: 20px 22px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  border-left-width: 3px;
  border-left-color: var(--border-strong);
}
.brief-card[data-kind="morning"] { border-left-color: var(--accent); }
.brief-card[data-kind="intraday"] { border-left-color: var(--info); }
.brief-card[data-kind="afternoon"] { border-left-color: var(--pos); }
.brief-card-head { display: flex; flex-direction: column; gap: 6px; }
.brief-card-titles { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px; }
.brief-kind {
  font: 700 10px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  padding: 3px 7px;
  border-radius: var(--r-pill);
  background: var(--surface-3);
  color: var(--muted-strong);
}
.brief-kind-morning { color: var(--accent); background: color-mix(in srgb, var(--accent) 14%, transparent); }
.brief-kind-intraday { color: var(--info); background: color-mix(in srgb, var(--info) 14%, transparent); }
.brief-kind-afternoon { color: var(--pos); background: color-mix(in srgb, var(--pos) 14%, transparent); }
.brief-date { font: 600 0.72rem/1 var(--font-mono); color: var(--muted-strong); }
.brief-stamp { font: 600 10px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .08em; color: var(--muted); }
.brief-headline { margin: 2px 0 0; font: 700 1.4rem/1.3 var(--font-serif); letter-spacing: -0.02em; color: var(--text-strong); }
.brief-summary { margin: 0; font: 400 1rem/1.7 var(--font-sans); color: var(--text); max-width: 76ch; }
.brief-decision { display: flex; flex-direction: column; gap: 10px; padding: 12px 13px; border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--border)); border-left: 3px solid var(--accent); border-radius: 10px; background: color-mix(in srgb, var(--accent) 4%, var(--surface)); }
.brief-decision-press { border-left-color: var(--pos); background: color-mix(in srgb, var(--pos) 4%, var(--surface)); }
.brief-decision-protect { border-left-color: var(--neg); background: color-mix(in srgb, var(--neg) 4%, var(--surface)); }
.brief-decision-selective { border-left-color: var(--warn); background: color-mix(in srgb, var(--warn) 4%, var(--surface)); }
.brief-decision > header { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.brief-decision > header > div { min-width: 0; }
.brief-decision-kicker { display: block; margin-bottom: 4px; color: var(--accent); font: 700 9px/1 var(--font-mono); letter-spacing: .08em; text-transform: uppercase; }
.brief-decision-press .brief-decision-kicker { color: var(--pos); }
.brief-decision-protect .brief-decision-kicker { color: var(--neg); }
.brief-decision-selective .brief-decision-kicker { color: var(--warn); }
.brief-decision h4 { margin: 0; color: var(--text-strong); font: 750 15px/1.25 var(--font-sans); }
.brief-decision > header p { margin: 4px 0 0; color: var(--muted); font: 500 10px/1.35 var(--font-sans); }
.brief-decision-score { flex: 0 0 auto; padding: 5px 7px; border: 1px solid var(--border); border-radius: 999px; background: var(--surface-2); color: var(--muted-strong); font: 700 9px/1 var(--font-mono); }
.brief-decision-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); border: 1px solid var(--border); border-radius: 8px; overflow: hidden; background: var(--surface); }
.brief-decision-grid > span { display: flex; flex-direction: column; gap: 3px; min-width: 0; padding: 8px 9px; border-right: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.brief-decision-grid > span:nth-child(2n) { border-right: 0; }
.brief-decision-grid > span:nth-last-child(-n+2) { border-bottom: 0; }
.brief-decision-grid small { color: var(--muted); font: 700 8px/1 var(--font-mono); letter-spacing: .06em; text-transform: uppercase; }
.brief-decision-grid b { color: var(--text-strong); font: 650 10.5px/1.35 var(--font-sans); overflow-wrap: anywhere; }
.brief-decision-grid em { color: var(--muted); font: 500 9.5px/1.3 var(--font-sans); font-style: normal; overflow-wrap: anywhere; }
.brief-decision-actions { display: flex; flex-wrap: wrap; gap: 6px; }
.brief-decision-actions button { min-height: 34px; padding: 6px 9px; border: 1px solid var(--border); border-radius: 7px; background: var(--surface); color: var(--text); font: 650 10.5px/1.15 var(--font-sans); cursor: pointer; }
.brief-decision-actions button:hover, .brief-decision-actions button:focus-visible { border-color: var(--accent); color: var(--accent); background: var(--accent-soft); }
.brief-stats { display: flex; flex-wrap: wrap; gap: 6px; }
.brief-stat {
  display: inline-flex; flex-direction: column; gap: 2px;
  padding: 6px 10px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-1);
}
.brief-stat-label { font: 600 9px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
.brief-stat-val { font: 700 0.8rem/1.1 var(--font-mono); color: var(--text-strong); font-variant-numeric: tabular-nums; }
.brief-stat-val .pos { color: var(--pos); }
.brief-stat-val .neg { color: var(--neg); }
.brief-stat-chg { color: var(--muted); font-weight: 500; }
.brief-highlights { margin: 2px 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 9px; }
.brief-hl {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px;
  font: 400 0.95rem/1.6 var(--font-sans); color: var(--text);
  padding-left: 12px;
  border-left: 2px solid color-mix(in srgb, var(--accent) 45%, var(--border));
}
/* Fixed label column so the takeaway text starts on the same vertical line in
   every row (variable-length labels were ragged) — mirrors the watch-list rows'
   fixed-width ticker chip below. A longer label wraps within the column. */
.brief-hl-label {
  flex: 0 0 128px;
  font: 700 0.66rem/1.3 var(--font-mono);
  text-transform: uppercase; letter-spacing: .04em;
  color: var(--accent);
}
.brief-hl-text { flex: 1 1 200px; }
.brief-toolscan {
  display: flex; flex-direction: column; gap: 10px;
  padding: 13px;
  border: 1px solid color-mix(in srgb, var(--info) 30%, var(--border));
  border-radius: 10px;
  background: color-mix(in srgb, var(--info) 4%, var(--surface));
}
.brief-toolscan > header { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.brief-toolscan-kicker { display: block; margin-bottom: 4px; color: var(--info); font: 700 9px/1 var(--font-mono); letter-spacing: .08em; text-transform: uppercase; }
.brief-toolscan h4 { margin: 0; color: var(--text-strong); font: 750 15px/1.25 var(--font-sans); }
.brief-toolscan-count { flex: 0 0 auto; color: var(--muted); font: 650 9px/1.25 var(--font-mono); text-transform: uppercase; letter-spacing: .04em; text-align: right; }
.brief-toolscan-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; }
.brief-toolscan-row {
  display: grid; grid-template-columns: minmax(92px, auto) minmax(0, 1fr); align-items: start; gap: 6px 10px;
  min-width: 0; padding: 9px 10px;
  border: 1px solid var(--border); border-left: 2px solid var(--info); border-radius: 8px;
  background: var(--surface);
}
.brief-toolscan-row.is-positive { border-left-color: var(--pos); }
.brief-toolscan-row.is-risk { border-left-color: var(--neg); }
.brief-toolscan-row.is-watch { border-left-color: var(--warn); }
.brief-toolscan-source {
  appearance: none; justify-self: start; padding: 0; border: 0; background: none;
  color: var(--info); font: 700 9px/1.35 var(--font-mono); letter-spacing: .05em; text-transform: uppercase;
  text-align: left; cursor: pointer;
}
.brief-toolscan-source:hover, .brief-toolscan-source:focus-visible { color: var(--accent); text-decoration: underline; text-underline-offset: 2px; }
.brief-toolscan-row p { margin: 0; color: var(--text); font: 500 11px/1.45 var(--font-sans); overflow-wrap: anywhere; }
.brief-toolscan-syms { grid-column: 2; color: var(--muted); font: 650 9px/1.2 var(--font-mono); letter-spacing: .03em; }
.brief-toolscan-quiet { margin: 0; color: var(--muted); font: 500 11px/1.45 var(--font-sans); }
/* Detailed data blocks, grouped below the story behind a rule so the prose
   (headline / summary / takeaways) reads first. */
.brief-blocks {
  display: flex; flex-direction: column; gap: var(--s-4);
  margin-top: 2px; padding-top: 14px;
  border-top: 1px solid var(--border);
}
.brief-evidence { border: 1px solid var(--border); border-radius: 9px; background: var(--surface); overflow: hidden; }
.brief-evidence > summary { display: flex; align-items: center; gap: 7px; min-height: 42px; padding: 0 11px; list-style: none; color: var(--text-strong); font: 650 11px/1.25 var(--font-sans); cursor: pointer; }
.brief-evidence > summary::-webkit-details-marker { display: none; }
.brief-evidence > summary::before { content: '▸'; color: var(--accent); font-size: 12px; }
.brief-evidence[open] > summary::before { content: '▾'; }
.brief-evidence > summary span { margin-left: auto; color: var(--muted); font: 600 9px/1 var(--font-mono); text-transform: uppercase; }
.brief-evidence .brief-blocks { margin: 0; padding: 13px 11px 11px; }
.brief-block { display: flex; flex-direction: column; gap: 8px; }
.brief-block-title {
  margin: 0; font: 700 0.72rem/1.2 var(--font-mono);
  text-transform: uppercase; letter-spacing: .07em; color: var(--muted-strong);
  padding-bottom: 5px; border-bottom: 1px solid var(--hairline);
}
.brief-chips { display: flex; flex-wrap: wrap; gap: 5px; }
.brief-chip {
  display: inline-flex; align-items: center; gap: 4px;
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-pill); padding: 3px 9px;
  font: 600 0.72rem/1 var(--font-mono); color: var(--text);
  cursor: pointer; font-variant-numeric: tabular-nums;
}
a.brief-chip[data-sym]:hover { border-color: var(--border-strong); background: var(--surface-3); }
.brief-chip span { color: var(--muted); font-weight: 500; }
.brief-chip.pos { color: var(--pos); }
.brief-chip.neg { color: var(--neg); }
.brief-chip.pos span { color: color-mix(in srgb, var(--pos) 80%, var(--text)); }
.brief-chip.neg span { color: color-mix(in srgb, var(--neg) 80%, var(--text)); }
.brief-chip.foreign, .brief-chip.info, span.brief-chip { cursor: default; }
.brief-chip.flow span, .brief-chip.pick span { text-transform: uppercase; letter-spacing: .03em; color: var(--accent); }
.brief-analog {
  display: flex; flex-direction: column; gap: 7px;
  background: var(--surface);
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--border));
  border-radius: var(--r-1);
  padding: 10px 12px;
}
.brief-analog-head { font: 700 0.82rem/1.3 var(--font-sans); color: var(--accent); }
.brief-analog-row { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px; font: 400 0.84rem/1.5 var(--font-sans); color: var(--text); }
.brief-analog-k {
  flex: none;
  font: 700 0.62rem/1.4 var(--font-mono);
  text-transform: uppercase; letter-spacing: .04em;
  color: var(--muted-strong);
  min-width: 96px;
}
.brief-analog-v { flex: 1 1 220px; }
.brief-events { display: flex; flex-wrap: wrap; gap: 5px; }
.brief-event {
  display: inline-flex; align-items: baseline; gap: 6px;
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-1); padding: 4px 9px;
}
.brief-event-label { font: 600 0.72rem/1.2 var(--font-sans); color: var(--text); }
.brief-event-detail { font: 600 0.66rem/1 var(--font-mono); color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
.brief-hlines { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 5px; }
.brief-hline {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 8px;
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-2); padding: 6px 10px;
}
.brief-hline-title { font: 500 0.8rem/1.4 var(--font-sans); color: var(--text); flex: 1 1 240px; }
/* Watch-list rows: pin the ticker/% chip to one fixed column width so the
   reason text starts on the same vertical line in every row (variable-length
   symbols + percents were ragged), with the % pushed to the chip's right edge. */
.brief-hline > .brief-chip { min-width: 118px; justify-content: space-between; }
/* Tape headlines link to their source article when the feed gave us a permalink. */
a.brief-hline-title { text-decoration: none; transition: color .12s var(--ease-out); }
a.brief-hline-title:hover { color: var(--accent-strong); text-decoration: underline; text-underline-offset: 2px; }
a.brief-hline-title:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 2px; }
.brief-hline-ext { margin-left: 4px; font-size: 10px; color: var(--muted); }
a.brief-hline-title:hover .brief-hline-ext { color: var(--accent-strong); }
.brief-hline-meta { font: 600 0.62rem/1.2 var(--font-mono); color: var(--muted); text-transform: uppercase; letter-spacing: .04em; white-space: nowrap; }
@media (max-width: 760px) {
  .brief-card { padding: 15px; }
  .brief-decision-grid { grid-template-columns: minmax(0, 1fr); }
  .brief-decision-grid > span, .brief-decision-grid > span:nth-child(2n), .brief-decision-grid > span:nth-last-child(-n+2) { border-right: 0; border-bottom: 1px solid var(--border); }
  .brief-decision-grid > span:last-child { border-bottom: 0; }
  .brief-decision-actions { display: grid; grid-template-columns: minmax(0, 1fr); }
  .brief-decision-actions button { min-height: 40px; }
  .brief-hl-label { flex-basis: 100%; }
  .brief-toolscan > header { flex-direction: column; }
  .brief-toolscan-count { text-align: left; }
  .brief-toolscan-grid { grid-template-columns: minmax(0, 1fr); }
  .brief-toolscan-row { grid-template-columns: minmax(82px, auto) minmax(0, 1fr); }
}

/* ── News desk ───────────────────────────────────────────────────────── */
.sr-only {
  position: absolute !important;
  width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}
.news-feed-summary {
  display: block;
  margin: var(--s-3) 0;
  padding: 14px 15px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--muted);
  border-radius: var(--r-2);
  background: linear-gradient(135deg, color-mix(in srgb, var(--surface-2) 92%, transparent), var(--surface));
}
.news-feed-summary:empty { display: none; }
.news-posture-unresolved { border-left-color: var(--warn); }
.news-posture-favorable { border-left-color: var(--pos); }
.news-posture-adverse { border-left-color: var(--neg); }
.news-posture-mixed { border-left-color: var(--info); }
.news-posture-quiet { border-left-color: var(--muted); }
.news-posture-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.news-posture-kicker,
.news-posture-state { color: var(--muted); font: 700 9px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .08em; }
.news-posture-state { padding: 4px 7px; border-radius: var(--r-pill); background: var(--surface-3); }
.news-posture-unresolved .news-posture-state { color: var(--warn); background: var(--warn-soft); }
.news-posture-favorable .news-posture-state { color: var(--pos); background: var(--pos-soft); }
.news-posture-adverse .news-posture-state { color: var(--neg); background: var(--neg-soft); }
.news-posture-mixed .news-posture-state { color: var(--info); background: var(--info-soft); }
.news-feed-summary h3 { margin: 8px 0 5px; color: var(--text-strong); font: 750 1.08rem/1.25 var(--font-sans); }
.news-feed-summary > p { max-width: 920px; margin: 0; color: var(--text); font: 400 12.5px/1.5 var(--font-sans); }
.news-posture-metrics {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px; margin-top: 13px; overflow: hidden;
  border: 1px solid var(--border); border-radius: var(--r-2); background: var(--border);
}
.news-posture-metrics > div { min-width: 0; padding: 10px 11px; background: var(--surface); }
.news-posture-metrics b { display: block; color: var(--text-strong); font: 700 1rem/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.news-posture-metrics span,
.news-posture-metrics small { display: block; margin-top: 5px; color: var(--muted); font: 700 8.5px/1.2 var(--font-mono); text-transform: uppercase; letter-spacing: .055em; }
.news-posture-metrics small { margin-top: 3px; font-weight: 500; text-transform: none; letter-spacing: 0; }
.news-posture-triggers { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 9px; }
.news-posture-triggers > div { padding: 9px 10px; border: 1px solid var(--border); border-radius: var(--r-1); background: color-mix(in srgb, var(--surface-2) 78%, transparent); }
.news-posture-triggers span { display: block; margin-bottom: 4px; color: var(--muted); font: 700 8.5px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .07em; }
.news-posture-triggers b { color: var(--text); font: 600 11px/1.4 var(--font-sans); }
.news-posture-match { margin-top: 9px; color: var(--muted); font: 600 9.5px/1.2 var(--font-mono); }
@media (max-width: 640px) {
  .news-feed-summary { padding: 13px 12px; }
  .news-posture-metrics { grid-template-columns: 1fr 1fr; }
  .news-posture-triggers { grid-template-columns: 1fr; }
}
.news-feed-toolbar {
  display: grid;
  grid-template-columns: minmax(230px, 1fr) auto auto;
  align-items: center;
  gap: var(--s-2);
  margin-bottom: var(--s-2);
}
.news-feed-search-wrap { min-width: 0; }
.news-feed-search,
.news-feed-select-wrap select,
.news-more-grid select {
  width: 100%; min-height: 40px;
  border: 1px solid var(--border); border-radius: var(--r-2);
  background: var(--surface-2); color: var(--text);
  font: 600 0.78rem/1.2 var(--font-sans);
  transition: border-color var(--dur-1) var(--ease-out), box-shadow var(--dur-1) var(--ease-out);
}
.news-feed-search { padding: 9px 12px; }
.news-feed-search::placeholder { color: var(--muted); }
.news-feed-search:focus,
.news-feed-select-wrap select:focus,
.news-more-grid select:focus { outline: none; border-color: var(--accent); box-shadow: var(--focus-ring); }
.news-impact-filter {
  display: inline-flex; align-items: center; gap: 3px;
  padding: 3px; border: 1px solid var(--border); border-radius: var(--r-pill);
  background: var(--surface-2);
}
.news-filter-chip {
  min-height: 32px; padding: 5px 10px;
  border: 0; border-radius: var(--r-pill); background: transparent;
  color: var(--muted-strong); cursor: pointer;
  font: 700 0.66rem/1 var(--font-mono); white-space: nowrap;
}
.news-filter-chip:hover { color: var(--text-strong); background: var(--surface-3); }
.news-filter-chip.is-active { color: var(--accent-fg); background: var(--accent); }
.news-feed-select-wrap { display: flex; align-items: center; gap: 7px; }
.news-feed-select-wrap > span,
.news-more-grid label > span { font: 700 0.6rem/1 var(--font-mono); color: var(--muted); text-transform: uppercase; letter-spacing: .06em; white-space: nowrap; }
.news-feed-select-wrap select { width: auto; min-width: 130px; padding: 7px 28px 7px 9px; }
.news-more-filters {
  margin: 0 0 var(--s-3);
  border: 1px solid var(--border); border-radius: var(--r-2);
  background: var(--surface);
}
.news-more-filters > summary {
  display: flex; align-items: center; gap: 7px;
  min-height: 38px; padding: 7px 11px;
  cursor: pointer; list-style: none;
  font: 700 0.68rem/1.2 var(--font-mono); color: var(--muted-strong);
}
.news-more-filters > summary::-webkit-details-marker { display: none; }
.news-more-filters > summary::after { content: '▾'; margin-left: auto; transition: transform var(--dur-1) var(--ease-out); }
.news-more-filters[open] > summary::after { transform: rotate(180deg); }
.news-filter-count {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 18px; height: 18px; padding: 0 5px;
  border-radius: var(--r-pill); background: var(--accent-soft); color: var(--accent);
}
.news-more-grid {
  display: grid; grid-template-columns: repeat(5, minmax(120px, 1fr)); gap: var(--s-2);
  padding: var(--s-3); border-top: 1px solid var(--border);
}
.news-more-grid label { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.news-more-grid select { padding: 7px 26px 7px 9px; }
.news-feed-root { display: flex; flex-direction: column; gap: 7px; min-width: 0; }
.news-feed-item {
  position: relative; min-width: 0;
  padding: 13px 15px 13px 17px;
  border: 1px solid var(--border); border-left: 3px solid var(--border-strong);
  border-radius: var(--r-2); background: var(--surface-2);
  box-shadow: var(--elev-0);
}
.news-feed-item.impact-high { border-left-color: var(--violet); }
.news-feed-item.impact-notable { border-left-color: var(--info); }
.news-feed-item-top { display: flex; flex-wrap: wrap; align-items: center; gap: 5px; margin-bottom: 7px; }
.news-feed-item-top time {
  margin-left: auto;
  font: 600 0.64rem/1 var(--font-mono); color: var(--muted); font-variant-numeric: tabular-nums;
}
.news-impact-badge,
.news-direction-badge,
.news-macro-read,
.news-unconfirmed,
.news-carried {
  display: inline-flex; align-items: center;
  min-height: 20px; padding: 3px 7px; border-radius: var(--r-pill);
  font: 700 0.58rem/1 var(--font-mono); text-transform: uppercase; letter-spacing: .055em;
}
.impact-high .news-impact-badge { color: var(--violet); background: var(--violet-soft); }
.impact-notable .news-impact-badge { color: var(--info); background: var(--info-soft); }
.impact-context .news-impact-badge { color: var(--muted-strong); background: var(--surface-3); }
.direction-positive .news-direction-badge { color: var(--pos); background: var(--pos-soft); }
.direction-negative .news-direction-badge { color: var(--neg); background: var(--neg-soft); }
.direction-mixed .news-direction-badge { color: var(--warn); background: var(--warn-soft); }
.direction-unclear .news-direction-badge { color: var(--muted); border: 1px solid var(--border); }
.news-macro-read { color: var(--info); background: var(--info-soft); text-transform: none; letter-spacing: 0; }
.news-macro-read.surprise-above { color: var(--warn); background: var(--warn-soft); }
.news-macro-read.surprise-inline { color: var(--muted-strong); background: var(--surface-3); }
.news-unconfirmed { color: var(--warn); border: 1px solid color-mix(in srgb, var(--warn) 32%, var(--border)); }
.news-carried { color: var(--muted); background: var(--surface); }
.news-feed-headline {
  display: block; min-width: 0; margin: 0 0 7px;
  color: var(--text-strong); text-decoration: none;
  font: 650 1rem/1.38 var(--font-sans); letter-spacing: -.01em;
  overflow-wrap: anywhere;
}
a.news-feed-headline:hover { color: var(--accent-strong); text-decoration: underline; text-underline-offset: 3px; }
a.news-feed-headline:focus-visible,
.news-feed-sym:focus-visible,
.news-filter-chip:focus-visible,
.news-feed-more:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.news-feed-byline {
  display: flex; flex-wrap: wrap; align-items: center; gap: 5px 9px;
  color: var(--muted); font: 600 0.65rem/1.3 var(--font-mono);
  min-width: 0;
}
.news-feed-byline > span:not(.news-feed-market):not(.news-feed-macro):not(.news-feed-related) { overflow-wrap: anywhere; }
.news-feed-sym,
.news-feed-market,
.news-feed-macro {
  display: inline-flex; align-items: center; min-height: 23px; padding: 3px 7px;
  border: 1px solid var(--border-strong); border-radius: var(--r-pill);
  background: var(--surface); color: var(--text-strong); text-decoration: none;
  font: 700 0.65rem/1 var(--font-mono);
}
.news-feed-sym:hover { border-color: var(--accent); color: var(--accent-strong); }
.news-feed-market { color: var(--info); border-color: color-mix(in srgb, var(--info) 32%, var(--border)); }
.news-feed-macro { color: var(--violet); border-color: color-mix(in srgb, var(--violet) 35%, var(--border)); }
.news-feed-related { color: var(--muted-strong); font-size: .61rem; }
.news-feed-why {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 5px 10px;
  margin-top: 8px; padding-top: 8px; border-top: 1px solid var(--hairline);
  color: var(--muted-strong); font: 400 0.76rem/1.45 var(--font-sans);
}
.news-feed-why b { color: var(--text); font-weight: 700; }
.news-feed-reaction {
  display: inline-flex; align-items: center;
  padding: 3px 7px; border-radius: var(--r-pill); background: var(--surface);
  color: var(--muted-strong); font: 700 0.62rem/1 var(--font-mono); font-variant-numeric: tabular-nums;
}
.news-feed-reaction.pos { color: var(--pos); background: var(--pos-soft); }
.news-feed-reaction.neg { color: var(--neg); background: var(--neg-soft); }
.news-feed-status,
.news-feed-empty { margin: 10px 0; color: var(--muted); font: 500 0.86rem/1.5 var(--font-sans); }
.news-feed-error { color: var(--neg); }
.news-feed-more {
  display: block; width: 100%; min-height: 42px; margin-top: var(--s-3);
  border: 1px solid var(--border); border-radius: var(--r-2);
  background: var(--surface-2); color: var(--text);
  cursor: pointer; font: 700 0.72rem/1 var(--font-mono);
}
.news-feed-more:hover { border-color: var(--border-strong); background: var(--surface-3); }
.news-filter-count[hidden],
.news-feed-more[hidden],
.news-feed-empty[hidden] { display: none !important; }

@media (max-width: 760px) {
  .news-feed-toolbar { grid-template-columns: 1fr; }
  .news-impact-filter { justify-self: start; max-width: 100%; overflow-x: auto; }
  .news-feed-select-wrap { width: 100%; }
  .news-feed-select-wrap select { flex: 1 1 auto; width: 100%; }
  .news-more-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 480px) {
  .news-feed-summary { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .news-feed-summary > div { flex-direction: column; align-items: flex-start; gap: 4px; padding: 9px 8px; }
  .news-feed-summary span { font-size: .56rem; }
  .news-feed-summary p { grid-column: 1 / -1; }
  .news-more-grid { grid-template-columns: 1fr; }
  .news-feed-search,
  .news-feed-select-wrap select,
  .news-more-grid select { min-height: 44px; }
  .news-filter-chip { min-height: 38px; }
  .news-feed-item { padding: 12px 12px 12px 14px; }
  .news-feed-headline { font-size: .94rem; }
  .news-feed-item-top time { flex-basis: auto; }
}

@media (max-width: 640px) {
  .heatmap-controls { grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 8px; }
  .heatmap-group-control,
  .heatmap-color-control { grid-column: span 3; }
  .heatmap-search-control { grid-column: 1 / -1; }
  .heatmap-live-toggle { grid-column: span 2; min-height: 44px; }
  .heatmap-zoom { grid-column: span 4; min-height: 44px; }
  .heatmap-control select,
  .heatmap-search-input { min-height: 44px; }
  .heatmap-live-state { justify-self: start; }
  .heatmap-root {
    height: 60vh;
    min-height: 380px;
  }
  .heatmap-legend-bar { flex-basis: 140px; }
  .heatmap-eod-decision { grid-template-columns: 1fr; }
  .heatmap-eod-group-chip { flex: 1 1 calc(50% - 3px); justify-content: space-between; }
  .heatmap-eod-details > summary small { font-size: 9px; }
  .heatmap-eod-sectors { grid-template-columns: 1fr; }
  /* Thumb-sized zoom controls — 26px buttons are fiddly on touch. */
  .heatmap-zoom-btn { min-width: 34px; height: 34px; }
}

/* ---- Gamma OI tab --------------------------------------------------- */
.oi-card { padding: var(--s-4); }
.oi-card-header { align-items: center; }
.oi-collapse-btn {
  background: none;
  border: none;
  color: inherit;
  display: inline-flex;
  align-items: center;
  gap: var(--s-2);
  cursor: pointer;
  padding: 0;
}
.oi-collapse-btn:focus-visible { outline: none; box-shadow: var(--focus-ring); border-radius: var(--r-2); }
.oi-collapse-btn[aria-expanded="false"] .oi-chevron { transform: rotate(-90deg); }
.oi-chevron { transition: transform var(--xt); color: var(--text-2); }
.oi-card .oi-body[hidden] { display: none; }

.oi-controls {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-3);
  align-items: center;
  margin-bottom: var(--s-3);
}
.oi-search {
  display: inline-flex;
  align-items: center;
  gap: var(--s-2);
  padding: var(--s-2) var(--s-3);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  color: var(--text-2);
  min-width: 240px;
}
.oi-search:focus-within {
  border-color: var(--accent);
  box-shadow: var(--focus-ring);
}
.oi-search input {
  background: transparent;
  border: none;
  outline: none;
  color: var(--text);
  flex: 1;
  font: inherit;
  min-width: 0;
}
.oi-search-clear {
  background: none;
  border: none;
  color: var(--text-2);
  cursor: pointer;
  padding: 0 var(--s-1);
  font-size: 1.1em;
  line-height: 1;
}
.oi-toggle {
  display: inline-flex;
  align-items: center;
  gap: var(--s-2);
  color: var(--text-2);
  cursor: pointer;
}
.oi-sort {
  display: inline-flex;
  align-items: center;
  gap: var(--s-2);
  color: var(--text-2);
}
.oi-sort-label { font-size: 0.9em; }
.oi-sort select {
  background: var(--surface-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  padding: var(--s-2) var(--s-3);
  font: inherit;
}
.oi-action-btn {
  background: var(--surface-2);
  color: var(--text-2);
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  padding: var(--s-2) var(--s-3);
  font: inherit;
  cursor: pointer;
  transition: background-color var(--xt), color var(--xt);
}
.oi-action-btn:hover { color: var(--text); }
.oi-action-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--accent-on);
  border-color: transparent;
}

.oi-list {
  display: grid;
  gap: var(--s-3);
}
.oi-row {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: var(--s-3) var(--s-4);
  display: flex;
  flex-direction: column;
  gap: var(--s-3);
}
.oi-row:hover {
  background: color-mix(in srgb, var(--accent) 3%, var(--surface-2));
  border-color: var(--border-strong);
}
.oi-row.is-flagged {
  border-color: color-mix(in srgb, var(--accent) 50%, transparent);
  background: color-mix(in srgb, var(--accent) 5%, var(--surface-2));
}
.oi-row.is-collapsed { padding-bottom: var(--s-3); }
.oi-row-head {
  display: flex;
  align-items: center;
  gap: var(--s-3);
  flex-wrap: wrap;
  background: none;
  border: none;
  color: inherit;
  padding: 0;
  cursor: pointer;
  text-align: left;
  width: 100%;
}
.oi-row-head:focus-visible { outline: none; box-shadow: var(--focus-ring); border-radius: var(--r-2); }
.oi-row-chevron { transition: transform var(--xt); color: var(--text-2); flex-shrink: 0; }
.oi-row-head[aria-expanded="false"] .oi-row-chevron { transform: rotate(-90deg); }

.oi-symbol {
  font-weight: 600;
  font-size: 1.05em;
  letter-spacing: 0.02em;
  color: var(--text);
}
.oi-spot {
  color: var(--text-2);
  font-variant-numeric: tabular-nums;
}
.oi-summary-bits {
  display: inline-flex;
  flex-wrap: wrap;
  gap: var(--s-2);
  margin-left: auto;
  color: var(--text-2);
  font-size: 0.9em;
}
.oi-wall, .oi-cp, .oi-short {
  display: inline-flex;
  align-items: center;
  padding: 2px var(--s-2);
  border-radius: var(--r-pill);
  border: 1px solid var(--border);
  background: var(--surface-3);
  font-variant-numeric: tabular-nums;
}
.oi-short {
  color: var(--violet);
  border-color: color-mix(in srgb, var(--violet) 35%, transparent);
  background: color-mix(in srgb, var(--violet) 7%, var(--surface-3));
}
.oi-wall-call {
  color: var(--up);
  border-color: color-mix(in srgb, var(--up) 35%, transparent);
}
.oi-wall-put {
  color: var(--dn);
  border-color: color-mix(in srgb, var(--dn) 35%, transparent);
}

.oi-score {
  display: inline-flex;
  align-items: center;
  padding: 2px var(--s-2);
  border-radius: var(--r-pill);
  font-weight: 600;
  font-size: 0.88em;
  letter-spacing: 0.02em;
  border: 1px solid var(--border);
  background: var(--surface-3);
  color: var(--text-2);
}
.oi-score.tier-1 { color: var(--text-3); }
.oi-score.tier-2 { color: var(--text-2); }
.oi-score.tier-3 {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-3));
  color: var(--text);
  border-color: color-mix(in srgb, var(--accent) 25%, transparent);
}
.oi-score.tier-4 {
  background: color-mix(in srgb, var(--accent) 22%, var(--surface-2));
  color: var(--accent);
  border-color: color-mix(in srgb, var(--accent) 55%, transparent);
}
.oi-score.tier-5 {
  background: color-mix(in srgb, var(--up) 22%, var(--surface-2));
  color: var(--up);
  border-color: color-mix(in srgb, var(--up) 55%, transparent);
}
.oi-score.is-flagged {
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 30%, transparent);
}

.oi-body-row { display: flex; flex-direction: column; gap: var(--s-3); }
.oi-body-row[hidden] { display: none; }

.oi-reasons {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-2);
}
.oi-reason {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px var(--s-2);
  border-radius: var(--r-pill);
  font-size: 0.85em;
  background: color-mix(in srgb, var(--accent) 10%, var(--surface-3));
  color: var(--text);
  border: 1px solid color-mix(in srgb, var(--accent) 30%, transparent);
}
.oi-reason-tick { color: var(--up); font-weight: 700; }

/* Options ladder — two columns, calls left + puts right. Each "rung" is
   one strike. Rungs are pre-sorted closest-to-spot first by the JS, so
   visually the top of each column is ATM and the bottom is the most
   distant. Bar widths share a scale across both sides so a tall call
   wall really does look taller than a smaller put wall. */
.oi-ladder {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--s-3);
}
.oi-ladder-col {
  display: flex;
  flex-direction: column;
  gap: var(--s-2);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: var(--s-3);
  min-width: 0;
}
.oi-ladder-calls {
  border-color: color-mix(in srgb, var(--up) 28%, var(--border));
  background: color-mix(in srgb, var(--up) 3%, var(--surface));
}
.oi-ladder-puts {
  border-color: color-mix(in srgb, var(--dn) 28%, var(--border));
  background: color-mix(in srgb, var(--dn) 3%, var(--surface));
}
.oi-ladder-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--s-2);
  padding-bottom: var(--s-2);
  border-bottom: 1px solid var(--border);
}
.oi-ladder-side {
  font-weight: 700;
  letter-spacing: 0.08em;
  font-size: 0.78em;
  text-transform: uppercase;
}
.oi-ladder-calls .oi-ladder-side { color: var(--up); }
.oi-ladder-puts .oi-ladder-side { color: var(--dn); }
.oi-ladder-count {
  color: var(--text-3);
  font-size: 0.78em;
  letter-spacing: 0.04em;
}
.oi-ladder-empty {
  color: var(--text-3);
  font-style: italic;
  font-size: 0.88em;
  padding: var(--s-3) 0;
  text-align: center;
}
.oi-ladder-rungs {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--s-2);
}
.oi-rung {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: var(--s-2);
  border-radius: var(--r-2);
  background: var(--surface-2);
  border: 1px solid transparent;
  font-variant-numeric: tabular-nums;
  transition: border-color var(--xt), background-color var(--xt);
}
.oi-rung:hover {
  background: color-mix(in srgb, var(--accent) 4%, var(--surface-2));
}
.oi-rung.is-wall.is-call {
  border-color: color-mix(in srgb, var(--up) 45%, transparent);
  background: color-mix(in srgb, var(--up) 8%, var(--surface-2));
}
.oi-rung.is-wall.is-put {
  border-color: color-mix(in srgb, var(--dn) 45%, transparent);
  background: color-mix(in srgb, var(--dn) 8%, var(--surface-2));
}
.oi-rung-head {
  display: flex;
  align-items: baseline;
  gap: var(--s-2);
  flex-wrap: wrap;
}
.oi-rung-strike {
  font-weight: 600;
  font-size: 1em;
  color: var(--text);
}
.oi-rung-spot {
  font-size: 0.8em;
  color: var(--text-3);
}
.oi-rung-spot.is-atm { color: var(--accent); font-weight: 500; }
.oi-rung-spot.is-itm { color: var(--text-2); }
.oi-rung-wall {
  font-size: 0.66em;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 1px 5px;
  border-radius: var(--r-pill);
  border: 1px solid currentColor;
}
.oi-rung-wall.is-call { color: var(--up); }
.oi-rung-wall.is-put { color: var(--dn); }
.oi-rung-oi {
  margin-left: auto;
  color: var(--text-2);
  font-size: 0.85em;
}
.oi-rung-oi b { color: var(--text); font-weight: 600; }
.oi-rung-bar {
  position: relative;
  height: 6px;
  border-radius: 3px;
  background: color-mix(in srgb, var(--text-3) 14%, transparent);
  overflow: hidden;
}
.oi-rung-bar-fill {
  position: absolute;
  inset: 0 auto 0 0;
  border-radius: inherit;
  background: linear-gradient(90deg,
    color-mix(in srgb, currentColor 60%, transparent),
    currentColor);
  transition: width var(--xt);
}
.oi-rung.is-call .oi-rung-bar-fill { color: var(--up); }
.oi-rung.is-put  .oi-rung-bar-fill { color: var(--dn); }
.oi-rung-meta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s-2);
  color: var(--text-3);
  font-size: 0.8em;
}
.oi-rung-delta.is-up { color: var(--up); }
.oi-rung-delta.is-dn { color: var(--dn); }
.oi-rung-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.oi-chip {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  border-radius: var(--r-pill);
  font-size: 0.78em;
  font-weight: 500;
  border: 1px solid var(--border);
  background: var(--surface-3);
  color: var(--text-2);
}
.oi-chip-big {
  color: var(--text);
  border-color: var(--border-strong);
}
.oi-chip-delta30 {
  color: var(--accent);
  border-color: color-mix(in srgb, var(--accent) 45%, transparent);
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-3));
}
.oi-chip-delta100 {
  color: var(--up);
  border-color: color-mix(in srgb, var(--up) 55%, transparent);
  background: color-mix(in srgb, var(--up) 18%, var(--surface-3));
}
.oi-chip-volhot {
  color: var(--accent);
  border-color: color-mix(in srgb, var(--accent) 55%, transparent);
  background: color-mix(in srgb, var(--accent) 15%, var(--surface-3));
}

.oi-empty {
  padding: var(--s-4);
  color: var(--muted);
  text-align: center;
}

@media (max-width: 720px) {
  .oi-ladder { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  /* Controls: full-width search on its own row (same treatment as the
     Volume tab), tighter toolbar gaps. */
  .oi-controls { gap: var(--s-2); }
  .oi-search { flex: 1 1 100%; min-width: 0; }
  .oi-row-head { gap: var(--s-2); }
  .oi-summary-bits { margin-left: 0; width: 100%; }
  .oi-symbol { font-size: 1em; }
  .oi-ladder-col { padding: var(--s-2); }
  .oi-rung { padding: var(--s-2); }
  .oi-rung-head { gap: var(--s-1); }
  .oi-rung-meta { font-size: 0.78em; }
  .oi-rung-strike { font-size: 0.95em; }
}

/* ===================================================================
   Gamma exposure (GEX) heatmap — per-ticker strike × expiration grid
   computed client-side (see computeGex/renderGex in app-js).
   =================================================================== */
.gex-card { padding: var(--s-4); margin-bottom: var(--s-4); }
.gex-card .gex-key-pos { color: var(--up); font-weight: 500; }
.gex-card .gex-key-neg { color: var(--dn); font-weight: 500; }
.gex-controls {
  display: flex; flex-wrap: wrap; align-items: flex-end; gap: var(--s-3);
  margin-bottom: var(--s-4);
}
.gex-control { display: flex; flex-direction: column; gap: var(--s-1); }
.gex-control-label { font-size: 0.78em; color: var(--text-3); text-transform: uppercase; letter-spacing: 0.04em; }
.gex-control select {
  appearance: none; background: var(--surface-2); color: var(--text);
  border: 1px solid var(--border); border-radius: var(--r-2);
  padding: var(--s-2) var(--s-3); font: inherit; min-width: 130px; cursor: pointer;
}
.gex-control select:focus-visible { outline: none; box-shadow: var(--focus-ring); }
/* Searchable ticker combobox (replaces the old <select>). Reuses the shared
   .combo styling; just size it to sit inline with the other GEX controls. */
.gex-control-ticker { flex: 0 1 280px; min-width: 200px; }
.gex-combo { flex: none; width: 100%; min-width: 0; }
.gex-combo input { height: auto; padding-top: var(--s-2); padding-bottom: var(--s-2); }
.gex-action-btn {
  background: var(--surface-2); color: var(--text-2); border: 1px solid var(--border);
  border-radius: var(--r-2); padding: var(--s-2) var(--s-3); font: inherit; cursor: pointer;
  transition: color var(--xt), border-color var(--xt);
}
.gex-action-btn:hover { color: var(--text); border-color: var(--border-strong); }
.gex-action-btn:focus-visible { outline: none; box-shadow: var(--focus-ring); }

.gex-summary { display: flex; flex-direction: column; gap: var(--s-3); margin-bottom: var(--s-4); }
/* Verdict badges — the one-second read (Lean / Regime / Volatility / Positioning). */
.gex-verdict { display: flex; flex-wrap: wrap; gap: var(--s-2); }
.gex-badge {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 6px 12px; border-radius: var(--r-pill);
  border: 1px solid var(--border); background: var(--surface-2);
  font-size: var(--fs-sm);
}
.gex-badge-k { font-size: 0.72em; color: var(--text-3); text-transform: uppercase; letter-spacing: 0.05em; }
.gex-badge-v { font-weight: 600; color: var(--text-strong); font-variant-numeric: tabular-nums; }
.gex-badge-sub { font-weight: 500; color: var(--text-3); font-size: 0.88em; }
.gex-badge.is-pos { border-color: color-mix(in srgb, var(--up) 45%, var(--border)); background: color-mix(in srgb, var(--up) 8%, var(--surface-2)); }
.gex-badge.is-pos .gex-badge-v { color: var(--up); }
.gex-badge.is-neg { border-color: color-mix(in srgb, var(--dn) 45%, var(--border)); background: color-mix(in srgb, var(--dn) 8%, var(--surface-2)); }
.gex-badge.is-neg .gex-badge-v { color: var(--dn); }
.gex-metrics { display: flex; flex-wrap: wrap; gap: var(--s-2); }
.gex-metric {
  flex: 1 1 150px; min-width: 130px;
  background: var(--surface-2); border: 1px solid var(--border);
  border-radius: var(--r-3); padding: var(--s-3);
  display: flex; flex-direction: column; gap: 2px;
}
.gex-metric-label { font-size: 0.72em; color: var(--text-3); text-transform: uppercase; letter-spacing: 0.05em; }
.gex-metric-val { font-size: 1.25em; font-weight: 600; color: var(--text-strong); font-variant-numeric: tabular-nums; }
.gex-metric-sub { font-size: 0.78em; color: var(--text-3); }
.gex-metric.is-pos .gex-metric-val { color: var(--up); }
.gex-metric.is-neg .gex-metric-val { color: var(--dn); }
.gex-spot-chg { font-size: 0.6em; font-weight: 600; vertical-align: middle; }
.gex-spot-chg.is-up { color: var(--up); }
.gex-spot-chg.is-dn { color: var(--dn); }

.gex-keylevels { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-2); }
.gex-keylevels-label { font-size: 0.72em; color: var(--text-3); text-transform: uppercase; letter-spacing: 0.05em; }
.gex-keychip {
  font-size: 0.82em; font-variant-numeric: tabular-nums;
  padding: 3px var(--s-2); border-radius: var(--r-pill);
  border: 1px solid var(--border); background: var(--surface-2); color: var(--text);
}
.gex-keychip.is-pos { border-color: color-mix(in srgb, var(--pos) 40%, var(--border)); }
.gex-keychip.is-neg { border-color: color-mix(in srgb, var(--neg) 40%, var(--border)); }
.gex-keychip-exp { color: var(--text-3); }

/* Plain-English read of the current dealer-gamma situation (gexNarrative). */
.gex-takeaway {
  margin: 0;
  padding: var(--s-3);
  border: 1px solid var(--border);
  border-left: 3px solid var(--text-3);
  border-radius: var(--r-2);
  background: var(--surface-2);
  color: var(--text-2);
  font-size: var(--fs-sm); line-height: 1.55;
}
.gex-takeaway strong { color: var(--text-strong); font-weight: 600; }
.gex-takeaway.is-pos { border-left-color: var(--up); }
.gex-takeaway.is-neg { border-left-color: var(--dn); }

.gex-grid-wrap {
  overflow: auto; max-height: 70vh;
  border: 1px solid var(--border); border-radius: var(--r-3);
}
.gex-table { border-collapse: separate; border-spacing: 0; width: 100%; font-variant-numeric: tabular-nums; }
.gex-table th, .gex-table td {
  padding: 5px var(--s-2); text-align: center; white-space: nowrap;
  font-size: 0.82em; border-bottom: 1px solid var(--border); border-right: 1px solid var(--border);
}
.gex-th-strike, .gex-th-exp, .gex-th-total {
  position: sticky; top: 0; z-index: 3;
  background: var(--surface-2); color: var(--text-2);
  font-weight: 600; font-size: 0.74em; text-transform: uppercase; letter-spacing: 0.03em;
}
.gex-th-exp { display: table-cell; }
.gex-th-date { display: block; color: var(--text); }
.gex-th-dte { display: block; font-size: 0.85em; color: var(--text-3); font-weight: 400; }
.gex-th-strike { left: 0; z-index: 4; text-align: right; }
.gex-strike {
  position: sticky; left: 0; z-index: 2;
  background: var(--surface-2); color: var(--text-2);
  text-align: right; font-weight: 600;
}
.gex-cell { color: var(--text-strong); font-weight: 500; }
.gex-cell.is-empty { color: var(--text-3); background: transparent; }
/* Cells carrying data-gex-k hand their strike/expiration to the contract
   grader on click — show it. */
[data-gex-k] { cursor: pointer; }
td[data-gex-k]:hover, th[data-gex-k]:hover { box-shadow: inset 0 0 0 1.5px var(--accent); }
.gex-tr:hover .gex-strike { color: var(--text); }
.gex-spot-row .gex-spot-strike {
  background: var(--accent-soft); color: var(--accent-strong); font-weight: 700;
  border-top: 2px solid var(--accent); border-bottom: 2px solid var(--accent);
}
.gex-spot-tag {
  font-size: 0.68em; text-transform: uppercase; letter-spacing: 0.05em;
  color: var(--accent); font-weight: 600;
}
.gex-spot-cell { background: color-mix(in srgb, var(--accent) 7%, transparent); border-top: 2px solid var(--accent); border-bottom: 2px solid var(--accent); }

/* Per-strike "Net Σ" aggregate column — the gamma profile beside each strike.
   The diverging bar is drawn as an inline-styled cell background (gexTotalBg);
   these rules just handle the value's color + the empty/zero state. */
.gex-total-cell { font-weight: 600; color: var(--text-strong); }
.gex-total-cell.is-pos { color: var(--accent-strong); }
.gex-total-cell.is-neg { color: var(--neg); }
.gex-total-cell.is-empty { color: var(--text-3); background: transparent; }

/* Call / put wall row markers — a CW/PW tag in the strike cell plus an inset
   accent rail on the sticky strike column. */
.gex-wall-tag {
  display: inline-block; margin-left: 4px; padding: 0 4px; border-radius: var(--r-1);
  font-size: 0.64em; font-weight: 700; letter-spacing: 0.03em; vertical-align: middle;
}
.gex-wall-tag.is-call { color: var(--accent-strong); background: var(--accent-soft); }
.gex-wall-tag.is-put { color: var(--neg); background: color-mix(in srgb, var(--neg) 14%, transparent); }
.gex-tr.is-callwall .gex-strike { box-shadow: inset 3px 0 0 var(--accent); }
.gex-tr.is-putwall .gex-strike { box-shadow: inset 3px 0 0 var(--neg); }

/* Gamma-flip reference line — amber + dashed so it reads distinctly from the
   solid-green spot line (the two often sit close together). */
.gex-flip-row .gex-flip-strike {
  background: var(--warn-soft); color: var(--warn); font-weight: 700;
  border-top: 2px dashed var(--warn); border-bottom: 2px dashed var(--warn);
}
.gex-flip-tag {
  font-size: 0.68em; text-transform: uppercase; letter-spacing: 0.05em;
  color: var(--warn); font-weight: 600;
}
.gex-flip-cell { background: var(--warn-tint); border-top: 2px dashed var(--warn); border-bottom: 2px dashed var(--warn); }

.gex-legend { display: flex; align-items: center; gap: var(--s-2); margin-top: var(--s-3); justify-content: center; }
.gex-legend-label { font-size: 0.74em; color: var(--text-3); }
.gex-legend-bar {
  width: 180px; height: 8px; border-radius: var(--r-pill);
  background: linear-gradient(90deg, rgba(255,77,94,0.9), rgba(255,77,94,0.15), var(--surface-2), rgba(22,224,138,0.15), rgba(22,224,138,0.9));
}
.gex-empty { padding: var(--s-4); color: var(--muted); text-align: center; }

@media (max-width: 640px) {
  .gex-metric { flex-basis: 120px; min-width: 110px; }
  .gex-metric-val { font-size: 1.1em; }
  .gex-table th, .gex-table td { font-size: 0.76em; padding: 4px 6px; }
}

/* ===================================================================
   Mobile refinements (final pass)
   ===================================================================
   Layered on top of the established mobile blocks higher up in this
   stylesheet (look for the "Tablet & narrow desktop (<=900px)" /
   "Phone (<=640px)" sections starting around line 6694). Those already
   handle the bulk of layout adjustments — padding, table stacking,
   font sizes, input zoom prevention. THIS block only adds the
   refinements those blocks don't cover:

     1. tap-highlight suppression (global, dark-UI cosmetic fix)
     2. hover-state cleanup for touch devices (cards, tiles)
     3. landing-page polish — hero numerals + card padding at <=560px
        (the existing 640px block doesn't reach into .landing-*)
     4. footer + freshness stacking on phones
     5. safe-area-inset handling for notched / rounded-screen phones

   Anything that overlaps with the existing mobile rules — main /
   page-sub / page-tabs / site-header padding, .icon-btn sizing,
   input font-size — is intentionally NOT redefined here so this
   block doesn't undo the existing per-breakpoint gradient.
   ------------------------------------------------------------------- */

/* Suppress the iOS Safari double-tap zoom flash on every interactive
   element. We already handle focus rings via :focus-visible; the
   default grey/blue tap-highlight just looks like a bug on dark UI. */
html { -webkit-tap-highlight-color: transparent; }

/* Rapid taps on small controls (filter chips, segmented toggles, pagination,
   the pin/compare buttons) must register as TAPS, not as a double-tap zoom
   gesture — touch-action: manipulation disables double-tap-to-zoom on the
   control itself while leaving pinch zoom and scrolling untouched. Links are
   included; text content is not, so a reader can still double-tap-zoom prose. */
button, [role="button"], [role="tab"], [role="option"], a, select, label,
input[type="checkbox"], input[type="radio"], summary {
  touch-action: manipulation;
}

/* Flinging a horizontally-scrollable strip to its edge must not chain into
   the browser's edge-swipe (back/forward navigation on iOS/Android) — that
   reads as "the site randomly navigated away". Vertical chaining stays. */
.narr-tabs {
  overscroll-behavior-x: contain;
}

/* Hover-capable pointers only. Touch devices fire :hover on tap and
   then strand the hovered state until the next tap elsewhere — for
   purely cosmetic hover effects (translate/scale, glow halos, soft
   tint shifts) this reads as a UI bug. The existing @media (hover: none)
   block around line 6684 handles flow-chip / cal-chip / narr-card /
   pf-risk-block. This adds the four heaviest remaining offenders:
   landing-card (transform + glow + arrow slide), pick-card (border
   shift), heatmap-tile (brightness pump), and the cmd-palette
   trigger (background swap). */
@media (hover: none) {
  .landing-quick-card:hover { border-color: var(--border); background: var(--surface); transform: none; }
  .landing-quick-card:hover > em { color: var(--muted); transform: translateY(-50%); }
  .landing-card:hover {
    transform: none;
    box-shadow: var(--elev-1);
    border-color: var(--border);
    background: var(--surface);
    background-image: var(--grad-surface);
  }
  .landing-card:hover::before { transform: scaleX(0); }
  .landing-card:hover .landing-card-arrow {
    color: var(--muted);
    transform: translateX(0);
  }
  .pick-card:hover { border-color: var(--border); }
  .heatmap-tile:hover { filter: none; }
  .cmd-palette-trigger:hover {
    color: var(--muted);
    border-color: var(--border);
    background: var(--surface-2);
  }
}

/* === Landing page polish (<=560px) ================================
   The existing 640px block tightens main/header/page-tabs but doesn't
   touch the home-tab landing hero or the section cards, so those still
   render with desktop-scale padding and the ~44px hero numerals can
   wrap mid-digit on a card whose stat is "$200.42". Scale the hero
   typography, tighten card padding, and reduce vertical rhythm so the
   home tab fits in one viewport on a 6.1" phone instead of forcing
   four screenfuls of scroll just to see the section titles. */
@media (max-width: 560px) {
  .landing-hero {
    padding: var(--s-5) var(--s-3) var(--s-4);
    margin-bottom: var(--s-4);
  }
  .landing-hero-title { font-size: var(--fs-xl); }
  .landing-hero-eyebrow { font-size: 11px; margin-bottom: var(--s-2); }
  .landing-hero-sub { font-size: 11px; }
  .landing-quick { gap: 6px; }
  .landing-quick-card { padding: 9px 28px 9px 10px; }
  .landing-quick-card > b { font-size: 11px; }
  .landing-quick-card > small { font-size: 8.5px; }
  .landing-quick-card > em { right: 9px; }
  .landing-pulse { flex-wrap: nowrap; margin-inline: calc(var(--s-3) * -1); padding-inline: var(--s-3); overflow-x: auto; overscroll-behavior-inline: contain; scrollbar-width: none; }
  .landing-pulse::-webkit-scrollbar { display: none; }
  .pulse-item { flex: 0 0 auto; scroll-snap-align: start; }
  .landing-section { margin-bottom: var(--s-4); }
  .landing-section-head { padding: 0; }
  .landing-grid { gap: 8px; }
  .landing-card {
    padding: 10px;
    min-height: 112px;
    gap: var(--s-1);
  }
  .landing-card-eyebrow { font-size: 10.5px; letter-spacing: .06em; }
  .landing-card-arrow { font-size: 14px; }
  .landing-card-stat { font-size: 24px; overflow-wrap: anywhere; }
  .landing-card-sub { font-size: 8px; line-height: 1.25; letter-spacing: .07em; }
  .landing-card-desc { display: none; }
  .landing-card-head { margin-bottom: 0; }
  .landing-card::after { left: 10px; right: 10px; bottom: 8px; }

  /* Footer — let the legal links + build timestamp stack so neither
     gets squeezed against the screen edge. The existing footer rule
     uses flex-wrap which still keeps both rows on the same line at
     360–420px widths. */
  .site-footer {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--s-3);
    padding: var(--s-4) var(--s-3) var(--s-5);
  }

  /* Picks — at 480px the rank+content already stack via the 860px
     rule. Tighten the inner padding so the card isn't mostly empty
     whitespace at compact widths. */
  .pick-card {
    padding: var(--s-2) var(--s-2) var(--s-3);
    gap: var(--s-2);
  }
  .pick-rank-num { font-size: 20px; }
  .pick-contract { padding: 6px 8px; }
  .pick-tier { padding: 6px 10px; }
}

@media (max-width: 340px) {
  .landing-quick, .landing-grid { grid-template-columns: minmax(0, 1fr); }
}

/* === Body overflow protection =====================================
   Some absolutely-positioned children (tooltips, heatmap tiles using
   percentage transforms, the ambient radial gradient on body) can
   briefly extend a pixel or two past the viewport edge and trigger a
   horizontal scrollbar. overflow-x: clip is the modern way to silently
   crop without creating a scroll container, which would break
   position: sticky on the header. (Safari 16+, all other evergreen.) */
@media (max-width: 560px) {
  html, body { overflow-x: clip; }
}

/* === Compact phones (<=380px) =====================================
   iPhone SE / mini territory. The existing 400px block tightens
   tickers-grid and per-card padding, but the page chrome (freshness
   timestamp, header nav cluster, footer) still tries to lay out on
   one line and clips. Force column stacking on those three rows. */
@media (max-width: 380px) {
  .freshness { flex-direction: column; align-items: flex-start; }
  .site-nav { gap: 4px; }
  .cmd-palette-trigger { padding: 8px; min-width: 36px; }
  .site-footer { font-size: 11px; gap: var(--s-2); }
}

/* === Safe-area handling for notched / rounded phones ==============
   The header is sticky and the footer is flush to the bottom; both
   need to respect env(safe-area-inset-*) so content doesn't bleed
   under the iOS home-indicator pill or the iPhone notch when the
   browser chrome auto-hides on scroll. Using max() preserves the
   existing per-breakpoint horizontal padding when the inset is 0
   (rectangular screens / Android) and only adds extra padding when
   the inset is non-zero (iPhone X+ / Pixel XL+). */
@supports (padding: max(0px)) {
  .site-header {
    padding-left: max(var(--s-3), env(safe-area-inset-left));
    padding-right: max(var(--s-3), env(safe-area-inset-right));
  }
  main {
    padding-left: max(var(--s-2), env(safe-area-inset-left));
    padding-right: max(var(--s-2), env(safe-area-inset-right));
  }
  .side-nav {
    padding-left: env(safe-area-inset-left);
  }
  .site-footer {
    padding-bottom: max(var(--s-5), env(safe-area-inset-bottom));
    padding-left: max(var(--s-3), env(safe-area-inset-left));
    padding-right: max(var(--s-3), env(safe-area-inset-right));
  }
}

/* Overnight markets / correlations tab + Grade-tab peer-read widget. */
.overnight-decision{margin-top:.25rem;}
.overnight-broad{display:flex;flex-wrap:wrap;gap:.4rem;margin-bottom:1rem;}
.ovn-chip{display:inline-flex;align-items:center;gap:.4rem;padding:.22rem .55rem;border-radius:999px;border:1px solid var(--border);background:var(--surface);font-size:.78rem;white-space:nowrap;}
.ovn-chip-name{color:var(--muted-strong);}
.ovn-chip-ch,.ovn-tile-ch,.ovn-w-ch,.ovn-w-imp{font-variant-numeric:tabular-nums;font-weight:600;}
.ovn-desk{display:flex;flex-direction:column;gap:.65rem;margin-bottom:.8rem;padding:.8rem;border:1px solid color-mix(in srgb,var(--accent) 28%,var(--border));border-radius:12px;background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 5%,var(--surface)),var(--surface) 60%);}
.ovn-desk-head{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;}
.ovn-desk-head>div{min-width:0;}
.ovn-desk-kicker{font:700 .62rem/1 var(--font-mono);letter-spacing:.1em;text-transform:uppercase;color:var(--accent-strong);}
.ovn-desk-head h3{margin:.2rem 0 0;font:750 1rem/1.25 var(--font-sans);color:var(--text-strong);}
.ovn-desk-head>small{font:.68rem/1.3 var(--font-sans);color:var(--muted);text-align:right;}
.ovn-desk-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:.5rem;}
.ovn-driver{display:flex;flex-direction:column;gap:.35rem;min-width:0;padding:.65rem;border:1px solid var(--border);border-left:3px solid var(--border-strong);border-radius:9px;background:var(--surface-2);}
.ovn-driver.ovn-up{border-left-color:var(--pos);}
.ovn-driver.ovn-dn{border-left-color:var(--neg);}
.ovn-driver-top{display:flex;align-items:center;justify-content:space-between;gap:.4rem;font:700 .62rem/1 var(--font-mono);letter-spacing:.07em;text-transform:uppercase;color:var(--muted);}
.ovn-driver-main{display:flex;align-items:baseline;justify-content:space-between;gap:.6rem;}
.ovn-driver-main b{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:700 .84rem/1.25 var(--font-sans);color:var(--text-strong);}
.ovn-driver-main strong{flex:none;font:750 .83rem/1 var(--font-mono);font-variant-numeric:tabular-nums;}
.ovn-driver.ovn-up .ovn-driver-main strong{color:var(--pos);}
.ovn-driver.ovn-dn .ovn-driver-main strong{color:var(--neg);}
.ovn-driver-type-rate{border-left-color:var(--warn) !important;}
.ovn-driver-type-rate .ovn-driver-main strong{color:var(--warn) !important;}
.ovn-driver-type-vol.ovn-up{border-left-color:var(--neg) !important;}
.ovn-driver-type-vol.ovn-up .ovn-driver-main strong{color:var(--neg) !important;}
.ovn-driver-meta{display:flex;flex-wrap:wrap;gap:.25rem .55rem;font:.68rem/1.3 var(--font-sans);color:var(--muted-strong);}
.ovn-driver-watch{display:flex;align-items:center;flex-wrap:wrap;gap:.28rem;margin-top:auto;padding-top:.25rem;border-top:1px solid var(--hairline);}
.ovn-driver-watch>span{font:700 .56rem/1 var(--font-mono);letter-spacing:.07em;text-transform:uppercase;color:var(--muted);}
.ovn-driver-watch button{appearance:none;border:1px solid var(--border-strong);border-radius:999px;background:var(--surface);padding:.14rem .38rem;font:700 .64rem/1 var(--font-mono);color:var(--text);cursor:pointer;}
.ovn-driver-watch button:hover,.ovn-driver-watch button:focus-visible{border-color:var(--accent);color:var(--accent);}
.ovn-driver-context{opacity:.72;}
.ovn-region-list{display:flex;flex-direction:column;gap:.5rem;}
.ovn-region{border:1px solid var(--border);border-radius:10px;background:var(--surface-2);overflow:clip;}
.ovn-region[open]{border-color:color-mix(in srgb,var(--accent) 28%,var(--border));}
.ovn-region>summary{min-height:48px;display:flex;align-items:center;justify-content:space-between;gap:.8rem;padding:.5rem .7rem;list-style:none;cursor:pointer;}
.ovn-region>summary::-webkit-details-marker{display:none;}
.ovn-region>summary::before{content:'›';flex:none;color:var(--accent);font-size:1.05rem;line-height:1;transition:transform var(--dur-1);}
.ovn-region[open]>summary::before{transform:rotate(90deg);}
.ovn-region>summary>span:first-of-type{display:flex;flex-direction:column;gap:.15rem;min-width:0;flex:1;}
.ovn-region>summary b{font:700 .76rem/1.15 var(--font-mono);letter-spacing:.06em;text-transform:uppercase;color:var(--text-strong);}
.ovn-region>summary small{font:.66rem/1.2 var(--font-sans);color:var(--muted);}
.ovn-region-lead{display:flex;align-items:baseline;justify-content:flex-end;gap:.45rem;min-width:0;}
.ovn-region-lead em{max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:500 .72rem/1.2 var(--font-sans);font-style:normal;color:var(--muted-strong);}
.ovn-region-lead strong{flex:none;font:700 .74rem/1 var(--font-mono);font-variant-numeric:tabular-nums;color:var(--muted-strong);}
.ovn-region-lead strong.ovn-up{color:var(--pos);}
.ovn-region-lead strong.ovn-dn{color:var(--neg);}
.ovn-region-body{padding:.6rem;border-top:1px solid var(--hairline);background:var(--surface);}
.ovn-region-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:.6rem;}
.ovn-tile{border:1px solid var(--border);border-radius:10px;background:var(--surface-2);padding:.6rem .7rem;display:flex;flex-direction:column;gap:.3rem;}
.ovn-tile.ovn-up{border-left:3px solid var(--pos);}
.ovn-tile.ovn-dn{border-left:3px solid var(--neg);}
.ovn-tile.ovn-flat{border-left:3px solid var(--border-strong);}
.ovn-tile-top{display:flex;justify-content:space-between;align-items:baseline;gap:.5rem;}
.ovn-tile-name{font-weight:600;}
.ovn-tile-lead{font-size:.75rem;color:var(--muted-strong);}
.ovn-tile-flags{display:flex;flex-wrap:wrap;align-items:center;gap:.3rem;font-size:.72rem;color:var(--muted);}
.ovn-tile-flags-lbl{text-transform:uppercase;letter-spacing:.06em;}
.ovn-flag{font:inherit;font-size:.72rem;cursor:pointer;border:1px solid var(--border-strong);background:var(--surface);color:var(--text-2);border-radius:6px;padding:.05rem .35rem;}
.ovn-flag:hover{border-color:var(--accent);color:var(--accent);opacity:1 !important;}
.ovn-flag-r{margin-left:.18rem;font-variant-numeric:tabular-nums;color:var(--muted-strong);}
.ovn-flag-weak{border-style:dashed;}
.ovn-tile-sub{display:flex;align-items:baseline;gap:.5rem;}
.ovn-tile-level{font-variant-numeric:tabular-nums;font-size:.82rem;color:var(--muted-strong);}
.ovn-tile-asof{font-size:.68rem;color:var(--muted);}
.ovn-chip-lvl{font-variant-numeric:tabular-nums;color:var(--text-2);}
.ovn-keylvl-lbl{align-self:center;font-size:.7rem;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);margin-right:.15rem;}
.ovn-tag{font-size:.62rem;text-transform:uppercase;letter-spacing:.04em;padding:.02rem .3rem;border-radius:5px;border:1px solid var(--border-strong);color:var(--muted);vertical-align:middle;white-space:nowrap;}
.overnight-empty{color:var(--muted-strong);}
.ovn-up .ovn-chip-ch,.ovn-up .ovn-tile-ch,.ovn-up .ovn-w-ch,.ovn-w-head.ovn-up b{color:var(--pos);}
.ovn-dn .ovn-chip-ch,.ovn-dn .ovn-tile-ch,.ovn-dn .ovn-w-ch,.ovn-w-head.ovn-dn b{color:var(--neg);}
.ovn-flat .ovn-chip-ch,.ovn-flat .ovn-tile-ch,.ovn-flat .ovn-w-ch{color:var(--muted-strong);}
.ovn-w-imp.ovn-up{color:var(--pos);}
.ovn-w-imp.ovn-dn{color:var(--neg);}
.ovn-w-imp.ovn-flat{color:var(--muted-strong);}
.ovn-widget{margin:.75rem 0;padding:.7rem .85rem;border:1px solid var(--border);border-radius:12px;background:var(--surface-2);}
.ovn-w-title{margin:0 0 .5rem;font-size:.72rem;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);}
.ovn-w-head{font-size:.95rem;margin-bottom:.5rem;}
.ovn-w-r{color:var(--muted-strong);font-size:.82em;}
.ovn-w-peers{display:flex;flex-direction:column;gap:.25rem;margin-bottom:.55rem;}
.ovn-w-row{display:grid;grid-template-columns:1fr auto auto auto;gap:.5rem;align-items:baseline;font-size:.83rem;padding:.18rem 0;border-bottom:1px solid var(--border);}
.ovn-w-row:last-child{border-bottom:0;}
.ovn-w-peer{color:var(--text-2);}
.ovn-w-stat{color:var(--muted-strong);font-variant-numeric:tabular-nums;}
.ovn-w-imp{text-align:right;}
.ovn-w-broad{display:flex;flex-wrap:wrap;gap:.35rem;align-items:center;}
.ovn-w-nopeer{color:var(--muted-strong);font-size:.8rem;}
.ovn-w-loading{color:var(--muted-strong);font-size:.85rem;}
.ovn-w-weak{opacity:.6;}
.ovn-w-legend{font-size:.72rem;color:var(--muted);margin-bottom:.55rem;line-height:1.35;}
/* Phone: the 4-column peer rows (name + r + beta + implied) get tight at
   390px — shrink the type/gaps and let a long peer name ellipsize instead
   of squeezing the stats columns. */
@media (max-width: 640px){
  .overnight-broad{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;padding-bottom:.15rem;margin-bottom:.7rem;}
  .overnight-broad::-webkit-scrollbar{display:none;}
  .ovn-keylvl-lbl,.ovn-chip{flex:0 0 auto;}
  .ovn-desk{padding:.65rem;}
  .ovn-desk-head{align-items:flex-start;}
  .ovn-desk-head>small{max-width:118px;}
  .ovn-desk-grid{display:flex;overflow-x:auto;scroll-snap-type:x proximity;scrollbar-width:none;padding-bottom:.15rem;}
  .ovn-desk-grid::-webkit-scrollbar{display:none;}
  .ovn-driver{flex:0 0 min(252px,78vw);scroll-snap-align:start;}
  .ovn-region>summary{align-items:flex-start;gap:.45rem;padding:.55rem .6rem;}
  .ovn-region-lead{max-width:47%;flex-direction:column;align-items:flex-end;gap:.2rem;}
  .ovn-region-lead em{max-width:145px;}
  .ovn-w-row{grid-template-columns:minmax(0,1fr) auto auto auto;gap:.35rem;font-size:.78rem;}
  .ovn-w-peer{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
}

/* ===== Generic chart hover readout (svg[data-ch], app.js chHover) ======= */
/* One shared crosshair line + snap dot + tooltip, fixed-positioned by the
   delegated engine in app.js. pointer-events:none so they never steal the
   hover from the chart under them. */
svg[data-ch]{ cursor: crosshair; touch-action: pan-y; }
[data-cr]{ cursor: crosshair; touch-action: pan-y; }
.is-range-comparing .opt-pc-hover,
.is-range-comparing .opt-pc-tip,
.is-range-comparing .opt-fund-eh-cross,
.is-range-comparing .opt-fund-eh-crossdot,
.is-range-comparing .opt-fund-eh-readout,
.is-range-comparing .fng-spark-cursor,
.is-range-comparing .fng-spark-dot,
.is-range-comparing .fng-spark-tip,
.is-range-comparing .cmp-chart-cross,
.is-range-comparing .cmp-chart-dot { display: none !important; }
.ch-line{
  position: fixed; z-index: 960; width: 0;
  border-left: 1px dashed color-mix(in srgb, var(--text) 40%, transparent);
  pointer-events: none;
}
.ch-dot{
  position: fixed; z-index: 961; width: 9px; height: 9px; margin: -4.5px 0 0 -4.5px;
  border-radius: 50%; background: var(--accent);
  box-shadow: 0 0 0 2px var(--surface);
  pointer-events: none;
}
.ch-tip{
  position: fixed; z-index: 962; max-width: 280px;
  padding: 6px 9px; border-radius: var(--r-2);
  background: var(--text-strong); color: var(--surface);
  font-size: 12px; font-weight: 500; line-height: 1.45;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  box-shadow: 0 4px 14px rgb(0 0 0 / .2);
  pointer-events: none;
}
.ch-range-band {
  position: fixed;
  z-index: 958;
  pointer-events: none;
  border-left: 1px solid var(--accent);
  border-right: 1px solid var(--accent);
  background: color-mix(in srgb, var(--accent) 14%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 8%, transparent);
}
.ch-range-band[hidden], .ch-range-tip[hidden] { display: none; }
.ch-range-tip {
  position: fixed;
  z-index: 963;
  min-width: 220px;
  max-width: min(360px, calc(100vw - 16px));
  padding: 9px 11px;
  border: 1px solid var(--border-strong);
  border-radius: var(--r-2);
  background: var(--surface);
  color: var(--text);
  box-shadow: var(--elev-pop);
  font: 600 11px/1.35 var(--font-mono);
  font-variant-numeric: tabular-nums;
  pointer-events: none;
}
.ch-range-head {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 7px;
  padding-bottom: 7px;
  margin-bottom: 5px;
  border-bottom: 1px solid var(--hairline);
  color: var(--muted-strong);
}
.ch-range-head span:last-child { text-align: right; }
.ch-range-head i { color: var(--muted); font-style: normal; font-weight: 500; }
.ch-range-guide { color: var(--muted-strong); font-family: var(--font-sans); font-weight: 600; }
.ch-range-row {
  display: grid;
  grid-template-columns: minmax(52px, auto) minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  padding: 2px 0;
}
.ch-range-row b { overflow: hidden; color: var(--text-strong); text-overflow: ellipsis; white-space: nowrap; }
.ch-range-row span { color: var(--muted); text-align: right; white-space: nowrap; }
.ch-range-row strong { min-width: 58px; text-align: right; }
.ch-range-row strong.is-up { color: var(--pos); }
.ch-range-row strong.is-down { color: var(--neg); }
.ch-range-row strong.is-flat { color: var(--muted); }
@media (max-width: 640px) {
  .ch-range-tip { max-height: 44vh; overflow: hidden; }
  .ch-range-row { grid-template-columns: minmax(48px, auto) minmax(0, 1fr) auto; gap: 6px; }
}
